  str_item_6001531 = "Ode ao Amor",
  str_item_6001532 = "Sua Luz Estelar",
  str_item_intro_6000001 = "Medalhão Stand By Me. Com o passar dos anos, o número de moedas cresceu para um tamanho alarmante. Neste ponto, apenas um porta-moedas do tamanho de uma casa poderia conter tanta riqueza.",
  str_item_intro_6000002 = "Medalhão Stand By Me. Parece quase impossível calcular essa vasta quantidade de riqueza acumulada. Ousar fazer isso deixará até mesmo os mercadores Umbraton mais avarentos tontos a ponto de desmaiar.",
  str_item_intro_6000101 = "Medalhão Stand By Me. Parabéns! Apesar de apenas tentar algumas vezes, não há como dizer o que o futuro reserva!",
  str_item_intro_6000102 = "Medalhão Stand By Me. Você é bastante capaz de pilotar o Colossus agora! Seu vínculo com os vaga-lumes parece estar ficando mais forte também.",
  str_item_intro_6000103 = "Medalhão Stand By Me. Nuvens à sua frente e nuvens ao seu redor. Mergulhe abaixo deles para ver o vasto mundo abaixo e o céu azul pontilhado de nuvens acima.",
  str_item_intro_6000104 = "Medalhão Stand By Me. Você viajou muito e longe como o Navegador de Soroz. Pode-se até dizer que seu verdadeiro lar está nos céus sem limites acima de Astra.",
  str_item_intro_6000201 = "Medalhão Stand By Me. Leve a imagem da terra em seu coração e vá para onde quiser com um aceno de sua mão. Todo o mundo está ao seu alcance.",
  str_item_intro_6000202 = "Medalhão Stand By Me. Depois de tantas viagens, a configuração da terra deve estar profundamente gravada em sua mente, certo? Você consegue ver suas montanhas e rios, mesmo quando fecha os olhos?",
  str_item_intro_6000301 = "Medalhão Stand By Me. O caminho a seguir certamente será longo e árduo. Encontrar companheiros confiáveis de todas as esferas da vida lhe servirá bem.",
  str_item_intro_6000302 = "Medalhão Stand By Me. Ao longo de suas muitas viagens, você forjou muitas novas amizades com pessoas de todo o mundo. Um feito impressionante, de fato!",
  str_item_intro_6000303 = "Medalhão Stand By Me. Não importa onde você vá, você está sempre cercado por amigos íntimos. Amigos que vão rir e chorar ao seu lado, e enfrentar quaisquer adversidades que possam surgir em seu caminho...",
  str_item_intro_6000401 = "Medalhão Stand By Me. O céu parece iluminar um pouco mais a cada novo aliado que percebe seu verdadeiro potencial. Talvez essa luz misteriosa seja o poder que une você e seus amigos?",
  str_item_intro_6000402 = "Medalhão Stand By Me. Depois que seus aliados adquirirem o poder da luz, a energia que ilumina o céu também poderá ser vista em suas mãos.",
  str_item_intro_6000403 = "Medalhão Stand By Me. Aqueles abençoados com o poder da luz se unirão e oferecerão sua força a um filho do destino, para que seu brilho alcance até os cantos mais sombrios e desanimados do mundo.",
  str_item_intro_6000501 = "Medalhão Stand By Me. Quando duas estrelas aparecem próximas uma da outra, sua luz cintilante é um símbolo de sua confiança, um sinal de que elas refletirão o brilho uma da outra por muito tempo.",
  str_item_intro_6000502 = "Medalhão Stand By Me. À medida que as estrelas viajam pelos céus, seus caminhos convergem, ligando-se e ressoando como os corações e pensamentos de espíritos afins com crenças semelhantes.",
  str_item_intro_6000503 = "Medalhão Stand By Me. Como constelações no céu noturno, seus aliados brilham com a luz da absoluta confiança e unidade. Os laços que os conectam representam a convergência de suas esperanças e ideias.",
  str_item_intro_6000601 = "Medalhão Stand By Me. Apesar de ser a primeira vez que você os vê, as sementes da compreensão já foram plantadas. Quatro mãos, interligadas na ponta dos dedos, representam a conexão entre dois corações.",
  str_item_intro_6000602 = "Medalhão Stand By Me. Apesar de todos esses anos passados no subsolo, a alegria de voar nunca foi esquecida. Embora esta seja apenas a primeira vez, é mais do que suficiente.",
  str_item_intro_6000603 = "Medalhão Stand By Me. O som de passos se aproximando não apenas denota perigo, mas a chegada da destruição total.",
  str_item_intro_6000604 = "Medalhão Stand By Me. Diante de inúmeros adversários, ele escolheu acabar com tudo com um rugido de fazer tremer a terra. Não foi um ato desesperado de sacrifício, mas uma estratégia calculada e intencional.",
  str_item_intro_6000605 = "Medalhão Stand By Me. Uma mensagem do seu povo! Mas que tipo de passado está por trás dessa voz suave?",
  str_item_intro_6000606 = "Medalhão Stand By Me. Eternamente residindo nos céus azuis acima, é o centro de toda a civilização e um símbolo da luz.",
  str_item_intro_6000607 = "Medalhão Stand By Me. \"O futuro não pertence à luz, mas às trevas.\" Naquele momento, seu sorriso se contorceu em algo selvagem... algo perverso. Embora seja das mesmas pessoas que você, ela se perdeu há muito tempo.",
  str_item_intro_6000608 = "Medalhão Stand By Me. O inimigo sorri orgulhosamente quando seus planos malignos se concretizam. No desespero mais sombrio, um dente-de-leão flutua em uma brisa suave. O que o futuro reserva para todos nós? Ou melhor... ainda há um futuro a ser visto?",
  str_item_intro_6000609 = "Medalhão Stand By Me. Há um ditado no Astra: \"As escolhas de alguém superam em muito seus esforços\". Muitos hesitam nas junções mais cruciais do destino; diante dessas decisões, eles só podem confiar em seus corações, em sua intuição e em seus amigos.",
  str_item_intro_6000610 = "Medalhão Stand By Me. Uma arma que transforma a luz em um poderoso feixe de energia é o domínio de Lumopolis e apenas Lumopolis. Embora tenha um preço alto, a ameaça iminente do inimigo deve ser evitada a todo custo.",
  str_item_intro_6000611 = "Medalhão Stand By Me. O Colossus preto foi derrotado, e tanto o mestre quanto a máquina caíram em um vale distante. No entanto, sua derrota não significa necessariamente sua morte...",
  str_item_intro_6000612 = "Medalhão Stand By Me. Aqueles que buscam o poder com intenção singular estão condenados a perecer por ele. Quando ela se lançou na escuridão, era seu destino encontrar seu fim na escuridão também.",
  str_item_intro_6000613 = "Medalhão Stand By Me. As linhas são a \"natureza\" expressa na matemática. A concha é um recipiente de moeda, e a continuidade não é necessariamente necessária.",
  str_item_intro_6000614 = "Medalhão Stand By Me. A dupla que uma vez lutou como camaradas em guerras agora seguiu caminhos separados devido a diferenças passadas.",
  str_item_intro_6000615 = "Medalhão Stand By Me. Ela caiu em um sono sem fim sob o Chord Link. Quando acordar, espere que ela libere grande poder.",
  str_item_intro_6000616 = "Medalhão Stand By Me. O Caelestite finalmente tem um lugar para chamar de lar sob o Obelisco do Retorno, mas sua presença também muda seu destino...",
  str_item_intro_6000617 = "Medalhão Stand By Me. Para explorar o território da Noite Eterna, os Cavaleiros de Lumopolis e os oficiais da Federação Illumina devem unir forças, porque os perigos ali são tudo menos comuns.",
  str_item_intro_6000618 = "Medalhão Stand By Me. Isso representa uma grande honra no exercício militar em que muitas forças participaram.",
  str_item_intro_6000619 = "Medalhão Stand By Me. O portão grosso bloqueia todos os intrusos no nível mais baixo da Cidade Baixa para proteger itens importantes e valiosos de ladrões e patifes.",
  str_item_intro_6000701 = "Medalhão Stand By Me. Este não é apenas o começo, mas uma chance de superar o resto. Aqueles que são ousados o suficiente para sempre dar o primeiro passo serão os que vencerão as adversidades e chegarão ao cume.",
  str_item_intro_6000702 = "Medalhão Stand By Me. Embora muitos obstáculos possam estar à frente, a luta continua a mesma, e nunca se deve parar de se esforçar para melhorar e alcançar maiores alturas. Poderia este ser o poder da Ascensão?",
  str_item_intro_6000703 = "Medalhão Stand By Me. Depois de atingir este pico, é fácil olhar para o mundo abaixo e descansar sobre os louros. Para os verdadeiramente ambiciosos, no entanto, essa satisfação é apenas um momento fugaz de alegria na jornada para alcançar as alturas finais...",
  str_item_intro_6000704 = "Medalhão Stand By Me. Aqueles que chegam ao topo são superiores a muitos dos desafiantes, mas a fome de conquista não pode ser saciada e os passos nunca param.",
  str_item_intro_6000705 = "Medalhão Stand By Me. O pico viu muitas batalhas;\nSomente no pico se conhecerá a dificuldade.\nO pico é reservado para os vencedores,\nSomente no pico se negligenciará o resto.",
  str_item_intro_6000706 = "Medalhão Stand By Me. Embora esta seja apenas a primeira vez, aqueles que conseguem isso são excepcionais e superiores a muitos.",
  str_item_intro_6000801 = "Medalhão Stand By Me. Confinamento surpreso, reencontro inesperado;\nno alto da jaula, aqueles que não querem ficar presos quebram as algemas.",
  str_item_intro_6000802 = "Medalhão Stand By Me. O que o gato deseja? Além de sua comida enlatada favorita, deve ser...",
  str_item_intro_6000803 = "Medalhão Stand By Me. É família para \"Holiday\" e a fez perceber que o café é sua casa e onde ela deveria ficar...",
  str_item_intro_6000804 = "Medalhão Stand By Me. O palácio está bem fechado em meio à neve e à geada, mas quando aquela figura esguia vier para a aurora, ele se abrirá.",
  str_item_intro_6000901 = "Medalhão Stand By Me. Fissuras se espalhavam como teias de aranha pelo chão, e todos os sinais apontavam para uma presença repugnante emergindo de baixo...",
  str_item_intro_6000902 = "Medalhão Stand By Me. A caverna está escura, exceto pela própria fonte de luz dos intrusos. Mas aqui não é sossego, pois muitos \"nativos\" aguardam...",
  str_item_intro_6000903 = "Medalhão Stand By Me. Existe um fim para isso? O pensamento frequentemente assombra a mente do explorador, embora o corajoso não tenha medo e se aventure mais uma vez.",
  str_item_intro_6001001 = "Medalhão Stand By Me. As imagens podem ser uma arma e as ilusões podem causar danos. Às vezes, olhos afiados são muito melhores do que braços sólidos.",
  str_item_intro_6001002 = "Medalhão Stand By Me. Deixe queimar! Testemunhe a chama destruir os infiéis!",
  str_item_intro_6001003 = "Medalhão Stand By Me. O alto chamado anuncia a presença do inimigo, e o silêncio marca sua morte e fim.",
  str_item_intro_6001004 = "Medalhão Stand By Me. O oponente ou o vazio é mais aterrorizante? Parece que a única maneira de vencê-lo é amarrá-lo e prendê-lo para sempre.",
  str_item_intro_6001005 = "Medalhão Stand By Me. Nenhum corpo mortal, apenas uma consciência pairando, embora só pudesse se dispersar na luz crescente.",
  str_item_intro_6001006 = "Medalhão Stand By Me. A injustiça do destino pode enlouquecer e transformar a escuridão. Nesse ponto, armas e lâminas são as únicas soluções contra isso.",
  str_item_intro_6001007 = "Medalhão Stand By Me. Quando confrontado com dor e raiva sem fim o tempo todo, terminar é o melhor presente.",
  str_item_intro_6001008 = "Medalhão Stand By Me. É o mais escuro antes da luz. Aguente, e você verá que o sol ilumina o caminho que você está seguindo.",
  str_item_intro_6001009 = "Medalhão Stand By Me. Vozes desencarnadas e ruídos insuportáveis entrelaçados para formar a dor e o pesadelo do inimigo.",
  str_item_intro_6001010 = "Medalhão Stand By Me. Alguém sem lar pode ser exilado? Talvez, mas muito poucos saberão sobre isso.",
  str_item_intro_6001011 = "Medalhão Stand By Me. A pedra carmesim originou-se de um alvo contaminado e, depois de se libertar, tornou-se a mais bela gema.",
  str_item_intro_6001012 = "Medalhão Stand By Me. Os mortais não têm valor, exceto suas almas, pelas quais os deuses lutam.",
  str_item_intro_6001013 = "Medalhão Stand By Me. Não cavaleiros de Lumopolis, mas seus inimigos de longa data. Seu disfarce foi quebrado - agora tudo o que resta é uma batalha até o fim.",
  str_item_intro_6001101 = "Medalhão Stand By Me. A cada virada de página, o texto maravilhoso inunda os olhos e estimula a mente como um sino agradável.",
  str_item_intro_6001102 = "Medalhão Stand By Me. Não é desrespeitoso sentar em um livro quando você aprendeu tudo nele.",
  str_item_intro_6001103 = "Medalhão Stand By Me. Usar livros como cama e travesseiro significa que também se pode desfrutar dos mundos que eles continham em seus sonhos.",
  str_item_intro_6001201 = "Medalhão Stand By Me. Os verdadeiros jardineiros cuidam de todas as mudas com as próprias mãos. Embora suas mãos e roupas estejam frequentemente sujas de suor e terra, ver cada muda atingir a maturidade e florescer com prosperidade é uma das maiores alegrias de sua vida.",
  str_item_intro_6001202 = "Medalhão Stand By Me. Quando essas plantas curiosas crescerem e preencherem o espaço com sua beleza natural, Cloud Gardens ficará muito mais diferente à luz do sol poente.",
  str_item_intro_6001203 = "Medalhão Stand By Me. Somente um mestre poderia pescar peixes raros como esses!",
  str_item_intro_6001204 = "Medalhão Stand By Me. Esta é uma grande ocasião para todos os pescadores, não só pelo festival em si, mas pela chegada de um certo mestre pescador.",
  str_item_intro_6001205 = "Medalhão Stand By Me. Sem perceber, você acumulou uma riqueza de conhecimento para construir novas estruturas. Em breve, o espaço vazio naquele vale não parecerá tão desolado.",
  str_item_intro_6001206 = "Medalhão Stand By Me. Depois de dominar a construção de tantas estruturas, você está pronto para transformar Cloud Gardens em uma cidade próspera a qualquer momento. Como o mestre de Cloud Gardens, esse dever cabe apenas a você.",
  str_item_intro_6001301 = "Medalhão Stand By Me. Elysium, um lugar com um passado lendário... Depois de despertar o herói há muito adormecido, que tipo de vínculo eles compartilharão?",
  str_item_intro_6001302 = "Medalhão Stand By Me. O juramento de dias passados ainda está intacto, e os inimigos daquela época ainda representam uma ameaça. Palavras nunca poderiam quebrar seu voto ou impedi-los de agir.",
  str_item_intro_6001400 = "Medalhão Stand By Me. A vida é como um jogo, e as aventuras em suas mãos são igualmente emocionantes. Aqueles que conseguirem superar etapas com condições tão difíceis certamente também terão sucesso na vida real.",
  str_item_intro_6001401 = "Medalhão Stand By Me. É fielmente narrado sem preconceito ou ocultação. Ele armazenou memórias para você ler os bons velhos tempos.",
  str_item_intro_6001402 = "Medalhão Stand By Me. Um palco flutuando no céu ressoa com canções de louvor que caem em todos os cantos do continente como bênçãos divinas. Entre sonhos e visões surgem os acordes do amor e da cura.",
  str_item_intro_6001403 = "Medalhão Stand By Me. Um aliado indispensável no oceano sem fim. Diz-se que não apenas guia os navios pelo caminho certo, mas também guia pelo labirinto do destino...",
  str_item_intro_6001404 = "Um Medalhão Stand By Me. É um dom, uma expressão do coração, uma forma de comunicação. Não há necessidade de palavras - simplesmente dar para o seu ente querido é o suficiente.",
  str_item_intro_6001405 = "Medalhão Stand By Me. Um buquê de flores reservado para um dia especial. Quando chega a hora marcada, eles desfilam em plena floração, enchendo o ar com a inebriante fragrância do amor. Respire fundo e aproveite este momento inestimável.",
  str_item_intro_6001406 = "Medalhão Stand By Me. Nunca saindo do lado do detetive, tudo o que um detetive precisa fazer é alcançá-lo e ele prestará seus serviços. Com isso, até as menores pistas podem ser descobertas.",
  str_item_intro_6001407 = "Medalhão Stand By Me. Lembranças do Dia da Família, ilusões fugazes no brilho de um cristal. Embora esses eventos ilusórios pertençam a um reino ilusório de pessoas e coisas ilusórias, tudo parece tão real, como se tivesse sido experimentado em primeira mão.",
  str_item_intro_6001408 = "Pessoas reais estão presas em um reino fabricado, que não pode ser quebrado pela força ou elas ficariam presas para sempre...",
  str_item_intro_6001409 = "Medalha Fique Comigo. Representa o eremita recluso no Vale Denuo, que espalha escamas iridescentes e partículas cintilantes enquanto dança elegantemente, lançando um feitiço de fascínio em todos que o contemplam...",
  str_item_intro_6001410 = "Medalhão Stand By Me. A vitória não vem apenas da guerra, mas também está profundamente enraizada na construção diária, crescimento e desenvolvimento contínuo.",
  str_item_intro_6002001 = "Medalhão Stand By Me. Um guardião de pessoas boas e mensageiro dos deuses realmente existe? Ou é apenas uma fantasia?",
  str_item_intro_6002002 = "Medalhão Stand By Me. Faça seus preparativos enquanto o sol ainda está brilhando. À luz do sol, nunca se esqueça da ameaça das trevas. Em tempos de paz, nunca esqueça que o inimigo pode estar sempre à espreita nas sombras próximas...",
  str_item_intro_6002003 = "Medalhão Stand By Me. Uma misteriosa besta lendária dos confins de Northland, diz-se que respira chamas do gelo mais frio e pode congelar uma aldeia inteira de uma só vez.",
  str_item_intro_6002004 = "Medalhão Stand By Me. Há um certo espelho em algum lugar do mundo, um que refletirá apenas o rosto do espectador e de mais ninguém. Essa reflexão, no entanto, é dita ter vida e mente próprias...",
  str_item_intro_6002005 = "Medalhão Stand By Me. Eles começaram como objetos comuns. Somente nas mãos dos sábios eles ganharão a consciência e a alma para completar sua missão.",
  str_item_intro_6002006 = "Medalhão Stand By Me. Se o aço é mais pesado que o ar, então por que ele pode voar? E se o ferro é mais pesado que a água, como pode ser usado para fazer navios? Diante de questões como essa, o conhecimento e a lógica lhe servirão melhor do que o \"bom senso\".",
  str_item_intro_6002007 = "Medalhão Stand By Me. Somente os deuses podem fazer o aço volumoso se mover como uma voz incorpórea.",
  str_item_intro_6002008 = "Medalhão Stand By Me. O deserto não tem limites. Por que alguém iria vagar aqui pode nunca ser conhecido. Ou essa poderia ser a única intenção, vagar.",
  str_item_intro_6002009 = "Medalhão Stand By Me. O prazer tem um preço, não importa quem você seja. Mesmo que esse preço não seja pago no início, será pago algum dia... E com juros.",
  str_item_intro_6002010 = "Medalhão Stand By Me. Gritos aterrorizantes, aplausos dos aliados... O fascínio da guerra não estava na conquista, estratégia ou coragem, mas na vitória e no fato de outro rei ter nascido.",
  str_item_intro_6002011 = "Medalhão Stand By Me. Uma concha de aço não é suficiente para transformar um homem comum em um lutador indestrutível. Você precisará de coordenação, flexibilidade e persistência.",
  str_item_intro_6002012 = "Medalhão Stand By Me. Poderia realmente existir uma garrafa sem dentro ou fora? Sem essa distinção, não haveria espaço e, portanto, nenhuma garrafa de que falar... Mas talvez o espaço seja infinito e não precise de distinção? De qualquer forma, tal objeto está no reino dos deuses e só poderia existir por meios divinos.",
  str_item_intro_6002013 = "Medalhão Stand By Me. Uma faixa de papel pode ter apenas um lado? A resposta está escondida dentro da própria tira; tudo o que se precisa fazer é vê-lo da maneira certa. Ao fazer isso, também se pode ver o mundo inteiro sob uma luz diferente...",
  str_item_intro_6002014 = "Medalhão Stand By Me. As coisas podem existir até nos menores espaços. Ao olhar para este mundo em uma garrafa, já lhe ocorreu que alguém pode estar fazendo o mesmo com o seu mundo também?",
  str_item_intro_6002015 = "Medalhão Stand By Me. Muitas lendas afirmam que todos os seres vivos nasceram da mesma árvore, uma noção que convida ao ridículo de várias pessoas. Ao pesquisar as origens de certas criaturas, no entanto, essas pessoas inevitavelmente começam a duvidar de suas declarações anteriores...",
  str_item_intro_6002016 = "Medalhão Stand By Me. Se uma única fileira de cordas pudesse produzir sons cintilantes, e se fosse uma fileira dupla? Embora isso também exija um músico com habilidade e força excepcionais.",
  str_item_intro_6002017 = "Medalhão Stand By Me. Suas rodas são seu corpo, então pisar é seu ataque primário. Ore para que você não tenha que enfrentar as lâminas rolantes em uma batalha.",
  str_item_intro_6002018 = "Medalhão Stand By Me. Se fortalezas pudessem um dia dominar a terra como o lendário gigante, elas seriam invencíveis.",
  str_item_intro_6002019 = "Medalhão Stand By Me. Quando os mortais pensam em \"nada\", eles emprestam-lhe uma espécie de existência. Sem forma, ele entra através de seus olhos, penetrando profundamente em suas mentes e criando um tipo diferente de \"nada\" dentro.",
  str_item_intro_6002020 = "Medalhão Stand By Me. Incansável, sem queixas... Isso descreveria as montarias para quem atravessa o deserto.",
  str_item_intro_6002021 = "Medalhão Stand By Me. Jogos de estratégia são apreciados em todo o mundo, e aqueles que ocupam altos cargos em suas sociedades tendem a ver o resto do mundo como um jogo de xadrez. No entanto, as \"peças\" neste jogo de xadrez são autoconscientes, assim como o próprio tabuleiro de xadrez. E assim, muitos desses jogos de xadrez estão destinados a serem totalmente destruídos, como foram ao longo da história.",
  str_item_intro_6002022 = "Medalhão Stand By Me. \"Caia na destruição eterna... Contemple o mundo mais uma vez, e deixe-o servir como sua memória final.\" Isto é o que as criaturas das trevas dizem a todos os seres vivos do mundo.",
  str_item_intro_6002023 = "Medalhão Stand By Me. Alegadamente, as posições das estrelas no céu representam o destino de um mortal, então os homens construíram torres imponentes para observar as estrelas e prever o futuro. Ironicamente, o futuro desta torre não podia ser previsto.",
  str_item_intro_6002024 = "Medalhão Stand By Me. Uma fera feroz com um corpo forte e movimentos rápidos. Mas o que realmente aterroriza as pessoas são seus espinhos de cauda astutos e venenosos.",
  str_item_intro_6002025 = "Medalhão Stand By Me. Como um mensageiro do inferno, veio a este mundo com ira. O submundo não é onde ele pertencia, mas o ciclo de morte e reencarnação.",
  str_item_intro_6001500 = "Medalhão Stand By Me.\nPaisagem sonora ampla, begônias em seu auge. Incline-se, ouça ecos como uma rima. Ventos do leste carregam o som das flores. Nos pavilhões, um momento sublime.",
  str_item_intro_6001507 = "Medalhão Stand By Me.\nEm Northland, alguns flocos de neve são recém-caídos e outros perduram por eras. A qual categoria pertence este medalhão que você segura?",
  str_item_intro_6001508 = "Medalhão Stand By Me.\nTodas as aventuras que tivemos serão valorizadas.",
  str_item_intro_6001510 = "Esta flor intocada é tão pura e bela.\nAssim como ela.",
  str_item_intro_6001511 = "Medalhão Stand By Me.\nCom sabedoria extraordinária, é possível construir navios para conectar terras distantes ou forjar armas para desencadear o caos. Nestes momentos, a verdadeira sabedoria reside nas escolhas de cada um.",
  str_item_intro_6000620 = "Medalhão Stand By Me.\nUm mecha colossal de combate forjado pela Illumina. Possui um exterior resistente e um poder de fogo formidável. Como sempre, as vulnerabilidades de tais gigantes geralmente estão escondidas sob a superfície...",
  str_item_intro_6000621 = "Medalhão Fique comigo. Uma torre que guarda a última linha de defesa, destruindo todos os inimigos que se aproximam.",
  str_item_intro_6001512 = "Medalhão Stand By Me. \nTodos o querem, mas nem todos podem suportar seu fardo.",
  str_item_intro_6001515 = "Medalhão Stand By Me. \nUma máquina que está cheia de perigos desconhecidos. Ninguém sabe por quanto tempo mais continuará a funcionar, e sempre faz sons assustadores de sibilo no meio da noite.",
  str_item_intro_6001516 = "Medalhão Stand By Me. \nAurorianos e demônios, como eles são diferentes? Ambos mastigam figuras de açúcar doce sob os fogos de artifício do Festival da Primavera, celebrando esta ocasião auspiciosa juntos.",
  str_item_intro_6001517 = "Medalhão Stand By Me.\nAlgol desenvolveu esta pulseira para monitorar dados de saúde como frequência cardíaca, pressão arterial e saturação de oxigênio no sangue em tempo real, e usa esses dados para desenvolver planos de fitness para o usuário.",
  str_item_intro_6001520 = "Medalhão Stand By Me. \nO dever dos guardiões carrega um peso pesado, mas eles o abraçam de bom grado, escolhendo ficar dentro da tempestade de neve.",
  str_item_intro_6001521 = "Um Medalhão Stand By Me. \nSacrifícios não devem ser feitos simplesmente por honra. \"Você pode ser heróis, mas são muito mais do que apenas isso.\"",
  str_item_intro_6001524 = "Medalhão Stand By Me.\n\"Isso foi divertido! Vamos de novo, vamos de novo!\"",
  str_item_intro_6001525 = "Medalhão Stand By Me. \nA inspiração inflamou em minha mente, tornando este um momento memorável para os livros de recordes.",
  str_item_intro_6001526 = "Medalhão Stand By Me.\n\"Esse poder não é só meu.\"",
  str_item_intro_6001529 = "Medalhão Stand By Me.\n\"Faz um tempo, meu contratante. Embora perigosa, essa jornada leva à verdade.\"",
  str_item_intro_6001530 = "Medalhão Stand By Me. \nEmbora o príncipe nunca tenha retornado, sua jornada pavimentou o caminho para a sobrevivência de seu povo. Não importa quanto tempo passe, seus corações sempre estarão unidos. Por causa disso, seus descendentes um dia, mais cedo ou mais tarde, se reunirão no continente.",
  str_item_intro_6001531 = "Medalhão Stand By Me. \nDisseram-lhe que o amor é como um belo sonho.",
  str_item_intro_6001532 = "Medalhão Stand By Me.\nÉ uma jornada difícil, mas no final, parece que você está apenas assistindo à felicidade dos outros se reunindo.\nAinda assim, por todos os seus esforços para ajudar as estrelas, como não poderíamos lhe dar nossa mais profunda gratidão?",
  str_item_6100001 = "Placa Comemorativa Stand By Me",
  str_item_6100002 = "Stand By Me Tabuleiro de Batalha",
  str_item_6100003 = "Fique Comigo Laje de Obsidiana",
  str_item_6100004 = "Stand By Me Machinery Board",
  str_item_intro_6100001 = "Placa comemorativa Stand By Me. Um quadro comemorativo adequado para Cloud Gardens, onde os medalhões Stand By Me podem ser exibidos.",
  str_item_intro_6100002 = "Placa comemorativa Stand By Me. Embora os visuais neste quadro evoquem um forte senso de guerra, isso não impediu ninguém de colocar suas medalhas nele.",
  str_item_intro_6100003 = "Placa comemorativa Stand By Me. Esta rocha de cor preta parece pertencer ao deserto. Quem o mudou para cá? Pelo menos as pequenas saliências são ótimas para manter as medalhas no lugar.",
  str_item_intro_6100004 = "Placa comemorativa Stand By Me. Este pano de fundo faz você se sentir como se estivesse em uma máquina gigante ou em uma fábrica, e você não consegue resistir ao desejo de organizar suas medalhas de maneira organizada. Mas organizá-los livremente também é uma possibilidade; talvez a espontaneidade parecesse especial?",
