  str_item_4090334 = "Memórias Sakura",
  str_item_intro_1400851 = "A Testemunha de Umbraton que possui neutralidade inabalável. Há muitos relatórios na mala que sempre carrega consigo. É conhecida como o Arquivo Móvel de Umbraton.",
  str_item_intro_3000220 = "Pontos de Ação: usados para desafiar estágios de evento especial. Recupera automaticamente com o tempo.",
  str_item_intro_3000221 = "Uma fruta visco rara. É considerada pelo povo de Northland como o símbolo da esperança e da abundância. Usada para trocar presentes no Mercado de Cedro.",
  str_item_intro_3000001 = "Um transporte de luz fabricado com uma técnica especial, essencial para qualquer tipo de expedição.",
  str_item_intro_3000002 = "Moedas emitidas por Lumópolis. Brilhantes e abundantes, elas são aceitas e negociadas por todo o continente.",
  str_item_intro_3000003 = "Gema obtida ao polir Lumocristais.\nPode ser usada para invocar Aurorianos, trocar por Flares Estelares Especiais e Flares Estelares, além de comprar Prismas.",
  str_item_intro_3000004 = "Conhecimento de ordens antigas e experiências de combate. Quanto maior o nível, melhor a conexão com a Colossus. Útil para saber mais sobre a Colossus.",
  str_item_intro_3000005 = "Vaga-lumes são recuperados automaticamente. A velocidade de recuperação é afetada por sua Sala Lúmina e pode ser aumentada por fundir Colossus\nPatches na Oficina. Esses construtos em miniatura são operados por comandos do controlador da Colossus e são responsáveis por manter e restaurar a\nintegridade estrutural da Colossus.",
  str_item_intro_3000006 = "Leitura mostrada no Luminômetro. Todos devem sair quando chegar a 0, ou o perigo é iminente.",
  str_item_intro_3000007 = "Fragmentos de tomos antigos encontrados no Território Secreto. Algumas agências se interessariam em comprá-los.",
  str_item_intro_3000008 = "Pontos ganhos ao completar Missões Diárias. Ganhe recompensas extras em certos níveis.",
  str_item_intro_3000009 = "Prova de Conquistas",
  str_item_intro_3000010 = "Aurorians ficarão próximos de você",
  str_item_intro_3000011 = "Dado Sagrado",
  str_item_intro_3000012 = "Uma estrutura especial encontrada na Estação de Recursos. Ele pode coletar todos os tipos de recursos para você.\n(Use-o durante a varredura consecutiva para reduzir a quantidade de prisma necessária para concluir os estágios e obter recursos imediatamente)",
  str_item_intro_3000013 = "Uma substância especial criada pela Oficina da Colossus. Supostamente, seu princípio de funcionamento veio de tecnologia antiga. Use-a para mudar a composição básica de certos itens, transformando-os em novos itens.",
  str_item_intro_3000014 = "Cristal natural impregnado com Lúmina.\nVocê pode usar Lumocristais na loja para comprar packs de presente e trajes Aurorian. Além disso, você pode converter Lumocristais em Lumâmbar para invocar Aurorians e restaurar Prisma.",
  str_item_intro_3000015 = "Joia transparente encontrada com a Pedra-Coração. Emite um brilho forte e pode ser trocada por itens preciosos na Loja de Joia Estelar.",
  str_item_intro_3000016 = "Joias Estelares de maior raridade. Extremamente valiosas, bem populares na Loja de Estrela.",
  str_item_intro_3000017 = "Os materiais necessários para abastecer as atividades da Colossus são distribuídos pela Sala Lúmina, que fornece a fonte de energia para a Colossus.",
  str_item_intro_3000018 = "Pedaços de pedra encontrados em várias partes dos Jardins das Nuvens que deveriam ser relíquias, mas sua função exata é desconhecida. Os Chubbs gostam dessas peças e trocam certas coisas por elas.",
  str_item_intro_3000019 = "Uma Gema Estelar muito rara que a maioria das pessoas não pode comprar. Só pode ser negociado na Loja Astral.",
  str_item_intro_3000021 = "Um disco de armazenamento criado pela ponte de Soroz e pelo simulador. O Navigator pode colocar suas memórias dentro para criar hologramas no disco de nuvem do Colossus.",
  str_item_intro_3000022 = "Uma madeira rara e preciosa que dizem vir de alguma planta exótica. É popular entre os escalões superiores da sociedade por causa de sua raridade e sua forma redonda e suave natural. Existe uma guilda especial em Umbraton que a compra e a usa como moeda em locais de nicho.",
  str_item_intro_3000025 = "Rumores de conter as palavras de The Forsaken, o artefato permanece indecifrado, deixando essas afirmações como mera especulação. Ainda assim, sua ótima condição o torna atraente para afiliações em busca da verdade interessadas em adquiri-lo.",
  str_item_intro_3000026 = "Rumores de conter as palavras de The Forsaken, o artefato permanece indecifrado, deixando essas afirmações como mera especulação. Seu estado fragmentado sugere que coletar várias peças pode ser necessário para atrair potenciais compradores.",
  str_item_intro_3000029 = "Marcador dourado obtido pelos elites que concluíram o Livro de Evento Especial.\nResgatável por recompensas na Loja do Livro de Eventos.",
  str_item_intro_3000030 = "Marcador obtido pelos jogadores que passaram pelo Livro de Evento Especial.\nResgatável por recompensas na Loja do Livro de Evento.",
  str_item_intro_3000031 = "Item obtido pelos jogadores que passaram pelo Livro de Eventos Especiais.\nResgatável por trajes normais na Loja do Livro de Eventos.",
  str_item_intro_3000032 = "Item obtido pelos jogadores que passaram pelo Livro de Eventos Especiais.\nResgatável por móveis Colossus na Loja do Livro de Eventos.",
  str_item_intro_3501001 = "Um item usado para refinar equipamentos.\nEssa substância misteriosa cria um vínculo mais forte entre um item e seu portador, mas deve ser armazenada em um recipiente especial para evitar que se disperse.",
  str_item_intro_3000100 = [[
Dispositivo capaz de emitir sinais de recrutamento.
Pode ser usado no recrutamento para obter Aurorianos.]],
  str_item_intro_3000101 = [[
Dispositivo capaz de emitir sinais especiais de recrutamento.
Pode ser usado em recrutamentos por tempo limitado para obter Aurorianos.]],
  str_item_intro_3000110 = "Item exclusivo de Recrutamento de Halloween. Permite recrutar dez vezes no conjunto de recrutamento especial de Halloween. Este é um item de tempo limitado que, finalizado o Recrutamento Especial de Halloween, será convertido em 3.000 Lumâmbar.",
  str_item_intro_3000112 = "Um item de recrutamento de Natal exclusivo permite que você realize Recrutamento ×10 do Pool de Recrutamento de Natal.\nEste é um item de tempo limitado e será convertido em Lumamber × 3.000 após o término do Recrutamento de Natal.",
  str_item_intro_3000113 = "Um item que pode ser usado no recrutamento exclusivo de parceria para recrutar 10 vezes.\nO item expirará, então use-o antes das 09:00 (UTC+0) de 26 de janeiro de 2022. Ele não será convertido em outro item quando expirar.",
  str_item_intro_3000114 = "Um item exclusivo que pode ser usado no recrutamento de collab para recrutar 10 vezes.\nUse este item por tempo limitado antes de 12 de fevereiro de 2022, 09:00 (UTC +0) ou ele desaparecerá. Ele não será convertido em outro item.",
  str_item_intro_3000343 = "Um item de recrutamento exclusivo de colaboração que pode ser usado no recrutamento de colaboração para recrutar 10 vezes.\nUse este item por tempo limitado antes das 09:00 de 7 de novembro de 2022 (UTC +0), 04:00 de 7 de novembro de 2022 (UTC -5) ou ele expirará. Ele não será convertido em outro item.",
  str_item_intro_3000115 = "Item exclusivo de Recrutamento Festivo Especial. Permite que você recrute dez vezes do pool especial de recrutamento festivo.\nUm item de tempo limitado, será convertido em 3.000 Lumamber no final do Recrutamento Festivo Especial.",
  str_item_intro_3000116 = "Pode ser usado no recrutamento exclusivo da Iluminação Iluminada para recrutar uma vez.\nEste item expirará, portanto, use-o antes do final do recrutamento exclusivo da Iluminação Iluminada, ou então ele desaparecerá. Ele não será convertido em outro item quando expirar.",
  str_item_intro_3000117 = "Pode ser usado no recrutamento exclusivo da Iluminação Iluminada para recrutar 10 vezes.\nEste item expirará, portanto, use-o antes do final do recrutamento exclusivo da Iluminação Iluminada, ou então ele desaparecerá. Ele não será convertido em outro item quando expirar.",
  str_item_intro_3000141 = "Pode ser usado para recrutar 10 vezes no recrutamento exclusivo da Iluminação Iluminada ou no recrutamento recomendado do Vigilante Solitário.\nEste item expirará, portanto, use-o antes que esses recrutamentos cheguem ao fim, caso contrário, ele desaparecerá. Ele não será convertido em outro item quando expirar.",
  str_item_3000142 = "Através de Fendas Fulgor Estelar Especial",
  str_item_3000143 = "Através de Fendas 10× Espírito de Recrutamento",
  str_item_intro_3000142 = "Pode ser usado para recrutar uma vez no recrutamento exclusivo Transcendent Emergence ou no recrutamento limitado Lonely Castle in the Mist.\nEste item irá expirar, então, por favor, use-o antes que esses recrutamentos cheguem ao fim, caso contrário ele irá desaparecer. Ele não será convertido em outro item quando expirar.",
  str_item_intro_3000143 = "Pode ser usado para recrutar 10 vezes no recrutamento exclusivo Transcendent Emergence ou no recrutamento limitado Lonely Castle in the Mist.\nEste item irá expirar, então, por favor, use-o antes que esses recrutamentos cheguem ao fim, caso contrário, ele desaparecerá. Ele não será convertido em outro item quando expirar.",
  str_item_3000145 = "Alquimista 10× Espírito de Recrutamento",
  str_item_intro_3000145 = "Pode ser usado para recrutar dez vezes dos recrutamentos exclusivos de colaboração do Alquimista Viajante ou Cadência do Comerciante.\nEste item irá expirar, então, por favor, use-o antes do final desses recrutamentos, ou então ele irá desaparecer. Ele não será convertido em outro item quando expirar.",
  str_item_intro_3000118 = "Um item de recrutamento exclusivo de colaboração que pode ser usado no recrutamento de colaboração para recrutar 10 vezes.\nUse este item por tempo limitado antes das 09:00 de 3 de agosto de 2022 (UTC +0) ou ele expirará. Ele não será convertido em outro item.",
  str_item_intro_3000119 = "Pode ser usado para recrutar uma vez do Queen do recrutamento exclusivo do Norte.\nEste item expirará, portanto, use-o antes do final do Queen do recrutamento exclusivo do Norte, senão desaparecerá. Ele não será convertido em outro item quando expirar.",
  str_item_intro_3000120 = "Pode ser usado para recrutar 10 vezes do Queen do recrutamento exclusivo do Norte.\nEste item expirará, portanto, use-o antes do final do Queen do recrutamento exclusivo do Norte, senão desaparecerá. Ele não será convertido em outro item quando expirar.",
  str_item_intro_3000121 = "Permite que você recrute dez vezes no Recrutamento Festivo do Vento de Verão.\nUm item de tempo limitado, ele será convertido em 3.000 Lumamber no final do Summer Wind Festive Recruitment.",
  str_item_3000146 = "Falcão Quebra-neve 10× Espírito de Recrutamento",
  str_item_intro_3000146 = "Permite que você recrute dez vezes no Recrutamento Especial Falcão Quebrando Neve.\nUm item de tempo limitado, será convertido em 3.000 Lumamber no final do Recrutamento Especial Falcão Quebrando Neve.",
  str_item_intro_3000122 = "Permite que você recrute dez vezes no Recrutamento Especial Winter Glaze.\nUm item de tempo limitado, será convertido em 3.000 Lumamber no final do Recrutamento Especial Winter Glaze.",
  str_item_intro_3000123 = "Pode ser usado para recrutar uma vez do atual recrutamento exclusivo da Rainha do Norte.\nEste item irá expirar, então, por favor, use-o antes do final do atual recrutamento exclusivo da Rainha do Norte, ou então ele desaparecerá. Não será convertido em outro item quando expirar.",
  str_item_intro_3000124 = "Este não é um livro de autógrafos comum porque contém o autógrafo de Goldie! Você terá uma conexão misteriosa com este ídolo apenas por possuir este livro!\nPode ser usado para recrutar uma vez no recrutamento exclusivo Lucky Star.\nEste item irá expirar, então, por favor, use-o antes do final do recrutamento exclusivo Lucky Star, ou então ele desaparecerá. Ele não será convertido em outro item quando expirar.",
  str_item_intro_3000125 = "Permite que você recrute dez vezes no Recrutamento Especial do Festival da Primavera.\nUm item de tempo limitado, será convertido em 3.000 Lumamber no final do Recrutamento Especial do Festival da Primavera.",
  str_item_intro_3000126 = "Permite que você recrute dez vezes no Recrutamento Especial do Esquadrão de Patrulha. Um item por tempo limitado, será convertido em 3.000 Lumamber no final do Recrutamento Especial do Esquadrão de Patrulha.",
  str_item_intro_3000127 = "Pode ser usado para recrutar uma vez no recrutamento exclusivo Lustrous Soul.\nEste item irá expirar, então, por favor, use-o antes do final do recrutamento exclusivo Lustrous Soul, ou então ele irá desaparecer. Ele não será convertido em outro item quando expirar.",
  str_item_intro_3000128 = "Pode ser usado para recrutar dez vezes do recrutamento exclusivo Lustrous Soul.\nEste item irá expirar, então, por favor, use-o antes do final do recrutamento exclusivo Lustrous Soul, ou então ele irá desaparecer. Ele não será convertido em outro item quando expirar.",
  str_item_intro_3000129 = "Permite que você recrute dez vezes na Recrutamento Especial da Feira.\nUm item por tempo limitado, será convertido em 3.000 Lumâmbar no final do Recrutamento Especial da Feira.",
  str_item_intro_3000133 = "Permite que você recrute dez vezes no Recrutamento Especial Ode de Inverno.\nUm item de tempo limitado, será convertido em 3.000 Lumamber no final do Recrutamento Especial Ode de Inverno.",
  str_item_intro_3000138 = "Permite que você recrute dez vezes do Recrutamento Festivo Especial.\nUm item de tempo limitado, será convertido em 3.000 Lumamber no final do Recrutamento Festivo Especial.",
  str_item_intro_3000201 = "Uma pequena insígnia feita por alguns membros da Rediesel Wrench ao modificar uma porca. Eles acreditam que a insígnia representa o reconhecimento do deserto, portanto só é emitida por aqueles aceitos pela Rediesel Wrench.",
  str_item_intro_3000211 = "Um vale-presente que pode ser trocado por presentes especiais na recepção do Hotel Tir'. Dizem que o selo nele é um retrato do Diretor Geral do hotel.",
  str_item_intro_3000212 = "Após concluir as missões no Livro do Evento Especial, você receberá uma quantidade de Pontos de Contribuição de Umbraton, que pode ser usados para desbloquear recompensas. Umbraton sempre sorri aos aventureiros sonhadores.",
  str_item_intro_3000213 = "Pontos de Ação: usados para desafiar certos estágios de eventos. Pontos de Ação são recuperados com o tempo.",
  str_item_intro_3000214 = "Comida especial enviada pela União Mensageira para complementar a energia de seus mensageiros. O sabor de cada embalagem é um mistério até que seja aberta... Talvez você possa experimentar um dia.",
  str_item_intro_3000215 = "Progresso de Reforma (sem detalhes no momento)",
  str_item_intro_3000217 = "Mérito: Uma manifestação física das conquistas militares de alguém, simbolizando a contribuição de um soldado para a Federação Illumina.",
  str_item_intro_3000219 = "Suporte a dor do combate e demonstre sua força com suor e sangue na Arena Sombria! Deixe seu glorioso nome ressoar em Umbraton!",
  str_item_intro_3000202 = "Item Eventual. Pode ser usado no evento de ilustração do Grande Daruma. Acumule certa quantidade para desbloquear a história exclusiva de Hiiro.\nEssa pétala de nuvescer caída é uma especialidade da Montanha Nebulosa. Moradores da Montanha Nebulosa acreditam que traz boa sorte.",
  str_item_intro_3000224 = "Item de evento Aurora Aeterna. Acumule uma certa quantidade para receber recompensas de Scala Gloriari.",
  str_item_intro_3000225 = "Item de Descanso da Aia Dragão usado para sorteio de prêmios na Cozinha de Tohru.\nA refeição quente está quase pronta, então pegue seu prato!",
  str_item_intro_3000226 = "Uma bebida que é incomum no Astra e revigora quem a bebe.",
  str_item_intro_3000227 = "Uma moeda de aparência antiga, muito diferente das moedas que vemos hoje.",
  str_item_intro_3000229 = "Um símbolo de honra para exploradores e aventureiros, geralmente é adquirido por meio de esforços extremamente árduos ou pela superação de grandes adversidades.",
  str_item_intro_3000236 = "Pontos recompensados por completar desafios. A quantidade obtida varia com cada nível de dificuldade.",
  str_item_intro_3000238 = "Durante o festival, Cloud Islanders escrevem palavras de bênçãos neste papel, desejando felicidade para o ano.",
  str_item_intro_3000239 = "Um grampo popular no Extremo Oriente, parece adorável e é fácil de transportar. Geralmente servido com acompanhamentos.",
  str_item_intro_3000240 = "Item exclusivo do Espelho dos Desejos da Silky Dreams. Permite que você faça um desejo em Silky Dreams' Wishing Mirror.\nEste é um item de tempo limitado. Depois que o Espelho dos Desejos dos Sonhos Sedosos terminar, este item será convertido em 100 Lumamber.",
  str_item_intro_3000241 = "Esta moeda de prata é a principal moeda na Cloud Island.",
  str_item_intro_3000242 = "Um cartão contendo registros do desempenho de cada competidor e com as assinaturas de cada funcionário do posto de controle.",
  str_item_intro_3000244 = "Ele tem um poder inexplicável que permite que aqueles presos dentro dele se movam livremente e até se libertem de suas amarras...",
  str_item_intro_3000245 = "O suposto produto de certos fragmentos de espírito na urdidura. Algumas pessoas estão particularmente interessadas neles.",
  str_item_intro_3000246 = "Informações obtidas após quantificação e avaliações totais. Ele pode ser usado para delinear um perímetro de pesquisa.",
  str_item_intro_3000247 = "Um sinal normal captado pelo detector portátil",
  str_item_intro_3000248 = "Um sinal especial captado pelo detector portátil",
  str_item_intro_3000253 = "O bilhete é emitido pela outrora poderosa Associação Andersen. Você pode trocá-lo por algo se encontrar alguém disposto a endossá-lo.",
  str_item_intro_3000256 = "Pontos necessários para atacar os esconderijos dos bandidos. Retire-os e continue avançando!",
  str_item_intro_3000258 = "Rabiscos de notícias, anedotas e fofocas. Se quiser conhecer toda a história, é só seguir as fotos e procurar por si mesmo.",
  str_item_intro_3000259 = "Na Harbour Fair todos os anos, Harbour City emite uma moeda especial, que pode ser usada no lugar de dinheiro na Street Fair, para todos os seus cidadãos.",
  str_item_intro_3000266 = "Um novo aquário! Tem todos os equipamentos e criaturas aquáticas que você pode imaginar, e nunca está muito cheio! Visite agora caso você perca!\nUm item exclusivo do Dia no Aquário que pode ser usado para fazer um pedido no aquário. Este é um item de tempo limitado. Quando o evento Day at the Aquarium terminar, este item será convertido em 100 Lumamber.",
  str_item_intro_3000267 = "Um sinal normal captado pelo detector portátil",
  str_item_intro_3000268 = "Um sinal especial captado pelo detector portátil",
  str_item_intro_3000270 = "De acordo com um mago, esses tipos de cartas de aparência simples têm poderes mágicos que permitem que ele se transforme em muitas coisas!\nObtido consumindo Prism e limpando o palco durante o evento.",
  str_item_intro_3000271 = "Cápsulas de balas vazias e reutilizáveis que podem ser trocadas no Depósito de Suprimentos por suprimentos.\nObtido usando o Prism para limpar os estágios durante o evento.",
  str_item_intro_3000275 = "Este ingresso não só lhe dará uma visão do último filme de um determinado ator famoso, mas também uma entrevista pessoal com ele!\nUm item exclusivo do evento Under the Spotlight que pode ser usado para fazer desejos. Este item de tempo limitado será convertido em 100 Lumamber quando o evento Sob os holofotes terminar.",
  str_item_intro_3000276 = "Adereços semelhantes a moedas feitos por Nina para adicionar à atmosfera medonha da casa mal-assombrada. Pode ser usado para trocar lembranças.",
  str_item_intro_3000278 = "Peças que foram espalhadas por todo o lugar. Talvez eles sirvam para alguma utilidade!\nObtido usando o Prisma para limpar fases durante o evento.",
  str_item_intro_3000280 = "Item exclusivo de repetição do Fluffy Serendipity. Olhe no espelho para fazer um desejo.\nEste é um item por tempo limitado. Quando a reprise Fluffy Serendipity - Wishing Mirror expirar, este item será convertido em 100 Lumamber.",
  str_item_intro_3000281 = "Anunciado como o trabalho de um diretor genial, a lenda diz que ele riu tanto assistindo seu filme completo pela primeira vez que morreu.",
  str_item_intro_3000282 = "Parece ser o roteiro de uma aventura de fantasia. Enquanto algumas partes são bastante românticas e imaginativas, outras são totalmente clichês.",
  str_item_intro_3000283 = "Este roteiro parece ser uma adaptação de uma história real. No entanto, como ninguém sabe o destino final do protagonista original, o final foi deixado inteiramente para a interpretação artística do escritor.",
  str_item_intro_3000284 = "Um roteiro que Jomu misteriosamente caiu em suas mãos. Ele mencionou algo sobre uma pesada compensação uma vez que \"tudo é dito e feito\".",
  str_item_intro_3000285 = "Um roteiro dado a você por Lilica. Acreditando que você tem potencial de direção, ela lhe confiou a tarefa de gravar um vídeo promocional para isso.",
  str_item_intro_3000286 = "Um roteiro dado a você por Vivian. Segundo ela, é a mais recente tentativa da Federação Illumina de reforçar seus esforços de recrutamento.",
  str_item_intro_3000288 = "Um caderno cheio de ideias que você e Bethlehem tiveram enquanto criavam um sonho.\nItem exclusivo Sweet Melody's Embrace. Necessário para fazer desejos durante o Abraço de Sweet Melody. Este é um item por tempo limitado. Quando Sweet Melody's Embrace chegar ao fim, este item será convertido em 100 Lumamber.",
  str_item_intro_3000291 = "Um registro de coisas descobertas durante sua jornada. Com isso, você poderá se lembrar de muitas informações importantes mesmo depois de voltar para casa.",
  str_item_intro_3000292 = "Como você poderia perder produtos exclusivos para o ídolo mais popular de todo o continente?! Os oportunistas definitivamente estarão procurando ganhar dinheiro rápido com fãs obstinados com mercadorias tão especiais.",
  str_item_intro_3000293 = "Um item tradicional do Norte. Na véspera do festival de inverno, as crianças penduram meias na cama e escrevem cartas dizendo o que mais desejam. Na manhã seguinte, os presentes que eles desejam aparecem em suas meias! Quanto a quem os coloca lá, quem sabe?",
  str_item_intro_3000294 = "Este cartão em branco parece ter algum tipo de poder mágico. A lenda diz que se você escrever seus desejos nele, eles se tornarão realidade. Embora seja difícil acreditar em uma afirmação tão ultrajante, quem iria torcer o nariz com a chance de receber tal bênção?",
  str_item_intro_3000297 = "Este roteiro recebido de uma pessoa anônima parece conter histórias emocionantes e românticas,\nmas a história nele parece familiar por algum motivo...",
  str_item_intro_3000298 = "Um roteiro adaptado de histórias que são contadas ao redor do mundo. Você encontrará histórias sobre todos os tipos de perigos e coisas sinistras aqui.",
  str_item_intro_3000299 = "Um dos livros de histórias mais populares em Cloud Island no momento. Você recebeu isso de uma pessoa misteriosa que atravessou o oceano.\nÀ primeira vista, parece ser uma história sobre luta de espadas e um apocalipse iminente...",
  str_item_intro_3000300 = "Um cheque da Lin Guild. Pode ser trocado por itens no The Docks, de acordo com o valor informado acima.",
  str_item_intro_3000307 = "Um fragmento de gesso de aparência peculiar que parece ter caído de uma estátua. Talvez haja algumas pistas...",
  str_item_intro_3000311 = "Diz a lenda que, se você brindar aos outros enquanto bebe deste copo majestoso, ficará sóbrio a noite toda.\nItem Hipnotizante Exclusivo Eventide. Use-o durante o evento para fazer um desejo! Este é um item por tempo limitado e será convertido em 100 Lumamber quando o evento Mesmerizing Eventide terminar.",
  str_item_intro_3000313 = "A moeda usada no Illumina Supply Center. É a única prova do transporte e implantação de suprimentos.",
  str_item_intro_3000321 = "Estes parecem ser fragmentos de algum cristal curioso, contendo gotas de água ainda mais curiosas.\nUso: Você pode comprar os itens que quiser na Sala de Adivinhação.\nFonte: Conclua os estágios da História Principal ou Raid de Recursos que requerem Prisma.",
  str_item_intro_3000326 = "Uma moeda que parece requintada, mas de alguma forma exala uma aura perigosa... Bem, a Sra. Rot disse que poderia ser trocada por algo, então deve estar tudo bem...\nFonte: Complete a Ms. Rot's Quest.",
  str_item_intro_3000330 = "Se uma flor amarrada por espinhos floresce ou não depende inteiramente da flor, não do que o mundo pensa dela. Item exclusivo do evento Blooming Firethorn. Pode ser usado para fazer um desejo durante o evento Blooming Firethorn. Este é um item por tempo limitado e será convertido em 100 Lumamber quando o evento Blooming Firethorn terminar.",
  str_item_intro_3000332 = "O trabalho se acumulou como montanhas enquanto se protegiam do assédio dos Eclipsitas e monitoravam os movimentos à frente... Tudo isso deixa Wrath: Orgulho Fervoroso sem escolha a não ser organizar meticulosamente a escassa mão de obra para uma reconstrução parcial de Crepúsculo.",
  str_item_intro_3000334 = "Reconhecimento de Barton em relação às táticas de Wrath",
  str_item_intro_3000335 = "Reconhecimento de Hiiro em relação às táticas de Wrath",
  str_item_intro_3000336 = "Reconhecimento de Vivian em relação às táticas de Wrath",
  str_item_intro_3000337 = "Reconhecimento de Sharona em relação às táticas de Wrath",
  str_item_intro_3000353 = "Seu desejo se tornará realidade um dia.",
  str_item_intro_3000354 = "Acumule um certo número de Casulos Divergentes e troque-os por presentes no Centro de Trocas.",
  str_item_intro_3000356 = "Incenso favorito no Reino Ji, meticulosamente projetado com uma fragrância delicadamente sutil.\n\"À medida que o incenso queima e envia fumaça para o céu, as pessoas enviam oferendas para o céu e a terra - Chen'ni entende essa prática cultural. Mas sempre há alguns dias por ano em que a fumaça é tão espessa que Chen'ni não consegue abrir os olhos...\"",
  str_item_intro_3000361 = "Seria necessário muito esforço apenas para coletar e ordenar os dados que foram bagunçados devido ao mau funcionamento.\nUm novo estágio de restauração de fotos é desbloqueado após um certo valor ser consumido.",
  str_item_intro_3000366 = "Um item essencial para fazer o pacto com Aurorians específicos.",
  str_item_intro_3000367 = "Um pirulito especial de Umbraton que muda aleatoriamente de sabor, proporcionando surpresas infinitas. Na escassez do deserto, o valor deste doce é tão bom quanto ouro.",
  str_item_intro_3000368 = "Um kit de suprimentos preparado para todos os Navegadores trabalhadores.\nTodos os seus esforços e crescimento serão registrados e recompensados.",
  str_item_intro_3000374 = "Uma ficha de jogo com aparência nostálgica e áspera ao toque. Diz-se que os melhores jogadores só precisam de uma ficha para jogar a noite toda.",
  str_item_intro_3000376 = "Pode ser trocado por vouchers de mercadorias diárias em Gannon City. Aqueles que fizeram contribuições especiais para Illumina também podem usá-los para solicitar itens personalizados personalizados.",
  str_item_intro_3000377 = "Conforme a lenda, o sangue do santo nunca flui em vão, mas permanece eterno, como âmbar. Oferecê-lo à verdade é como apresentar devoção ao Senhor.",
  str_item_intro_3000381 = "Acordando de um sonho grandioso, o orvalho condensado entre as folhas desaparece em um instante, assim como aquele belo sonho do qual você não consegue mais voltar. Ofereça-o ao dragão miragem no sonho pela possibilidade de receber uma recompensa.",
  str_item_intro_3000383 = "A magia de Windelion ganha vida com o papel colorido de Eraveil. Sua textura suave e durável é perfeita para criar decorações únicas ou bonecas Windelion. É um recipiente para memórias queridas e uma faísca para sonhos ainda por vir.",
  str_item_intro_3100001 = "Usado para subir o nível de Aurorians, +50% de EXP para Aurorians de Floresta. Jaspe Verde. Medite para relembrar memórias de batalha e ganhar pouco EXP.",
  str_item_intro_3100002 = "Usado para subir o nível de Aurorians, +50% de EXP para Aurorians de Floresta.\nJaspe verde valioso. Use-o para repensar as cenas de batalhas e ganhar EXP moderado.",
  str_item_intro_3100003 = "Usado para subir o nível de Aurorians, +50% de EXP para Aurorians de Floresta. Jaspe verde muito valioso. Use-o para reviver uma batalha e ganhar muito EXP.",
  str_item_intro_3100004 = "Usado para subir o nível de Aurorians, +50% de EXP para Aurorians de Água. Jaspe Azul. Medite para relembrar memórias de batalha e ganhar pouco EXP.",
  str_item_intro_3100005 = "Usado para subir o nível de Aurorians, +50% de EXP para Aurorians de Água. Jaspe Azul valioso. Use-o para repensar cenas de batalhas e ganhar EXP moderado.",
  str_item_intro_3100006 = "Usado para subir o nível de Aurorians, +50% de EXP para Aurorians de Água. Jaspe Azul muito valioso. Use-o para reviver uma batalha e ganhar muito EXP.",
  str_item_intro_3100007 = "Usado para subir o nível de Aurorians, +50% de EXP para Aurorians de Trovão. Jaspe Amarelo. Medite para relembrar memórias de batalha e ganhar pouco EXP.",
  str_item_intro_3100008 = "Usado para subir o nível de Aurorians, +50% de EXP para Aurorians de Trovão. Jaspe Amarelo valioso. Use-o para repensar cenas de batalhas e ganhar EXP moderado.",
  str_item_intro_3100009 = "Usado para subir o nível de Aurorians, +50% de EXP para Aurorians de Trovão. Jaspe Amarelo muito valioso. Use-o para reviver uma batalha e ganhar muito EXP.",
  str_item_intro_3100010 = "Usado para subir o nível de Aurorians, +50% de EXP para Aurorians de Fogo. Jaspe Vermelho. Medite para relembrar memórias de batalha e ganhar pouco EXP.",
  str_item_intro_3100011 = "Usado para subir o nível de Aurorians, +50% de EXP para Aurorians de Fogo. Jaspe Vermelho valioso. Use-o para repensar cenas de batalhas e ganhar EXP moderado.",
  str_item_intro_3100012 = "Usado para subir o nível de Aurorians, +50% de EXP para Aurorians de Fogo. Jaspe Vermelho muito valioso. Use-o para reviver uma batalha e ganhar muito EXP.",
  str_item_intro_3100013 = "Usado para subir o nível de Aurorians.\nJaspe Branco com energia especial. Aurorians podem usá-lo para ganhar pouco EXP.",
  str_item_intro_3100014 = "Usado para subir o nível de Aurorians.\nJaspe Branco valioso. Aurorians podem usá-lo para repensar cenas de batalhas e ganhar EXP moderado.",
  str_item_intro_3100015 = "Usado para subir o nível de Aurorians.\nJaspe Branco muito raro. Aurorians podem usá-lo para reviver uma batalha e ganhar muito EXP.",
  str_item_intro_3210101 = "Um material básico de ascensão, usado para a ascensão de Aurorians de Lumópolis.\nMantido na Academia Matinal de Lumópolis e melhorado com uma magia única, pode aumentar o poder de Aurorians.",
  str_item_intro_3210201 = "Um material básico de ascensão, usado para a ascensão de Aurorians de Umbraton.\nLibação especial na moda em Umbraton. Forte e suave, pode aumentar o poder do bebedor.",
  str_item_intro_3210301 = "Um material básico de ascensão, usado para a ascensão de Aurorians de Northland.\nOrvalho de Pinha condensado que absorveu os elementos únicos de Northland para conceder poder aos cidadãos de Northland.",
  str_item_intro_3210401 = "Um material básico de ascensão, usado para a ascensão de Aurorians de Rediesel Wrench.\nRediesel especial com um sabor tão pungente que apenas membros fortes da Rediesel Wrench ousam provar.",
  str_item_intro_3210501 = "Um material básico de ascensão, usado para a ascensão de Aurorians da Federação Illumina.\nUm Arquivo de Batalha da Federação Illumina que melhora o combate do leitor.",
  str_item_intro_3210601 = "Um material básico de ascensão, usado para a ascensão de Aurorians da True Order.\nPergaminhos com conhecimento antigo. Membros da True Order podem se aprimorar ao decifrá-los.",
  str_item_intro_3210701 = "Um material básico de ascensão, usado para a ascensão de Aurorians Independentes.\nHistórias de várias pessoas com passados diferentes e com um jargão confuso. Leitores Independentes aprenderão diversos truques de sobrevivência.",
  str_item_intro_3210801 = "Um material básico de ascensão, usado para a ascensão de Aurorians de Longzhou.\nProduzido pela Farmácia Longzhou, esta pílula superior aumenta a força física e fortalece ossos e músculos.",
  str_item_intro_3210102 = "Um material normal de ascensão, usado para a ascensão de Aurorians de Lumópolis.\nMantido na Academia Matinal de Lumópolis, dizem que pode ser criado a partir do poder da luz matinal e aumentar muito o poder de Aurorians.",
  str_item_intro_3210202 = "Um material normal de ascensão, usado para a ascensão de Aurorians de Umbraton.\nVersão refinada do Refresco do Destino I. Mais forte e suave, para um aproveitamento ainda maior de poder.",
  str_item_intro_3210302 = "Um material normal de ascensão, usado para a ascensão de Aurorians de Northland.\nGeada de Pinha condensada incomum. Uma das fontes cruciais de magia de Northland.",
  str_item_intro_3210402 = "Um material de ascensão comum que é usado para a ascensão dos Aurorians da Rediesel Wrench. \nNormalmente encontrado no coração do Deserto Rediesel, aprimora as habilidades de luta dos membros da Rediesel Wrench.",
  str_item_intro_3210502 = "Um material normal de ascensão, usado para a ascensão de Aurorians da Federação Illumina.\nUm Arquivo de Batalha da Federação Illumina. Reúne informações que podem melhorar muito o combate do leitor.",
  str_item_intro_3210602 = "Um material normal de ascensão, usado para a ascensão de Aurorians da True Order.\nUm livro contendo conhecimento antigo importante. Membros da True Order podem se aprimorar muito ao decifrá-lo.",
  str_item_intro_3210702 = "Um material normal de ascensão, usado para a ascensão de Aurorians Independentes.\nDicas de várias pessoas com passados diferentes, para leitores de Independent usarem.",
  str_item_intro_3210802 = "Um material normal de ascensão, usado para a ascensão de Aurorians de Longzhou.\nEsta pílula é refinada por cultivadores de Longzhou com materiais espirituais e dizem ter o efeito de limpar a medula do corpo.",
  str_item_intro_3210103 = "Um material avançado de ascensão, usado para a ascensão de Aurorians de Lumópolis.\nMantido na Academia Matinal de Lumópolis e melhorado com uma magia única, pode aumentar o poder de Aurorians para outro nível.",
  str_item_intro_3210203 = "Um material avançado de ascensão, usado para a ascensão de Aurorians de Umbraton.\nA melhor versão do Refresco do Destino I, com um sabor inacreditável, para um reforço enorme de poder.",
  str_item_intro_3210303 = "Um material avançado de ascensão, usado para a ascensão de Aurorians de Northland.\nSupostamente o cristal de orvalho perfeito. Chamado de \"Lágrima de Northland\", fornece uma energia mágica formidável aos de Northland.",
  str_item_intro_3210403 = "Material de ascensão avançado usado para a ascensão dos Aurorians da Rediesel Wrench.\nO rediesel mais puro em forma semilíquida. Apenas os membros mais fortes da Rediesel Wrench se aproximariam.",
  str_item_intro_3210503 = "Um material avançado de ascensão, usado para a ascensão de Aurorians da Federação Illumina.\nUm Arquivo de Batalha da Federação Illumina com muitos detalhes, que podem aumentar o combate do leitor para outro nível.",
  str_item_intro_3210603 = "Um material avançado de ascensão, usado para a ascensão de Aurorians da True Order.\nUm tomo detalhando o conhecimento antigo. Membros da True Order podem melhorar muito ao decifrá-lo.",
  str_item_intro_3210703 = "Um material avançado de ascensão, usado para a ascensão de Aurorians Independentes.\nRelatos e sabedoria detalhados de várias pessoas de passados diferentes para garantir excelência na sobrevivência.",
  str_item_intro_3210803 = "Um material avançado de ascensão, usado para a ascensão de Aurorians de Longzhou.\nA essência do céu e da terra foi infundida nesta pílula pelos mestres secretos de Longzhou, concedendo-lhe o poder de reconstruir seus corpos, alcançar um avanço e aumentar significativamente sua cultivação.",
  str_item_intro_3201011 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Água.\nUm pó brilhante encontrado no solo, próximo à água. Uma das matérias-primas de processamento industrial em grande escala.",
  str_item_intro_3201012 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Água.\nPartículas brilhantes de cristal azul.",
  str_item_intro_3201013 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Água.\nUm pó branco e puro, refinado por uma Luminática especial.",
  str_item_intro_3201014 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Água.\nUma substância misteriosa transformada em pedra pelo mar, com uma textura frágil e muitos poros.",
  str_item_intro_3201021 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Fogo.\nUm pó brilhante encontrado perto de áreas geotermais ativas. Uma das matérias-primas de processamento industrial em grande escala.",
  str_item_intro_3201022 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Fogo.\nPartículas ardentes de cristal vermelho.",
  str_item_intro_3201023 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Fogo.\nUm pó vermelho mágico, refinado por uma Luminática especial.",
  str_item_intro_3201024 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Fogo.\nUma substância misteriosa feita com rochas moídas sob altas temperaturas e forjadas em fogo constante.",
  str_item_intro_3201031 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Floresta.\nUm pó brilhante encontrado na litosfera. Uma das matérias-primas de processamento industrial em grande escala.",
  str_item_intro_3201032 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Floresta.\nPartículas brilhantes de cristal verde.",
  str_item_intro_3201033 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Floresta.\nUm pó verde-esmeralda mágico, refinado por uma Luminática especial.",
  str_item_intro_3201034 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Floresta.\nUma substância misteriosa convertida de plantas mortas antigas.",
  str_item_intro_3201041 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Trovão.\nUm pó radiante extremamente condutivo, com diversas aplicações industriais, cujo processamento posterior é necessário.",
  str_item_intro_3201042 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Trovão.\nPartículas raras de cristal com lampejos dourados ocasionais.",
  str_item_intro_3201043 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Trovão.\nUm pó dourado mágico, refinado por uma Luminática especial.",
  str_item_intro_3201044 = "Um material básico de ascensão, necessário para a ascensão de Aurorians de Trovão.\nUma rocha misteriosa normalmente coletada de locais atingidos por relâmpago. É dito que possui o poder do trovão.",
  str_item_intro_3202011 = "Um material normal de ascensão, necessário para a ascensão de Aurorians de Água.\nPó de Hidrofulgor processado e purificado. Subproduto primário da produção industrial.",
  str_item_intro_3202012 = "Um material normal de ascensão, necessário para a ascensão de Aurorians de Água.\nPedaços brilhantes raros de cristal azul.",
  str_item_intro_3202013 = "Um material normal, necessário para a ascensão de Aurorians de Água.\nSolução de Essência de Água e solvente especial.",
  str_item_intro_3202014 = "Um material normal de ascensão, necessário para a ascensão de Aurorians de Água.\nSubstância semilíquida destilada de minério em água salgada.",
