  str_item_intro_3202022 = "Um material normal de ascensão, necessário para a ascensão de Aurorians de Fogo.\nPedaços ardentes de cristal vermelho.",
  str_item_intro_3202023 = "Um material normal, necessário para a ascensão de Aurorians de Fogo.\nSolução de Essência de Fogo e solvente especial.",
  str_item_intro_3202024 = "Um material normal de ascensão, necessário para a ascensão de Aurorians de Fogo.\nMaterial especial obtido por uma chama intensa.",
  str_item_intro_3202031 = "Um material normal de ascensão, necessário para a ascensão de Aurorians de Floresta.\nPó de Arbofulgor processado e purificado. Semiproduto primário da produção industrial.",
  str_item_intro_3202032 = "Um material normal de ascensão, necessário para a ascensão de Aurorians de Floresta.\nPedaços brilhantes de cristal verde.",
  str_item_intro_3202033 = "Um material normal, necessário para a ascensão de Aurorians de Floresta.\nSolução de Essência de Floresta e solvente especial.",
  str_item_intro_3202034 = "Um material normal de ascensão, necessário para a ascensão de Aurorians de Floresta.\nAmálgama convertida de diversos extratos de planta e cassiteritas.",
  str_item_intro_3202041 = "Um material normal de ascensão, necessário para a ascensão de Aurorians de Trovão.\nPó de Eletrofulgor processado e purificado. Semiproduto primário da produção industrial.",
  str_item_intro_3202042 = "Um material normal de ascensão, necessário para a ascensão de Aurorians de Trovão.\nPartículas raras de cristal com lampejos roxos ocasionais.",
  str_item_intro_3202043 = "Um material normal, necessário para a ascensão de Aurorians de Trovão.\nSolução de Essência de Floresta e solvente especial.",
  str_item_intro_3202044 = "Um material normal de ascensão, necessário para a ascensão de Aurorians de Trovão.\nMaterial especial obtido de rochas atingidas por raios.",
  str_item_intro_3203011 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Água.\nXisto obtido por processamento complexo de Silte de Hidrofulgor. Um semiproduto industrial padrão.",
  str_item_intro_3203012 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Água.\nCristal azul valioso, transparente, rígido e raro.",
