  str_item_intro_3203021 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Fogo.\nXisto obtido por processamento complexo de Silte de Ignifulgor. Um semiproduto industrial padrão.",
  str_item_intro_3203022 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Fogo.\nCristal vermelho valioso com uma radiância ardente.",
