  str_item_intro_3203033 = "Um material avançado, necessário para a ascensão de Aurorians de Floresta.\nUma poção valiosa feita de compostos de Poção de Floresta I.",
  str_item_intro_3203034 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Floresta.\nUma liga verde extraída de um grande grupo de plantas.",
  str_item_intro_3203041 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Trovão.\nXisto obtido por processamento complexo de Silte de Eletrofulgor. Um semiproduto industrial padrão.",
  str_item_intro_3203042 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Trovão.\nCristal dourado brilhante, valioso.",
  str_item_intro_3203043 = "Um material avançado, necessário para a ascensão de Aurorians de Trovão.\nUma poção valiosa feita de compostos de Poção de Trovão I, após destilação e filtração.",
  str_item_intro_3203044 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Trovão.\nFragmentos de rochas ao serem atingidos por um raio.",
  str_item_intro_3204011 = "Um material especial de ascensão, necessário para a ascensão de Aurorians de Água.\nComposto metálico de Rocha de Hidrofulgor processada e outras substâncias. Produto industrial especial.",
  str_item_intro_3204012 = "Um material especial de ascensão, necessário para a ascensão de Aurorians de Água.\nAgregado de cristais azuis raros.",
  str_item_intro_3204013 = "Um material especial, necessário para a ascensão de Aurorians de Água.\nPoção de Água II concentrada que aumenta muito a força de um Aurorian.",
  str_item_intro_3204014 = "Um material especial de ascensão, necessário para a ascensão de Aurorians de Água.\nUm objeto mágico poderoso feito de magia desconhecida, água de mar profundo e mercúrio líquido.",
  str_item_intro_3204021 = "Um material especial de ascensão, necessário para a ascensão de Aurorians de Fogo.\nComposto metálico de Rocha de Ignifulgor processada e outras substâncias. Produto industrial especial.",
  str_item_intro_3204022 = "Um material especial de ascensão, necessário para a ascensão de Aurorians de Fogo.\nAgregado de cristais rubros raros.",
  str_item_intro_3204023 = "Um material especial, necessário para a ascensão de Aurorians de Água.\nPoção de Fogo II concentrada que aumenta muito a força de um Aurorian.",
  str_item_intro_3204024 = "Um material especial de ascensão, necessário para a ascensão de Aurorians de Fogo.\nUma liga de grande poder, forjada e refinada da erupção de um vulcão.",
  str_item_intro_3204031 = "Um material especial de ascensão, necessário para a ascensão de Aurorians de Floresta.\nComposto metálico de Rocha de Arbofulgor processada e outras substâncias. Produto industrial especial.",
  str_item_intro_3204032 = "Um material especial de ascensão, necessário para a ascensão de Aurorians de Floresta.\nAgregado de cristais verdes raros.",
  str_item_intro_3204033 = "Um material especial, necessário para a ascensão de Aurorians de Floresta.\nPoção de Floresta II concentrada que aumenta muito a força de um Aurorian.",
  str_item_intro_3204034 = "Um material especial de ascensão, necessário para a ascensão de Aurorians de Floresta.\nUm objeto de grande poder, condensado de plantas raras e um mercúrio verde especial.",
  str_item_intro_3204041 = "Um material especial de ascensão, necessário para a ascensão de Aurorians de Trovão.\nComposto metálico de Rocha de Eletrofulgor processada e outras substâncias. Produto industrial especial.",
  str_item_intro_3204042 = "Um material especial de ascensão, necessário para a ascensão de Aurorians de Trovão.\nAgregado de cristais dourados raros.",
  str_item_intro_3204043 = "Um material especial, necessário para a ascensão de Aurorians de Trovão.\nPoção de Trovão II concentrada que aumenta muito a força de um Aurorian.",
  str_item_intro_3204044 = "Um material especial de ascensão, necessário para a ascensão de Aurorians de Trovão.\nUm material mágico feito de mercúrio infundido com raios. Perigoso, volátil e poderoso.",
  str_item_intro_3205011 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Água.\nComposto metálico de Casas de Hidrofulgor e outras substâncias. Produto industrial de maior nível.",
  str_item_intro_3205012 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Água.\nUma joia rara, criada por vários cristais azuis infundidos com Lúmina.",
  str_item_intro_3205013 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Água.\nUm produto refinado de Poção de Água III que aumenta significativamente a força de um Aurorian.",
  str_item_intro_3205014 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Água.\nUm objeto duro feito de água de mar profundo. Belo, macio e extremamente caro.",
  str_item_intro_3205021 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Fogo.\nComposto metálico de Casas de Ignifulgor e outras substâncias. Produto industrial de maior nível.",
  str_item_intro_3205022 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Fogo.\nUma joia rara, criada por vários cristais rubros infundidos com Lúmina.",
  str_item_intro_3205023 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Fogo.\nUm produto refinado de Poção de Fogo III que aumenta significativamente a força de um Aurorian.",
  str_item_intro_3205024 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Fogo.\nUma pepita de prata avermelhada, forjada a partir de rochas vulcânicas em fogo intenso. Extremamente caro.",
  str_item_intro_3205031 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Floresta.\nComposto metálico de Casas de Arbofulgor e outras substâncias. Produto industrial de maior nível.",
  str_item_intro_3205032 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Floresta.\nUma joia rara, criada por vários cristais verdes infundidos com Lúmina.",
  str_item_intro_3205033 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Floresta.\nUm produto refinado de Poção de Floresta III que aumenta significativamente a força de um Aurorian.",
  str_item_intro_3205034 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Floresta.\nUma pepita de prata criada ao quebrar e refinar sementes de plantas raras, usando um método secreto. Extremamente caro.",
  str_item_intro_3205041 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Trovão.\nComposto metálico de Casas de Eletrofulgor e outras substâncias. Produto industrial de maior nível.",
  str_item_intro_3205042 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Trovão.\nUma joia rara, criada por vários cristais amarelos infundidos com Lúmina.",
  str_item_intro_3205043 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Trovão.\nUm produto refinado de Poção de Trovão III que aumenta significativamente a força de um Aurorian.",
  str_item_intro_3205044 = "Um material avançado de ascensão, necessário para a ascensão de Aurorians de Trovão.\nUm material mágico obtido ao infundir prata com corrente elétrica. Incrivelmente duro e contém o poder do trovão.",
  str_item_intro_3220000 = "Serve a um propósito especial no Avanço de Aurorian.\nUma joia rara com energia desconhecida, que concede poderes especiais nas mãos de certos Aurorians, cujos potenciais podem ser desbloqueados ao dominá-la.",
  str_item_intro_3220001 = "Objeto essencial de Avanço para Nikinis.\nUma joia única que remete a um espelho. Um exame minucioso revela o reflexo de uma jovem mulher de branco.",
  str_item_intro_3220002 = "Objeto essencial de Avanço para Hiiro.\nEssa joia preciosa mostra a imagem de um dragão vermelho cereja, ocasionalmente.",
  str_item_intro_3220004 = "Objeto essencial de Avanço para Kuma & Pengy.\nEssa joia dá arrepios quando Kuma e Pengy a usam, por isso é a favorita deles.",
  str_item_intro_3220005 = "Objeto essencial de Avanço para Mia.\nEssa joia parece ter aprisionado o outro lado de Mia... Talvez ela ofereça um vislumbre de quem ela realmente é.",
  str_item_intro_3220006 = "Objeto essencial de Avanço para Carleen.\nEssa joia ocasionalmente brilha com um contorno sombrio e pálido de um feixe ofuscante.",
  str_item_intro_3220009 = "Objeto essencial de Avanço para Faust.\nUma joia com padrões estranhos e distorcidos que inspiram pânico, mas Faust não se afasta, ao invés disso é atraído por ela.",
  str_item_intro_3220010 = "Objeto essencial de Avanço para Louise.\nUma joia distinta, brilhante que supostamente inspirou Louise Carlisle a escrever incontáveis histórias.",
  str_item_intro_3220011 = "Objeto essencial de Avanço para Sharona.\nOlhe de perto para ver o contorno borrado de um dragão gigantesco flutuando.",
  str_item_intro_3220012 = "Objeto essencial de Avanço para Nemesis.\nUm joia dura perfeitamente cortada e com um poder incrível.",
  str_item_intro_3220013 = "Objeto essencial de Avanço para Noah.\nExtremamente frio ao toque sem causar queimaduras ou qualquer dano. Favorito de Noah.",
  str_item_intro_3220014 = "Objeto essencial de Avanço para Schwartz.\nUma gema com brilho intenso. Schwartz sente que ela não apenas o representa, mas toda Lumópolis.",
  str_item_intro_3220015 = "Hachi e Gin podem ver muitos locais diferentes dentro dessa joia e extrair uma inspiração artística extraordinária dela.\nObjeto de avanço essencial para Hachi e Gin.",
  str_item_intro_3220016 = "Objeto essencial de Avanço para Kafka.\nUma joia extremamente dura, que dizem ter protegido alguém de um ataque letal.",
  str_item_intro_3220017 = "Objeto essencial de Avanço para Rabbie.\nUma análise minuciosa revela uma chama saltitando, lembrando um coelho. Amuleto da sorte de Rabbie.",
  str_item_intro_3220018 = "Objeto essencial de Avanço para Regina.\nUma joia parecida com o sol, que ilumina até os cantos mais escuros, assim como eleva o nível da música de Regina.",
  str_item_intro_3220019 = "Objeto essencial de Avanço para Victoria.\nEssa joia contém inúmeras partículas em forma de lágrima, supostamente do próprio sangue de Victoria.",
  str_item_intro_3220021 = "Objeto essencial de Avanço para Jola.\nQuando Jola encosta nessa joia, ondas verdes acorrentadas dançam na borda.",
  str_item_intro_3220023 = "Objeto essencial de Avanço para Connolly.\nA condensação de uma gota preta que se transforma em uma joia firme na mão de Connolly.",
  str_item_intro_3220024 = "Objeto essencial de Avanço para Benny e Kuro.\nEssa joia lampeja com uma luz vermelha e preta, e você pode até ouvir o som de espadas cortando e balas, se chegar perto.",
  str_item_intro_3220025 = "Objeto essencial de Avanço para Charon.\nA favorita de Charon, essa joia brilha com listras vermelhas e pretas.",
  str_item_intro_3220026 = "Objeto essencial de Avanço para Uriel.\nJoia com lampejos ocasionais de chamas castanhas e pretas. Muito bonita de ver, mas também niilista.",
  str_item_intro_3220027 = "Objeto essencial de Avanço para Michele.\nSupostamente descoberta em uma tempestade severa, essa joia concede a seu dono um grande poder.",
  str_item_intro_3220028 = "Objeto essencial de Avanço para Raphaela.\nJoia transparente com um poder surpreendente. Quando Raphaela a usa, sua habilidade de cura é melhorada.",
  str_item_intro_3220029 = "Objeto essencial de Avanço para Gabriela.\nEssa joia emite um belo brilho verde quando Gabriela a ativa.",
  str_item_intro_3220030 = "Objeto essencial de Avanço para Sinsa.\nEssa joia emite um calor intenso a todo momento. Apenas Sinsa pode usá-la.",
  str_item_intro_3220033 = "Objeto essencial de Avanço para Vice.\nEssa joia mostra centelhas lindas de cores diferentes, cada lampejo como se fosse trecho do passado.",
  str_item_intro_3220036 = "Objeto essencial de Avanço para Hydrad.\nUma joia sinistra. Hydrad, entretanto, não tem medo dela e normalmente se gaba: \"Assim como eu\".",
  str_item_intro_3220038 = "Objeto essencial de Avanço para Gronru.\nDizem que contém diversos elementos artificiais, provavelmente não é um produto da natureza, e sim, um vestígio de uma civilização antiga.",
  str_item_intro_3220040 = "Objeto essencial de Avanço para Joanie Boom.\nMelhor não mexer com essa joia inflamável, por segurança.",
  str_item_intro_3220041 = "Objeto essencial de Avanço para Srta. Blanc.\nUma joia com um brilho elegante e relaxante de se ver. Combina perfeitamente com uma moça elegante.",
  str_item_intro_3220042 = "Objeto essencial de Avanço para Barton.\nEssa joia camufla chamas vermelhas de guerra que apenas Barton pode ver. Ou talvez a manifestação de seu desejo mais profundo.",
  str_item_intro_3220044 = "Objeto essencial de Avanço para Vivian.\nUm joia com brilho intenso. Um acessório fantástico para o punho de uma espada.",
  str_item_intro_3220045 = "Objeto essencial de Avanço para Nails.\nUma certa pessoa chamou a aresta incrivelmente afiada dessa joia de representação de punição...",
  str_item_intro_3220046 = "Objeto essencial de Avanço para Keating.\nMuitos \"poemas\" aparecem nas mentes de membros de Keating quando usam essa joia.",
  str_item_intro_3220048 = "Objeto essencial de Avanço para Dayna.\nDayna pode aprender habilidades de luta com essa joia.",
  str_item_intro_3220054 = "Objeto essencial de Avanço para Nadine.\nUma joia branca que emite um brilho suave e relaxante.",
  str_item_intro_3220055 = "Pittman se perde diversas vezes no caminho da verdade, mas este cristal lhe traz força e determinação.\nObjeto essencial de Avanço para Pittman.",
  str_item_intro_3220056 = "Objeto essencial de Avanço para Constantine.\nEssa joia registra tudo automaticamente quando Constantine caça Eclipsitas e é a melhor parceira de Constantine.",
  str_item_intro_3220057 = "Objeto essencial de Avanço para Philyshy.\nEsse cristal, às vezes, solta um sopro de escuridão para que a verdadeira natureza de Philyshy possa ser vista de perto.",
  str_item_intro_3220060 = "Objeto essencial de Avanço para Jona.\nA base de bronze derretida desse cristal é forjada das balas de Jona e mostra seus feitos passados.",
  str_item_intro_3220061 = "Objeto essencial de Avanço para Chandra.\nAo analisar com cuidado, no interior dessa joia transparente há um turbilhão dançante de energia, como se contivesse várias emoções que ela coletou.",
  str_item_intro_3220062 = "Objeto essencial de Avanço para Sylva.\nDizem que essa joia foi encontrada nas profundezas da Floresta Barlavento. Ela é fria ao toque e representa Sylva, Protetor da Floresta.",
  str_item_intro_3220064 = "Objeto essencial de Avanço para Wrath.\nEssa grande joia fica leve na mão de Wrath, o suficiente para flutuar no ar...",
  str_item_intro_3220065 = "Quando Tweety olha para esse cristal, ela pode ver a vaga imagem de sua cidade natal, Montanha Nebulosa...\nObjeto essencial de Avanço para Tweety.",
  str_item_intro_3220067 = "Objeto essencial de Avanço para Alice.\nEssa joia assume a forma de um coração e exala uma vitalidade especial quando Alice a segura.",
  str_item_intro_3220068 = "Objeto essencial de Avanço para Wendy.\nEssa joia extremamente leve também é resistente, espelhando a personalidade de Wendy.",
  str_item_intro_3220070 = "Objeto essencial de Avanço para Leona.\nEncare esse cristal e ouça o rugido trovejante de um dragão em seus ouvidos.",
  str_item_intro_3220071 = "Objeto essencial de Avanço para Taki.\nA cena de um dragão gigante cuspidor de fogo aparece, ocasionalmente, nessa joia. Simboliza Taki, uma vez que essa joia pertence apenas a ele.",
  str_item_intro_3220073 = "Objeto essencial de Avanço para Patty & Patsy.\nEssa joia alterna entre brilhos carmesins e sensações de escuridão.",
  str_item_intro_3220075 = "Objeto essencial de Avanço para Odi.\nVocê pode ouvir uma estática fraca ao colocar essa joia em sua orelha. Talvez ela seja usada para comunicação.",
  str_item_intro_3220076 = "Objeto essencial de Avanço para Kleken.\nUma joia linda que mostra diferentes tons em diferentes ângulos. Ela muda ainda mais na mão de Kleken.",
  str_item_intro_3220077 = "Objeto essencial de Avanço para Bethlehem.\nClara e extremamente fria ao toque. Supostamente evoluiu do primeiro bloco de gelo na história, e apenas a Rainha do Norte pode usá-la.",
  str_item_intro_3220078 = "Objeto essencial de Avanço para Robyn.\nUma joia verde-esmeralda que dizem afastar todas as coisas tóxicas do usuário. Talismã de Robyn.",
  str_item_intro_3220079 = "Objeto essencial de Avanço para Michenny.\nUma joia impecavelmente quadrada e equilibrada, perfeita para manter o equilíbrio de balanças.",
  str_item_intro_3220081 = "Objeto essencial de Avanço para Brock.\nEssa joia é bem quente ao toque, refletindo o vigor perpétuo de alguém.",
  str_item_intro_3220083 = "Objeto essencial de Avanço para Lilliam.\nQuando essa joia se aproxima de seu mestre real, ela exibe padrões elétricos.",
  str_item_intro_3220084 = "Objeto essencial de Avanço para Istvan.\nChamas azuis dançam ocasionalmente nas bordas dessa joia. Se você se aproximar, quase pode ouvir ela chamar pelo Senhor Sombrio.",
  str_item_intro_3220085 = "Objeto essencial de Avanço para Jane.\nEncare essa joia preta por bastante tempo e talvez você veja escritas registradas...",
  str_item_intro_3220086 = "Objeto essencial de Avanço para Uriah.\nEssa jade branca elegante está na forma de uma flor.",
  str_item_intro_3220087 = "Objeto essencial de Avanço para Beverly.\nUm raio em forma de lança. Parece a Lança Relâmpago de Beverly que tremula de vez em quando.",
  str_item_intro_3220088 = "Objeto essencial de Avanço para Maggie.\nÀs vezes, esse cristal reluz com um brilho amarelo estranho. Examine-o de perto para ver a silhueta de uma garota.",
  str_item_intro_3220089 = "Objeto essencial de Avanço para Irridon.\nEssa joia reluz com um raio azul e contém um grande poder.",
  str_item_intro_3220090 = "Objeto essencial de Avanço para Barbara.\nAproxime-se dessa joia com uma base rubra e você pode ouvir canções barulhentas tocando.",
  str_item_intro_3220091 = "Objeto essencial de Avanço para Chloe.\nEsse cristal branco parece formar condensações em forma de lágrima. Aproxime-se e você pode ouvir uma harpa tocando.",
  str_item_intro_3220092 = "Objeto essencial de Avanço para Pact.\nEssa joia é incrivelmente dura e, supostamente, nunca sofre um arranhão.",
  str_item_intro_3220093 = "Objeto essencial de Avanço para Migard.\nEssa joia possui uma energia misteriosa, parece que foi extraída de uma criatura artificial.",
  str_item_intro_3220095 = "Objeto essencial de Avanço para Lester.\nSe você cheirar essa joia, sentirá como se estivesse na natureza. Lester é capaz de usar isso para encontrar o odor de seu gosto.",
  str_item_intro_3220096 = "Objeto essencial de Avanço para Sariel.\nQuando Sariel segura essa joia, ela assume a forma de uma gota d'água. Essa joia também concede um imenso poder a Sariel.",
  str_item_intro_3220097 = "Objeto essencial de Avanço para Corax.\nEssa joia é fria como o gelo e possui bordas extremamente afiadas. Pode ser usada ao invés de facas.",
  str_item_intro_3220098 = "Objeto essencial de Avanço para Cuscuta.\nSe você inspecionar essa joia com cuidado, verá uma flor preta e seca dentro dela.",
  str_item_intro_3220099 = "Objeto essencial de Avanço para Areia.\nA maldição afetando Areia parece enfraquecer quando ela olha para essa joia...",
  str_item_intro_3220100 = "Objeto essencial de Avanço para Sikare.\nUm céu estrelado está oculto nessa joia. Alguns dizem que é a verdadeira fonte do poder de Sikare.",
  str_item_intro_3220101 = "Objeto essencial de Avanço para Ansia.\nIsso possui um lindo lustre de bronze e vibra gentilmente. A vibração é muito parecida com a frequência sonora de uma certa faixa...",
  str_item_intro_3220102 = "Objeto essencial de Avanço para Tessa.\nUm raio esporádico tremula dentro dessa joia a todo momento e explode se alguém se aproximar. Apenas Tessa pode segurá-lo.",
  str_item_intro_3220103 = "Objeto essencial de Avanço para Eicy.\nSe encarar essa joia, verá um raio assustador sendo projetado...",
  str_item_intro_3220104 = "Objeto essencial de Avanço para Dawn.\nEssa joia pertence a Dawn porque reflete a sombra de uma flor branca quando ela a segura, além de a flor ser seu sustento espiritual.",
  str_item_intro_3220105 = "Objeto essencial de Avanço para Eve.\nPequenos arcos de relâmpago aparecem em volta dessa joia quando Eve a toca. Este é o poder especial de Eve.",
  str_item_intro_3220107 = "Solâmbar de Regal",
  str_item_intro_3220108 = "Solâmbar de Frostfire",
  str_item_intro_3220109 = "Solâmbar de Mythos",
  str_item_intro_3220110 = "Solâmbar de Réquiem",
  str_item_intro_3220111 = "Objeto essencial de Avanço para Beryl.\nEste cristal se torna vermelho feito sangue ao ser segurado por Beryl, tornando-se idêntico aos cristais no corpo dela.",
  str_item_intro_3220112 = "Objeto essencial de Avanço para Smokey.\nEsta joia sempre parece fazer objetos inflamáveis queimarem inexplicavelmente. Este poder peculiar só cessa quando a joia está nas mãos de Smokey.",
  str_item_intro_3220113 = "Objeto essencial de Avanço para Bonacie.\nQuando Bonacie toca esta joia, um fluxo de inspiração enche sua mente, e a ajuda a pensar em movimentos novos e inesquecíveis.",
  str_item_intro_3220114 = "Objeto essencial de Avanço para Genevieve.\nSempre vermelha brilhante, como uma chama ardente, às vezes esta joia relincha...",
  str_item_intro_3220115 = "Quando ela usa este cristal, Naroxel pode ouvir a voz da natureza com perfeita clareza, melhorando sua habilidade de se comunicar com animais e plantas.\nObjeto essencial de Avanço para Naroxel.",
  str_item_intro_3220116 = "Objeto essencial de Avanço para Fleur.\nEsta joia pode dar a Fleur muitas inspirações de planta, fazendo seu \"Plano de Produção de Robôs\" estar ainda mais perto da realização.",
  str_item_intro_3220117 = "Quando Gram segura isso em sua mão, ele se sente novamente naqueles dias com as Forças de Pedra, e seu coração se enche de emoção.\nObjeto essencial de Avanço para Gram.",
  str_item_intro_3220119 = "Quando Revy toca essa gema, você pode ouvir o som de sua lâmina gigante passando contra as correntes e pode sentir erupções crescentes de eletricidade.\nObjeto essencial de Avanço para Revy.",
  str_item_intro_3220120 = "Sob a luz do sol, essa joia irradia um brilho semelhante a uma gloriosa armadura branca.\nObjeto de Avanço essencial para Hedy.",
  str_item_intro_3220121 = "Às vezes, essa joia mostra a figura de uma jovem de cabelos curtos que Paloma não reconhece mais...\nObjeto essencial de Avanço para Paloma.",
  str_item_intro_3220122 = "Quando Allura coloca essa gema em seu ouvido, ela pode ouvir o som de um relógio, permitindo que exerça maestria sobre o tempo com mais precisão.\nObjeto essencial de Avanço para Allura.",
  str_item_intro_3220123 = "Com essa joia, Cordy pode lidar facilmente com qualquer emergência.\nObjeto de Avanço essencial para Cordy.",
  str_item_intro_3220126 = "Este cristal pode ser colocado na gema na frente do peito de Bethel e realça seu brilho.\nObjeto essencial de Avanço para Bethel.",
  str_item_intro_3220127 = "Objeto essencial de Avanço para Pasolo.\nNas mãos de Pasolo, este cristal fica extremamente fino e leve e flutua pelo ar como um papel voando.",
  str_item_intro_3220129 = "Este cristal é tão leve que Luke pode até fazê-lo flutuar no ar e dançar como uma borboleta.\nObjeto essencial de Avanço para Luke.",
  str_item_intro_3220131 = "A superfície da joia é esculpida com palavras arcaicas, e parece que só Novio entende seu significado.\nObjeto essencial de Avanço para Novio.",
  str_item_intro_3220132 = "Uma joia encharcada com mel, com brilho e aroma doce.\nObjeto essencial de Avanço para Lola.",
  str_item_intro_3220133 = "Uma joia que irrompe em um brilho incandescente sempre que alguém chega perto, exceto para Kobayashi, mudando para um rosa suave. Objeto essencial de Avanço para Tohru.",
  str_item_intro_3220134 = "Uma joia emitindo raios de vez em quando. É inesperadamente macia quando a segura.\nObjeto essencial de Avanço para Kanna.",
  str_item_intro_3220135 = "Uma corrente quente flui através desta joia constantemente. As mentes mais calmas podem ouvir o som de um córrego borbulhante.\nObjeto essencial de Avanço para Elma.",
  str_item_intro_3220136 = "Olhe fixamente e você verá coisas como o céu, oceano, montanhas, rios, cidades e finalmente um estranhos par de olhos olhando pra trás.\nObjeto essencial de Avanço para Lucoa.",
  str_item_intro_3220137 = "Você pode ouvir rugidos nefastos nesta joia, com os encantamentos inaudíveis de Fafnir entre eles.\nObjeto essencial de Avanço para Fafnir.",
  str_item_intro_3220138 = "Parece que você pode ver fios verdes quando Siobhan está segurando...\nObjeto Breakthrough essencial para Siobhan.",
  str_item_intro_3220139 = "Coloque esta gema contra seu ouvido e ouça com atenção, você poderá ouvir os sons de uma entidade desconhecida sendo convocada.\nObjeto Breakthrough essencial para Erica.",
  str_item_intro_3220140 = "Uma gema cuidadosamente esfregada com uma mistura de fragrância de pergaminho e tinta. Você quase podia ouvir o zumbido da leitura e das orações.\nObjeto Breakthrough essencial para Florine.",
  str_item_intro_3220141 = "Uma gema muito dura que emitia um som nítido quando atingida por um morcego. Excelente para a prática de swing de Ruby.\nEssencial para o avanço de Ruby.",
  str_item_intro_3220142 = "Uma jóia de aparência comum que poderia produzir uma ilusão de chamas furiosas sob o toque suave de Rouge.\nObjeto Breakthrough essencial para Rouge.",
  str_item_intro_3220143 = "Uma gema que ocasionalmente brilha em rosa pálido e faz um som refrescante e delicioso quando agitada suavemente.\nObjeto Breakthrough essencial para Rinne.",
  str_item_intro_3220144 = "Uma joia de aparência simples que é fria ao toque e emite uma pequena luz no escuro.\nObjeto Breakthrough essencial para Kayano.",
  str_item_intro_3220145 = "Nas mãos de Amemori, esta gema fica mais leve, ocasionalmente emitindo a palavra \"paciência.\"\nObjeto essencial de Avanço para Amemori.",
  str_item_intro_3220146 = "Esta joia cheira levemente a comida recém-cozida e, de perto, parece até brilhar em um peculiar vermelho ardente.\nObjeto Breakthrough essencial para Yao.",
  str_item_intro_3220147 = "Uma joia colorida que parece ter um sabor muito bom se fosse comestível. Após uma inspeção cuidadosa, duas luzes semelhantes, mas não idênticas, podem ser vistas nela.\nObjeto Breakthrough essencial para Momo&Anzu.",
  str_item_intro_3220148 = "A pedra é fria ao toque e emite um leve brilho azul quando iluminada pela luz do sol.\nObjeto de descoberta essencial para o Azure.",
  str_item_intro_3220149 = "Uma pedra levemente texturizada e aparentemente inócua. Ocasionalmente, uma figura de cabelos prateados aparece em sua superfície e, antes que você possa ver quem é, Roy esconde a pedra. Bem, de qualquer forma, ele é muito alto para alguém tirar isso dele.\nObjeto Breakthrough essencial para Roy.",
  str_item_intro_3220150 = "Por alguma razão, esta gema range o tempo todo como uma marionete sendo enrolada.\nObjeto Breakthrough essencial para Lenore.",
  str_item_intro_3220151 = "Esta jóia é dura e escaldante. O toque de Giles pode transformá-lo magicamente em um chifre de carneiro.\nUm item essencial para o avanço de Giles.",
  str_item_intro_3220152 = "A pegada de May pode gerar uma imagem de um gato na superfície desta gema. Às vezes, a silhueta de um auroriano aparece, mas ninguém pode dizer quem é.\nUm item essencial para o avanço de maio.",
  str_item_intro_3220153 = "Polido à mão por um dos joalheiros mais respeitados da Illumina, apenas aqueles que estão no comando da Federação Illumina podem empunhá-lo.\nObjeto Breakthrough essencial para Reinhardt.",
  str_item_intro_3220154 = "Em qualquer momento Vice está próximo, a gema começa a vibrar levemente, emitindo alternadamente um brilho vermelho e verde.\nObjeto Breakthrough essencial para Vice: Keen Sight.",
  str_item_intro_3220187 = "Uma pedra preciosa levemente pegajosa emite um aroma doce e delicado que pode ser detectado à medida que alguém se aproxima dela. Li Tianxian sempre exibe um sorriso satisfeito toda vez que a usa. Talvez seja na verdade uma barra de chocolate?\nObjeto Breakthrough essencial para Li Tianxian.",
  str_item_intro_3220188 = "Esta joia possui uma textura sedosa e uma delicada fragrância floral. Ao observá-la mais de perto, você encontrará seus intrincados padrões que formam uma flor de begônia.\nObjeto essencial de Avanço para Dantang.",
  str_item_intro_3221000 = "Pode ser resgatado por Aurorian Solamber exclusivo.",
  str_item_intro_3221001 = "Pode ser resgatado por Solamber Auroriano da Floresta de 5 Estrelas não exclusivo.",
  str_item_intro_3221002 = "Pode ser resgatado por Solamber Auroriano da Trovão de 5 Estrelas não exclusivo.",
  str_item_intro_3221003 = "Pode ser resgatado por Solamber Auroriano da Fogo de 5 Estrelas não exclusivo.",
  str_item_intro_3221004 = "Pode ser resgatado por Solamber Auroriano da Água de 5 Estrelas não exclusivo.",
  str_item_intro_3221005 = "Pode ser resgatado por Solamber Auroriano da Floresta de 6 Estrelas não exclusivo.",
  str_item_intro_3221006 = "Pode ser resgatado por Solamber Auroriano da Trovão de 6 Estrelas não exclusivo.",
  str_item_intro_3221007 = "Pode ser resgatado por Solamber Auroriano da Fogo de 6 Estrelas não exclusivo.",
  str_item_intro_3221008 = "Pode ser resgatado por Solamber Auroriano da Água de 6 Estrelas não exclusivo.",
  str_item_intro_5840001 = "O pacote de sementes de Árvore Única mais comum para cultivar as Árvores Únicas mais comuns.",
  str_item_intro_5840002 = "Um Pacote de Sementes de Árvore Única II para o cultivo de Árvores Únicas II com pequenas mutações.",
  str_item_intro_5840003 = "Um Pacote de Sementes de Árvore Única III para o cultivo de Árvores Únicas III com mutações frequentes.",
  str_item_intro_5840004 = "Um Unique Tree Seedpack IV para o cultivo de Unique Trees IV com mutações complexas.",
  str_item_intro_3220155 = "Uma gema dura e pesada. De vez em quando, uma enorme sombra negra pode ser vista piscando através dela, acompanhada pelo que parece ser o rosnado de uma fera feroz.\nObjeto Breakthrough essencial para Barton: Deft Blades.",
  str_item_intro_3220156 = "Uma jóia rara. Dê uma olhada e você notará seu brilho constantemente flutuante, como um sinal de uma vontade inflexível.\nEssencial para a descoberta de Nina.",
  str_item_intro_3220157 = "Uma joia composta de um material tão resistente que não desmorona, não importa o quanto você a deixe cair. Como nós sabemos? Bem, você terá que perguntar a Sanae.\nEssencial para a descoberta de Sanae.",
  str_item_intro_3220158 = "Uma necessidade para o avanço do Joker.\nUma jóia com um brilho brilhante.\nTem um forte senso de rebelião.",
  str_item_intro_3220159 = "Uma necessidade para o avanço do Queen.\nUma jóia que é completamente translúcida.\nTem um forte senso de rebelião.",
  str_item_intro_3220160 = "Uma necessidade para o avanço da Fox.\nUma jóia que é quente ao toque.\nTem um forte senso de rebelião.",
  str_item_intro_3220161 = "Uma necessidade para a descoberta de Violet.\nUma jóia em forma de flor.\nTem um forte senso de rebelião.",
  str_item_intro_3220162 = "Uma necessidade para a descoberta de Mona.\nUma gema com arranhões aparentemente feitos por garras afiadas.\nTem um forte senso de rebelião.",
  str_item_intro_3220164 = "À primeira vista, esta gema parece estar cheia de vapor que se transforma em chamas instantaneamente, mas independentemente das mudanças que ocorram dentro dessa pedra preciosa, sua robustez permanece inabalável.\nObjeto Breakthrough essencial para Carleen: Smoldering Soul.",
  str_item_intro_3220165 = "Quando Ciel olha atentamente para este cristal, ela sente que pode ver algumas fórmulas misteriosas que lhe trazem um fluxo constante de inspiração.\nObjeto Breakthrough essencial para Ciel.",
  str_item_intro_3220166 = "Esta gema vibra violentamente quando há bestas maravilhosas por perto.\nObjeto Breakthrough essencial para Fia.",
  str_item_intro_3220167 = "Esta jóia mágica cria ilusões de si mesma... Tenha cuidado e não se deixe enganar.\nObjeto Breakthrough essencial para Jeno.",
  str_item_intro_3220168 = "Esta jóia é fria ao toque. O som das ondas pode ser ouvido dentro dele às vezes.\nObjeto Breakthrough essencial para Rainbow.",
  str_item_intro_3220169 = "Sempre que segura essa pedra preciosa, Sadie sente uma enorme sensação de coragem fluindo da palma da mão para o resto do corpo. Até mesmo seu batimento cardíaco muda de acordo!\nObjeto Breakthrough essencial para Sadie.",
  str_item_intro_3220170 = "Uma jóia com um forte aroma defumado. O que é mais surpreendente é a ocasional imagem trêmula de uma lâmina em sua superfície.\nObjeto Breakthrough essencial para Pollux.",
  str_item_intro_3220171 = "Ao ouvir de perto esta jóia maravilhosa, você pode ouvir os grasnar de um corvo vindo de dentro.\nObjeto Breakthrough essencial para Casta.",
  str_item_intro_3220172 = "Se você olhar com cuidado, esta pedra preciosa pisca e pisca como os maiores momentos da história cinematográfica. Com ele, as habilidades de Lilica podem atingir patamares ainda mais novos!\nObjeto Breakthrough essencial para Lilica.",
  str_item_intro_3220173 = "Quando Minos dispara sua arma, a imagem de um minotauro furioso parece aparecer sob a superfície desta pedra preciosa.\nObjeto Breakthrough essencial para Minos.",
  str_item_intro_3220175 = "Uma joia coberta de cicatrizes. Você pode sentir suas bordas e cantos afiados quando está ao seu alcance, mas se você continuar segurando e nunca soltar, suas mãos serão aquecidas por um calor inexplicável.\nObjeto inovador essencial para Axelia.",
  str_item_intro_3220176 = "Uma joia que brilha vibrantemente com uma miríade de cores. Ela brilha intensamente mesmo sem ser polida, e a silhueta de um pássaro voando pode ser vista dentro da gema de vez em quando.\nObjeto inovador essencial para Beretta.",
  str_item_intro_3220177 = "Esta joia colorida parece incrivelmente quente. Se você carregá-lo por muito tempo, pode até compartilhar a boa sorte de Goldie.\nObjeto inovador essencial para Goldie.",
  str_item_intro_3220178 = "Esta joia é tão dura que, mesmo que você batesse nela o mais forte que pudesse com um martelo gigante, não deixaria um arranhão.\nObjeto inovador essencial para Vic.",
  str_item_intro_3220180 = "Parece sólido, mas salta para trás se você pressioná-lo. Brandy aparentemente usa isso para treinar a velocidade de seu dedo do obturador.\nObjeto inovador essencial para Brandy.",
  str_item_intro_3220181 = "O calor desta pedra em sua mão é a prova do coração apaixonado de Zhong Xu.\nObjeto inovador essencial para Zhong Xu.",
  str_item_intro_3220182 = "A cor desta pedra fina e resistente muda de acordo com o ângulo de luz que incide sobre ela.\nObjeto inovador essencial para Mu Yuebai.",
  str_item_intro_3220183 = "Esta pedra preciosa exala uma leve fragrância de ervas com um sabor levemente amargo e cheira como o boticário de Liqing.\nObjeto inovador essencial para Liqing.",
  str_item_intro_3220184 = "Tem uma sensação desgastada e envelhecida, mas ao mesmo tempo é muito brilhante e bonito.\nObjeto inovador essencial para Jeriah.",
  str_item_intro_3220185 = "Suave ao toque, parece que Kya o acaricia com frequência. Após uma inspeção mais detalhada, parece haver um mostrador em movimento dentro... isso é um relógio?\nObjeto inovador essencial para Kya.",
  str_item_intro_3220186 = "A luz pura e sagrada que envolve esta joia dá às pessoas a sensação de que irão manchar seu brilho ao tocá-la.\nObjeto inovador essencial para Tina.",
  str_item_intro_3220189 = "Duro ao toque, esta pedra reflete uma luz deslumbrante sob o sol. Se você cheirá-lo com cuidado, poderá detectar um toque de fragrância floral nele.\nObjeto inovador essencial para Leyn.",
  str_item_intro_3220190 = "Uma pedra preciosa requintadamente polida cortada com excelente habilidade. De qualquer forma, parece muito caro, então vamos guardá-lo com cuidado.\nObjeto inovador essencial para Matthieu.",
  str_item_intro_3220191 = "Embora pareça muito duro, é inesperadamente macio e flexível ao toque, como a pata de um cachorro. Você simplesmente não consegue parar de apertar uma e outra vez.\nObjeto inovador essencial para Hati.",
  str_item_intro_3220192 = "Esta pedra preciosa opaca parece áspera ao toque. Leo diz que isso é prova de que foi polido pelo vento e pela areia na fronteira.\nObjeto inovador essencial para Leo.",
  str_item_intro_3220193 = "Aproxime-se dele e você ouvirá o som distinto de água corrente. Talvez esse tipo de corrente fluindo no coração de Kristen...\nObjeto inovador essencial para Kristen.",
  str_item_intro_3220199 = "Sons melodiosos de pássaros podem ser ouvidos de dentro desta pedra preciosa cristalina.\nObjeto inovador essencial para Yingel.",
  str_item_intro_3220200 = "Uma pedra preciosa que Anatoli coletados foram produzidos nas veias dentro da Noite Eterna e transportados milhares de quilômetros de volta para Illumina. É quente ao toque e o reflexo de alguém pode ser visto vagamente em sua superfície.\nObjeto inovador essencial para Anatoli.",
  str_item_intro_3220201 = "À primeira vista, parece ser uma pedra comum, mas coloque-a no ouvido e ouça com atenção - você ouvirá o choque de dois rugidos entrelaçados, de alguma forma fazendo com que pareça ainda mais deslumbrante.\nObjeto inovador essencial para Mia: Lustrous Soul.",
  str_item_intro_3220202 = "Olhe para esta pedra preciosa e você verá o que parece ser um dia ensolarado após uma tempestade. Este é o futuro que aguarda Lumopolis sob seu governo.\nObjeto inovador essencial para Schwartz: Almighty Clamor.",
  str_item_intro_3220203 = "Uma bela pedra preciosa que irradia um brilho colorido quando exposta à luz do sol, projetando a imagem de um livro de adivinhação.\nObjeto inovador essencial para Jakine.",
  str_item_intro_3220204 = "Uma pedra preciosa envolta por uma luz quente como velas no inverno ou lâmpadas de rua no escuro que guiam o caminho para aqueles que estão perdidos.\nObjeto inovador essencial para Joshua.",
  str_item_intro_3220205 = "Uma pedra preciosa requintada com a qual Blanc costuma brincar. Ela diz que o fundo desta pedra preciosa reflete um halo vermelho, mas ninguém mais pode vê-lo.\nObjeto inovador essencial para Blanc: Pura Cordis.",
  str_item_intro_3220206 = "Lorelei brinca que esta pedra preciosa exala dinheiro, mas ela adora absolutamente.\nObjeto essencial de AVANÇO para Lorelei",
  str_item_intro_3220207 = "Suave na superfície, mas afiado ao toque, será que este cristal sugere que, sob sua aparência brilhante, também existem cicatrizes ocultas do passado?\nObjeto essencial para o avanço Cena.",
  str_item_intro_3220208 = "Um cristal deslumbrante e cintilante, girando devagar...\nObjeto essencial de avanço para Bopper.",
  str_item_intro_3220209 = "Objeto essencial de Avanço para Wrath: Orgulho Ardente.\nEle pica qualquer um que ouse tocar, causado pelo relâmpago carmesim inquieto que gira dentro do cristal, aguardando que ela conquiste seu campo de batalha escolhido.",
  str_item_intro_3220210 = "Objeto essencial de Avanço para Joselyne.\nAo observar de perto, uma suave radiação pulsa no núcleo da joia, lembrando os cânticos de fiéis devotos e a luz sagrada que rompe a noite.",
  str_item_intro_3220211 = "Esta joia ficou enterrada no subsolo por eras até Antony escavá-la, limpar a sujeira e desvendar a raiz de seu mistério.\nObjeto essencial de Avanço para Antony.",
  str_item_intro_3220212 = [[
Parece mais um cristal de gelo formado naturalmente do que uma pedra preciosa. Talvez Zarya tenha feito isso ela mesma?
Objeto Breakthrough essencial para Zarya.]],
  str_item_intro_3220213 = "No. 33 encontrou esta pedra preciosa perto das ruínas que ela já guardou. Sempre que sua solidão se torna insuportável, No. 33 a considera como sua companheira e tenta se comunicar com ela.\nObjeto inovador essencial para No. 33.",
  str_item_intro_3220214 = "Objeto essencial de Avanço para Rebecca. Esta pedra preciosa foi dada a Rebecca por seus pais. Sempre que ela a segura firmemente, pode sentir o calor eterno de sua família.",
  str_item_intro_3220215 = "Uma pedra preciosa formada a partir do veneno de Rebecca. Isa sente como se seu corpo estivesse cheio de energia sempre que tem isso consigo.\nObjeto essencial de Avanço para Isa.",
  str_item_intro_3220216 = "Esta pedra de aparência comum contém um poder desconhecido. Ninguém sabe em qual armadilha ou criação mecânica Xuan Ji irá incorporar esta pedra.\nObjeto essencial de Avanço para Xuan Ji.",
  str_item_intro_3220218 = "Esta gema misteriosa tem exatamente o mesmo peso que um Nightium. Se você ouvir com atenção, pode até ouvir o som do Nightium chacoalhando dentro da gema.\nObjeto Breakthrough essencial para Sheol.",
  str_item_intro_3220219 = "Esta gema brilhante e pesada parece estar tremendo levemente com emoções distantes em sua mão. É quase como se eventos passados que foram profundamente enterrados estivessem prestes a explodir.\nObjeto Breakthrough essencial para Istvan: Scarred Pith",
  str_item_intro_3220220 = "Vergil avaliou esta joia como tendo alto valor artístico. Foi relatado que ele gosta de carregar esta joia com ele como um amuleto da sorte. Objeto de Avanço essencial para Vergil.",
  str_item_intro_3220221 = "Uma pedra preciosa extremamente profunda e impressionante de origem desconhecida. Parece prever o futuro misterioso e imprevisível dos Aurorians...\nObjeto de Avanço essencial para Algol.",
  str_item_intro_3220223 = "Uma pedra formada a partir de escamas em uma era antiga, talvez guardando as reflexões distantes do clã de Chen'ni.\nObjeto essencial de Avanço para Chen'ni.",
  str_item_intro_3220224 = "Uma pedra que possivelmente abriga poderes misteriosos. Luo Song pode usá-la para colocar juízo em pequenos demônios travessos.\nObjeto Breakthrough essencial para Luo Song.",
  str_item_intro_3220225 = "Uma pedra preciosa com um tom protetor que se mistura perfeitamente com o gelo uma vez que cai na neve, tornando a recuperação quase impossível. Portanto, é melhor manuseá-la com cuidado.\nObjeto Breakthrough essencial para Tiare.",
  str_item_intro_3220227 = "Um pedaço de Lumamber com bordas e cantos anormalmente afiados. Embora seja necessário um grande cuidado ao manusear este Lumamber, pode-se sentir um calor suave e delicado vindo dele.\nObjeto essencial de Avanço para Rachel.",
  str_item_intro_3220228 = "Uma bela pedra preciosa que exala tanto um brilho colorido brilhante quanto a mais leve sugestão de doce.\nObjeto Breakthrough essencial para Zeta.",
  str_item_intro_3220229 = "Uma pedra comum que Batia diz que pode ser obtida usando uma picareta e uma fornalha, bem como outros métodos.\nObjeto Breakthrough essencial para Batia.",
  str_item_intro_3220230 = "No instante em que você toca esta pedra preciosa, pode ouvir sussurros antigos, não de longe ou perto do seu ouvido, mas profundamente em sua mente, como um ser antigo pulsando e lutando para se libertar.\nObjeto inovador essencial para Victoria: Elegy.",
  str_item_intro_3220231 = "Uma pedra preciosa com uma cor vívida e assustadora. No momento em que você a toca, o sangue começa a escorrer pelas paredes. Só quando você retira a mão com medo é que percebe que tudo é uma alucinação.\nObjeto essencial de Avanço para Wilhelm.",
  str_item_intro_3220232 = "Assim que você agarra essa pedra preciosa, vê milhares de lâminas caindo do céu, cortando sua carne. Você grita de dor, mas quando se olha, não encontra nenhum dano.\nObjeto de Avanço essencial para Nails: Rito Sagrado.",
  str_item_intro_3220233 = "Uma gema escavada das ruínas. Talvez você possa sentir a paixão da aventura dela.\nObjeto Breakthrough essencial para Ryza.",
  str_item_intro_3220234 = "Uma gema escavada das ruínas. Talvez você possa sentir a beleza da música dela.\nObjeto essencial de Avanço para Klaudia.",
  str_item_intro_3220235 = "Uma joia escavada das ruínas. Talvez você possa sentir um temperamento nobre dela.\nObjeto essencial de Avanço para Patricia.",
  str_item_intro_3220237 = "Uma joia cristalina com o toque de uma brisa fresca acima das nuvens e a suavidade úmida do mar profundo.\nSegure-a em sua mão, e você ouvirá um sussurro silencioso, \"Não tenha medo. O mundo está dormindo em seu sonho.\"\nObjeto Breakthrough essencial para Maya.",
  str_item_intro_3220238 = "Parece simples à primeira vista, mas quando você toca a borda, percebe o quão afiado realmente é. Há uma energia pulsante dentro, como uma raiva não expressa.\nObjeto essencial de Avanço para Mithra.",
  str_item_intro_3231101 = "Presente comum. Efeito maior quando dado a Aurorians de Lumópolis. Uma folha de prata fina, delicada e leve como uma pena. Um favorito de Lumópolis.",
  str_item_intro_3232101 = "Presente valioso. Efeito maior quando dado a Aurorians de Lumópolis. Lumâmbar embalado em ouro. A joia principal da alta sociedade de Lumópolis.",
  str_item_intro_3233101 = "Efeito maior quando dado a Aurorians de Lumópolis.\nArtesanato muito precioso feito com uma joia Lúmina fixada em um cristal branco valioso.",
  str_item_intro_3231102 = "Presente comum. Efeito maior quando dado a Aurorians de Umbraton. Réplica de pinturas famosas. Popular em Umbraton.",
  str_item_intro_3232102 = "Presente valioso. Efeito maior quando dado a Aurorians de Umbraton. Apenas certos magnatas de Umbraton conseguem um gole dessa preciosa libação.",
  str_item_intro_3233102 = "Efeito maior quando dado a Aurorians de Umbraton.\nUma joia sedutora com um brilho verde único, muito procurada em Umbraton.",
  str_item_intro_3231103 = "Presente comum. Efeito maior quando dado a Aurorians de Rediesel Wrench.\nUma sobra de substância de tempos antigos. Pessoas de Rediesel Wrench usam para decoração ou enfeitar sua Colossus.",
  str_item_intro_3232103 = "Presente valioso. Efeito maior quando dado a Aurorians de Rediesel Wrench.\nChave para dinamites, munição e explosivos. Moeda forte interna da Rediesel Wrench.",
  str_item_intro_3233103 = "Efeito maior quando dado a Aurorians de Rediesel Wrench.\nLicor forte raro que mexe com qualquer pessoa após uma dose. Amado pelas pessoas de Rediesel Wrench.",
  str_item_intro_3231104 = "Presente comum. Efeito maior quando dado a Aurorians da Federação Illumina.\nLivro de introdução da Federação Illumina, com imagens para um aprendizado fácil.",
  str_item_intro_3232104 = "Presente valioso. Efeito maior quando dado a Aurorians da Federação Illumina.\nManual da Federação Illumina que ensina ao leitor como usar a ciência para resolver vários problemas.",
  str_item_intro_3233104 = "Efeito maior quando dado a Aurorians da Federação Illumina.\nPara uso interno da Federação Illumina, com todos os campos de conhecimento conhecidos pela federação.",
  str_item_intro_3231105 = "Presente comum. Efeito maior quando dado a Aurorians de Northland.\nCristal de um floco de neve no momento em que foi formado. Pessoas de Northland acreditam que ele contém uma magia poderosa e adoram coletá-lo.",
  str_item_intro_3232105 = "Presente valioso. Efeito maior quando dado a Aurorians de Northland.\nUma joia colorida preciosa descoberta embaixo de um arco-íris, pessoas de Northland acreditam que traz boa sorte.",
  str_item_intro_3233105 = [[
Efeito maior quando dado a Aurorians de Northland.
Uma camada de gelo colorida do Lago Espelho congelado em Northland. Um favorito de Northland.]],
  str_item_intro_3231106 = "Presente comum. Efeito maior quando dado a Aurorians da True Order.\nEscaravelho antigo em âmbar. A True Order acredita que ele contém um poder misterioso.",
  str_item_intro_3232106 = "Presente valioso. Efeito maior quando dado a Aurorians da True Order.\nPergaminho contendo revelações inescrutáveis. Muitos segredos serão revelados se membros da True Order o decifrarem.",
  str_item_intro_3233106 = "Efeito maior quando dado a Aurorians da True Order.\nA True Order acredita que ele contém a revelação suprema que irá mudar a civilização que conhecemos.",
  str_item_intro_3231107 = "Presente comum. Efeito maior quando dado a Aurorians Independentes.\nRação desidratada, compacta e leve, popular em assentamentos pequenos.",
  str_item_intro_3232107 = "Presente valioso. Efeito maior quando dado a Aurorians Independentes.\nUma poção mágica que pode fazer qualquer um ser um médico em alguns assentamentos.",
  str_item_intro_3233107 = "Efeito maior quando dado a Aurorians Independentes.\nPeças de um mapa do tesouro procurado por muitas pessoas que acham que vale o risco.",
  str_item_intro_3232108 = "Presente comum. Efeito maior quando dado a Aurorians de Longzhou.\nUm leque dobrável com armação de bambu e superfície de papel ilustrada com encantadoras montanhas e rios. É usado nos quartos escuros dos salões principais em Longzhou.",
  str_item_intro_3233108 = "Presente valioso. Efeito maior quando dado a Aurorians de Longzhou.\nEste nó decorativo feito de corda vermelha simboliza uma conexão sincera e amor mútuo e é um dos presentes mais importantes no coração do povo de Longzhou.",
  str_item_intro_3231201 = "Presente comum. Efeito maior quando dado a Aurorians com uma inocência infantil.\nAmado por qualquer um com o coração de uma criança. Vem em cinco sabores e você pode usar apitos com ele.",
  str_item_intro_3232201 = "Presente valioso. Efeito maior quando dado a Aurorians com uma inocência infantil.\nProduto de entretenimento para qualquer um com o coração de uma criança. Usado com descrições verbais.",
  str_item_intro_3233201 = "Efeito maior quando dado a Aurorians com uma inocência infantil.\nModelo preferido por qualquer um com o coração de uma criança. Muito detalhado e fora de produção.",
  str_item_intro_3231202 = "Presente comum. Efeito maior quando dado a Aurorians românticos.\nBoneca artesanal preferida de românticos. Lembra um coelho e um urso. Criador desconhecido.",
  str_item_intro_3232202 = "Presente valioso. Efeito maior quando dado a Aurorians românticos.\nÉ muito romântico ver o espectro lindo de luzes dentro do frasco em um ambiente escuro.",
  str_item_intro_3233202 = "Efeito maior quando dado a Aurorians românticos.\nMarca páginas feito de uma planta rara, com padrões e cores variáveis.",
  str_item_intro_3231203 = "Presente comum. Efeito maior quando dado a Aurorians esotéricos.\nFamoso por sua aparência estranha, esse inseto atrai colecionadores de raridades.",
  str_item_intro_3232203 = "Presente valioso. Efeito maior quando dado a Aurorians esotéricos.\nEsse pontiagudo fóssil cristalizado de uma criatura desconhecida é para verdadeiros colecionadores.",
  str_item_intro_3233203 = "Efeito maior quando dado a Aurorians esotéricos.\nMadeira podre coletada por curiosos porque sussurros estranhos podem ser ouvidos, às vezes, em seu corte.",
  str_item_intro_3231204 = [[
Presente comum. Efeito maior quando dado a Aurorians nobres.
Um sino de prata extraordinariamente esculpido, compacto, leve, acredita-se que seja um amuleto da sorte.]],
  str_item_intro_3232204 = "Presente valioso. Efeito maior quando dado a Aurorians nobres.\nMinério raro que brilha em cores diferentes sob intensidades de luz diferentes. Um presente entre nobres.",
  str_item_intro_3233204 = "Efeito maior quando dado a Aurorians nobres.\nMateriais especiais e escassos adorados por nobres. A maioria é de regiões frias, é macio e leve, mas durável.",
  str_item_intro_3231205 = "Presente comum. Efeito maior quando dado a Aurorians decididos.\nUma especialidade do deserto. Pessoas decididas gostam muito desse sabor único.",
  str_item_intro_3232205 = [[
Presente comum. Efeito maior quando dado a Aurorians decididos.
Uma caixa de ferramentas para artesanato e reparos. Preferido por pessoas sensatas.]],
  str_item_intro_3233205 = "Efeito maior quando dado a Aurorians decididos.\nCapaz de medir funções biológicas e mecânicas. Produto perfeito para pessoas intuitivas.",
  str_item_intro_3239997 = "Estes vêm em todos os tipos de sabores! Dê aos Aurorianos para aumentar significativamente a Afinidade.",
  str_item_intro_3239998 = "Dê aos aurorianos para aumentar significativamente a afinidade!",
  str_item_intro_3239999 = "Chocolate irresistível! Dê aos aurorianos para aumentar significativamente a afinidade!",
  str_item_intro_3300001 = "Uma substância rígida, mas não é um metal... Parece um composto biológico de tempos antigos, capaz de reparar certas áreas danificadas de uma Colossus e reconectar conduítes de energia.",
  str_item_intro_3300002 = "Um patch de Colossus melhorado, suficiente para fortificar o interior de uma Colossus.",
  str_item_intro_3300003 = "Durável e flexível, com escritas desconhecidas sumindo e reaparecendo. Material necessário para restaurar instalações vitais de uma Colossus.",
  str_item_intro_3300004 = "Necessário para melhorar a Ponte, uma instalação necessária da Colossus. Muito raro. Use com cuidado.",
  str_item_intro_3300005 = "Um cubo mágico com uma estrutura intrigante, possivelmente deixado por um bravo explorador. Se a informação gravada nele for inserida na base de dados da Colossus, uma nova sala pode ser desbloqueada.",
  str_item_intro_3300006 = "Este plugin ficou enterrado por muitos anos. É parecido com o que Soroz perdeu dezessete anos atrás! É possível usá-lo para desbloquear uma sala na Colossus.",
  str_item_intro_3400001 = "Ganhe 1 de cada mat. básico para ascensão de Água.",
  str_item_intro_3400002 = "Ganhe 1 de cada mat. básico para ascensão de Fogo.",
  str_item_intro_3400003 = "Ganhe 1 de cada mat. básico para ascensão de Floresta.",
  str_item_intro_3400004 = "Ganhe 1 de cada mat. básico para ascensão de Trovão.",
  str_item_intro_3400005 = "Ganhe 1 de cada mat. normal para ascensão de Água.",
  str_item_intro_3400006 = "Ganhe 1 de cada mat. normal para ascensão de Fogo.",
  str_item_intro_3400007 = "Ganhe 1 de cada mat. normal para ascensão de Floresta.",
  str_item_intro_3400008 = "Ganhe 1 de cada mat. normal para ascensão de Trovão.",
  str_item_intro_3400009 = "Ganhe 1 de cada mat. avançado para ascensão de Água.",
  str_item_intro_3400010 = "Ganhe 1 de cada mat. avançado para ascensão de Fogo.",
  str_item_intro_3400011 = "Ganhe 1 de cada mat. avançado para ascensão de Floresta.",
  str_item_intro_3400012 = "Ganhe 1 de cada mat. avançado para ascensão de Trovão.",
  str_item_intro_3400013 = "Ganhe 1 mat. básico aleatório para asc. de Água.",
  str_item_intro_3400014 = "Ganhe 1 mat. básico aleatório para asc. de Fogo.",
  str_item_intro_3400015 = "Ganhe 1 mat. básico aleatório para asc. de Floresta.",
  str_item_intro_3400016 = "Ganhe 1 mat. básico aleatório para asc. de Trovão.",
  str_item_intro_3400017 = "Ganhe 1 mat. normal aleatório para asc. de Água.",
  str_item_intro_3400018 = "Ganhe 1 mat. normal aleatório para asc. de Fogo.",
  str_item_intro_3400019 = "Ganhe 1 mat. normal aleatório para asc. de Floresta.",
  str_item_intro_3400020 = "Ganhe 1 mat. normal aleatório para asc. de Trovão.",
  str_item_intro_3400021 = "Ganhe 1 mat. avançado aleatório para asc. de Água.",
  str_item_intro_3400022 = "Ganhe 1 mat. avançado aleatório para asc. de Fogo.",
  str_item_intro_3400023 = "Ganhe 1 mat. avançado aleatório para asc. de Floresta.",
  str_item_intro_3400024 = "Ganhe 1 mat. avançado aleatório para asc. de Trovão.",
  str_item_intro_3400025 = "Ganhe 1 de cada material básico para ascensão.",
  str_item_intro_3400026 = "Ganhe 1 de cada material normal para ascensão.",
  str_item_intro_3400027 = "Ganhe 1 de cada material avançado para ascensão.",
  str_item_intro_3400028 = "Ganhe 1 mat. básico aleatório para ascensão.",
  str_item_intro_3400029 = "Ganhe 1 mat. normal aleatório para ascensão.",
  str_item_intro_3400030 = "Ganhe 1 mat. avançado aleatório para ascensão.",
  str_item_intro_3400031 = "Jaspe Bruto Comum. Ganhe 1 Jaspe I aleatório (Azul, Rubro, Amarelo ou Verde).",
  str_item_intro_3400032 = "Coleção de vários Jaspes. Ganhe 1 Jaspe I de cada cor (Azul, Rubro, Amarelo e Verde).",
  str_item_intro_3400033 = "Jaspe Bruto Comum. Ganhe 1 Jaspe II aleatório (Azul, Rubro, Amarelo ou Verde).",
  str_item_intro_3400034 = "Coleção de vários Jaspes. Ganhe 1 Jaspe II de cada cor (Azul, Rubro, Amarelo e Verde).",
  str_item_intro_3400035 = "Jaspe Bruto com uma cor mais brilhante. Ganhe 1 Jaspe III aleatório (Azul, Rubro, Amarelo ou Verde).",
  str_item_intro_3400036 = "Coleção de vários Jaspes. Ganhe 1 Jaspe III de cada cor (Azul, Rubro, Amarelo e Verde).",
  str_item_intro_3400037 = "Presente anônimo. Abra e veja o que tem dentro.\nUse para ganhar 1 presente comum aleatório.",
  str_item_intro_3400038 = "Um presente anônimo sofisticado. Deve ter presentes melhores dentro, certo?\nUse para ganhar 1 presente valioso aleatório.",
  str_item_intro_3400039 = "Presentes dentro de um pacote magnífico devem ser valiosos. Abra-o!\nUse para ganhar um presente aleatório de Aurorian de grande valor.",
  str_item_intro_3400040 = "Caixa transparente feita de cristal e fortificada com Luminática. Leve e firme, ela contém Lumâmbar precioso. Use para ganhar 50 Lumâmbar.",
  str_item_intro_3400041 = "Caixa forte para ouro feita por Lumópolis. Com a popularidade de Noitium, é vista em todos os lugares.\nContém 100.000 Noitium.(e-mail)",
  str_item_intro_3400042 = "Caixa de cristal que brilha. Guarda Lúmina suficiente para recarregar prismas inteiros.\nUse para ganhar 10 Prismas.",
  str_item_intro_3400043 = [[
Caixa quadrada de cristal com um centro brilhante. Fornece energia para prismas.
Use para ganhar 60 Prismas.]],
  str_item_intro_3400044 = "Um grande baú feito de cristal polido com enfeites elaborados. Contém Lúmina suficiente para recarregar prismas com mais energia do que tinham antes.\nUse para ganhar 50 Prismas.",
  str_item_intro_3400045 = "Caixa grande de cristal que brilha. Guarda Lúmina suficiente para recarregar prismas inteiros.\nUse para ganhar 60 Prismas.",
  str_item_intro_3400046 = "Kit de Suprimento desenvolvido pela Coalizão Aurorian. Ganhe 1 mat. aleatório: Pedra da Noite Branca, Refresco do Destino I, Orvalho de Pinha, Extrato Rediesel, Arquivo de Batalha I, Pergaminho Antigo, Contos de Sobrevivência, Pílula de Fortalecimento Ósseo.",
  str_item_intro_3400047 = "Kit de Suprimento desenvolvido pela Coalizão Aurorian. Ganhe 1 mat. aleatório: Pedra da Manhã, Refresco do Destino III, Geada de Pinha, Concentrado Rediesel, Arquivo de Batalha II, Livro Antigo, Sobrevivência Básica, Pílula de Limpeza de Medula.",
  str_item_intro_3400048 = "Kit de Suprimento desenvolvido pela Coalizão Aurorian. Ganhe 1 mat. aleatório: Pedra do Amanhecer, Refresco do Destino III, Lágrima de Pinha, Essência Rediesel, Arquivo de Batalha III, Livro Antigo, Sobrevivepédia, Pílula de Reconstrução.",
  str_item_intro_3400049 = "Em Northland, há uma torre alta com uma luz acesa no topo. Enquanto ela durar, os Eclipsitas nunca devem se tornar uma ameaça ao norte do continente.",
  str_item_intro_3400050 = [[
Desbloqueia Assistente: Vice Roupa Casual.
Visual casual de Vice.]],
  str_item_intro_3400052 = "Desbloqueia a imagem de fundo: Floresta Nevosa\nEssa densa floresta na fronteira de Northland é coberta com uma camada espessa de neve no inverno. Aqueles que entram nessa floresta pitoresca por engano normalmente se perdem nela.",
  str_item_intro_3400053 = "Desbloqueia a imagem de fundo — Far East Dojo.\nÉ um lugar no Extremo Oriente, usado tanto para praticar artes marciais quanto para meditar.",
  str_item_intro_3400054 = "Use para desbloquear Pano de Fundo - Céu Maravilhoso.\nNa antiga cidade perdida, esse céu já foi o maior consolo para seus habitantes.",
  str_item_intro_3400055 = "Desbloqueia a imagem de fundo - Palco Perfeito.\nO lugar onde as meninas faziam sua performance no verão. Apesar de muito tempo ter passado, parece que nada mudou.",
  str_item_intro_3400056 = "Desbloqueia a imagem de fundo - Sakura Court Hallway.\nO corredor e pátio em estilo do Extremo Oriente oferece um cenário único durante a época das cerejeiras em flor.",
  str_item_intro_3400057 = "Desbloqueia a imagem de fundo - Trem do Comandante da Legião.\nQuando os quatro Comandantes da Legião da Federação Illumina viajaram juntos no trem especial, algo sério deve ter acontecido...",
  str_item_intro_3400058 = "Desbloqueia a imagem de fundo - Oasis.\nUm dos principais redutos do Rediesel Wrench localizado em uma área com terreno complexo e diversificado.",
  str_item_intro_3400059 = "Desbloqueia a imagem de fundo - Quatro Anjos.\nOs quatro comandantes cavaleiros representam o poder formidável dos Lumo Nobles.",
  str_item_intro_3400060 = "Desbloqueia o plano de fundo - festa de noite de verão.\nNo auge da festa da noite de verão, as meninas curtiram a música completamente, e suas risadas e cantos ainda podem ser ouvidos até hoje.",
  str_item_intro_3400061 = "Desbloqueia o plano de fundo - dente em chamas.\nO desfiladeiro, batizado com o nome de suas características irregulares, tem colinas íngremes que são notoriamente difíceis de navegar.",
  str_item_intro_3400062 = "Obtenha para desbloquear a imagem de fundo - Mystery Mansion.\nUma luxuosa casa de origem desconhecida e propriedade incerta, promete um tempo de lazer e despreocupação...",
  str_item_intro_3400063 = "Desbloqueia o plano de fundo: Sistema Circular.\nOriginário de uma região antiga, que segredo guarda?",
  str_item_intro_3400064 = "Desbloqueia o fundo: Chord Link.\nUma força misteriosa de um espaço misterioso...",
  str_item_intro_3400065 = "Desbloqueia o fundo: Piano Duet.\nLembre-se do momento em que você começou isso com Vice?",
  str_item_intro_3400066 = [[
Desbloqueia o plano de fundo: Eraveil Colossus.
Colossos apareceram em Eraveil novamente. Isso significa alguma coisa?]],
  str_item_intro_3400067 = "Desbloqueia a imagem de fundo - Carta dos Céus.\nÉ uma carta levada pelo vento, para dizer ao celestita que é hora de voltar para casa.",
  str_item_intro_3400068 = "Desbloqueia o fundo - Cemitério Silencioso\nUm lugar tranquilo em Eraveil, tão tranquilo que até o tempo lá foi pausado.",
  str_item_intro_3400069 = "Desbloqueia o plano de fundo: Poste Decorado.\nO Eraveil Post foi recentemente decorado. Ansiosos para as noites de férias nos próximos dias.",
  str_item_intro_3400070 = "Desbloqueia o plano de fundo: Memórias de Férias.\nFoi a primeira noite de férias que passei em Eraveil...",
  str_item_intro_3400071 = "Desbloqueia o plano de fundo: Rua Umbraton à noite.\nQuando a noite cai em Umbraton, as ruas estão silenciosas, mas uma pitada de perigo espreita.",
  str_item_intro_3400072 = [[
Desbloqueia o plano de fundo: Gloom of the Night.
A noite Umbraton engole tudo o que toca. Um raio de luz pode atravessar?]],
  str_item_intro_3400073 = "Desbloqueia o plano de fundo: Mansão Andersen.\nEsta imponente mansão reflete a riqueza e elegância de seu proprietário.",
  str_item_intro_3400074 = "Desbloqueia o plano de fundo: Cloud Blossom Hotel.\nExcelente comida, ótimas fontes termais, e eles ainda fornecem yukatas!",
  str_item_intro_3400075 = "Desbloqueia a imagem de fundo: Harbour City Pier.\nA área próxima ao porto de Harbour City é o melhor lugar para aproveitar a brisa sob o céu claro!",
  str_item_intro_3400076 = "Desbloqueia o plano de fundo: Noite de verão.\nSeria incrível se esses momentos durassem para sempre.",
  str_item_intro_3400077 = "Desbloqueia o plano de fundo: Aviso de trovão na praia.\nEsmague-o e o jogo terminará antes do prazo!",
  str_item_intro_3400078 = "Desbloqueia o plano de fundo: Memória da Igreja.\nUm edifício decadente em Euphoria. É bom apenas para abrigo, assim como em qualquer outro lugar, afinal.",
  str_item_intro_3400079 = "Desbloqueia o plano de fundo: Terra Misteriosa.\nUma terra escondida e sem nome onde muito do passado foi enterrado. Esses segredos verão a luz do dia novamente?",
  str_item_intro_3400080 = "Desbloqueia o plano de fundo: Sacrifício?\nEle escolheu se sacrificar contra os Eclipsitas que o atacavam. No entanto, ninguém sabia que isso era apenas uma parte de seu plano...",
  str_item_intro_3400082 = "Desbloqueia o plano de fundo: Busca da Verdade.\nEles acreditam que o que o mundo considera de conhecimento comum a todos é falso. A verdade real está muito além do que seus olhos podem perceber, apenas esperando que eles a persigam.",
  str_item_intro_3400083 = "Desbloqueia o plano de fundo: Colossus Stage.\nUm palco totalmente equipado foi montado próximo ao bar do Soroz para que todos possam mostrar seus talentos.",
  str_item_intro_3400084 = "Desbloqueia o plano de fundo: Ancient Abandoned City.\nApenas a visão do enorme prédio desmoronado é suficiente para pintar uma imagem de quão catastrófica foi aquela guerra antiga.",
  str_item_intro_3400085 = "Desbloqueia o plano de fundo: Sob o céu de inverno.\nSe você vir uma espada brilhante e um flash de cabelo loiro chicoteando no ar, provavelmente é a Rainha do Norte fazendo sua ronda sob o céu de inverno enquanto ela vigia seu reino com olhos vigilantes a cada inverno.",
  str_item_intro_3400086 = "Desbloqueia o plano de fundo: Aurora Sky.\nMesmo em Northland, esse tipo de aurora que cobre cada centímetro do céu e desaparece no horizonte é raro. Dizem que sempre que aparece, pode ter um efeito desconhecido no futuro...",
  str_item_intro_3400087 = "Desbloqueia o plano de fundo: Road of Song.\nEm um Colosso que vagueia por incontáveis terras, a figura de uma estrela jovem e brilhante enfeita os corredores. Seu canto divino, imbuído da força da esperança, logo se espalhará por todo o continente.",
  str_item_intro_3400088 = "Desbloqueia o plano de fundo: Deck of The Shadowind.\nSomente este enorme e sólido deck pode suportar um castelo tão alto.",
  str_item_intro_3400089 = "Desbloqueia o plano de fundo: Eastern Docks.\nAs docas, as casas e os barcos do continente do outro lado do mar são bem diferentes dos de Astra, mas as cenas ruidosas e movimentadas da vida permanecem as mesmas.",
  str_item_intro_3400090 = "Desbloqueia o plano de fundo: Não há mais camaradas.\nDepois de lutar lado a lado com o Grande Marechal, derrotando inúmeros inimigos juntos, chegou a hora de lutar contra ela.\nDestino, por que você zomba tanto de mim?",
  str_item_intro_3400091 = "Desbloqueia o fundo: Rediesel Courier.\nA filial do Deserto Rediesel da Courier Union parece ter se adaptado gradualmente à vida no Deserto Rediesel.",
  str_item_intro_3400092 = "Desbloqueia o plano de fundo: Escritório de Jeriah.\nJeriah lida com seus assuntos diários aqui e imprimiu este lugar com seu estilo pessoal.",
  str_item_intro_3400093 = "Desbloqueia o plano de fundo: Lugar Despreocupado.\nNesse clima, cafés, restaurantes ou bares têm uma função comum - descanso, recuperação e um lugar para todos se divertirem.",
  str_item_intro_3400094 = "Desbloqueia o plano de fundo: Casamento de Inverno\nEssas decorações cristalinas refletem as figuras impecáveis e transparentes do casal e representam seus sentimentos puros. Nem mesmo o frio resiste ao contato próximo com corações apaixonados em um casamento no inverno.",
  str_item_intro_3400099 = "Desbloqueia o plano de fundo: A Sombra nas Chamas.\nEnquanto os demônios escaldantes atacam de todos os lados, uma figura estende uma mão amiga...",
  str_item_intro_3400100 = "Desbloqueia o plano de fundo: visão geral do armazém.\nEspaços de armazenamento cercam, até onde os olhos podem ver. Talvez eles escondam os segredos de algum passado desconhecido.",
  str_item_intro_3400101 = "Desbloqueia o plano de fundo: Vista do Centro.\nUm refúgio imaculado e elegante, celebrado não apenas como o coração invicto de Lumópolis, mas como o centro de todo o continente.",
  str_item_intro_3400102 = "Desbloqueia o plano de fundo: Irmãos Brincalhões.\nUma cena emocionante de irmãos envolvidos em risadas. Embora inúmeros dias e noites tenham passado, a memória permanece vívida, gravada para sempre em seus corações.",
  str_item_intro_3400103 = "Desbloqueia o plano de fundo: Praça Anoitecer.\nA deslumbrante Praça Central em Lumópolis brilha magnificamente mesmo com a chegada da noite, rivalizando com seu brilho diurno.",
  str_item_intro_3400109 = "Desbloqueia o plano de fundo: Dawn Academia.\nExiste um lugar em Lumópolis onde os devotos estudam os ensinamentos do Deus da Luz, e todos que passam por suas portas sagradas são preenchidos com respeito.",
  str_item_intro_3400110 = "Desbloqueia o plano de fundo: Ruína Misteriosa.\nNeste espaço desconhecido, bem abaixo de Northland, parece que algum dispositivo artificial ainda está ativo.",
  str_item_intro_3400111 = "Desbloqueia o plano de fundo: Luz das Estrelas Suave.\nUma noite sem sono sozinho, na ponte sob o céu estrelado. Você ainda pode ouvir a música do universo sem nem mesmo precisar apertar as teclas do painel de controle.",
  str_item_intro_3400112 = "Desbloqueia o cenário: Tarde Tranquila.\nLumópolis abriga muitos jardins pequenos e elaborados onde os nobres desfrutam do chá da tarde. Até mesmo a iminente destruição do mundo parece estar a milhões de quilômetros de distância daqui.",
  str_item_intro_3400113 = "Desbloqueia o plano de fundo: Clínica Subterrânea.\nUma clínica relativamente simples que abriga memórias preciosas.",
  str_item_intro_3400114 = "Desbloqueia o plano de fundo: O Canto Mais Escuro.\nMesmo perdida na escuridão, ela ainda anseia abraçar a luz novamente.",
  str_item_intro_3400115 = "Desbloqueia o plano de fundo: Hospitalidade.\nApenas aqueles aprovados por Sheol têm permissão para residir neste quarto luxuoso e confortável.",
  str_item_intro_3400116 = "Desbloqueia o plano de fundo: Novo Continente.\nO Shadowind chegou com sucesso a um novo continente, mas isso não significa que sua aventura chegou ao fim, pois muitas outras coisas desconhecidas os aguardam.",
  str_item_intro_3400117 = "Desbloqueia o plano de fundo: Sombras Estão em Todo Lugar.\nO Senhor Sombrio continua a observar Umbraton. A sombra sempre observará você.",
  str_item_intro_3400118 = "Desbloqueia o plano de fundo: História Obscura.\nA história selada na poeira será exposta um dia. Esta pessoa é um ditador que dominou Umbraton ou um herói que salvou Umbraton?",
  str_item_intro_3400119 = "Desbloqueia o fundo: Sala de Recepção.\nEm uma sala com iluminação moderada, vários itens e decorações são organizados de maneira ordenada. Esta sala é dedicada para trabalho e recepção de convidados.",
  str_item_intro_3400120 = "Desbloqueia o cenário: Charme de Longzhou.\nO lado oeste da Baía dos Pavilhões Gêmeos está sob a gestão de Umbraton, mas culturalmente, vislumbres do charme único de Longzhou ainda brilham. Desde lanternas penduradas em todas as ruas até deliciosos petiscos de Longzhou, todos mostram as características vibrantes da terra distante, permitindo que os visitantes aqui se imerjam totalmente na cultura e costumes exóticos.",
  str_item_intro_3400121 = "Desbloqueia o plano de fundo: Porto da Baía dos Pavilhões Gêmeos.\nOs navios de carga partindo do continente de Longzhou finalmente atracam nos portos da Baía dos Pavilhões Gêmeos, onde finalizam suas trocas comerciais e de mercadorias antes de retornar. Esses portos desempenham um papel vital no transporte entre os continentes de Longzhou e Astra.",
  str_item_intro_3400122 = "Desbloqueia o cenário: Festival da Primavera no Reino Ji\nO Festival da Primavera é o festival mais importante no continente de Longzhou. A família real organizaria banquetes para convidados estimados, enquanto os cidadãos se reuniam para lazer e conversas. No Reino Ji, os locais organizam feiras de templo, prestam homenagem à Donzela do Dragão e afastam a besta Nian durante o festival, esperando por saúde e boa sorte no próximo ano. Alguns comerciantes contratam demônios para realizar shows temáticos sobre o ritual de perseguição à besta, adicionando um toque de diversão ao início do ano novo.",
  str_item_intro_3400126 = "Desbloqueia o plano de fundo: Banquete de Reunião do Festival da Primavera\nEm Longzhou, a noite do Festival da Primavera é um momento de reunião. O Caelestite e todos os seus companheiros em Longzhou se reuniram para ter um delicioso e auspicioso banquete de feriado juntos e desejar a todos um tempo melhor no próximo ano.",
  str_item_intro_3400123 = "Desbloqueia o Plano de Fundo: Cenário da Mansão.\nDotada de uma localização geográfica única e profundas raízes culturais, esta mansão na Ilha Azurite ostenta uma paisagem de tirar o fôlego e um encanto irresistível, tornando-se um resort preferido para os Nobres de Lumo passearem e relaxarem.",
  str_item_intro_3400129 = "Desbloqueia o plano de fundo: Caverna da Fronteira\nProfundamente dentro de cavernas cobertas de gelo, pilares de gelo conectam a cúpula à terra, parecendo esculturas de divindades. À medida que a aurora desce, esses pilares de gelo altos e robustos e as flores de gelo nas paredes da caverna brilham em suas formas peculiares, completando o ambiente solene e arrepiante.",
  str_item_intro_3400130 = "Desbloqueia a imagem de fundo: Fronteira Coberta de Neve\nEm dias frios e nevados, o aparentemente interminável deserto de neve tem um fim - Montanhas altas se erguem como um muro de cidade ao longe, dividindo o mundo. Algumas pequenas casas cobertas de gelo e neve são vagamente visíveis ao pé da montanha. A vida lá deve ser cheia de solidão, não é?",
  str_item_intro_3400133 = "Obtenha para desbloquear o fundo: Núcleo Vulcânico Subterrâneo.\nDepois de tantos anos, o nômade Rediesel Wrench nunca percebeu que o vulcão sob seus pés ainda fervilhava de vida.",
  str_item_intro_3400134 = "Obtenha para desbloquear o plano de fundo: Lua Sobre as Areias do Deserto.\nSentado no deserto sob o céu noturno está um grupo improvável de pessoas. Enquanto seus olhos cintilam à luz das estrelas, suas memórias se entrelaçam.",
  str_item_intro_3400135 = "Desbloqueia o plano de fundo: Spearhead\nSua estrutura interna é mais concisa e suave comparada a Soroz, e cada painel de controle exala uma aura perigosa.",
  str_item_intro_3400136 = "Desbloqueia o plano de fundo: Diversão Flamejante.\nRebelião e obediência são apenas dois tipos diferentes de lenha. Com a quantidade certa de calor, ambos irão acender e se tornar uma bola de fogo incontrolável!",
  str_item_intro_3400138 = "Desbloqueia o plano de fundo: Advento do Desfile da Verdade.\nVocê é a personificação da sabedoria coletiva da Verdadeira Ordem. Tudo o que você experimenta guiará a Verdadeira Ordem para um futuro cada vez maior.",
  str_item_intro_3400139 = "Desbloqueia o plano de fundo: Praia da Ilha Solitária.\nNos mares distantes, existe uma ilha solitária esquecida pelo mundo, cercada por um azul infinito e coberta por uma vegetação densa e exuberante. Ruínas antigas repousam neste berço verdejante e intocado, tendo resistido através das eras.",
  str_item_intro_3400140 = "Desbloqueia o plano de fundo: Encontro Varrido pelas Ondas.\nA ilha jaz silenciosamente no fundo do mar, junto com as evidências de sua antiga glória. Agora, uma nova aventura de verão está prestes a começar.\nCompanheiros que estão ao seu lado são os tesouros mais preciosos.\nNo tempo limitado que você tem, aproveite esta aventura sem fim com seus companheiros!",
  str_item_intro_3400141 = "Desbloqueia o plano de fundo: Anseio Milenar.",
  str_item_intro_3400142 = "Desbloqueia o plano de fundo: Encontrar Novamente.\nQuando as estrelas alcançam seu destino.\nEle avança, em direção aos seus companheiros e à luz do sol.",
  str_item_intro_3410101 = "Uma caixa básica azul. Abra para escolher 1 material básico de ascensão de Água.",
  str_item_intro_3410102 = "Uma caixa normal azul. Abra para escolher 1 material normal de ascensão de Água.",
  str_item_intro_3410103 = "Uma caixa avançada azul. Abra para escolher 1 material avançado de ascensão de Água.",
  str_item_intro_3410104 = "Uma caixa especial azul. Abra para escolher 1 material especial de ascensão de Água.",
  str_item_intro_3410201 = "Uma caixa básica rubra. Abra para escolher 1 material básico de ascensão de Fogo.",
  str_item_intro_3410202 = "Uma caixa normal rubra. Abra para escolher 1 material normal de ascensão de Fogo.",
  str_item_intro_3410203 = "Uma caixa avançada rubra. Abra para escolher 1 material avançado de ascensão de Fogo.",
  str_item_intro_3410204 = "Uma caixa especial rubra. Abra para escolher 1 material especial de ascensão de Fogo.",
  str_item_intro_3410301 = "Uma caixa básica verde. Abra para escolher 1 material básica de ascensão de Floresta.",
  str_item_intro_3410302 = "Uma caixa normal verde. Abra para escolher 1 material normal de ascensão de Floresta.",
  str_item_intro_3410303 = "Uma caixa avançada verde. Abra para escolher 1 material avançado de ascensão de Floresta.",
  str_item_intro_3410304 = "Uma caixa especial verde. Abra para escolher 1 material especial de ascensão de Floresta.",
  str_item_intro_3410401 = "Uma caixa básica amarela. Abra para escolher 1 material básico de ascensão de Trovão.",
  str_item_intro_3410402 = "Uma caixa normal amarela. Abra para escolher 1 material normal de ascensão de Trovão.",
  str_item_intro_3410403 = "Uma caixa avançada amarela. Abra para escolher 1 material avançado de ascensão de Trovão.",
  str_item_intro_3410404 = "Uma caixa especial amarela. Abra para escolher 1 material especial de ascensão de Trovão.",
  str_item_intro_3410501 = "Uma caixa preparada pela Coalizão Aurorian. Abra para escolher 1 material básico de ascensão de qualquer facção.",
  str_item_intro_3410502 = "Uma caixa preparada pela Coalizão Aurorian. Abra para escolher 1 material normal de ascensão de qualquer facção.",
  str_item_intro_3410503 = "Uma caixa preparada pela Coalizão Aurorian. Abra para escolher 1 material avançado de ascensão de qualquer facção.",
  str_item_intro_3410504 = "Uma caixa preparada pela Coalizão Aurorian. Abra para escolher 1 material especial de ascensão de qualquer facção.",
  str_item_intro_3410601 = "Uma caixa de Jaspe preparada pela Guilda Umbraton. Abra para escolher 1 Jaspe I.",
  str_item_intro_3410602 = "Uma caixa de Jaspe preparada pela Guilda Umbraton. Abra para escolher 1 Jaspe II.",
  str_item_intro_3410603 = "Uma caixa de Jaspe preparada pela Guilda Umbraton. Abra para escolher 1 Jaspe III.",
  str_item_intro_3410604 = "Um pacote usado anteriormente pela Coalizão Aurorian. Abra para escolher 1 presente valioso da facção.",
  str_item_intro_3410605 = "Você deixou uma marca significativa no Desolation Codex e recebeu a recompensa que merece.\nAbra para receber vários materiais de atualização aleatórios, além de uma pequena chance de obter Star Flares!",
  str_item_intro_3410606 = "Este baú do tesouro é a prova de seu profundo vínculo com os membros dos Caçadores Silenciosos. Abra-o para obter recompensas incríveis.",
  str_item_intro_3410607 = "Um baú com planta mecânico único. Abra-o para receber 1 Transporte.",
  str_item_intro_3410608 = "Uma caixa adquirida durante uma celebração festiva caótica. O conteúdo dentro permanece desconhecido. Quem não gosta de surpresas?",
  str_item_intro_3410609 = "Um pacote de presente especialmente encomendado. Abra-o para escolher 1 presente valioso.",
  str_item_intro_3410610 = "Rainbow Caixa de Pedidos III. Abra para escolher 1 material avançado de ascensão.",
  str_item_intro_3410611 = "Rainbow Caixa de Pedidos IV. Abra para escolher 1 material de ascensão premium.",
  str_item_intro_3410612 = "Escolha um dos Drusos Solamber do Trovão, Druso Solamber da Água, Druso Solamber da Floresta e Druso Solamber do Fogo para obter.",
  str_item_intro_3410613 = "Rainbow Order Box I. Abra para escolher 1 material básico de ascensão.",
  str_item_intro_3410614 = "Rainbow Ordem Caixa II. Abra-o para escolher 1 material de ascensão regular.",
  str_item_intro_3410615 = "Aberto para receber todos os materiais de atualização necessários para elevar um Auroriano à Ascensão III, incluindo: General Jasper II ×300, Nightium ×750.000, Caixa de Ordem de Coalizão I ×10, Caixa de Ordem de Coalizão II ×10, Caixa de Ordem de Coalizão III ×10, Rainbow Order Box I ×30, Rainbow Order Box II ×50, Rainbow Order Box III ×50 e Rainbow Order Box IV ×20.",
  str_item_intro_3410616 = "O esforço que você faz para fazer patrulhas duras e expulsões perigosas não é em vão. Abra isso e veja quais recompensas estão dentro!",
  str_item_intro_3420101 = "Aceite o suporte de Corax e ele se unirá a você em sua aventura!\nRecruta Corax e concede a você todos os materiais de melhoria necessários para alcançar a Ascensão I, Nv.10 dele.",
  str_item_intro_3420102 = "Aceite o suporte de Leona e ela se unirá a você em sua aventura!\nRecruta Leona e concede a você todos os materiais de melhoria necessários para alcançar a Ascensão I, Nv.10 dela.",
  str_item_intro_3420103 = "Aceite o suporte de Mia e ela se unirá a você em sua aventura!\nRecruta Mia e concede a você todos os materiais de melhoria necessários para alcançar a Ascensão I, Nv.10 dela.",
  str_item_intro_3420104 = "Aceite o suporte de Areia e ela se unirá a você em sua aventura!\nRecruta Areia e concede a você todos os materiais de melhoria necessários para alcançar a Ascensão I, Nv.10 dela.",
  str_item_intro_3420105 = "Aceite o suporte de Barton e ele se unirá a você em sua aventura!\nRecruta Barton e concede a você todos os materiais de melhoria necessários para alcançar a Ascensão I, Nv.25 dele.",
  str_item_intro_3420106 = "Aceite o suporte de Maggie e ela se unirá a você em sua aventura!\nRecruta Maggie e concede a você todos os materiais de melhoria necessários para alcançar a Ascensão I, Nv.25 dela.",
  str_item_intro_3420107 = "Aceite o suporte de Nemesis e ela se unirá a você em sua aventura!\nRecruta Nemesis e concede a você todos os materiais de melhoria necessários para alcançar a Ascensão I, Nv.25 dela.",
  str_item_intro_3420108 = "Aceite o suporte de Sikare e ela se unirá a você em sua aventura!\nRecruta Sikare e concede a você todos os materiais de melhoria necessários para alcançar a Ascensão I, Nv.25 dela.",
  str_item_intro_3420109 = "Aceite o suporte de Hydrad e ele se unirá a você em sua aventura!\nRecruta Hydrad e concede a você todos os materiais de melhoria necessários para alcançar a Ascensão II, Nv.1 dele.",
  str_item_intro_3420110 = "Aceite o suporte de Istvan e ele se unirá a você em sua aventura!\nRecruta Istvan e concede a você todos os materiais de melhoria necessários para alcançar a Ascensão II, Nv.1 dele.",
  str_item_intro_3420111 = "Aceite o suporte de Vivian e ela se unirá a você em sua aventura!\nRecruta Vivian e concede a você todos os materiais de melhoria necessários para alcançar a Ascensão II, Nv.1 dela.",
  str_item_intro_3420112 = "Aceite o suporte de Louise e ela se unirá a você em sua aventura!\nRecruta Louise e concede a você todos os materiais de melhoria necessários para alcançar a Ascensão II, Nv.1 dela.",
  str_item_intro_3420113 = "Escolha um Aurorian da seguinte lista de Aurorianos de 6 estrelas para lutar ao seu lado: <color=#ffffff>Hiiro/Sinsa/Eve/Uriel/Carleen/Sharona/Sariel/Raphael/Connolly/Charon/Eicy/Victoria/Jona/Nikinis/Gabriel/Migard/Michael/Gronru/Irridon/Wrath</color>.\nNota: O Kit de Recrutamento de Ano Novo tem um tempo limite. Quando expirar, será automaticamente convertido em 3000 Lumamber e enviado para você pela caixa de correio do jogo. Por favor, use-o antes das 09:00, 28 de fevereiro de 2022 (UTC+0), 04:00, 28 de fevereiro de 2022 (UTC-5). Por favor, converta este horário para o seu respectivo fuso horário.",
  str_item_intro_3420114 = "Após o uso, você pode selecionar um dos seguintes Aurorianos de 5 estrelas para participar de sua aventura.\n（<color=#ffffff>Nemesis, Barton, Maggie, Sikare</color>）",
  str_item_intro_3420115 = "Após o uso, você pode escolher um Aurorian (<color=#ffffff>Lucoa</color> ou <color=#ffffff>Elma</color>) para se juntar à sua aventura.",
  str_item_intro_3420116 = "Após o uso, você pode selecionar um dos seguintes Aurorianos de 5 estrelas para participar de sua aventura.\n(<color=#ffffff>Faust, Kleken, Pact ou Beverly</color>)",
  str_item_intro_3420134 = "Após o uso, você pode selecionar um dos seguintes Aurorianos de 6 estrelas para participar de sua aventura.\n(<color=#ffffff>Sinsa, Eve, Fleur, Jona</color>)",
  str_item_3420134 = "Caixa de Seleção Elite Rediesel",
  str_item_intro_3420117 = "Escolha um Aurorian da seguinte lista de Aurorian de 5 estrelas para lutar ao seu lado: <color=#ffffff>Kayano/Erica/Dayna/Vivian/Mia/Nemesis/Regina/Robyn/Faust/Kleken/Barton/Keating/Louise/Noah/Hydrad/Schwartz/Maggie/Istvan/Barbara/Leona/Pact/Odi/Philyshy/Corax/Benny and Curo/Cuscuta/Areia/Sikare Dantes/Beverly/Taki/Genevieve/Naroxel/Cordy</color>.",
  str_item_intro_3420118 = "Escolha um Auroriano da seguinte lista de Aurorianos de 6 estrelas para lutar ao seu lado: <color=#ffffff>Hiiro, Sinsa, Eve, Uriel, Carleen, Sharona, Sariel, Raphael, Connolly, Charon, Eicy, Victoria, Jona, Nikinis, Gabriel, Migard, Michael, Gronru, Irridon, Wrath, Beryl, Fleur, Smokey, Revy, Gram, Paloma, Bethel, Luke, Hedy, ou Novio</color>.\nNota: O Kit de Recrutamento de 1 ano expirará às 09:00, 31 de agosto de 2022 (UTC+0), 04:00, 31 de agosto de 2022 (UTC-5). Se não for resgatado até então, será automaticamente convertido em 3000 Lumamber, que serão enviados para você através do correio do jogo.",
  str_item_intro_3420119 = "Após o uso, você pode selecionar um dos seguintes Aurorianos de 5 estrelas para participar de sua aventura.\n(<color=#ffffff>Hydrad, Istvan, Louise ou Vivian</color>)",
  str_item_intro_3420120 = "Após o uso, você pode selecionar um dos seguintes Aurorianos de 5 estrelas para participar de sua aventura.\n(<color=#ffffff>Areia, Philyshy, Schwartz ou Naroxel</color>)",
  str_item_intro_3420121 = "Após o uso, você pode selecionar um dos seguintes Aurorianos de 5 estrelas para participar de sua aventura.\n(<color=#ffffff>Fox, Violet</color>)",
  str_item_intro_3420122 = "Após o uso, você pode selecionar um dos seguintes Aurorianos de 5 estrelas para participar de sua aventura.\n(<color=#ffffff>Corax, Benny and Curo, Odi e Schwartz</color>)",
  str_item_intro_3420123 = "Escolha um Aurorian da seguinte lista de Aurorian de 5 estrelas para lutar ao seu lado: <color=#ffffff>Sanae/Roy/Kayano/Erica/Dayna/Vivian/Mia/Nemesis/Regina/Robyn/Faust/Kleken/Barton/Keating/Louise/Noah/Hydrad/Schwartz/Maggie/Istvan/Barbara/Leona/Pact/Odi/Philyshy/Corax/Benny and Curo/Cuscuta/Areia/Sikare Dantes/Beverly/Taki/Genevieve/Naroxel</color>.",
  str_item_intro_3420124 = "Após o uso, você pode selecionar um dos seguintes Aurorianos de 5 estrelas para participar de sua aventura.\n(<color=#ffffff>Noah, Barbara, Odi, Keating</color>)",
  str_item_intro_3420125 = "Escolha um Aurorian da seguinte lista de Aurorian de 5 estrelas para lutar ao seu lado: <color=#ffffff>Casta/Ciel/Sanae/Roy/Kayano/Erica/Dayna/Vivian/Mia/Nemesis/Regina/Robyn/Faust/Kleken/Barton/Keating/Louise/Noah/Hydrad/Schwartz/Maggie/Istvan/Barbara/Leona/Pact/Odi/Philyshy/Corax/Benny and Curo/Cuscuta/Areia/Sikare/Beverly/Taki/Genevieve/Naroxel/Cordy</color>.",
  str_item_intro_3420126 = "Estas são as bênçãos de seus companheiros de aventura. Escolha um Auroriano da seguinte lista de Aurorianos de 5 estrelas para lutar ao seu lado: <color=#ffffff>Hydrad/Istvan/Louise/Roy</color>.",
  str_item_intro_3420127 = "Escolha um Aurorian da seguinte lista de Aurorian de 6 estrelas para lutar ao seu lado: <color=#ffffff>Victoria, Raphael, Connolly, Uriel, Gronru, Charon, Carleen, Sinsa, Sharona, Gabriel, Nikinis, Eve, Jona, Michael, Wrath, Irridon, Sariel, Eicy, Migard, Hiiro, Beryl, Fleur, Smokey, Revy, Gram, Paloma, Bethel, Luke, Hedy, Novio, Siobhan, Florine, Ruby, Rinne, Amemori, Yao, Azure, Lenore, Giles, Barton: Deft Blades.</color>.\nObservação: este kit expira às 09:00 de 31 de março de 2023 (UTC+0), 04:00 de 31 de março de 2023 (UTC-5). Reivindique-o a tempo, ou ele será automaticamente convertido em 3.000 Lumamber e enviado a você pela caixa de correio do jogo.",
  str_item_intro_3420128 = "Após o uso, você pode selecionar um dos seguintes Aurorianos de 5 estrelas para participar de sua aventura.\n(<color=#ffffff>Hydrad, Louise, Istvan, Roy</color>)",
  str_item_intro_3420129 = "Escolha um Aurorian da seguinte lista de Aurorian de 5 estrelas para lutar ao seu lado: <color=#ffffff>Beretta/Casta/Ciel/Sanae/Roy/Kayano/Erica/Dayna/Vivian/Mia/Nemesis/Regina/Robyn/Faust/Kleken/Barton/Keating/Louise/Noah/Hydrad/Schwartz/Maggie/Istvan/Barbara/Leona/Pact/Odi/Philyshy/Corax/Benny and Curo/Cuscuta/Areia/Sikare/Beverly/Taki/Genevieve/Naroxel/Cordy</color>.",
  str_item_intro_3420132 = "Escolha um Auroriano da seguinte lista de Aurorianos de 5 estrelas para lutar ao seu lado: <color=#ffffff>Beretta/Casta/Ciel/Sanae/Roy/Kayano/Erica/Dayna/Vivian/Mia/Nemesis/Regina/Robyn/Faust/Kleken/Barton/Keating/Louise/Noah/Hydrad/Schwartz/Maggie/Istvan/Barbara/Leona/Pact/Odi/Philyshy/Corax/Benny and Curo/Cuscuta/Areia/Sikare/Beverly/Taki/Genevieve/Naroxel/Cordy/Kya/Kristen/Blanc: Pura Cordis/Joselyne</color>.",
  str_item_intro_3420135 = "Escolha um Auroriano da seguinte lista de Aurorianos de 5 estrelas para lutar ao seu lado: <color=#ffffff>Beretta/Casta/Ciel/Sanae/Roy/Kayano/Erica/Dayna/Vivian/Mia/Nemesis/Regina/Robyn/Faust/Kleken/Barton/Keating/Louise/Noah/Hydrad/Schwartz/Maggie/Istvan/Barbara/Leona/Pact/Odi/Philyshy/Corax/Benny and Curo/Cuscuta/Areia/Sikare/Beverly/Taki/Genevieve/Naroxel/Cordy/Kya/Kristen/Blanc: Pura Cordis/Joselyne/Isa/Li Tianxian</color>.",
  str_item_intro_3420130 = "Escolha um Aurorian da seguinte lista de Aurorian de 6 estrelas para lutar ao seu lado: <color=#ffffff>Victoria, Raphael, Connolly, Uriel, Gronru, Charon, Carleen, Sinsa, Sharona, Gabriel, Nikinis, Eve, Jona, Michael, Wrath, Irridon, Sariel, Eicy, Migard, Hiiro, Beryl, Fleur, Smokey, Revy, Gram, Paloma, Bethel, Luke, Hedy, Novio, Siobhan, Florine, Ruby, Rinne, Amemori, Yao, Azure, Lenore, Giles, Barton: Deft Blades, Nina, Carleen: Smoldering Soul, Fia, Jeno, Pollux, Lilica, Minos, Axelia, Vic.</color>.\nObservação: este kit expira às 09:00 de 31 de agosto de 2023 (UTC+0), 04:00 de 31 de agosto de 2023 (UTC-5). Reivindique-o a tempo, ou ele será automaticamente convertido em 3.000 Lumamber e enviado a você pela caixa de correio do jogo.",
  str_item_intro_3430101 = "Abra para selecionar Corax, Leona, Mia ou Areia. Você também recebe todos os materiais de melhoria necessários para subir o Aurorian para Ascensão I, Nv.10!",
  str_item_intro_3430102 = "Abra para selecionar Barton, Maggie, Nemesis ou Sikare. Você também recebe todos os materiais de melhoria necessários para subir o Aurorian para Ascensão I, Nv.25!",
  str_item_intro_3430103 = "Abra para selecionar Hydrad, Istvan, Vivian ou Louise. Você também recebe todos os materiais de melhoria necessários para subir o Aurorian para Ascensão II, Nv.1!",
  str_item_intro_3440001 = "Use-o para obter chocolates escuros, Lumamber e materiais de atualização aleatórios de Auroria.",
  str_item_intro_3440002 = "Use para obter Sunny Sweets, Lumamber e materiais de atualização aleatórios de Auroria.",
  str_item_intro_3440003 = "O capitão Mu Yuebai entregou um envelope vermelho a todos quando vocês celebraram o Festival da Primavera juntos no Shadowind. Que tipo de surpresa poderia estar lá dentro?",
  str_item_intro_3440005 = "Use para obter Lumamber e materiais de atualização aleatórios de Auroria.",
  str_item_intro_3500001 = "Material misterioso encontrado em ruínas antigas. Contém grande poder e é essencial para reparar equipamentos.",
  str_item_intro_3500003 = "Promove instantaneamente um Aurorian para Ascensão II, Nv.1.\nUma relíquia antiga e misteriosa que contém uma substância e brilha intensamente. Pode aumentar muito o poder de um Aurorian.",
  str_item_intro_3511001 = "Aumenta o nível de Iluminação da Água.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar um trecho do treinamento de iluminação.",
  str_item_intro_3511002 = "Aumenta o nível de Iluminação da Água.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar um segmento aleatório do treinamento de iluminação.",
  str_item_intro_3511003 = "Aumenta o nível de Iluminação da Água.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar uma parte do treinamento de iluminação.",
  str_item_intro_3511004 = "Aumenta o nível de Iluminação da Água.\nIncorpore este cubo misterioso fornecido por Enlightener perfeitamente em um tablet para ativar e revelar uma parte importante do treinamento de iluminação.",
  str_item_intro_3511005 = "Aumenta o nível de Iluminação da Água.\nIncorpore este cubo misterioso fornecido por Enlightener perfeitamente em um tablet para ativar e revelar uma sequência chave do treinamento de iluminação.",
  str_item_intro_3512001 = "Aumenta o nível de Iluminação do Fogo.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar um trecho do treinamento de iluminação.",
  str_item_intro_3512002 = "Aumenta o nível de Iluminação do Fogo.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar um segmento aleatório do treinamento de iluminação.",
  str_item_intro_3512003 = "Aumenta o nível de Iluminação do Fogo.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar uma parte do treinamento de iluminação.",
  str_item_intro_3512004 = "Aumenta o nível de Iluminação do Fogo.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar uma parte importante do treinamento de iluminação.",
  str_item_intro_3512005 = "Aumenta o nível de Iluminação do Fogo.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar uma sequência chave do treinamento de iluminação.",
  str_item_intro_3513001 = "Aumenta o nível de Iluminação da Floresta.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar um trecho do treinamento de iluminação.",
  str_item_intro_3513002 = "Aumenta o nível de Iluminação da Floresta.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar um segmento aleatório do treinamento de iluminação.",
  str_item_intro_3513003 = "Aumenta o nível de Iluminação da Floresta.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar uma parte do treinamento de iluminação.",
  str_item_intro_3513004 = "Aumenta o nível de Iluminação da Floresta.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar uma parte importante do treinamento de iluminação.",
  str_item_intro_3513005 = "Aumenta o nível de Iluminação da Floresta.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar uma sequência chave do treinamento de iluminação.",
  str_item_intro_3514001 = "Aumenta o nível de Iluminação do Trovão.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar um trecho do treinamento de iluminação.",
  str_item_intro_3514002 = "Aumenta o nível de Iluminação do Trovão.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar um segmento aleatório do treinamento de iluminação.",
  str_item_intro_3514003 = "Aumenta o nível de Iluminação do Trovão.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar uma certa parte do treinamento de iluminação.",
  str_item_intro_3514004 = "Aumenta o nível de Iluminação do Trovão.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar uma parte importante do treinamento de iluminação.",
  str_item_intro_3514005 = "Aumenta o nível de Iluminação do Trovão.\nIncorpore este misterioso cubo fornecido por Enlightener perfeitamente em um tablet para ativar e revelar uma sequência chave do treinamento de iluminação.",
  str_item_intro_3621001 = "Uma cadeira almofada de encosto alto. Com um grande suporte para as costas, confortável para sonecas.",
  str_item_intro_3621002 = "Um sofá pequeno, para uma pessoa. Como não tem um encosto, talvez uma mesa pequena deva ser colocada a sua frente...",
  str_item_intro_3621003 = "Um sofá grande para duas pessoas, apesar de também ser confortável com uma pessoa só...",
  str_item_intro_3621004 = "Um sofá incomum para até quatro pessoas. Perfeito para encontros grandes.",
  str_item_intro_3621005 = "Uma pequena mesa hexagonal, usada para bebidas, bules, copos e lanches. Melhor em quartos pequenos.",
  str_item_intro_3621006 = "Uma mesa longa de chá, normalmente combinada com um sofá duplo ou quádruplo. Melhor em quartos grandes.",
  str_item_intro_3621007 = "Um dispositivo que serve bebidas automaticamente, contanto que tenha os ingredientes certos. Não dá para fazer café só com açúcar e água...",
  str_item_intro_3621008 = "Um instrumento musical, supostamente de uma tribo desconhecida de uma terra distante, popular em Umbraton. Normalmente composto de um tambor grande e vários tambores e pratos pequenos, outros instrumentos percussivos também podem ser adicionados. Independentemente da configuração, o conjunto é tocado por um único músico.",
  str_item_intro_3621009 = "Uma pequena planta em um vasinho. Ajuda a purificar o ar e dá um pouco de verde para uma sala.",
  str_item_intro_3621010 = "Planta envasada, alta como uma pessoa, purifica o ar ao redor e deixa qualquer sala um pouco mais natural. Também serve como esconderijo.",
  str_item_intro_3622001 = "Uma pintura de paisagem complexa e extravagante. Permite que o observador aprecie a beleza da natureza sem sair de casa.",
  str_item_intro_3623001 = "Uma lâmpada em forma de sol que pode ser fixada no teto. Recebe seu nome por sua iluminação intensa e grande área de cobertura.",
  str_item_intro_3623002 = "Lâmpada leve, fácil de instalar em ambiente interno com um suporte de ferro. Uma variedade ampla de decorações podem ser fixadas nela, tornando-a bem popular.",
  str_item_intro_3623003 = "Fornece uma brisa refrescante a qualquer sala. Era originalmente usado para canalizar ar limpo nas Subcidades. Logo depois foi descoberto que poderia mantar salas refrescantes e confortáveis.",
  str_item_intro_3623004 = "Lâmpadas instaladas em tetos. Usada por muitas cidades-Estados pelo baixo consumo de energia, ampla iluminação e tamanho compacto.",
  str_item_intro_3623005 = "Uma luz para ser pendurada no teto. Sua estrutura de trava articulada facilita o ajuste, mas ela balança em terremotos ou ventanias, o que pode ser perigoso. Por essa razão, esse tipo de luz é proibido em navios.",
  str_item_intro_3631001 = "Uma mobília luxuosa importada do Oriente por uma frota que dominou os oceanos. Estilo e cores elegantes, mas delicada ao toque. Cuidado ao colocá-la.",
  str_item_intro_3631002 = "Um ícone em forma de sol. Silencioso e solene, fortalece a fé de todos que o veem.",
  str_item_intro_3631003 = "Um barril grande e belo, feito por um artesão lendário. Apenas o melhor vinho pode ser armazenado em um recipiente precioso como esse.",
  str_item_intro_3631004 = "Dizem ser originária do Oriente, essa peça de mobília simples, mas útil, pode bloquear vento, separar espaços e fornecer privacidade. Além do mais, ela pode ser enfeitada para embelezar o espaço ao redor e criar um ar de mistério para seu dono. Tornou-se rapidamente popular nas cidades de Astra.",
  str_item_intro_3631005 = "Um instrumento dourado enorme, adornado com várias gemas que representam diferentes corpos celestiais. Ajuda estudiosos a se familiarizarem com astrologia e realizar adivinhações rapidamente, mas com precisão questionável...",
  str_item_intro_3632001 = "Um dispositivo de comunicação da Federação Illumina originário das Subcidades. Como as comunicações entre as cidades-Estado aumentaram, a adoção dessa tecnologia especial também.",
  str_item_intro_3632002 = "Um cálice dourado, frequentemente visto nas celebrações de Lumópolis. O criador também infundiu o cálice com Luminática desconhecida, concedendo um par de asas móveis ilusórias.",
  str_item_intro_3632003 = "Essa placa gravada representa a história antiga da civilização de Lumópolis. Dizem que cada padrão contém várias alusões literárias. Apenas vê-la causa uma sensação de atemporalidade...",
  str_item_intro_3632004 = "Um castiçal melhorado por Luminática, nunca é escurecido por fumaça e pode acender e extinguir automaticamente sua própria vela.",
  str_item_intro_3632005 = "Um relógio de parede, resultado da fusão harmoniosa entre o maquinário de Illumina e o artesanato de Lumópolis. Sua função principal é puramente decorativa, mas, por acaso, ele consegue marcar o tempo com precisão.",
  str_item_intro_3641101 = "Uma armadura decorativa, é uma peça tradicional entre os clãs nobres de Lumópolis, particularmente aqueles com histórias de guerreiros. Também serve para lembrar seus descendentes da nobreza de sua herança matrimonial e desencorajar comportamentos hedonistas na família.",
  str_item_intro_3641201 = "Uma mobília amada pelas pessoas de Umbraton que se passam por pessoas de cultura. É feita de uma madeira preciosa e possui livros clássicos e recipientes preciosos colocados nela. Porém, alguém pode simplesmente questionar a autenticidade dessas antiguidades...",
  str_item_intro_3641301 = "Um suporte de rifle produzido pela Federação Illumina que preenche qualquer sala com o espírito de batalha. Deixe que a força principal de combate contra os Eclipsitas pensem em mobílias como essa. Comparado aos modelos anteriores, esse suporte é mais leve, mas possui maior estabilidade.",
  str_item_intro_3641501 = "Um modelo em escala de um automóvel completo com canos, rebites, todos os tipos de metal e até partes de madeira. Esse pequeno modelo é a imagem do orgulho da Rediesel Wrench, o conversível Powerball.",
  str_item_intro_3641102 = "Um tapete de tecido luxuoso feito por um artesão habilidoso de Lumópolis. Não é um tapete que qualquer pessoa pode comprar... Além de ser muito valioso, também parece ser um símbolo de status.",
  str_item_intro_3641202 = "Um grande tapete preto produzido em Umbraton. Macio e espesso, foi tecido com maestria e silencia passos completamente.",
  str_item_intro_3641302 = "Um tapete quadrado com uma trama horizontal e vertical, representativa do estilo industrial da Federação Illumina. Basta uma olhada para saber que foi produzido pelas fábricas da Cidade Gannon. Muito resistente.",
  str_item_intro_3641402 = "Um tapete pesado e espesso, tecido com muito algodão de Northland e várias peles de animais. Fornece conforto até nos ambientes mais frios.",
  str_item_intro_3641502 = "Os grosseiros de Rediesel Wrench devem ter costurado roupas velhas aleatoriamente para fazer isso... O cheiro de Rediesel indica que eles devem tê-lo usado para tingir esse tapete. Alguém realmente pagaria por isso, para colocar em casa?",
  str_item_intro_3641602 = "Um carpete vermelho que chama a atenção, com um padrão quase imperceptível. Ao analisar de perto, o padrão parece estremecer e se contorcer, causando uma sensação de desconforto e mal-estar naqueles que olham para ele... Quem compraria esse carpete?",
  str_item_intro_3642102 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nUma obra-prima produzida por um pintor desconhecido de Lumópolis. O original pode ser encontrado na coleção de um nobre de alto ranque, e isto, obviamente, é uma réplica. As extraordinárias habilidades de pintura deixam o espectador à vontade após olhá-la e, é por isso, que tantas cópias foram feitas. Mesmo assim, toda cópia é consideravelmente cara, e os compradores lutam por uma chance de ter um para si.",
  str_item_intro_3642201 = "As forças clandestinas de Umbraton lutam abertamente e nas sombras. Essas duas espadas são usadas quando possuem uma disputa que não pode ser reconciliada. As duas partes da disputa nomeiam um espadachim para duelar com essas espadas, a fim de resolver o problema.",
  str_item_intro_3642301 = "Outro exemplo da forte influência militar na mobília Illumina, esse rifle é a primeira coisa que vem à mente quando os membros de Illumina pensam em decoração de paredes. Parece que estão sempre prontos para a guerra.",
  str_item_intro_3642401 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nMesmo em Northland invernal, o verde permanece. Dessa forma, os locais a veem como um símbolo de esperança e abundância, com a expressão: “Sem visco, sem felicidade”. Eles geralmente colhem e tecem a planta em uma guirlanda para trazer sorte para o lar.",
  str_item_intro_3641103 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nEste item representa o poder que príncipes e nobres de Lumópolis carregam. Decorado extravagantemente e feito de metais preciosos, ele transmite a tentação de poder e simboliza o peso que ele traz.",
  str_item_intro_3641503 = "Uma confusão de sucata, placas de metal e rebites, com uma almofada sabe-se lá de onde...\nApesar de estar um pouco grosseiro e danificado, é macio e surpreendentemente resistente.",
  str_item_intro_3651001 = "Um pequeno modelo em escala da Torre. Uma réplica de alta qualidade do original, e parece conter o poder selado do original também.",
  str_item_intro_3651002 = "Parece uma versão em miniatura extremamente realista da Torre. Você pode sentir um poder antigo misterioso na Torre quando se aproxima dela.",
  str_item_intro_3651003 = "Apenas aqueles que exploram os níveis mais altos da Torre podem obter essa decoração. Não é apenas extremamente realista, mas também possui parte do poder da Torre. Quando virem isso, se sentirão na frente da Torre verdadeira.",
  str_item_intro_3651004 = "Essa é uma lembrança extremamente rara que pode ser obtida apenas pelos que exploram a Torre. Apesar de ser só um modelo, ele parece igual à Torre. Se observá-lo com cuidado, você pode ver vários detalhes da Torre verdadeira. Dizem que ela pode afetar a Torre verdadeira...",
  str_item_intro_3651005 = "Uma recordação misteriosa entregue por uma torre e obtida apenas ao explorar as profundezas dela. Dizem que simboliza o desejo da torre e seu reconhecimento daqueles que são corajosos o suficiente para explorá-la.",
  str_item_intro_3651101 = "Uma estatueta de Eclipsita em miniatura encontrada no Território Secreto, provavelmente uma lembrança deixada por outro explorador. Falta a ferocidade do original, e até parece mais fofo... Assim que você se acostuma com ela.",
  str_item_intro_3651102 = "Encontrada nas profundezas do Território Secreto, essa estatueta parece ter sido feita com a aparência de algum Eclipsita de alto nível. Por seu rosto hediondo, pode causar medo em muitas pessoas, mesmo que não se mova. Porém, se você se acostumar, pode usá-la para assustar bandidos que invadem seu quarto...",
  str_item_intro_3651201 = "Uma estatueta extremamente rara que parece com Soroz. Criada com Luminática concentrada de amigos do Navegador, e produzida com técnicas misteriosas de Soroz. Ela representa o laço inabalável entre Soroz, o Navegador e seus colegas.",
  str_item_intro_3662001 = "Após fugir da perseguição dos Eclipsitas, para comemorar a primeira vez que todos se encontraram, Soroz pediu especialmente para Vaga-lume desenhar esse quadro baseado na imagem que ele registrou. A recriação da cena foi tão realista que muitos pensaram ser uma foto.",
  str_item_intro_3661101 = "Uma rocha encontrada na Ravina Olho Rubro que contém uma pequena quantidade do poder vulcânico e é quente ao ser tocada. De vez em quando, ela faz um som retumbante ou causa uma pequena erupção, mas é inofensiva. Aqueles valentes o suficiente podem usá-la para cozinhar.",
  str_item_intro_3661102 = "As flores brancas do amanhecer, que Dawn plantou na Ravina Olho Rubro, florescem uma vez em poucos anos. As flores são lindas e seu significado floriográfico é \"a esperança do amanhecer\".",
  str_item_intro_3662101 = "Devido à sua doença, Eve só podia beber água fria a 15 graus e água quente a 45 graus. No Deserto Rediesel, lugar em que água é escassa, Sinsa sempre tem duas garrafas termais para que sua irmãzinha tenha água para beber. Ele até desenhou um rosto sorridente na garrafa para deixar sua irmã feliz.",
  str_item_intro_3661103 = "Apesar do dojo não existir, o suporte de katana do Dojo Sakae é mantido em boas condições. Limpe a poeira e coloque katanas nele para recriar o passado glorioso do Dojo Sakae.",
  str_item_intro_3661104 = "Essa cerejeira rara e colorida só é encontrada nos arredores da Montanha Nebulosa. Pessoas gostam de deixar todos os tipos de bênçãos nela e rezam para que seus desejos se realizem.",
  str_item_intro_3662102 = "Uma pintura exótica de um dragão feroz dançante mostrando suas garras e presas. Porém, ao invés de intimidar as pessoas, ela dá uma sensação de segurança inexplicável. Talvez esteja relacionada à cultura única do Oriente.",
  str_item_intro_3661105 = "Um daruma popular na região da Montanha Nebulosa. Mantenha em casa para boa sorte. Talvez realize os desejos de seu dono.",
  str_item_intro_3661106 = "Um daruma que parece feroz. Mantenha isso em casa para afastar má sorte e impedir pessoas ruins de baterem à sua porta.",
  str_item_intro_3661107 = "Um daruma que às vezes brilha com uma luz dourada. Você quase consegue ver uma fortuna vindo em sua direção ao olhá-la. Bem, esperamos que ela venha.",
  str_item_intro_3661108 = "Um daruma que representa o conhecimento. Dizem que esse daruma atrai sucesso acadêmico, muitos estudantes oram para obter um. Ele deve ser muito popular na Cidade Gannon.",
  str_item_intro_3661109 = "Dizem que todo mundo encontra um daruma que combina com si mesmo. Essas bonecas concedem seus maiores desejos e abençoam você por toda sua vida.",
  str_item_intro_3661110 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nUm modelo do supervalorizado castelo à beira-mar, captura perfeitamente a aura misteriosa e estranha.\nÀs vezes, vozes indistintas são ouvidas de dentro das paredes, que não são completamente diferentes das lendas antigas que cercam essa estrutura.",
  str_item_intro_3661111 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nApós analisar a tecnologia de Soroz, Fleur criou um maquinário chamado \"Aço Rediesel MkV Zero\", que é um modelo. Comparado ao maquinário real, este modelo possui um desempenho incrementado e pode-se dizer que é perfeito, exceto por ser superpequeno.",
  str_item_intro_3661112 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nUm carro feito para ganhar uma grana extra no verão. Contém equipamento especial para fazer cubos de gelo e transformá-los em raspadinhas, fornecendo um refresco delicioso em dias quentes de verão a clientes sortudos. Apesar da temporada de raspadinha ter acabado, o equipamento no carrinho ainda funciona e às vezes liga sozinho (uma clara demonstração de que ele acredita ser jovem demais para ser aposentado).",
  str_item_intro_3661113 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nUm sofá inflável feito pelo Hotel Tir'. É equipado com arminha de água nos fundos, que espirra água em intervalos regulares e deixa todos aliviados e refrescados no sol escaldante do verão.",
  str_item_intro_3661114 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nUm sofá inflável feito pelo Hotel Tir'.\nO dispositivo de espirrar atrás da almofada gera um spray similar ao de uma fonte em intervalos regulares. Apesar de aliviar o calor, essa fonte é consideravelmente poderosa e costuma assustar quem se senta nele.",
  str_item_intro_3661115 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nUm sofá inflável feito pelo Hotel Tir'.\nDeve ser utilizado com cuidado, pois há um detonador de fogos de artifício automático nos fundos. Ao ativá-lo, ele solta inúmeros fogos de artifício e fornece a todos nos arredores um pequeno show de fogos. O ângulo de lançamento garante que as pessoas sentadas nele fiquem fora de perigo, mas não quer dizer que não dará um grande susto.",
  str_item_intro_3661116 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nUm sofá inflável feito pelo Hotel Tir'.\nOs puxadores nas laterais são máquinas de bolha. Ao ativá-los, bolhar coloridas enchem o ambiente. Muito popular com as crianças.",
  str_item_intro_3661117 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nUm sofá d'água portátil feito pelo Hotel Tir'.\nApós abrir este sofá, é possível decorá-lo com acessórios de coqueiros. Ao enchê-lo com água, ele faz o cotidiano parecer um dia na praia.",
  str_item_intro_3661118 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nUma prancha de surfe feita pelo Hotel Tir'. Feita com materiais especiais, resulta em uma prancha leve, durável e forte. Com seu formato aquadinâmico especialmente criado, esta prancha de surfe é capaz de dominar qualquer onda.",
  str_item_intro_3662103 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nUma lembrança da sua época no festival O Monarca do Oceano. Quando você olha para o mar e o céu azuis, e para a praia com suas árvores verdes balançando, é como se estivesse de novo na praia, revivendo aquele dia feliz.",
  str_item_intro_3661119 = "Item de mobília. Pode ser colocada nas salas da sua Colossus.\nA Subcidade 24 é uma das bases essencias da Linha Dunafogo e assume a maioria das operações médicas, treinamento, logística da vanguarda, dentre outros deveres. Esse modelo em miniatura reflete perfeitamente sua natureza abrangente.",
  str_item_intro_3661120 = "Item de mobília. Pode ser colocada nas salas da sua Colossus.\nA mesa de expedição era para uso interno da Academia Militar da Federação Illumina. Ela foi planejada por técnicos especiais e feita na escala apropriada. Essa mesa, composta de areia, madeira e modelos, simula com precisão a situação estratégia de um campo de batalha real e permite que estudantes conduzam exercícios de guerra sob diferentes condições de batalha.",
  str_item_intro_3661121 = "Item de mobília. Pode ser colocada nas salas da sua Colossus.\nO corpo principal desse quadro de coleção de medalhas é uma placa de ferro marcada com muitos buracos. Dizem que esse item é um tributo aos esforços valentes das Forças de Pedra contra os Eclipsitas. Também é símbolo de sua glória duradoura. As medalhas penduradas representam que as Forças de Pedra nunca estão distantes e sempre permanecerão firmes na Linha Defensiva com cada nova geração de soldados para deter a ameaça Eclipsita.",
  str_item_intro_3662104 = "Item de mobília. Pode ser colocada nas salas da sua Colossus.\nA Federação Illumina requisitou especialmente esse banner para os defensores da Linha Dunafogo para condecorá-los por repelir uma grande invasão de Eclipsitas. Sempre que defensores veem esse banner tremulando na linha defensiva, o senso de honra que ele transmite os lembra de sua crença solene: onde a vida estiver em perigo, é onde estaremos.",
  str_item_intro_3661122 = "Não se preocupe... Não tem nenhum cadáver enterrado aqui, então não dá pra chamar isso de lápide de verdade. O quê? Essa mão? Ah, é tudo parte do show!",
  str_item_intro_3661123 = "Aparece sempre que você se recusa a dar Noitium! Bem, ele não pode falar, na verdade, não é um fantasma... É só uma galinha debaixo de um lençol.",
  str_item_intro_3662105 = "Na verdade, esse abajur é feito de painéis de madeira em forma de abóbora. Quando ligado, a luz brilha em seus olhos, nariz e boca, criando uma atmosfera um tanto sombria.",
  str_item_intro_3661124 = "Branca de cima a baixo, com um topo perfeitamente reto, essa torre serve como o símbolo de Eraveil. Esse modelo refinado mostra a aparência daquele monumento de maneira perfeita.",
  str_item_intro_3661125 = "Uma boneca de uma jovem Celestita. Fica muito bonitinha se a colocar no chão... E parece que os vaga-lumes gostaram muito dela.",
  str_item_intro_3661126 = "Um dente-de-leão plantado. Embora a flor pareça muito frágil, essa planta obstinada pode sobreviver em qualquer lugar, desde que tenha água e terra.",
  str_item_intro_3661127 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nÉ só um modelo? Não, é um mundo em miniatura! Não só possui um trem em movimento, mas também uma paisagem natural realista, incluindo montanhas, rios e árvores! Observe o trem em torno da montanha por um momento, e você se sentirá uma parte deste pequeno mundo, absorvendo a bela paisagem.",
  str_item_intro_3661128 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nAgora você também pode contemplar as lindas árvores de outono na Colossus! Por algum motivo, este bonsai mantém a cor da estação durante todo o ano. Suas folhas amarelas caem ocasionalmente, permitindo que você se deleite com a personificação melancólica do outono a qualquer hora e em qualquer lugar, mesmo fazendo ainda mais bagunça para os vagalumes limparem.",
  str_item_intro_3661129 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nEssa flor sempre está virada para o sol! Observe esta plantinha no vaso cheia de positividade... coloque-a no seu quarto e veja-o se encher de calor e otimismo.",
  str_item_intro_3661130 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nUm cinto dourado simboliza sua honra e prova o sangue, suor e lágrimas derramados por você na Arena Sombria de Umbraton. Embora você não deixe ninguém tocá-lo, eles podem admirar a distância.",
  str_item_intro_3661131 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nUma transação razoável deve ser justa para ambos os lados. Como símbolo da pesagem de mercadorias, esta balança folheada a ouro representa o conceito de justiça reconhecido por ambas as partes. É frequentemente colocada nos saguões das guildas de Umbraton, para mostrar aos convidados que seus acordos são justos e honestos.",
  str_item_intro_3662106 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nUm leque cheio de cultura estrangeira. Feito de papel macio e resistente. Os desenhos nele expressam um estilo exótico raramente visto nesta parte do mundo.",
  str_item_intro_3662107 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nUm mosaico de vitral produzido por um artesão de Lumópolis que transcende a beleza da própria natureza. Quando a luz brilha nele, isso reflete suas cores vívidas para um efeito lindo e ofuscante.",
  str_item_intro_3661132 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nSupostamente um dragão de gelo que patrulhava os céus de Northland, apesar de atualmente ser uma mera estátua inofensiva. Também ainda emite um vestígio de ar frio. Que conveniente!",
  str_item_intro_3661133 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nA prateleira e os mantos parecem comuns, mas de acordo com alguns antigos anciões, há uma história magnífica por trás deles…",
  str_item_intro_3661134 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nDe acordo com algumas lendas populares de Northland, você encontrará seu amor verdadeiro se usá-lo!",
  str_item_intro_3661135 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nO tipo mais comum de casa em Northland. Replicou com exatidão até a fumaça esporádica subindo da chaminé de um telhado cheio de neve. As luzes nas janelas dão a impressão de que a casa de miniatura está de fato ocupada.",
  str_item_intro_3662109 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nA cabeça de uma rena, mas não de uma verdadeira. Na verdade, é pelo estufado com madeira lascada, e tem um mecanismo especial para fazer os olhos se mexerem de vez em quando!",
  str_item_intro_3661136 = "Mobília para sala na Colossus.\nNada pode expressar o amor mais do que cozinhar e servir uma parte do seu próprio corpo. Considerando a igual distribuição de gordura, Tohru está muito confiante do sabor delicioso da sua cauda. Ela também é a mestre dos grelhados, já que a prática leva à perfeição. Ainda assim, cuidado que é venenoso.",
  str_item_intro_3661137 = "Mobília para sala na Colossus.\nFeito à mão de forma espontânea por Tohru. Para dragões, a arte humana está além da compreensão, já que o objeto e os procedimentos são muito simples. Tohru imitou o trabalho de outros para criar este entalhe de madeira. Ela não se importa com o propósito disso, desde que ele seja apreciado.",
  str_item_intro_3662110 = "Mobília para sala na Colossus.\nA selfie é obrigatória em qualquer viagem de grupo! Fiquem mais perto… É quase impossível juntar cinco dragões na mesma foto… Sorriam!",
  str_item_intro_3661138 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUm piano encontrado na Cidade Perdida. Embora semelhante em estilo a alguns pianos no Astra, é particularmente bem feito e ainda produz um som bonito mesmo depois de todos esses anos. Mesmo que soe um pouco fora, ele ainda pode ser ajustado de acordo com sua estrutura interna única! Que jóia rara para músicos!",
  str_item_intro_3661139 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUma peça discreta que é de alguma forma diferente do estilo simples usual da Illumina. Com sua textura suave única e planta bonito, até mesmo os de Lumopolis gostariam.",
  str_item_intro_3661140 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUm tapete encontrado na Cidade Perdida. Além de ser feito de um material muito especial, seu padrão em forma de diamante que se cruza o torna ainda mais marcante.",
  str_item_intro_3661141 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nFacilmente encontrado nas ruas da Cidade Perdida, é quase tão comum quanto as luzes da rua, tornando-os um substituto tentador para as placas de trânsito... Sua tela apresenta uma confusão de padrões que piscam constantemente, e é impossível saber o que está dentro isto. Parece que a única maneira de descobrir é quebrando-o.",
  str_item_intro_3661142 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUma caixa de correio encontrada na Cidade Perdida. Como a gravação havia desbotado, foi inicialmente confundida com uma pequena caixa de armazenamento para rações de emergência. Foi só quando encontraram cartas dentro que as pessoas perceberam que era uma caixa de correio. No entanto, parece que ninguém ainda está usando.",
  str_item_intro_3661143 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUm acessório comum colocado nas estradas da Cidade Perdida para os transeuntes descansarem. Bem, se for colocado em casa, pode ser usado para sentar e deitar.",
  str_item_intro_3661144 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nDepois de todos esses anos, ainda está milagrosamente intacto! A tecnologia em Lost City é simplesmente surpreendente. Uma vez que um pedaço de papel é colocado, ele é imediatamente cortado em tiras finas, tornando qualquer mensagem ininteligível.",
  str_item_intro_3661145 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nAinda está em condições notáveis depois de todos esses anos... mas está fora de uso. Uma pequena arrumação revela um ambiente de trabalho limpo e organizado e todos os tipos de material de escritório que simplesmente enchem o escritório de energia.",
  str_item_intro_3661146 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nNão só gira deliciosamente, mas a altura do assento também pode ser ajustada, e o encosto pode até ser abaixado, permitindo que o usuário se deite confortavelmente para um pouco de sono. Em termos de ambiente, colocá-lo com a mesa cria uma maravilhosa sensação de harmonia que faz com que se demore no trabalho e esqueça o tempo.",
  str_item_intro_3661147 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUm ornamento do Extremo Oriente feito de bambu que requer água corrente. O seu engenhoso mecanismo permite emitir em intervalos regulares um baque refrescante e agradável, que também serve como temporizador.",
  str_item_intro_3661148 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUma planta de bambu de crescimento rápido que requer podas regulares. Embora seja um pouco problemático, você pode obter toneladas de bambu, e o som farfalhante quando suas folhas são sopradas também é revitalizante.",
  str_item_intro_3663001 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUma boneca pendurada sob o beiral. É simples de fazer e fica muito fofo. Quando o vento sopra, ele até dança com ele, como se estivesse rezando para que a chuva vá embora. Se funcionar, significa que os céus viram a dança deles!",
  str_item_intro_3661149 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUm capacete usado por guerreiros do Extremo Oriente. Ele apresenta ornamentos exagerados que dizem representar não apenas a facção ou clã ao qual o guerreiro pertencia, mas, mais importante, um símbolo de honra.",
  str_item_intro_3661150 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nOriginalmente, era uma bandeira que os soldados ou samurais colocavam nas costas para guiar as tropas na retaguarda na batalha. Quando colocado em casa, dá um sentimento solene.",
  str_item_intro_3662111 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUma peça de caligrafia que é popular entre as pessoas do Extremo Oriente. Eles geralmente são escritos por mestres calígrafos, mas é claro que a maioria é apenas cópia. Eles possuem uma beleza especial aos olhos do povo do Extremo Oriente e é quase impossível para os estrangeiros apreciarem.",
  str_item_intro_3661151 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nEmbora seja chamada de paisagem, a palavra murcha na frente indica que essa paisagem em miniatura na verdade não tem água, mas usa areia fina para representar água e pedras para representar montanhas rochosas. No Extremo Oriente, acredita-se que esse tipo de paisagem estática ajuda a meditar e acalmar a mente.",
  str_item_intro_3661152 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUma lâmpada de rua decorada no estilo do Extremo Oriente que é comumente encontrada em Cloud Island. Os moradores locais os utilizam não apenas para iluminação, mas também como sinalização viária.",
  str_item_intro_3663002 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nOs moradores de Koufu-jou os penduram em suas portas para iluminação, e as lanternas de cada casa tornam as ruas tão claras quanto o dia. As pessoas também o usam com uma vara de bambu para iluminar o caminho à noite.",
  str_item_intro_3661159 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUma lança foi dada a Carleen quando ela foi ordenada cavaleiro. Mais tarde, tornou-se sua arma de batalha exclusiva. Embora seja apenas uma réplica, ainda emite o poder do Moon Cocoon quando colocado em casa...",
  str_item_intro_3662116 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nProdutor famoso — a decoração favorita do Tourdog. Diz-se que enquanto esta lousa estiver pendurada em casa, muitas vezes ele pode ouvir os sons crocantes da lousa, e os sons de um novo dia de trabalho o motivam constantemente. Ao vê-lo trabalhando diligentemente, os espectadores não podem deixar de ser encorajados a trabalhar duro também.",
  str_item_intro_3661153 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUsado frequentemente por líderes de torcida em comícios para acompanhar suas várias danças de torcida. No entanto, alguém modificou este par instalando um componente bizarro nele, e agora eles torcem por conta própria. Você pode achar estranho no começo, mas é divertido quando você se acostuma.",
  str_item_intro_3661154 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nPneus de carros de corrida descartados que foram reciclados e empilhados em uma cadeira. Um pouco rústico, mas muito macio.",
  str_item_intro_3662112 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUm banner que foi usado como a linha de chegada do Blazing Rally. Os participantes da corrida adoram trazê-lo para casa para decoração ou colocá-lo em seu carro como lembrança.",
  str_item_intro_3661155 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nTodos os anos, quase todos os membros da Rediesel Wrench participam e competem em uma corrida de rally auto-organizada, atraindo espectadores de todas as esferas da vida. Esta taça é a prova do excelente desempenho do proprietário na corrida.",
  str_item_intro_3661156 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUma planta que geralmente só cresce no deserto, resistente ao clima extremamente frio e seco. Entre as mais difíceis de todas as plantas de casa, não requer muita rega. Tenha cuidado com seus espinhos!",
  str_item_intro_3662113 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nChamado de \"pneu energizante\", mas na verdade apenas um pneu de carro de corrida comum. No entanto, quando pendurado como decoração de parede, enche a sala com a exuberância emocionante de um rally.",
  str_item_intro_3661157 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nDe acordo com os membros da Verdadeira Ordem, este pergaminho foi descoberto pela primeira vez em uma antiga ruína. Não tem palavras, mas aqueles da Verdadeira Ordem são capazes de vislumbrar a Revelação de dentro...",
  str_item_intro_3642602 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nDesenhado por um membro desconhecido da Verdadeira Ordem que se autoproclamou ter visto a Verdade do Mundo, deixou isso para trás e depois desapareceu. Sua proclamação é posta em dúvida pela maioria, mas é inegável que há algo estranhamente sedutor nessa pintura bizarra...",
  str_item_intro_3661158 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nInseparável, perfeito, circulatório, verdadeiro, único... Os membros da Verdadeira Ordem interpretam o padrão de forma diferente, mas todos acreditam que colocar um heptagrama debaixo dos pés ajuda a ver a verdade suprema...",
  str_item_intro_3662115 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nDunas de areia! Carros de corrida! O Blazing Rally convida os pilotos mais corajosos, indomáveis e engenhosos para uma festa de velocidade! Até o conteúdo do seu coração! Até o fim do mundo!",
  str_item_intro_3661169 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUma pequena peça de maquinaria alimentada por uma força misteriosa que gira sem parar quando levemente empurrada. Há rumores de que continuará girando até o fim do mundo se não for interrompido.",
  str_item_intro_3661170 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUm portão que costumava ser colocado em Cloud Gardens. É elegante e adequado para decoração em outros lugares.",
  str_item_intro_3661162 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nQualquer pessoa que seja capaz de remover um conjunto intacto de espinhas de peixe e organizá-las de forma tão ordenada deve ter um conhecimento profundo de peixes. Este ornamento de espinha de peixe não é apenas uma peça decorativa, mas também uma demonstração do artesanato de seu criador.",
  str_item_intro_3662117 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nPode-se imaginar a habilidade do pescador olhando para a fricção. Um peixe gigantesco como este deve ter causado ondas enormes quando lutou. O pescador provavelmente teve que se enrolar um pouco com ele antes de finalmente derrubá-lo, e decidiu manter essa fricção como lembrança.",
  str_item_intro_3661163 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUma cadeira feita de um toco redondo, sua superfície é áspera e seus anéis de crescimento são visíveis. No entanto, adiciona uma sensação única de deserto à sala.",
  str_item_intro_3661164 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nHá rumores de que o tapete foi usado pelos celestitas. É pintado com padrões compostos por várias linhas e formas. Alguns dizem que os padrões se assemelham a parte da torre se você os olhar por tempo suficiente, enquanto outros pensam que se assemelham ao céu. É verdadeiramente misterioso.",
  str_item_intro_3661165 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUm modelo de um veículo de outro mundo.\nParece um objeto muito familiar para os Phantom Thieves of Hearts.\nMona olha para ele com um sorriso presunçoso – ou é apenas sua imaginação?",
  str_item_intro_3661166 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUm brinquedo de pelúcia de um demônio de outro mundo.\nTem a forma de um boneco de neve, e é por isso que as pessoas gostam.\nVocê ouviu isso? Parecia alguém dizendo \"hee-ho\".",
  str_item_intro_3661167 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUm dispositivo misterioso encontrado nas ruínas antigas. Dizem que é capaz de fritar alimentos e até tem recursos de tempero! É um item tão raro e valioso que muitos participaram de uma competição Food Cart King pela chance de obtê-lo...",
  str_item_intro_3661168 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nColoque óleo, grãos descascados e temperos, geralmente açúcar, e os grãos descascados começarão a inchar depois que a máquina for ativada, fazendo um lanche maravilhoso. Infelizmente, esta é apenas uma decoração que não pode ser usada...",
  str_item_intro_3661160 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUma obrigação em todos os parques de diversões! As crianças adoram! Claro, este é um pouco pequeno... Só pode ser usado como decoração.",
  str_item_intro_3661161 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nÉ uma gangorra! Uma gangorra! Mas parece que foi feito para um animal pequeno. Os vaga-lumes a bordo do Colossus adoram. Muitas vezes você pode vê-los saltando para cima e para baixo, praticando a coordenação de seus movimentos.",
  str_item_intro_3661001 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nQuando está totalmente inflada, essa boia parece um... Eclipsita poderoso?! Ah... De qualquer jeito, é apenas uma boia, e também é rosa. Ela não parece assustadora, na verdade, é até fofa.",
  str_item_intro_3661002 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nOriginalmente criado e vendido na Federação Illumina, foi repintado em uma pequena cidade para dar uma aparência de verão. Após sua pintura nova, dizem que gera uma brisa mais fresca que antes!",
  str_item_intro_3661003 = "Item de mobília. Pode ser colocada nas salas da sua Colossus.\nEssa placa de estação do Centro de Transporte de Lumópolis parece misteriosamente sólido e resistente, sem traços de ferrugem após anos de sol e chuva. Suas cores simples e desenho estiloso fazem dela o perfeito souvenir de uma longa jornada para Lumópolis.",
  str_item_intro_3661004 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nApesar dessa coroa não conceder poderes verdadeiros, é um símbolo de uma pessoa encantadora. A coroa já foi presenteada à vencedora do Miss Umbraton. As belíssimas joias combinam com a beleza estonteante, o que causa uma forte impressão no público.",
  str_item_intro_3661005 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nEsse chapéu é popular principalmente nas regiões desérticas. Com uma aba larga, protege contra o vento e a areia. Aqueles que vivem próximos ao deserto usam essa combinação de manto e chapéu com uma máscara durante certos festivais, dançando e cantando para os forasteiros como forma de compartilhar a cultura deles.",
  str_item_intro_3661006 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nO \"pufe\" era originalmente uma iguaria da região desértica, feita com base nas vagens nativas. O conceito foi levado ao reino para que fossem criados assentos. Segundo os locais, colocar uma expressão facial fofa em seu pufe faz com que as pessoas sintam mais vontade de pular nele.",
  str_item_intro_3661007 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nReviva as batalhas da Arena Sombria na sua Colossus! As imagens dos competidores projetadas mostram cada detalhe de combate e recriam a emoção do torneio.",
  str_item_intro_3661008 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nUm grande bonsai de bordo que pode por si só decorar um quarto. Claro, ficaria melhor com algumas outras decorações para acompanhá-lo.",
  str_item_intro_3661009 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nUma pequena planta de bordo no vaso. Combine-a com outras plantas para formar um arranjo verdadeiramente bonito.",
  str_item_intro_3661010 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nAlguns aldeões acreditam que esta máscara armazena poder para espantar o mal e trazer boa sorte, então eles geralmente colocam-na em uma posição eminente na casa, torcendo para que abençoe toda a família.",
  str_item_intro_3661011 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nOriginalmente do Oriente, este tipo de mobília se tornou popular ao redor do continente nos últimos anos. No inverno, ela traz calor e paz de espírito, e desde que você sente nela, você pode ficar o dia todo sem se mover. Alguns até começaram a se referir a esse fenômeno como Feitiço da Mesa Quente.",
  str_item_intro_3661012 = "Item de mobília. Pode ser colocado em salas da sua Colossus.\nO abeto é a árvore mais comum em Northland e também um material importante usado na construção de casas e mobília. Por causa disso, o abeto representa o conceito de família em Northland, e o povo de Northland coloca o abeto em suas casas durante o feriado de Ano-Novo. Eles penduram várias decorações nos galhos do abeto e colocam presentes embaixo deles para abri-los na presença da família para celebrar o seu festival mais importante.",
  str_item_intro_3661013 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nPessoas no Oriente adoram celebrar os feriados com isso. Supostamente no início era só uma comida, mas quando o povo de Northland acreditou que isso podia trazer felicidade, foi substituído com argila e roupas. Porém, parece um pouco com Tweety…",
  str_item_intro_3661014 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\n\"Faça um bolo em forma de coração para alguém especial quando chegar a hora.\" A tendência parecia decolar da noite para o dia, mas é bastante popular entre as meninas. Afinal, além de ser agradável aos olhos, também é delicioso e, mais importante, dá uma sensação tão deliciosa!",
  str_item_intro_3661015 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nParece ser um ornamento pendurado do Extremo Oriente. Leve e conveniente, pode ser pendurado sob beirais ou em portas ou janelas. Enquanto houver vento, ele fará um som claro e vibrante que é simplesmente refrescante e relaxante.",
  str_item_intro_3661016 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nO urso bonito é perfeito como um presente e tem um sabor inesperadamente bom também. Mas, você pode realmente suportar para comê-lo?",
  str_item_intro_3661017 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nDizem que é um brinquedo baseado no bobo do antigo rei. Parece bobo e fofo e serve como um ótimo presente para trazer um tipo único de alegria.",
  str_item_intro_3661018 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nPreferido pelos membros da Rediesel Wrench, este capacete oferece proteção em todos os tipos de acidentes e protege o piloto do vento e da poeira. Suas cores brilhantes garantem que seu usuário nunca passe despercebido.",
  str_item_intro_3661019 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nEste modelo Soroz é feito de finas folhas de material que foram unidas. Parece ser a obra-prima de algumas crianças e, embora se assemelhe à realidade em muitos aspectos, alguns detalhes revelam a alegria e o humor das crianças.",
  str_item_intro_3661020 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUma gigantesca torre de bolo feita sob medida para comemorar um ano de estarmos juntos. É maravilhoso quando colocado na frente de seus olhos. Porque é tão... alto! Além de sua aparência deslumbrante, cada camada de bolo também gira levemente, revelando suas várias rendas coloridas.",
  str_item_intro_3661021 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nAh... já faz um ano. Todas essas memórias passadas podem ser encontradas nele.",
  str_item_intro_3662118 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUm pôster de carta de advertência que os Phantom Thieves of Hearts enviam para seus alvos em outro mundo. O design gráfico é bastante artístico.\nOlhando para o pôster, Fox parece muito satisfeito consigo mesmo. Ou é sua imaginação?",
  str_item_intro_3661022 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nVocê acha o esquema de cores familiar? Isso mesmo! Esta prancha de surf é projetada com base em Brock e é tão durável, confiável e fácil de controlar quanto ele!",
  str_item_intro_3661176 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nAlguém realmente plantou a árvore inteira em um vaso! Só pela vista! Eles devem gostar muito de palmeiras para pensar nisso.",
  str_item_intro_3661171 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUma escultura de estrela do mar realista, que pode ser confundida com uma estrela do mar real à primeira vista. Embora feito com areia macia, de alguma forma é capaz de manter sua forma e é inesperadamente resistente.",
  str_item_intro_3661172 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nSim, é sólido, mas ainda feito com areia. Então, não tome o nome muito literalmente! Foi dado o nome esperando que durasse mais e, até agora, o castelo foi mantido muito bem.",
  str_item_intro_3661173 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nConfira! Um evento repleto de muitas performances maravilhosas de cair o queixo que o público nunca esquecerá! É por isso que até seu pôster parece atraente.",
  str_item_intro_3661174 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUma bola multicolorida. Basta dar algumas voltas no palco para atrair os olhos do público, sem falar em todos os truques de vaudeville que se pode realizar com ele. Um dos principais itens necessários em um show incrível.",
  str_item_intro_3661175 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nMuitos balões! Eles são coloridos e fazem você se sentir um pouco flutuante quando você os segura! Apenas lembre-se de não deixar crianças muito pequenas brincarem com eles, ou então os balões podem realmente arrastá-los para o céu!",
  str_item_intro_3661177 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nQue tipo de árvore é essa? Seus galhos são todos retorcidos e retorcidos... Parece o tipo de árvore que você veria em um filme de terror. Seria ainda mais assustador com algumas lanternas assustadoras penduradas nele...",
  str_item_intro_3661178 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nDeveria estar... sorrindo? Apenas a pessoa que o fez saberia, mas definitivamente há algo estranho em como está sorrindo. Novamente, isso é realmente um sorriso...?",
  str_item_intro_3661179 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nGlub, glub, glub... Quem sabe que tipo de mistura maluca está fervendo neste caldeirão? Poderia ser uma poção do amor, como as dos contos de fadas? Ou talvez algo muito mais sinistro...",
  str_item_intro_3661180 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUm boneco estranho feito por mercadores ainda mais estranhos em Umbraton. Na superfície, parece com Soroz, mas se você apertar um pouco... Ele solta um grito alto e assustador. Eu me pergunto que tipo de travessura isso deveria ser?",
  str_item_intro_3661023 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUma vez cheio de água, ele gerará continuamente um fluxo de água usando seus mecanismos embutidos. Perfeito para combater o calor tórrido do verão. A propósito, lembre-se de limpar o chão após o uso.",
  str_item_intro_3661024 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nEste monociclo pode realmente avançar mesmo com uma roda! É apenas um pouco lento... Ao observar as habilidades de pilotagem acrobática do piloto, não se pode deixar de se sentir surpreso e ansioso ao mesmo tempo.",
  str_item_intro_3661025 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nParece ser um dispositivo antigo encontrado em uma das muitas ruínas misteriosas de Astra. Apesar de ser relativamente antigo, ainda funciona surpreendentemente bem e pode gravar fielmente imagens de vídeo.",
  str_item_intro_3701001 = "Esse livro é apenas um volume de uma série. Coloque na estante do Café para que possa vê-lo sempre que quiser!",
  str_item_intro_3701002 = "Esse livro é apenas um volume de uma série. Coloque na estante do Café para que possa vê-lo sempre que quiser!",
