  str_item_intro_3711003 = "Esse livro é apenas um volume de uma série. Coloque na estante do Café para que possa vê-lo sempre que quiser!",
  str_item_intro_3711004 = "Esse livro é apenas um volume de uma série. Coloque na estante do Café para que possa vê-lo sempre que quiser!",
  str_item_intro_3711005 = "Esse livro é apenas um volume de uma série. Coloque na estante do Café para que possa vê-lo sempre que quiser!",
  str_item_intro_3751002 = "Desbloqueia o avatar correspondente.\nTive uma ótima ideia! Oh! Você também? Shh, deixa isso só entre nós, hein?",
  str_item_intro_3751003 = "Desbloqueia o avatar correspondente.\nOlhe aquela pessoa, tão legal! Uau, aquela pessoa! Não pode ser!",
  str_item_intro_3751004 = "Desbloqueia o avatar correspondente.\nAs coisas estão dando errado de novo! O que fazer? Não quero xingar, mas...",
  str_item_intro_3751005 = "Desbloqueia o avatar correspondente.\nAh, droga. Como isso foi acontecer? Parece que ainda há espaço para melhorar, vamos tentar mais!",
  str_item_intro_3751006 = "Desbloqueia o avatar correspondente.\nAh, não! Estragamos nossa tarefa. O chefe vai nos repreender? Não vamos ser muito pessimistas.",
  str_item_intro_3751009 = "Desbloqueia o avatar correspondente.\nNão duvide de si mesmo. Todos têm a sua própria missão. Tenho certeza disso!",
  str_item_intro_3751011 = "Desbloqueia o avatar correspondente.\nVocê já terminou todas as missões que passei? Aqui, pegue essa florzinha vermelha.",
  str_item_intro_3751015 = "Desbloqueia o avatar correspondente.\nEsse som é muito relaxante e agradável. Você quer escutá-lo junto comigo?",
  str_item_intro_3751017 = "Desbloqueia o avatar correspondente.\nEu não consigo sentar e ser um fardo. Será que devo inventar algo novo? Talvez algo como...",
  str_item_intro_3751019 = "Desbloqueia o avatar correspondente.\nMesmo com tanto conhecimento, é impossível descrever o que está acontecendo. É inacreditável.",
  str_item_intro_3751023 = "Desbloqueia o avatar correspondente.\nPor que está com tanta pressa? Tá querendo comer de graça? É melhor ir, antes que seja tarde.",
  str_item_intro_3751025 = "Desbloqueia o avatar correspondente.\nPor que está tentando me matar, pobrezinho? Não há mais nada pra fazer?",
  str_item_intro_3751030 = "Desbloqueia o avatar correspondente.\nNossa querida Colossus, por que você vai além do seu poder e voa no céu?",
  str_item_intro_3751032 = "Desbloqueia o avatar correspondente.\nPor que você não conhece a si mesmo? Por que não olha no espelho? Aqueles que são completamente inúteis vivem na ignorância.",
  str_item_intro_3751033 = "Desbloqueia o avatar correspondente.\nPor mais perto que estejamos, minha lâmina não dá margem a infratores da lei.",
  str_item_intro_3751034 = "Desbloqueia o avatar correspondente.\nQuando você olha para a sombra, a sombra está observando você.",
  str_item_intro_3751035 = "Desbloqueia o avatar correspondente.\nA verdade muitas vezes está escondida nas nuvens, meio encoberta e meio revelada. Você e eu precisamos manter nossos olhos abertos.",
  str_item_intro_3751036 = "Desbloqueia o avatar correspondente.\nOrdem? Regras? Haha! O que é isso?",
  str_item_intro_3751037 = "Desbloqueia o avatar correspondente.\nO futuro ainda é sombrio, mas vejo um raio de esperança.",
  str_item_intro_3751038 = [[
Desbloqueia o avatar correspondente.
Bem feito! Junte-se a mim na luta contra os Eclipsites! Esplendor Ilumina!]],
  str_item_intro_3751301 = "Obtenha esse Avatar para usar.\n\"Nada mal! Ei, quer se juntar à Rediesel Wrench?\"",
  str_item_intro_3751302 = "Obtenha esse Avatar para usar.\n\"Agradeço a todos, minha força retornou. Quer que eu cuide de alguns Eclipsitas?\"",
  str_item_intro_3751303 = [[
Desbloqueia o avatar correspondente.
Venha comigo para a Montanha Nebulosa e podemos brincar entre as flores.]],
  str_item_intro_3751304 = "Desbloqueia o avatar correspondente.\nRaspadinhas cuidadosamente preparadas pelo dono da barraca com Gela Cérebro garantem um refresco excelente sob o sol do verão.",
  str_item_intro_3751305 = "Desbloqueia o avatar correspondente.\nUse isto e torne-se Aço Rediesel MkV Zero!",
  str_item_intro_3751306 = "Desbloqueia o avatar correspondente.\nHã...? Todos saíram para se divertir? Bem, acho que deveria ir também…",
  str_item_intro_3751307 = "Desbloqueia o avatar correspondente.\nPrecisa esfriar a cabeça? Permita-me! Gelescer!",
  str_item_intro_3751308 = "Desbloqueia o avatar correspondente.\nJá passaram cem dias? Merecemos um bolo para comemorar!",
  str_item_intro_3751309 = "Desbloqueia o avatar correspondente.\nHmm... Estou começando a gostar do deserto.",
  str_item_intro_3751310 = "Desbloqueia o avatar correspondente.\nPor que estou com essa sensação estranha na cabeça? Ah, são eles... Tá, vou deixar assim.",
  str_item_intro_3751311 = "Desbloqueia o avatar correspondente.\nNós vencemos? Pegue os fogos de artifício! É hora de celebrar!",
  str_item_intro_3751312 = "Desbloqueia o avatar correspondente.\nEspero que nós possamos chegar a um consenso.",
  str_item_intro_3751313 = "Desbloqueia o avatar correspondente.\nQuer ver o rosto por baixo da máscara? Posso mostrar... Você só precisa se juntar ao meu grupo de mercenários.",
  str_item_intro_3751314 = "Desbloqueia o avatar correspondente.\nAvante, Noite Branca... Um dia, quero eliminar todas as injustiças do mundo.",
  str_item_intro_3751315 = "Desbloqueia o avatar correspondente.\nRepresenta a maior honra da Arena Sombria de Umbraton! Prova inegável de que você é um mestre do combate!",
  str_item_intro_3751316 = "Desbloqueia o avatar correspondente.\nNave-Nave-Navegador! Deixa eu mostlar uma mágica!",
  str_item_intro_3751317 = "Desbloqueia o avatar correspondente.\nUm sorriso tão maldoso... Vamos causar confusão!",
  str_item_intro_3751318 = "Desbloqueia o avatar correspondente.\nEu me deparei com uma gatinho fofo durante minha patrulha! Hoje é um bom dia!",
  str_item_intro_3751319 = "Desbloqueia o avatar correspondente.\nSímbolo de autoridade em Lumópolis. Geralmente reservado à nobreza.",
  str_item_intro_3751320 = "Desbloqueia o avatar correspondente.\nÉ assim que o povo de Northland se veste para o Ano-Novo, e eu não sou exceção.",
  str_item_intro_3751321 = "Desbloqueia o avatar correspondente.\nDesejo a você paz e felicidade no Ano-Novo.",
  str_item_intro_3751322 = "Desbloqueia o avatar correspondente.\nAgora você sabe quem é a melhor empregada!",
  str_item_intro_3751323 = "Desbloqueia o avatar correspondente.\nUma criança boazinha se comporta até dormindo. Ela não vai reclamar de nada, e você ainda pode pôr uma laranja na cabeça dela enquanto ela dorme.",
  str_item_intro_3751324 = "Desbloqueia o avatar correspondente.\n\"Devagar e com precisão, vou atraí-los...\"",
  str_item_intro_3751325 = [[
Desbloqueia o avatar correspondente.
"Olhando para isso... deve ter pelo menos mil anos!"]],
  str_item_intro_3751326 = "Desbloqueia o avatar correspondente.\n\"Procurando comemorar? Cada festival tem suas próprias características especiais.\"",
  str_item_intro_3751327 = [[
Desbloqueia o avatar correspondente.
"Ei! Quer dar uma volta comigo?!"]],
  str_item_intro_3751328 = "Desbloqueia o avatar correspondente.\n\"Um notebook é sempre melhor do que uma boa memória.\"",
  str_item_intro_3751329 = "Desbloqueia o Avatar correspondente.\n*uivos* Espero que você não tenha se assustado!",
  str_item_intro_3751330 = "Desbloqueia o avatar correspondente.\n\"O amor é precioso,\nA liberdade é mais.\nAmbos podem ser abandonados,\nPor causa de um voto.\"",
  str_item_intro_3751331 = "Desbloqueia o avatar correspondente.\n\"Jingles! Você quer um jingle miau?\"",
  str_item_intro_3751332 = "Desbloqueia o avatar correspondente.\n\"Por favor, ouça o som do Kagura Bell.\"",
  str_item_intro_3751333 = "Desbloqueia o avatar correspondente.\n\"Eu não vou dar o pão para ninguém!\"",
  str_item_intro_3751334 = "Desbloqueia o avatar correspondente.\n\"Você está acordado? Comece a trabalhar então!\"",
  str_item_intro_3751335 = "Desbloqueia o avatar correspondente.\n\"Vitória! Quer se divertir um pouco para comemorar?\"",
  str_item_intro_3751336 = [[
Desbloqueia o avatar correspondente.
"Parece comigo, certo?"]],
  str_item_intro_3751338 = "Desbloqueia o avatar correspondente.\n\"Ahahah. A cabeça do gatinho está te observando.\"",
  str_item_intro_3751339 = "Desbloqueia o avatar correspondente.\n\"Como eles são diferentes?\"",
  str_item_intro_3751340 = "Desbloqueia o Avatar correspondente.\n\"Você sempre cuidou bem de mim, então, por favor, aceite isso.\"",
  str_item_intro_3751341 = "Desbloqueia o Avatar correspondente.\n\"Ouvi dizer que hoje é o dia de expressar nossos corações... assim?\"",
  str_item_intro_3751342 = "Desbloqueia o avatar correspondente.\n\"Ouvi dizer que este pijama está na moda entre os Navegantes. Fiquei muito tempo na fila para pegá-lo!\"",
  str_item_intro_3751343 = [[
Desbloqueia o avatar correspondente.
A cor dos olhos... mudou.]],
  str_item_intro_3751344 = [[
Desbloqueia o avatar correspondente.
"Hmm... Eu esqueci de fazer alguma coisa?"]],
  str_item_intro_3751345 = "Desbloqueia o quadro de avatar correspondente.\nAnotar assuntos de grande importância é um bom hábito para o Chefe de Gabinete.",
  str_item_intro_3751346 = "Desbloqueia o avatar correspondente.\nEste equipamento? Eu o peguei enquanto fazia compras em Umbraton. Não é simplesmente único?",
  str_item_intro_3751347 = "Desbloqueia o avatar correspondente.\nChubb Merchant parece ter recebido um grande presente e está cantando de felicidade.",
  str_item_intro_3751348 = "Desbloqueia o avatar correspondente.\nA Ilumina precisa de você! Estamos ansiosos para ter você!",
  str_item_intro_3751349 = "Desbloqueia o avatar correspondente.\nHum? Quer me ouvir cantar? Claro. Em troca, você vai jogar comigo!",
  str_item_intro_3751350 = "Desbloqueia o avatar correspondente.\n\"Por que eu me vesti de Yumi? Porque ela é super fofa.\"",
  str_item_intro_3751351 = "Desbloqueia o avatar correspondente.\n\"As orelhas? Philyshy me fez usar isso ou ela iria me denunciar à oficial Sharona por acidentalmente pisar em seu rabo...\"",
  str_item_intro_3751352 = "Desbloqueia o avatar correspondente.\n\"Junte-se a mim! Você nunca vai perder!\"",
  str_item_intro_3751353 = "Desbloqueia o avatar correspondente.\n\"Huh? O que há de tão difícil nisso?\"",
  str_item_intro_3751354 = "Desbloqueia o avatar correspondente.\n\"Você deveria fazer uma pausa de vez em quando também.\"",
  str_item_intro_3751355 = [[
Desbloqueia o avatar correspondente.
"Onde eu estava?"]],
  str_item_intro_3751356 = "Desbloqueia o avatar correspondente.\n\"Ahhhh! Está tão quente!\"",
  str_item_intro_3751357 = "Desbloqueia o avatar correspondente.\n\"É um verão quente e usar um chapéu de sol é uma ótima maneira de evitar queimaduras solares. Cuidado com o calor, navegador.\"",
  str_item_intro_3751358 = "Desbloqueia o avatar correspondente.\n\"Quem diria não a uma xícara de gelo raspado gelado e delicioso em um dia quente de verão?\"",
  str_item_intro_3751359 = "Desbloqueia o avatar correspondente.\nNeste verão quente, você sempre pode sentir uma pitada de frescor ao lado de Carleen.",
  str_item_intro_3751360 = "Desbloqueia o avatar correspondente.\n\"É muito aconchegante aqui. Vamos curtir a paz do carnaval.\"",
  str_item_intro_3751361 = "Desbloqueia o avatar correspondente.\nA noite é minha amiga e os morcegos são meus súditos. Quem sou eu?",
  str_item_intro_3763022 = "Desbloqueia o avatar correspondente.\nNão tenha medo! Mandei fazer essa lanterna de abóbora para melhorar o clima do evento nos próximos dias. Nada mal, certo?",
  str_item_intro_3751362 = [[
Desbloqueia o avatar correspondente.
Deixe-me ver o que aconteceu!]],
  str_item_intro_3751363 = "Desbloqueia o avatar correspondente.\nÉ muito sério, mas uma cobra ainda pode ficar na minha cabeça.",
  str_item_intro_3751365 = "Desbloqueia o avatar correspondente após a obtenção. \"Quer comprar doces? Troque suas histórias por eles.\"",
  str_item_intro_3751366 = "Desbloqueia o avatar correspondente após a obtenção. \"Você não se importaria de eu te vestir como um lobo, certo?\"",
  str_item_intro_3751367 = "Desbloqueia o avatar correspondente após a obtenção.\n\"Charon ansiosamente colocou dentes falsos e uma capa. O show começou!\"",
  str_item_intro_3751368 = "Desbloqueia o avatar correspondente após a obtenção. \"Para Hiiro, tornar-se um mago também pode servir como um tipo de treinamento.\"",
  str_item_intro_3751369 = "Desbloqueia o avatar correspondente após a obtenção. \"Paloma embrulhou-se em bandagens para surpreender todas as crianças que vierem doces ou travessuras.\"",
  str_item_intro_3751370 = [[
Desbloqueia o avatar correspondente.
"Esta moeda... representa meu passado."]],
  str_item_intro_3751371 = "Desbloqueia o avatar correspondente.\n\"Essas luzes de várias cores são tão bonitas.\"",
  str_item_intro_3751372 = "Desbloqueia o avatar correspondente.\n\"Venha comigo e torne-se um ídolo!\"",
  str_item_intro_3751373 = "Desbloqueia o avatar correspondente.\n\"Pronto... Ação!\"",
  str_item_intro_3751374 = "Desbloqueia o avatar correspondente.\nPhilyshy disse que trocou alguns peixes secos por esses populares pijamas de Ano Novo. Hmm... Eles são muito confortáveis, mas por que eles têm orelhas?",
  str_item_intro_3751375 = "Desbloqueia o avatar correspondente. Macarrão de caracol do rio, com seu aroma único, é a comida favorita de Mu Yuebai.",
  str_item_intro_3751376 = "Desbloqueia o avatar correspondente.\nVocê não parece muito bem. Gostaria que demos uma olhada em você?",
  str_item_intro_3751377 = "Desbloqueia o avatar correspondente.\nObservar silenciosamente as pessoas e as coisas é uma espécie de hábito para Jeriah.",
  str_item_intro_3751378 = "Desbloqueia o avatar correspondente.\nCom seu semblante sempre justo, Michael agarra todas as rosas que ela vê.",
  str_item_intro_3751379 = "Desbloqueia o avatar correspondente.\nCumprimentar o mundo com uma fantasia atraente às vezes pode oferecer uma experiência completamente diferente.",
  str_item_intro_3751380 = "Desbloqueia o avatar correspondente.\n\"Perigoso. Por favor, não imite.\"",
  str_item_intro_3751381 = "Desbloqueia o avatar correspondente.\n\"Jeno está convidando você para tomar uma xícara de café preto com ele. Você aceita o convite dele?\"",
  str_item_intro_3751382 = "Desbloqueia o avatar correspondente.\n\"Um juiz de Lumopolis deve ter a coragem de tomar a decisão final.\"",
  str_item_intro_3751383 = "Desbloqueia o avatar correspondente.\n\"Esta boneca se parece comigo, então me sinto segura ao abraçá-lo.\"",
  str_item_intro_3751384 = "Desbloqueia o avatar correspondente.\n\"Gosto dessa música porque me acalma.\"",
  str_item_intro_3751385 = "Desbloqueia o avatar correspondente.\n\"Yingel, que é muito chegado aos papa-moscas, deve ser muito gentil.\"",
  str_item_intro_3751386 = "Desbloqueia o avatar correspondente.\n\"Use sua espada para expandir as fronteiras e suas mãos para confortar os corações das pessoas. Leo adere firmemente a este princípio.\"",
  str_item_intro_3751387 = "Desbloqueia o avatar correspondente.\n\"O aroma do chá preto é calmante para Mia e a ajuda a relaxar.\"",
  str_item_intro_3751388 = "Desbloqueia o avatar correspondente.\n\"De quem é a flor favorita das violetas em suas mãos?\"",
  str_item_intro_3751389 = "Desbloqueia o avatar correspondente.\n\"O que você vê na bola de cristal? O passado ou o futuro?\"",
  str_item_intro_3751390 = "Desbloqueia o quadro de avatar correspondente.\n\"Quando você está triste, um abraço gentil pode melhorar?\"",
  str_item_intro_3751391 = "Desbloqueia o quadro de avatar correspondente.\n\"Seja meu público ou seja meu parceiro, qual é a sua escolha?\"",
  str_item_intro_3751392 = "Desbloqueia o quadro de avatar correspondente.\n\"Resfrie o calor do verão com uma refrescante tigela de gelo raspado!\"",
  str_item_intro_3751393 = "Desbloqueia o avatar correspondente.\nEu tenho uma ótima ideia para ganhar dinheiro. Quer tentar?",
  str_item_intro_3751394 = "Desbloqueia o avatar correspondente.\nQuer saber o que está me fazendo rir? Vá em frente, dê um palpite!",
  str_item_intro_3751395 = "Desbloqueia o avatar correspondente.\nQuer descobrir qual é a minha sobremesa favorita de verão? Bem, provavelmente é sorvete com carne seca de lagarto por cima.",
  str_item_intro_3751501 = "Desbloqueia o avatar correspondente.\nEssa flor do amanhecer representa esperança. Expulse a escuridão do seu passado!",
  str_item_intro_3751502 = "Desbloqueia o avatar correspondente.\nO emblema da Família Sakura. Ele representa o reconhecimento de Hiiro por você.",
  str_item_intro_3751503 = [[
Desbloqueia o avatar correspondente.
Caso precise da ajuda dessa guerreira misteriosa, por favor, entre em contato com os Trabalhos Estranhos do Sr. Taki.]],
  str_item_intro_3751504 = "Desbloqueia o avatar correspondente.\nHeehee... E se tomarmos o chá da tarde juntos? Ou você não aguenta sete barris de chá?",
  str_item_intro_3751505 = "Desbloqueia o avatar correspondente.\nAfunde na escuridão eterna comigo.",
  str_item_intro_3751506 = "Desbloqueia o avatar correspondente.\nNão pode lutar contra os Eclipsitas? Não se preocupe, eu luto então!",
  str_item_intro_3751507 = "Desbloqueia o avatar correspondente.\nUma surpresa de Windelion! Que presentes fascinantes contém?",
  str_item_intro_3751508 = [[
Desbloqueia o avatar correspondente.
Brinde comigo e vamos aproveitar esta noite maravilhosa juntos.]],
  str_item_intro_3751509 = "Desbloqueia o avatar correspondente.\n\"Parece que... você precisa de ajuda.\"",
  str_item_intro_3751510 = "Desbloqueia o avatar correspondente.\nEstou falando sério, essa carne foi feita para Kobayashi. Não toque nela!",
  str_item_intro_3751511 = [[
Desbloqueia o avatar correspondente.
"Eu? Eu tenho dormido cedo..."]],
  str_item_intro_3751512 = "Desbloqueia o avatar correspondente.\n\"Ahh... estou com sede... Cadê a água?\"",
  str_item_intro_3751513 = "Desbloqueia o avatar correspondente.\n\"Você está realmente me perguntando o que eu acho de Lord Navigator...?\"",
  str_item_intro_3751514 = [[
Desbloqueia o avatar correspondente.
Onde mais posso encontrar comida deliciosa?]],
  str_item_intro_3751515 = [[
Desbloqueia o avatar correspondente.
"Vamos dar uma volta!"]],
  str_item_intro_3751516 = "Desbloqueia o avatar correspondente.\n\"Alguém pode entender Lenore?\"",
  str_item_intro_3751517 = "Desbloqueia o avatar correspondente.\nA futura estratégia...",
  str_item_intro_3751518 = "Desbloqueia o avatar correspondente.\n\"A hora do chá da tarde é a hora mais alegre do dia.\"",
  str_item_intro_3751519 = [[
Desbloqueia o avatar correspondente.
"Roger."]],
  str_item_intro_3751520 = "Desbloqueia o avatar correspondente.\n\"É a minha vez agora?\"",
  str_item_intro_3751521 = "Desbloqueia o avatar correspondente.\n\"Lumópolis e o continente... Nós definitivamente não vamos e não devemos ficar assim.\"",
  str_item_intro_3751522 = "Desbloqueia o avatar correspondente.\nAlgo em sua mente? Vamos nos refrescar juntos na água!",
  str_item_intro_3751523 = [[
Desbloqueia o avatar correspondente.
"Vamos, vamos ter uma partida!"]],
  str_item_intro_3751524 = [[
Desbloqueia o avatar correspondente.
"Ufa... Tudo feito."]],
  str_item_intro_3751525 = "Desbloqueia o avatar correspondente.\nSobreviver ou perecer?\nEssa é a questão.",
  str_item_intro_3751526 = "Desbloqueia o avatar correspondente.\nAí vem a inspiração! Entendi! Este vai ser um grande sucesso!",
  str_item_intro_3751527 = "Desbloqueia o avatar correspondente.\nUm chapéu com uma caveira. O swashbuckler desce com um boné de caveira; é Sadie e Coolster, punindo bandidos e cantando um rap.",
  str_item_intro_3751530 = [[
Desbloqueia o avatar correspondente.
"A jardinagem realmente ajuda a melhorar o temperamento!"]],
  str_item_intro_3751531 = "Desbloqueia o avatar correspondente.\n\"Ela é linda, mas também muito... perigosa.\"",
  str_item_intro_3751532 = "Desbloqueia o avatar correspondente.\n\"Ah! Que calor... Tão macio!\"",
  str_item_intro_3751533 = "Desbloqueia o avatar correspondente.\n\"Parece que ela ainda está absorta naquela velha história. Não vamos incomodá-la.\"",
  str_item_intro_3751534 = "Desbloqueia o avatar correspondente.\n\"Feliz Ano Novo! Vamos soltar alguns fogos de artifício!\"",
  str_item_intro_3751535 = "Desbloqueia o avatar correspondente.\nEste barco... é realmente fascinante.",
  str_item_intro_3751536 = [[
Desbloqueia o avatar correspondente.
Gostoso-gostoso! Existe mais algum?]],
  str_item_intro_3751537 = [[
Desbloqueia o avatar correspondente.
Vou me atrasar! Acho que vou ter que comer andando de novo hoje!]],
  str_item_intro_3751538 = "Desbloqueia o avatar correspondente.\n\"Eu não estou dormindo... Zzz...\"",
  str_item_intro_3751539 = "Desbloqueia o avatar correspondente.\n\"Você pode limpá-lo de uma só vez?\"",
  str_item_intro_3751540 = "Desbloqueia o avatar correspondente.\n\"Papai mamãe...\"",
  str_item_intro_3751541 = "Desbloqueia o avatar correspondente.\n\"Aquele criminoso nojento... não vou deixar você escapar!\"",
  str_item_intro_3751542 = "Desbloqueia o avatar correspondente.\n\"Onde está minha presa? Bem na minha frente, é claro!\"",
  str_item_intro_3751543 = "Desbloqueia o avatar correspondente.\n\"Um caderno é sempre melhor que uma boa memória...\"",
  str_item_intro_3751544 = "Desbloqueia o avatar correspondente.\n\"O Exercício Militar Conjunto começa agora!\"",
  str_item_intro_3751545 = "Desbloqueia o avatar correspondente.\n\"Não negligencie nada, pois os detalhes são importantes.\"",
  str_item_intro_3751547 = "Desbloqueia o avatar correspondente.\n\"Vê-los assim me deixa feliz.\"",
  str_item_intro_3751548 = "Desbloqueia o avatar correspondente.\nSente o impulso? Então simplesmente aproveite com abertura e confiança.",
  str_item_intro_3751549 = [[
Desbloqueia o avatar correspondente.
O perigo realmente amplifica a beleza?]],
  str_item_intro_3751550 = "Desbloqueia o avatar correspondente.\nIdeias sólidas e ação formam a base do sucesso!",
  str_item_intro_3751601 = "Desbloqueia o avatar correspondente.\nUm escudo de torre rachado carregado exclusivamente por Cavaleiros Lumo. Tem formato de pipa e é largo no topo e estreito na parte de baixo, com bordas distintas e uma superfície esculpida com o emblema da igreja.",
  str_item_intro_3751602 = "Desbloqueia a moldura de avatar correspondente.\n\"Uma árvore morta com três esferas coloridas penduradas. Para Martha, o passado se foi, e nesse reino nevado com muitas luzes ela vai dar boas-vindas à uma nova vida.\"",
  str_item_intro_3751603 = "Desbloqueia o Avatar correspondente.\n\"Tem uma engrenagem no centro do pneu. Rosa tinha entrado no deserto e quem seguia a trilha não conseguia mais encontrá-la, apenas os sulcos deixados pelos pneus.\"",
  str_item_intro_3751604 = "Desbloqueia o Avatar correspondente.\n\"Entre os lírios florescentes há uma lâmina afiada. De acordo com a escrita de Yvonne, o destino da Sra. Mercúrio Vermelho está escondido na névoa. Ninguém sabe se ela vai presentear sua espada ou o lírio em suas mangas.\"",
  str_item_intro_3751901 = "Desbloqueia o avatar correspondente.\nSoroz não é só uma Colossus. É um amigo que fez companhia a você por 17 anos.",
  str_item_intro_3751902 = "Desbloqueia o avatar correspondente.\nUsar esse capacete faz você se sentir como um guardião da Noite Branca. Que tipo de Noite Branca? Não vamos investigar isso.",
  str_item_intro_3755004 = "Desbloqueia o avatar correspondente.\n\"Pérolas brilham suavemente, graça da luz da manhã; Florescem em silêncio, um abraço delicado; Será que o mundo percebe, essa perseguição requintada?\"",
  str_item_intro_3762001 = "Desbloqueia a moldura de avatar correspondente.\nEsse padrão antigo representa o reconhecimento dos Caçadores Silenciosos por você. Aceite essa honra suprema do passado.",
  str_item_intro_3762002 = "Desbloqueia a moldura de avatar correspondente.\nUm belo acessório. Decore seu avatar com ele!",
  str_item_intro_3763001 = "Desbloqueia a moldura de avatar correspondente.\nAbaixo do sol escaldante, acima das ondas azuis, nossas memórias inesquecíveis permanecerão eternamente nessa praia quente.",
  str_item_intro_3763002 = "Desbloqueia a moldura de avatar correspondente.\nColoque em sua cabeça e se parecerá um excelente soldado de Illumina.",
  str_item_intro_3763003 = "Desbloqueia a moldura de avatar correspondente.\nQuem não precisa de ajuda para pesar os prós e contras de algo?",
  str_item_intro_3763004 = "Desbloqueia a moldura de avatar correspondente.\nColoque-o e você será a pessoa mais descolada da festa!",
  str_item_intro_3763005 = [[
Desbloqueia o quadro de avatar correspondente.
Um banner dedicado aos bons alunos! Mantem!]],
  str_item_intro_3763006 = "Desbloqueia o quadro de avatar correspondente.\nIsso não é fofo?",
  str_item_intro_3763007 = [[
Desbloqueia o quadro de avatar correspondente.
Faremos companhia....]],
  str_item_intro_3763008 = "Desbloqueia o quadro de avatar correspondente.\nO prêmio de pesca!",
  str_item_intro_3763010 = "Desbloqueia o quadro de avatar correspondente.\nÉ o cheiro da primavera!",
  str_item_intro_3763011 = [[
Desbloqueia o quadro de avatar correspondente.
"Eu sinto que isso vai me ajudar a me tornar um grande piloto!"]],
  str_item_intro_3763012 = "Desbloqueia o quadro de avatar correspondente.\n\"Sob a cortina escarlate há uma canção de ninar escura...\"",
  str_item_intro_3763013 = "Desbloqueia o quadro de avatar correspondente.\nA impressionante coroa é um símbolo de honra e dignidade.",
  str_item_intro_3763014 = [[
Desbloqueia o quadro de avatar correspondente.
Exclusivamente para o Grande Marechal!]],
  str_item_intro_3763015 = "Desbloqueia o quadro de avatar correspondente.\n\"Vestir isso melhorará as habilidades de hospitalidade de alguém?\"",
  str_item_intro_3763016 = "Desbloqueia o quadro de avatar correspondente.\nVista isto, grande mágico!",
  str_item_intro_3763017 = "Desbloqueia o quadro de avatar correspondente.\nO sol é muito forte, então cuide-se e não se queime!",
  str_item_intro_3763018 = "Desbloqueia o quadro de avatar correspondente.\nÉ o aniversário de 1 ano! Vista-o e vá comemorar!",
  str_item_intro_3763019 = "Desbloqueia o quadro de avatar correspondente.\nBasta colocar isso e você ficará todo felpudo como uma Bica!",
  str_item_intro_3763020 = "Desbloqueia o quadro de avatar correspondente.\nNão se preocupe, não está quente!",
  str_item_intro_3763021 = "Desbloqueia o quadro de avatar correspondente.\nParece que a garra de um morcego está agarrando sua cabeça? A faixa de cabeça é muito apertada.",
  str_item_intro_3763023 = "Desbloqueia o quadro de avatar correspondente.\nDizem que usar este boné ajuda a fazer rap melhor. Surpreendentemente, também melhora suas habilidades no beisebol.",
  str_item_intro_3763024 = [[
Buka bingkai avatar yang sesuai.
Suatu keharusan bagi penyanyi mana pun! Benamkan diri Anda dalam musik!]],
  str_item_intro_3763025 = "Desbloqueia o quadro de avatar correspondente.\nNão é para comer, é para vestir!",
  str_item_intro_3763026 = "Desbloqueia o quadro de avatar correspondente.\nUsar isso pode realmente torná-lo tão forte quanto Jeriah? Uma coisa é certa, pelo menos vai mantê-lo a salvo do vento...",
  str_item_intro_3763027 = "Desbloqueia o avatar correspondente.\n\"Na verdade, é um par de óculos transparentes.\"",
  str_item_intro_3763028 = "Desbloqueia o avatar correspondente.\n\"Aha! Ele é o culpado!\"",
  str_item_intro_3763029 = "Desbloqueia o quadro de avatar correspondente. \"Aniversário de 2 anos? Coloque-o! Lembre-se de anotar o do ano passado, hein?\"",
  str_item_intro_3763031 = "Desbloqueia o quadro de avatar correspondente. \"Esse mundo realmente existe? Se não existe, por que estou aqui?\"",
  str_item_intro_3763032 = "Desbloqueia a moldura de avatar correspondente.\nParece fácil se machucar; quem estaria disposto a usá-lo...",
  str_item_intro_3763033 = "Desbloqueia a moldura de avatar correspondente.\nÉ isso que você quer dizer com ser um cavalheiro?",
  str_item_intro_3800001 = "Contém 50 Lumâmbar.",
  str_item_intro_3800002 = "Contém 50 Lumâmbar.",
  str_item_intro_3800003 = "Contém 50 Lumâmbar.",
  str_item_intro_3800004 = "Contém 50 Lumâmbar.",
  str_item_intro_3800005 = "Contém 50 Lumâmbar.",
  str_item_intro_3801001 = "Material de avanço de Aurorian Lendário.\nTodos os membros dos Caçadores Silenciosos possuem esse brasão. Mesmo após mil anos, ele ainda possui um grande poder e pode estimular o potencial dos Caçadores Silenciosos.",
  str_item_intro_3900101 = "Após cada comando simulado, o simulador vai conceder um certo número de pontos de acordo com seu desempenho. Após acumular uma quantidade de Pontos de Comando, você é promovido ao Nível de Comando correspondente, representando sua proficiência tática.",
  str_item_intro_3900201 = "Você pode obter valiosos Fragmentos de Dados de Batalhas de Comando das salas de simulação por uma coleção de dados massiva armazenada nos seus Discos de Dados. Com fragmento de dados suficientes, você pode obter uma mensagem completa deles.",
  str_item_intro_3910100 = "Através de treinamento diligente vem a vitória.\nDerrote todos os inimigos neste desafio de Disco de Dados para concluir o estágio.",
  str_item_intro_3910200 = "Geralmente, o objetivo do combate não é derrotar o inimigo, mas coletar recursos suficientes para vencer a guerra.\nNeste desafio do Disco de Dados, você precisa obter um número de itens especiais para concluir o estágio.",
  str_item_intro_3910300 = "Defenda seus aliados até o fim, mesmo que isso custe sua própria vida.\nNeste desafio do Disco de Dados, certifique-se que o NPC sobreviva por X rodadas.",
  str_item_intro_3910400 = "Você sabe que tipo de inimigo está à frente? Eles certamente são muito fortes, sem exceção. Tome cuidado.\nNeste desafio do Disco de Dados, derrote o inimigo elite para concluir o estágio.",
  str_item_intro_3910500 = "A mente é mais afiada do que qualquer espada.\nNeste desafio do Disco de Dados, você deve resolver o enigma para concluir o estágio.",
  str_item_intro_3910600 = "A batalha é um jogo, assim como o xadrez.\nNeste desafio do Disco de Dados, derrote todos os inimigos para concluir o estágio.",
  str_item_intro_3910700 = "No campo de batalha cruel, o único vencedor de verdade é o último sobrevivente.\nNeste desafio do Disco de Dados, sobreviva por X rodadas para concluir o estágio.",
  str_item_intro_3910800 = "O inimigo ataca como ondas, e sua defesa será a barragem. Aguente firme.\nNeste desafio do Disco de Dados, derrote todos os inimigos para concluir o estágio.",
  str_item_intro_3910900 = "Você e seus inimigos compartilham as mesmas táticas. Vocês podem ser almas gêmeas.\nNeste desafio do Disco de Dados, derrote todos os inimigos para concluir o estágio.",
  str_item_intro_3911000 = "Corte a cabeça da cobra, e o corpo cairá. Derrote o líder inimigo e a vitória será sua.\nNeste desafio do Disco de Dados, derrote o líder inimigo para concluir o estágio.",
  str_item_intro_4090014 = "Unidos pelo destino, as memórias dos gêmeos se juntam lentamente, enquanto um narciso branco como a neve floresce sob a neve escura ao lado do Lago Espelho, aguardando o reencontro através do espelho.",
  str_item_intro_4090334 = "Fornecida pelo Hotel Nuvescer, esta vestimenta mostra o estilo da Montanha Nebulosa. A yukata foi personalizada para Vice. Acompanha uma faixa e berloque, assim como sinos adoráveis, criando um ar um tanto incomum para Vice. Quando coloca a yukata, ela se lembra de um momento inesquecível e precioso.",
  str_item_intro_4090923 = "Pare de me encarar!\nNão tem nada mais desconcertante. Espinhos entrelaçados levantando os pés de Pact, rasgando suas meias de seda e o véu preto em pedaços. Em meio ao caos, Pact tenta equilibrar a taça em sua mão. Parece que este vestido digno e luxuoso não é tão fácil de controlar quanto parece.",
  str_item_intro_4090383 = "Isso não é bom! Gronru está presa em sua caixa de brinquedos e não consegue sair! Para celebrar a chegada do Ano-Novo, Gronru tem um presente surpresa pra você! Olhe como ela é fofa, presa naquele lugar com uma pilha de brinquedos e com um traje vermelho e branco festivo. Ela até amarrou um belo laço em seu braço mecânico! Tente ignorar a bomba de aparência mortífera na cabeça dela…",
  str_item_intro_4090333 = "Vice escolheu um traje de banho confortável para participar do festival Monarca do Oceano. O traje de banho possui um desenho especial para coincidir com os hábitos de vestimenta de Vice e permite que sua cauda fique livre. Além dessa estrutura especial, olhe com atenção e perceberá que o sol preto e dourado combina com sua personalidade vibrante. Conforme seu triturador de gelo funciona, essa beldade de cabelo curto convida você a se juntar a ela na água com um sorriso. Vôlei de praia, bebidas geladas, a barraca de raspadinha... Durante aquele verão, você e Vice compartilharam algumas memórias pessoais.",
  str_item_intro_4090853 = "Um traje sinistramente atraente composto de um top cativante, uma saia elegante, lindas mangas de tecido, um véu de cerimônia e botas estilosas… O traje de Jane não só é deslumbrante: as flores ao redor da bainha da sua saia possuem um significado especial. Mas por que ela escolheria vestir esse traje quando ela se orgulha de ser uma forasteira?",
  str_item_intro_4090863 = "Parte da série Donzela Branca, projetada para a celebração do Monarca do Oceano. Seu puro brilho branco impecável foi selecionado especialmente para refletir a inocência e a devoção inseparáveis da identidade de Uriah. Vinhas floridas aparecem em sua volta, silenciosamente respondendo seu chamado. Para outros, seu estado mental continua inalterado. Apenas as flores ao seu redor conhecem a verdade... Quando está em plena vista à beira-mar, ela não pode deixar de se sentir um pouco tímida com essa roupa. O céu ensolarado, a brisa salgada do oceano, a água fria do mar... Quando ela brandir sua espada cerimonial, a mais bela e poética música tocará mais uma vez.",
  str_item_intro_4090573 = "Enquanto Philyshy se enrola na cama vestindo seu pijama felpudo, ela cai em um sono profundo e tem um lindo sonho. Nele, Yumi está ao lado dela, a abraçando e acariciando seus cabelos, como um pequeno aquecedor pessoal, aquecendo seu coração e a levando de volta a tempos mais simples.",
  str_item_intro_4091023 = "Esta roupa simples incorpora a essência do que significa ter uma alma em chamas, e nos confins escuros e opressivos da arena subterrânea, ela serve como a única luz guia. Renegados sobem ao palco, lutando com corpos, espírito e perseverança robustos, seu sangue queimando como fogo. Eles se enfurecem como meteoros em chamas, depois desaparecem como cinzas. Ela estala os dedos, pronta para caçar tudo em sua mira.",
  str_item_intro_4090453 = "Conforme a neve começa a cair, o inverno chega com ela. As ruas vazias estão cheias apenas com o tremeluzir de quentes luzes amarelas. Se você for um viajante solitário, não se preocupe em se perder. Apenas olhe ao redor, sua carruagem o aguarda. Com um terno branco, botas pretas, cabelos lisos e brilhantes e elegância, um cavalheiro discreto e calmo está aguardando para levar você.",
  str_item_intro_4090993 = "Areia se curva timidamente no sofá, suas pernas nuas, sapatos descartados para um lado, e o vestido exótico indicando que ela acabou de voltar de um baile. Como uma princesa de um conto de fadas, seu vestido mágico desaparecerá com o avanço do relógio, mas essa memória, esse tempo passado com você, nunca desaparecerá.",
  str_item_intro_4090263 = "Qual é o significado da existência para uma consciência incorpórea? Depois de colocar essas roupas estranhas, a pergunta desconcertante permanece na mente de Uriel, obrigando-a a ponderar sem fim. Ela pode encontrar a resposta no mundo da literatura simulada? Quem sabe. Mas você pode andar, pensar e sentir junto com sua busca.",
  str_item_intro_4090543 = "Austero e sério é o modus operandi de Nadine. Nunca se cansando, ela sempre cumpre suas funções. Mesmo com sua nova roupa de primavera e uma linda lanterna, seu personagem brilha.",
  str_item_intro_4091113 = "Depois de chegar à praia, até mesmo o geralmente melancólico Beryl está mais relaxado que o normal. Este maiô é bastante minimalista, mas ainda é capaz de acentuar a figura de Beryl de vez em quando. No entanto, ela está alheia a isso e completamente fixada em construir seu castelo de areia. Essa é talvez a coisa favorita de Beryl sobre esta viagem à praia.",
  str_item_intro_4090883 = "Céu azul, nuvens brancas, ruas lisas – isso não parece o Deserto Rediesel, e Maggie também parece muito diferente. Ela usa um uniforme de marinheiro limpo e engomado, sua gravata-borboleta balançando ao vento. Nesta manhã brilhante, você pode vê-la cavalgando vagarosamente, mordiscando seu pão. Ela não vai se atrasar para a escola?\n\nEssa roupa faz Maggie se destacar entre as Chaves Rediesel, e também permite que ela veja um cenário muito diferente. Talvez isso seja parte de sua magia?",
  str_item_intro_4090963 = "Hum, professor? É Sariel? Parece que Sariel leva seu segundo emprego a sério. Ela até vestiu o uniforme! Este novo Sariel parece muito mais confiável que o antigo. Ela fala gentil e eloquentemente. Talvez em breve você possa aprender uma lição com ela!",
  str_item_intro_4091053 = "As roupas podem ser comuns, mas Eve ainda é Miss Popularidade em Rediesel Wrench. Nem ela sabe o quão popular ela é. E agora, como líder de torcida, ela ficou ainda mais amada depois de vestir essa roupa! Só não olhe, ou você vai levar uma chave inglesa na cara!",
  str_item_intro_4090064 = "Esta roupa leve e sedosa coberta de fitas... pijama?! Por que alguém projetaria uma coisa dessas? Como alguém deve usá-lo na frente dos outros? Perturbada, Carleen não sabia como proceder, então ela decidiu experimentá-lo primeiro, mas ela não esperava se sentir completamente diferente de seu habitual eu sério.\nPara se juntar à festa do pijama e se divertir com todos, Carleen decidiu mergulhar.",
  str_item_intro_4090303 = "Mangas pretas e um manto carmesim. Apresentando, o samurai que livrou o mundo dos malfeitores—Shinnosuke!\nComo líder da Chave Rediesel, Sinsa pratica o princípio do “faça como os locais fazem”. Seja as roupas que ele usa ou a lâmina em sua cintura, eles são uma representação perfeita do charme de Cloud Island, e até mesmo sua risada parece ser totalmente espontânea. Mas esteja avisado, se este samurai ronin estiver de bom humor, ele pode recitar um poema improvisado e cantar uma música...",
  str_item_intro_4090443 = "A brisa sopra pelos pinheiros e o sol quente ilumina o salão. Quando você fugir da agitação da cidade e do trabalho sem fim, por que não aproveitar a oportunidade para descansar no tranquilo Cloud Mountain Hotel? O princípio de equilíbrio entre vida profissional e pessoal da Vivian é a verdadeira maneira de recuperar força e energia antes de retomar o trabalho!\nClaro, tudo isso deve ser planejado!",
  str_item_intro_4090643 = "A nova roupa de combate de Wrath é tecida com fios de seda orientais, não apenas justos, mas também elegantes e graciosos. Embora pareça um pouco fino, é fácil de se movimentar e não parece impedir sua capacidade de luta.\nDando socos e flexionando seus músculos, correndo e removendo todos os obstáculos em seu caminho - não importa quais perigos surjam em seu caminho, a inabalável Ira os enfrentará de cabeça!",
  str_item_intro_4090893 = "Para aproveitar ao máximo esse feriado raro, Irridon preparou roupas no estilo Cloud Island. O tecido dourado adornado com bordados combinados com uma capa de pele branca como a neve parece simplesmente magnífico. Ela estava ansiosa para usar sua roupa em um passeio pelas ruas de Cloud Island ou fazer um passeio de trem para apreciar as vistas.\nNo entanto, eventos repentinos atrapalharam todos os seus planos e, para proteger suas férias, Irridon não hesitou em transformar a estação de Cloud Island no Salão da Justiça.",
  str_item_intro_4090653 = "\"Navegador, venha pway hanetsuki comigo!\"\nTweety estava em tal excitação quando ela se aproximou. Mas quem diria que um divertido jogo casual iria se transformar em uma batalha implacável pelo topo?! Com saques tão magníficos e chutes fortes, é impossível para um jogador comum sobreviver!\nQuem perder o jogo será punido com o desenho de seus rostos. Só podemos esperar que Tweety mostre alguma misericórdia e se controle um pouco...",
  str_item_intro_4090233 = "Embora tímida por natureza, Connolly decidiu ajudar a animar seus amigos que participavam das corridas. No entanto, comparado com o que ela estava acostumada a usar diariamente, esse uniforme era realmente \"outra coisa\".\nMesmo assim, Connolly aceitou a roupa ousada apresentada a ela por um vendedor na esperança de se tornar mais extrovertida.",
  str_item_intro_4090613 = "\"Ooh... Então é assim que o continente se parece!\"\nChandra, no alto das nuvens, não tem medo de altura. Enquanto ela assiste ao rali acontecendo lá embaixo, a intensa competição a faz exclamar de vez em quando. Mas... o que há com o balão de ar quente e sua roupa estranha?\nAcontece que tudo faz parte de sua misteriosa \"terapia de visualização\", que parece ajudar as pessoas a liberar emoções reprimidas.",
  str_item_intro_4090843 = "\"Tão quente como a areia do deserto e tão fresca como a água da nascente, uma justaposição do moderno e do tradicional.\"\n\"Chocante e ultrajante...\"\nEmbora as críticas variassem muito, no minuto em que Istvan vestiu sua fantasia, todas as críticas caíram. Embora mais adequado para um grande salão, mesmo aqui ele exala o carisma de um superstar. Talvez seja a aura do próprio \"Shadowlord\" que empresta um fator extra de charme.",
  str_item_intro_4090603 = "A roupa de um juiz de corrida sempre se destaca. Afinal, para que os pilotos identifiquem os juízes em alta velocidade, eles precisam se destacar.\nJona, que só se candidatou ao emprego porque precisava de dinheiro para pagar a conta do bar, logo descobriu os segredos obscuros da corrida. Embora pretendesse cuidar da própria vida, acabou indo para a pista por causa de uma garotinha, determinada a fazer justiça aos bandidos que lideram as corridas fixas.",
  str_item_intro_4090713 = "O sol escaldante faz com que os carros de corrida emitam colunas de fumaça e o suor evapora com um silvo assim que atinge o solo.\nMesmo assim, Taki entra nas corridas \"totalmente preparado\", determinado a superar seus oponentes. Mas ele está realmente apenas nisso pelo dinheiro?",
  str_item_intro_4091263 = "O autor best-seller, que está preso em um gargalo criativo, se veste bem, planejando vagar pelas ruas em busca de ideias. Qual é o ponto de vestir-se? Talvez seja porque ela não quer que as pessoas saibam que o majestoso gerente da guilda tem um hobby tão \"feminino\" em particular.\nMas tome cuidado para não subestimar Bethela dedicação de ela ao seu hobby - ela está disposta a arriscar tudo apenas por um lampejo de inspiração...",
  str_item_intro_4090673 = "A brisa sopra e o vestido branco fofo balança suavemente, revelando as flores vermelhas bordadas. AliceA roupa de de alguma forma lembra as pessoas de... um tipo de bolo. Sim. O bolo de morango que só se pode saborear em festas de aniversário. Mas na Dream Dessert House, você pode experimentar qualquer sobremesa de graça, desde que responda às perguntas de Alice, o proprietário, honestamente. Isto é Aliceé uma punição especial para você. Ops, quero dizer... \"recompensa\" especial.",
  str_item_intro_4090103 = "\"Uma roupa limpa e arrumada é o orgulho de uma empregada doméstica\"!\nColoque o traje de empregada Lita costurado à mão e a faixa de cabeça com renda. Ah, não esqueça de colocar o avental com o laço dourado.\nHoje Louise tem que ajudar o mestre a se vestir e organizar um chá da tarde. Não se preocupe, as abelhas, os cervos e até as nuvens ajudarão.\nOlhar! A empregada já começou a trabalhar.",
  str_item_intro_4090283 = "Ahem, vamos dar as boas-vindas à empregada chefe de Upton Manor! O que, ela parece familiar? Sim você está certo. Este é o nosso querido Rafael!\nRecentemente, ela recebeu uma missão especial para treinar as empregadas de Lumopolis em habilidades de batalha. Agora que o semestre está chegando ao fim, as empregadas, sob a cuidadosa orientação de Raphael, têm obtido excelentes resultados. É que... A carreira de empregada doméstica de Rafael não parece estar indo tão bem.",
  str_item_intro_4091163 = "A brisa sopra e o vestido branco fofo balança suavemente, revelando as flores vermelhas bordadas. AliceA roupa de de alguma forma lembra as pessoas de... um tipo de bolo. Sim. O bolo de morango que só se pode saborear em festas de aniversário. Mas na Dream Dessert House, você pode experimentar qualquer sobremesa de graça, desde que responda às perguntas de Alice, o proprietário, honestamente. Isto é Aliceé uma punição especial para você. Ops, quero dizer... \"recompensa\" especial.",
  str_item_intro_4090703 = "Sob o escrutínio afiado de Leona, você sente o ar ao seu redor aquecer e sua respiração encurtar. É por causa dos nervos? Na verdade, quem não ficaria nervoso na frente do poderoso e belo Leona? Com sandálias de tiras enroladas nas pernas e seu corpo adornado com acessórios, ela parece muito diferente de seu eu habitual. Ainda assim, ela exala sem esforço a sensação de que tudo no mundo é sua ostra.",
  str_item_intro_4090813 = "Este é o traje que Brock especialmente preparado para si mesmo em busca de um certo \"algo\". Calções de banho que o ajudam a deslocar-se com facilidade, uma prancha de surf com o seu estilo especial e um casaco transparente que lembra uma gabardina. Casaco transparente? Vamos ser francos, a verdadeira razão Brock desenhou um casaco transparente foi provavelmente para pescar elogios de nós – Eis que aquele corpo dele construído a partir de proteína em pó e exercícios intensos, de sol e suor, anseia por seus elogios.",
  str_item_intro_4091123 = "Uma lenda urbana popular em Umbraton recentemente. Cartões de visita, ladrões destruindo o caos por toda parte, uma jóia roubada... Nosso principal suspeito é o descuidado Smokey afinal? Se você quer saber a verdade, temo que primeiro terá que abrir as algemas dela. Claro, seu novo título é tão intrigante quanto suas novas roupas - \"Gato Preto\", que virá e pegará as gemas em três dias, como prometido.",
  str_item_intro_4090384 = "Esta roupa veio primeiro, ou o jogo que esta roupa acompanhava veio primeiro? Não importa mais. O importante é que Gronru preparou isso especialmente para suas férias e entrou no modo de férias imediatamente após usá-lo. Mesmo que ela vá apenas ao aquário por um dia e não à praia.",
  str_item_intro_4090413 = "Quantas identidades ela tem? Ela é a Guia de Lumopolis, mas também tem muitas outras responsabilidades. Um deles é servir como embaixador público do Tir' Hotel. Este maiô que ela está vestindo é para uma sessão de fotos de um flyer. Delicado e preciso, é feito do material mais requintado. Olhando para ela, não se pode deixar de se perguntar sobre este hotel que ela está promovendo.",
  str_item_intro_4090873 = "Beverly usa esta armadura para se adaptar melhor ao ambiente local quando visita o território insular de sua família. Embora seja muito mais minimalista do que seu traje habitual, sua aura aristocrática é forte demais para esconder, não apenas por causa de suas raízes familiares guerreiras, mas também por causa de sua busca pela honra de um nobre.",
  str_item_intro_4091293 = "Embora ele esteja vestido com roupas frescas de verão, seu olhar sério informa a todos que ele não está aqui para relaxar, mas para cumprir uma missão obrigatória. Essa roupa permite que Luke mantenha sua resistência na floresta quente e úmida, e também é uma roupa formal especialmente preparada para ser usada na luta para proteger borboletas preciosas de caçadores desavergonhados.",
  str_item_intro_4091483 = "A festa da água no deserto está prestes a começar, mas o que deixa muitas pessoas particularmente animadas é a oportunidade de testemunhar a incrível figura de Azure! Ela é especialmente atraente sob as roupas transparentes... Ahem, por favor, controle-se e não olhe por muito tempo! Desfrutar de uma brisa quente e úmida da noite, ouvir música alta e dançar com uma multidão de vez em quando é uma explosão!",
  str_item_intro_4090254 = "Uma roupa de palco magnífica que exala um ar elegante de nobreza antiga. Parece bastante deslocado com a moda de hoje, mas isso é porque Caronte projetou seu novo traje para ser assim. Por mais extravagante que seja, rapidamente chama a atenção do público sempre que Charon está diante da câmera, concedendo-lhe a oportunidade de mostrar suas habilidades de atuação inesquecivelmente impressionantes em todo o seu potencial. Nesses momentos, pode-se dizer que tanto Caronte quanto seu traje foram feitos para atuar.",
  str_item_intro_4090683 = "Extra, extra! Uma colaboração recente entre o Courier Union e os jornais Umbraton dá aos correios um trabalho adicional: a venda de assinaturas de jornais. E assim, Wendy veste seu uniforme novinho em folha e inicia seus esforços de venda de jornais com sua empolgação e diligência características! A natureza rápida e espirituosa de Wendy nunca a deixa ficar atrás de seus colegas, mesmo quando ela está assumindo uma tarefa desconhecida!",
  str_item_intro_4091003 = "Sikare, geralmente ligada ao passado, trocou seu visual regular por um novo para lidar com uma situação inesperada. Embora ela pareça uma médica normal, o conteúdo de sua maleta está cheio de instrumentos médicos que são tudo menos comuns. Isso porque ela deve atender não apenas às doenças dos vivos, mas também aos desejos dos falecidos...",
  str_item_intro_4091203 = "Graças à demanda popular, Hedy acaba participando de um evento de intercâmbio destinado a promover a união e cooperação entre a Federação Illumina e Lumopolis. A pedido de seus superiores, ela viaja para Gannon City para atuar como xerife por um dia, promovendo a segurança no trânsito e a prevenção do crime nas ruas. Apesar de ser uma orgulhosa cavaleira de Lumopolis, Hedy obedece e veste seu uniforme da Federação. Embora ela ache um pouco desconfortável, isso não obscurece seu charme e confiança naturais.",
  str_item_intro_4091193 = "Revy intencionalmente acaba na prisão em seu esforço para obter um lendário molho picante de suas memórias, indo para o perigo sozinha. Atrás dessas enormes paredes de pedra, ela se encontra cercada por criminosos endurecidos de áreas criminosas. Uma situação perigosa, de fato... Revy, que vem da Federação Illumina e nunca experimentou os perigos caóticos de tal lugar, pode ter sucesso em sua missão secreta especial?",
  str_item_intro_4091213 = "Uma linda flor carmesim adornada com incontáveis espinhos cruéis: tudo na aparência de Paloma grita: \"aproxime-se por sua própria conta e risco\". Juntamente com um leve sorriso, um ar de elegância fria a envolve. Aqueles que põem os olhos nesta donzela mortal sabem em seus corações que provocá-la seria a última coisa que fariam. Incorrer na ira do mais sinistro senhor do crime de Umbraton seria uma decisão mais sábia em comparação. Ou ela já se tornou um senhor do crime...",
  str_item_intro_4090123 = "Um dia, uma lenda surgiu repentinamente em Gannon - a do \"Executor da Justiça\", também conhecido como \"O Justiceiro\". Um súbito relâmpago abre o céu sempre que alguém quebra as regras, e Nemesis aparece ao lado deles para aplicar uma punição estrondosa. Depois de fazer isso, ela entrega uma frase que os corta até os ossos e os força a se arrepender. Depois de executar sua justiça, ela desaparece em um flash de luz para punir outro malfeitor.",
  str_item_intro_4090773 = "Em um raro dia de folga, Bethlehem se depara com a biografia de uma talentosa cantora. Ela logo se perde nas páginas deste livro, tornando-se uma com a cantora, experimentando sua ascensão à fama, seus triunfos e depois a perda de sua voz. \"E se eu fosse como ela?\" É uma pergunta para a qual Belém não tem resposta. Tudo o que ela consegue fazer é se imaginar no lugar da cantora, pegando um instrumento musical e tocando. Ela imagina ter uma paixão pela criação, ela imagina inevitavelmente perder a voz no palco, ela imagina a vida como cantora, tudo isso ao mesmo tempo em que aceita seu próprio futuro.",
  str_item_intro_4090833 = "Para despertar Lilin, que eles defendem com tanto ardor, eles devem... se tornar ídolos? Mesmo assim, elas parecem cumprir rigidamente sua programação como empregadas domésticas. Eles podem realmente chegar ao topo de uma profissão onde vitalidade e criatividade são cruciais? Bem, se houver um plano que eles possam seguir e sua vantagem numérica possa ser utilizada de alguma forma, pode ser possível...",
  str_item_intro_4091313 = "Embora mantenha sua perspectiva única do mundo, Novio se torna um pianista mestre no instante em que veste seu novo visual. Ele traz calor e boa vontade aos sobreviventes de Northland e encoraja um certo membro especial da audiência a perseverar e seguir em frente com determinação, sempre lutando pelo autoaperfeiçoamento.",
  str_item_intro_4091383 = "Embora seu superior a obrigue a participar da competição de ídolos, Siobhan ainda faz o possível para se preparar bem. Enquanto trabalha em seus talentos, ela também dedica um esforço considerável para pesquisar e desenhar a roupa perfeita. Este espírito inflexível de pesquisa científica traz uma transformação surpreendente em Siobhan - sua luz brilhante que não pode ser extinta, o caminho inignorável para o futuro estrelato.",
  str_item_intro_4090273 = "Ela é um horror entre os amantes de Lumopolis - a cada Dia da Coroa da Lua, haverá um cavaleiro de branco patrulhando todos os cantos da cidade, procurando pelos apaixonados. Assim que encontrar um, ela emitirá imediatamente uma \"Proibição de se apaixonar\". Por isso, ela é conhecida como o \"relâmpago que quebra o amor\", que apavora os amantes.",
  str_item_intro_4090553 = "Ao contrário de sua aparência profissional habitual, Pittman parece ter sido influenciado pela festividade do Mooncrown Day quando escolheu sua roupa. Carrega uma doçura que raramente se vê nele sem perder a firmeza e elegância habituais. Claro, isso não é porque ele é falado, mas simplesmente para ser um mensageiro qualificado e realizar um desejo há muito acalentado por outra pessoa.",
  str_item_intro_4090913 = "No mundo de Chloe, o amor sempre vem com a separação, então seria um pouco demais pedir a ela para tocar a música que celebra o doce amor. Nesse caso, podemos louvar o amor eterno em nome de Deus - o afeto das pessoas pode desaparecer depois de alguns anos, mas não se preocupe, a luz abençoará e amará a todos igualmente.",
  str_item_intro_4091673 = "Não faltam todos os tipos de truques de mágica em um lugar social como este, mas um senso de mistério é a chave para todos eles. Um cartão, uma palavra ou mesmo apenas um olhar. Alguém poderia completar a grande e requintada performance em um momento de desatenção sem ninguém saber. Embora não haja aplausos como de costume, é um bom negócio para Jeno quando ele quer fazer favores para seus amigos de vez em quando.",
  str_item_intro_4090043 = "Um cadáver frio, pistas marcadas, cordão após cordão... Uma cena tão clássica e cheia de suspense sempre pode fazer a imaginação de qualquer um voar. Por exemplo, o detetive pode ser o assassino ou conivente com o assassino, o assassino pode estar escondido entre nós, ou todas as testemunhas podem ser assassinos... Quem diria que o falecido e o detetive estavam trabalhando juntos?",
  str_item_intro_4090483 = "Uma atmosfera sinistra penetrou nas ruas pacíficas de Umbraton. Embora os transeuntes na rua parecessem desfrutar da noite tranquila, os olhos vigilantes de um determinado patrulheiro observam de perto para capturar todos os vestígios de pecado. Enquanto estiverem escondidos nesta cidade, ela, a guardiã da paz, não deixará de patrulhar as ruas. Tudo é para... sua única irmã!",
  str_item_intro_4091484 = "Um escritório com janelas claras e limpas, um sofá macio, vinho inebriante e o diretor interino meio deitado no sofá. Não deixe que seu comportamento preguiçoso o engane - essa linda mulher é perigosa, especialmente para aquela que logo se tornaria sua presa, literalmente.",
  str_item_intro_4091663 = "\"Bem... onde estão aqueles pequeninos fofos?\" Para encontrar essas bestas maravilhosas e expor a verdade, Fia torna-se um detetive e começa a investigar este misterioso caso cuidadosamente, examinando todos os tipos de evidências e considerando os principais pontos de suspeita. Olhando para o quão séria e trabalhadora ela parece, talvez ela realmente descubra algo.",
  str_item_intro_4090983 = "Sob a ordem do Shadowlord, o recluso Cuscuta tem a tarefa de ser um detetive e pegar criminosos desenfreados. Embora ela lute com visitas de rua e entrevistas com testemunhas, sua intuição aguçada permite que ela deduza a identidade do criminoso a partir das pistas em mãos. Do conforto de sua cadeira, ela observa o jogo de xadrez e se perde na contemplação até encontrar a resposta por dedução.",
  str_item_intro_4091034 = "As pessoas não devem cometer crimes, ou enfrentarão a condenação dos céus, que é conhecida no mundo mortal como julgamento, julgamento e punição. Claro, o processo não é tão assustador quanto parece, especialmente quando Eicy torna-se seu oficial de interrogatório. A menina gentil nunca recorre à violência para quebrar as defesas de uma pessoa... Ou melhor, essas defesas são inúteis em primeiro lugar. Portanto, se você a conhecer, não comece uma briga inútil. Apenas deixe tudo para Eicy.",
  str_item_intro_4090293 = "A fim de honrar o desejo final do mestre, Gabriel vestiu um vestido magnífico e se aventurou no orfanato em Umbraton. O ambiente sombrio e degradado contrastava com o traje requintado, e as ações um tanto desajeitadas de Gabriel levaram os órfãos a confundi-la com uma bruxa. Mas, no final, os órfãos sentiram a dedicação sincera de Gabriel em proteger seu lar, e o próprio vestido parecia irradiar uma luz reconfortante.",
  str_item_intro_4090463 = "Para os adultos, pode ser um terrível grimório de magia negra, mas para eles, é uma porta de entrada para um reino maravilhoso de fantasia, encantamento e maravilhas extraordinárias criadas exclusivamente para suas almas curiosas e espirituosas. Para preparar a poção proibida, eles procuram incansavelmente ingredientes peculiares, vestindo roupas únicas que apenas acentuam ainda mais sua individualidade.",
  str_item_intro_4090623 = "Para garantir a sessão de estudo organizada por Leah vai bem, Sylva fez um esforço especial para vestir esse traje formal, lembrando um jovem estudioso pronto para conhecer seu estimado professor - inteligente, sábio e bem-educado. Seu comportamento infundiu sem esforço a sessão de estudo com uma atmosfera positiva, ganhando o título de 'estudante modelo'...",
  str_item_intro_4091433 = "Enquanto viajam pela floresta à noite, dizem que seres sinistros permanecem no mundo após uma tempestade. Por esta razão, Rinne veste suas vestes cerimoniais e segura o Kagura Bell no alto, pronto para expurgar presenças vis deste mundo em defesa dos vivos.\n\"Uma ode aos mortos e aos vivos. May esta canção o acompanha até o outro lado do rio Lethe.\"\n\"O rio Lethe corre. O ressentimento e a amargura crescem.\"\n\"A datura canta em harmonia.\"\n\"Ouça em paz. Deixe sua alma me seguir.\"",
  str_item_intro_5000001 = "Diz-se que contém algumas substâncias misteriosas com informações antigas, que podem acelerar a construção de edifícios e a fabricação de móveis.",
  str_item_intro_5000002 = "Cloud Gardens - Atualizações de tesouros",
  str_item_intro_5002101 = "Madeira resistente, adequada para construção civil, fabricação de móveis, etc.",
  str_item_intro_5002201 = "O minério recém-escavado precisa ser processado. Dito isto, já tem algum valor no mercado.",
  str_item_intro_5003001 = "Pedaços de pedra encontrados em várias partes dos Jardins das Nuvens que deveriam ser relíquias, mas sua função exata é desconhecida. Os Chubbs gostam dessas peças e trocam certas coisas por elas.",
  str_item_intro_5003101 = "Uma cola comum para construção civil e fabricação de móveis, que pode unir bem os materiais e tornar os componentes fortes.",
  str_item_intro_5003102 = "A melhor cola para construção civil e fabricação de móveis. Apenas um pouco é suficiente para unir os materiais firmemente e tornar os componentes muito fortes.",
  str_item_intro_5011001 = "Machado Leve Nv. 1. Seu cabo é oco, permitindo cortar rapidamente troncos grossos de árvores.",
  str_item_intro_5011002 = "Machado Leve Nv. 2. Seu cabo é oco, permitindo cortar rapidamente troncos grossos de árvores.",
  str_item_intro_5011003 = "Machado Leve Nv. 3. Seu cabo é oco, permitindo cortar rapidamente troncos grossos de árvores.",
  str_item_intro_5011004 = "Machado Leve Nv. 4. Seu cabo é oco, permitindo cortar rapidamente troncos grossos de árvores.",
  str_item_intro_5011005 = "Machado Leve Nv. 5. Seu cabo é oco, permitindo cortar rapidamente troncos grossos de árvores.",
  str_item_intro_5012001 = "Bastão de Campeão Nv. 1. É bem equilibrado, resistente e tem uma linha de pesca forte, tornando-se uma ótima ferramenta para capturar peixes grandes.",
  str_item_intro_5012002 = "Bastão de Campeão Nv. 2. É bem equilibrado, resistente e tem uma linha de pesca forte, tornando-se uma ótima ferramenta para capturar peixes grandes.",
  str_item_intro_5012003 = "Bastão de Campeão Nv. 3. É bem equilibrado, resistente e tem uma linha de pesca forte, tornando-se uma ótima ferramenta para capturar peixes grandes.",
  str_item_intro_5012004 = "Bastão de Campeão Nv. 4. É bem equilibrado, resistente e tem uma linha de pesca forte, tornando-se uma ótima ferramenta para capturar peixes grandes.",
  str_item_intro_5012005 = "Bastão de Campeão Nv. 5. É bem equilibrado, resistente e tem uma linha de pesca forte, tornando-se uma ótima ferramenta para capturar peixes grandes.",
  str_item_intro_5013001 = "Picareta Pesada Nv. 1. Com uma cabeça pesada, sua força oscilante é forte o suficiente para quebrar qualquer rocha.",
  str_item_intro_5013002 = "Picareta Pesada Nv. 2. Com uma cabeça pesada, sua força de balanço é forte o suficiente para quebrar qualquer pedra.",
  str_item_intro_5013003 = "Picareta Pesada Nv. 3. Com uma cabeça pesada, sua força oscilante é forte o suficiente para quebrar qualquer rocha.",
  str_item_intro_5013004 = "Picareta Pesada Nv. 4. Com uma cabeça pesada, sua força de balanço é forte o suficiente para quebrar qualquer rocha.",
  str_item_intro_5013005 = "Picareta Pesada Nv. 5. Com uma cabeça pesada, sua força oscilante é forte o suficiente para quebrar qualquer rocha.",
  str_item_intro_5014001 = "A cabeça da pá é espessa, portanto, mesmo que atinja rochas duras, nunca lasca. Ele vai fazer a escavação como uma brisa.",
  str_item_intro_5011012 = "Uma pedra áspera e dura que pode afiar uma borda maçante.\nO Light Axe pode ser atualizado na mochila.",
  str_item_intro_5012012 = "A madeira de alta qualidade encontrada nos Cloud Gardens é cortada em fatias finas para aumentar a dureza do corpo da haste e manter sua tenacidade. Com a linha de pesca especial, a Champion's Rod pode lidar facilmente com todos os tipos de situações. O Bastão do Campeão pode ser atualizado na mochila.",
  str_item_intro_5013012 = "Girando a roda rapidamente com a mão, você pode afiar a ponta romba da palheta.\nA picareta ponderada pode ser atualizada na mochila.",
  str_item_intro_5111001 = "Este é o projeto do Pavilhão do Conquistador. Use-o para desbloquear o método de produção do Pavilhão do Conquistador na Torre Jacinto.",
  str_item_intro_5111002 = "Este é o planta do Stone Arch. Use-o para desbloquear o método de produção do Stone Arch na Hyacinth Tower.",
  str_item_intro_5111003 = "Este é o projeto do Midway Freight Depot. Use-o para desbloquear o método de produção do Midway Freight Depot na Hyacinth Tower.",
  str_item_intro_5111004 = "Este é o planta do Poço Esmeralda. Use-o para desbloquear o método de produção do Emerald Well na Hyacinth Tower.",
  str_item_intro_5111005 = "Este é o projeto do Moinho de Vento Helix. Use-o para desbloquear o método de produção do item na Hyacinth Tower.",
  str_item_intro_5121001 = "Este é o planta da cerca de madeira Cloud Gardens. Use-o para desbloquear o método de produção de Cloud Gardens Wooden Railing na Hyacinth Tower.",
  str_item_intro_5121002 = "Este é o planta do corrimão de madeira Cloud Gardens. Use-o para desbloquear o método de produção de Cloud Gardens Wooden Railing na Hyacinth Tower.",
  str_item_intro_5121003 = "Este é o planta do Cloud Gardens Wooden Hedge. Use-o para desbloquear o método de produção de Cloud Gardens Wooden Hedge na Hyacinth Tower.",
  str_item_intro_5121004 = "Este é o planta do Cloud Gardens Stone Railing. Use-o para desbloquear o método de produção de Cloud Gardens Stone Railing na Hyacinth Tower.",
  str_item_intro_5121005 = "Este é o planta do Cloud Gardens Stone Hedge. Use-o para desbloquear o método de produção de Cloud Gardens Stone Hedge na Hyacinth Tower.",
