  str_item_intro_5134049 = "Este é o projeto do Record Obelisk. Use-o para desbloquear o método de produção do item na Torre Jacinto.",
  str_item_intro_5211001 = "Um pavilhão com pilares tortos e um telhado de pedra coberto de musgo. Embora não pareça estar de acordo com o senso comum arquitetônico, o pavilhão é, no entanto, muito robusto.",
  str_item_intro_5211002 = "Diz-se que o arco foi esculpido em um único bloco de pedra e, mesmo que seja coberto com uma camada de grama, não há necessidade de se preocupar com sua durabilidade.",
  str_item_intro_5211003 = "Uma parada para as pessoas fazerem uma pausa no transporte de suprimentos no vale. É rápido de construir e fácil de desmontar, então muitos podem ser construídos no caminho.",
  str_item_intro_5211004 = "Um poço sem fundo construído na captação de fontes de água subterrânea. Uma cerca de pedra foi instalada em torno dela para evitar cair na água. Como o poço é muito profundo, a água é pura e fresca.",
  str_item_intro_5211005 = "Um moinho de vento de forma única. Embora pareça estar na extremidade inferior, faz uso suficiente do vento! E com alguma tecnologia maravilhosa, as velas giram lentamente mesmo quando não há vento.",
  str_item_intro_5221001 = "Cercas de madeira. Quando conectados, eles podem cercar um pedaço de terra em Cloud Gardens.",
  str_item_intro_5221002 = "Grades mais curtas. As tiras de madeira emendadas aleatoriamente dão uma vibe rústica.",
  str_item_intro_5221003 = "Sebes de madeira fáceis de fazer. Ideal para barricar e dividir áreas.",
  str_item_intro_5221004 = "Cercas de pedra que são pesadas, mas fortes. Eles são mais duráveis do que cercas de madeira.",
  str_item_intro_5221005 = "Sebes de pedra. Uma vez plantadas no solo, podem ser usadas por muitos anos, mesmo quando expostas a diferentes intempéries.",
  str_item_intro_5221006 = "Os trilhos de pedra resistentes não apenas parecem estáveis, mas também dão às pessoas uma sensação de segurança.",
  str_item_intro_5223001 = "Pisos quadrados que podem ser colocados ordenadamente. Adequado para estradas principais e edifícios importantes.",
  str_item_intro_5223005 = "Pavimentos feitos de pedras irregulares. Adequado para pavimentar caminhos e decorar pátios.",
  str_item_intro_5231001 = "Uma mesa apoiada por duas lajes de pedra trapezoidais. Pesado, mas resistente.",
  str_item_intro_5231002 = "Uma mesa de pedra redonda menor. Quando combinadas com as cadeiras correspondentes, são adequadas para conversas casuais entre dois amigos.",
  str_item_intro_5231003 = "Uma mesa de madeira com suportes nos quatro lados. Amplo e plano, é adequado para várias pessoas se sentarem juntas no lazer.",
  str_item_intro_5232001 = "Um banco de pedra redondo com um pilar de pedra dentro do corpo oco para apoio. Não é apenas robusto, mas suas bordas arredondadas também reduzem os riscos de segurança.",
  str_item_intro_5232002 = "Um banco de pedra quadrado, largo na parte inferior e estreito na parte superior, tem uma camada de madeira para isolar o ar frio da pedra. É generoso na forma e simples na produção. A única mosca na pomada é que é fácil atingir a borda do banco de pedra.",
  str_item_intro_5232003 = "Uma cadeira de madeira simples e leve que se apoia em ambos os lados. A cadeira vai balançar um pouco quando você se sentar nela.",
  str_item_intro_5232005 = "Suspensa por uma corda de um pilar de pedra de formato estranho, a cama é projetada na forma de uma folha redonda, que inteligentemente mantém seu equilíbrio e permite que as pessoas se deitem confortavelmente nela sem cair.",
  str_item_intro_5232006 = "Um banco composto por uma plataforma de pedra. Você pode não apenas sentar, mas também deitar nele. Como é feito de pedra, também é frio ao toque.",
  str_item_intro_5233001 = "Duas pedras, uma grande e outra pequena, são colocadas de forma escalonada. Se colocados na posição correta, podem trazer um cenário único para as residências vizinhas.",
  str_item_intro_5233002 = "Parece uma estalagmite que foi ampliada várias vezes. Se devidamente decorado, vai deixar uma vibe diferente.",
  str_item_intro_5233003 = "Conjunto de vários pedaços de seixos de formas variadas, geralmente colocados como decoração na beira da estrada e no pátio.",
  str_item_intro_5233004 = "A cobertura do pavilhão é em forma de guarda-chuva. Apoiado por uma coluna, é intencionalmente projetado para ser torto, supostamente para criar mais sombra. Seu teto é coberto de videiras. Quando o vento sopra pelos galhos e folhas penduradas, é uma cena especial.",
  str_item_intro_5233005 = "A combinação de rochas sobrepostas, pequenas cachoeiras formadas por água borbulhante e uma pequena piscina cercada por grossos flocos de pedra podem trazer sons de água contínuos e agradáveis para o pátio.",
  str_item_intro_5233006 = "Um pilar de rocha vertical que pode ser usado como o corpo principal de um grupo de rochas.",
  str_item_intro_5233007 = "É composto de muitos pilares de rocha inclinados e parece uma pequena montanha.",
  str_item_intro_5233008 = "Os pilares rochosos ligeiramente inclinados são adequados para a transição entre rochas com formas muito diferentes.",
  str_item_intro_5233009 = "Com seu pico afiado e forma geral esbelta, este pilar de rocha proporciona uma sensação de frieza. É melhor encontrar rochas adequadas para combiná-lo.",
  str_item_intro_5233010 = "Parece um morro inclinado e também pode ser considerado o corpo principal de um grupo rochoso.",
  str_item_intro_5234001 = "Uma lâmpada de rua que oferece brilho duradouro usando uma tecnologia fantástica. Esta lâmpada baixa só pode iluminar uma pequena área.",
  str_item_intro_5234002 = "Uma lâmpada de rua apoiada por um poste. A altura desta fonte de luz permite iluminar áreas distantes.",
  str_item_intro_5234007 = "Um suporte de flores alto que permite que as pessoas desfrutem de flores desabrochando à distância.",
  str_item_intro_5234009 = "Com vários sinais de trânsito pregados no topo, esta placa de madeira pode impedir que as pessoas se percam nos Cloud Gardens. Apenas certifique-se de colocá-lo na posição correta!",
  str_item_intro_5234011 = "Um guarda-chuva que pode trazer sombra suficiente. A desvantagem é que é um pouco pesado e difícil de transportar.",
  str_item_intro_5234012 = "Uma flor com o nome do sol. O seu caule alto e a sua grande flor conferem-lhe um temperamento arrogante. Algumas pessoas acreditam que esta flor representa \"um coração em busca de luz\".",
  str_item_intro_5234013 = "Uma área que estava empilhada com pedras. O terreno foi nivelado, e esta área é especialmente usada para plantar várias flores.",
  str_item_intro_5234014 = "Um suporte de flores baixo. Adequado para decorações de beira de estrada e frente de porta.",
  str_item_intro_5234018 = "Uma barraca de uma pessoa usada na natureza. A forma de cone garante que a barraca seja suficientemente alta. É fácil de configurar, mas tão pequeno que só pode acomodar uma pessoa.",
  str_item_intro_5234019 = "Uma toalha de mesa com todos os tipos de comida. Parece que você poderá desfrutar de uma deliciosa refeição na natureza!",
  str_item_intro_5234020 = "Um fogão robusto e resistente ao calor. O vão na base garante uma boa entrada de ar para grandes chamas que emitem calor intenso.",
  str_item_intro_5234023 = "Mesmo as ervas daninhas não devem ser desperdiçadas. Recolha-os agora porque você nunca sabe o que pode usá-los para mais tarde.",
  str_item_intro_5234024 = "Uma grande caixa feita de tábuas de madeira que é fácil de processar. É muito adequado para armazenar materiais.",
  str_item_intro_5234025 = "Uma pilha de várias caixas de madeira. Você sabe que é um armazém quando os vê.",
  str_item_intro_5234037 = "Um fogão de fogueira construído com pedras. Adequado para iniciar um incêndio controlado na natureza.",
  str_item_intro_5234038 = "Uma âncora resgatada do fundo do mar. É extremamente forte e resistente e parece que pode manter um grande navio no lugar, mesmo quando o oceano está turbulento. É uma pena que sua carga tenha desaparecido há muito tempo, deixando-o esperando perpetuamente por um novo dono.",
  str_item_intro_5234039 = "Alimentada por ondas ondulantes, esta prancha de surf permite ao seu utilizador ir e vir à vontade na água e executar vários movimentos. Parece uma pena colocar isso em Cloud Gardens...",
  str_item_intro_5241002 = "Um balanço que balança um pouco quando você se senta nele. Cuidado para não balançar muito alto! Algumas pessoas gostariam de sentar e dormir. Os sentimentos rolantes podem realmente fazer uma pessoa adormecer rapidamente.",
  str_item_intro_5241003 = "Um brinquedo que oferece uma experiência que lembra um pouco a condução real. Diz-se que as pessoas podem usá-lo para trabalhar em seu equilíbrio.",
  str_item_intro_5241004 = "Empinar pipas é uma boa atividade para dias ensolarados e arejados. Depois de voar a pipa para o céu, desde que a corda da pipa esteja amarrada na prateleira, ela não será arremessada.",
  str_item_intro_5241005 = "Um cavalete leve projetado para esboços ao ar livre. É apenas o ângulo e o tamanho certos para mantê-lo focado enquanto desenha.",
  str_item_intro_5241006 = "O palco e os alto-falantes são cuidadosamente posicionados para que o público possa apreciar a performance de todos os ângulos. Diz-se que este teatro também tem uma tecnologia maravilhosa, às vezes mostrando diferentes efeitos especiais para vários programas.",
  str_item_intro_5241007 = "Diz-se que esta estátua foi construída para homenagear uma mulher celestita que visitou todas as famosas montanhas e rios do continente. Mas ninguém mais se lembra do nome dela, e esta estátua é tudo o que resta para as gerações futuras lembrarem.",
  str_item_intro_5241008 = "Toda vez que você vê, você sempre vai querer dar alguns socos... mas você nunca pode derrubá-lo, o que é um pouco decepcionante. No entanto, é ótimo para ventilação.",
  str_item_intro_5241016 = "Um enorme corredor. As colunas parecem os ossos de alguma criatura antiga... Algumas pessoas dizem que o corredor é na verdade um componente importante do Colosso.",
  str_item_intro_5242101 = "Apesar de sua aparência estranha do lado de fora, a estrutura única permite muita luz e ar na sala, tornando-a muito habitável.",
  str_item_intro_5243001 = "Terra fértil que pode fornecer nutrientes suficientes para qualquer tipo de planta.",
  str_item_intro_5234008 = "A cabeça deste espantalho é feita de linho. Se você olhar de perto, parece uma pessoa com muitas marcas de varíola no rosto e é uma ferramenta bastante eficaz para assustar as pessoas.",
  str_item_intro_5234015 = "Uma imagem vale mais que mil palavras. Esta placa de madeira pode ser entendida com apenas um olhar: \"Por favor, não machuque os pangalos!\"",
  str_item_intro_5234016 = "Um dispositivo que pode ser usado para contar as horas pela projeção da luz solar, a forma primitiva de um relógio. A desvantagem é que o relógio de sol não funciona em dias nublados e chuvosos ou durante a noite.",
  str_item_intro_5234017 = "Instrumento usado para determinar a direção do vento. É sensível o suficiente para que até mesmo uma brisa suave possa ser medida com precisão. Se o vento estiver muito forte e mudar de direção de tempos em tempos, lembre-se de derrubá-lo! Para que não gire muito rápido e quebre.",
  str_item_intro_5234026 = "Um moinho de pedra que aparentemente exige muito esforço para manobrar. Diz-se ter sido usado para moer farinha nos tempos antigos. Embora tenha perdido sua eficiência na era moderna, ainda é bom para treinamento de força ocasional.",
  str_item_intro_5234027 = "Um barril de madeira leve, mas resistente. A alça tem um design antiderrapante para que não derrame e nenhum esforço seja desperdiçado.",
  str_item_intro_5234028 = "Embora seja feito de cerâmica, suas bordas foram reforçadas, tornando-o resistente a quedas e estilhaços, e possui alças para facilitar o deslocamento.",
  str_item_intro_5234029 = "Uma máquina que requer apenas um único operador para fiar o tecido. A única desvantagem é a manutenção complicada...",
  str_item_intro_5234030 = "Um pote cheio de grama verde exuberante. É muito pesado e requer um certo grau de força física para se mover.",
  str_item_intro_5234033 = "Uma prateleira coberta de videiras. Pode fornecer sombra no verão e permanecer verde mesmo no final do outono.",
  str_item_intro_5234036 = "Um canteiro de flores composto por três camadas de pedras garante que as flores possam ser plantadas na camada superior para atrair mais atenção, enquanto as duas camadas inferiores podem conter a fauna verde para maior contraste.",
  str_item_intro_5241015 = "Um dispositivo fascinante no qual você pode colocar discos para tocar música. Os alto-falantes tornaram possível a transmissão de música de modo que ela reverbera ao longe.",
  str_item_intro_5241017 = "Aquário",
  str_item_intro_5251001 = "Torre Jacinto",
  str_item_intro_5252001 = "Museu",
  str_item_intro_5253001 = "Loja",
  str_item_intro_5254001 = "Fonte da esperança",
  str_item_intro_5255001 = "Uma caixa grande, resistente, impermeável e à prova de poeira que é capaz de armazenar muitos itens.",
  str_item_intro_5256001 = "As aventuras com nossos amigos são cheias de desafios, emoções e muita alegria e risadas. Para comemorar esses momentos inesquecíveis durante nossas viagens, nossos amigos fizeram esses crachás e os colocaram aqui como recompensa para os celestitas e para eles mesmos e como lembrança.",
  str_item_intro_5270001 = "Parcela de Reprodução",
  str_item_intro_5275001 = "Por amor e esperança, vamos espalhar nossas canções por todo o continente!\nEste palco foi construído especialmente para turnês - ele possui várias funções, pode ser erguido em pouco tempo e também é muito robusto, capaz de suportar todo tipo de caos cantado e dançado em sua superfície sólida.",
  str_item_intro_5275002 = "Algumas batidas são o suficiente para adicionar aquela atmosfera extra especial a uma performance! Se você acredita que uma banda tem um líder natural, deve ser o baterista. É por isso que isso é essencial para qualquer estágio de turnê.",
  str_item_intro_5275003 = "Mesmo a dance music requer algum conhecimento de composição musical, e com este teclado fácil de usar, com uma ampla gama de sons e efeitos, qualquer tecladista decente pode se tornar uma máquina de fazer música solo.",
  str_item_intro_5275004 = "Desejo a uma estrela! Ninguém sabe quando esse boato começou a se espalhar entre os fãs de ídolos, mas aparentemente, quando você deseja uma decoração de estrela como essa, seu encorajamento sincero será transmitido diretamente ao seu ídolo favorito!",
  str_item_intro_5275005 = "Se você quiser torcer pelo seu ídolo favorito, vai precisar de alguma mercadoria oficial para acenar no ar, então colocar uma mesa como esta perto do palco só faz sentido - assim, os fãs podem colocar as mãos em todos os tipos de equipamentos de suporte quando eles mais precisam.",
  str_item_intro_5275006 = "A maioria das turnês exige que uma variedade de guitarras seja preparada com antecedência. Este suporte de guitarra não apenas permite que os guitarristas escolham qualquer guitarra que se adapte ao seu estilo, mas também permite que vários guitarristas conectem e toquem juntos, dando um nível adicional de emoção a qualquer apresentação.",
  str_item_intro_5275007 = "Este tipo de dispositivo de amplificação é indispensável para artistas em turnê - não importa quão grande seja o local, e não importa quão grande seja o público, isso fará com que a voz de um ídolo possa ser ouvida por todos... e também é muito fofo!",
  str_item_intro_5275008 = "Essas decorações são geralmente colocadas perto de locais de turismo. Quando você os vê flutuando no céu e voando ao vento, não pode deixar de sentir que eles estão realmente dançando com seu ídolo estimado.",
  str_item_intro_5275009 = "Essas luzes decorativas são frequentemente encontradas perto de palcos de turnê e parecem ser usadas pelos fãs para torcer por seus ídolos. Embora não sejam mercadoria oficial, são surpreendentemente bem feitos.",
  str_item_intro_5275010 = "Como qualquer turnê poderia ser completa sem ídolos de pé? Mesmo que você não possa tirar fotos com seu ídolo, ou mesmo ver seu ídolo de perto, desde que você tenha isso, você garante algumas selfies decentes.",
  str_item_intro_5275011 = "As flores representam desejos de felicidade, portanto, naturalmente, muitas flores representam muitos desejos de felicidade. Se você não tomar cuidado, todo o local da turnê pode acabar sendo inundado com cestas de flores enviadas por fãs fervorosos desejando felicidades ao seu ídolo favorito.",
  str_item_intro_5275012 = "Aparentemente, as decorações de estrelas nesta parede foram coladas pelos fãs, uma a uma. Isso não é apenas uma decoração - é uma prova da devoção de uma base de fãs, um símbolo de suas mais sinceras esperanças de que seu ídolo tenha uma turnê de sucesso.",
  str_item_intro_5275013 = "Esses assentos são especialmente organizados para turnês, embora muitos fãs prefiram ficar de pé neles para torcer por seus ídolos, em vez de sentar neles. Há outro motivo para os fãs subirem nessas cadeiras, é claro - para que seu ídolo possa vê-los no meio da multidão.",
  str_item_intro_5234043 = "Já que a neve é tão fofa, por que não fazer dela um sofá?\nTalvez muitas pessoas já tenham tido essa ideia antes. Claro, este sofá é feito de materiais comuns, só que a parte de trás parece uma montanha de neve e, com suas almofadas macias, realmente faz você se sentir como se estivesse deitado na neve.",
  str_item_intro_5234044 = "Diz a lenda que essa criatura extraordinária nunca envelhece, e essa exibição maravilhosa reflete a essência dessa lenda. Se você olhar para ele por um tempo, poderá se tornar viciado nele.",
  str_item_intro_5234045 = "A Courier Union carrega os pensamentos e desejos do mundo, até os confins do Astra! Diz-se que esta caixa de correio foi especialmente criada para o efeito, reduzindo a distância entre os entes queridos.",
  str_item_intro_5234046 = "Se houver algo que você não ouse dizer na cara de alguém, escreva em uma carta e coloque aqui. Esse alguém pode apenas ver e aprender como você se sente.",
  str_item_intro_5276001 = "Este local cerimonial geralmente montado para o Mooncrown Day é muito adequado para a realização de vários eventos, especialmente casamentos.",
  str_item_intro_5276002 = "Seja para desfiles de festivais ou casamentos, esta seria a melhor escolha para estilo, decoração e conforto.",
  str_item_intro_5276003 = "Uma nova invenção divertida. Se os casais ainda cuidam um do outro depois de dar uma volta neles, isso mostra o quanto eles se amam.",
  str_item_intro_5276004 = "As rosas deste pavilhão foram cultivadas especialmente para o festival e só florescem no Dia da Coroa da Lua para abençoar os recém-casados que aqui vêm.",
  str_item_intro_5276005 = "O chocolate é amargo em sua base, e só se torna doce com a adição de açúcar. Talvez... isso simbolize como é algum amor? De qualquer forma, tornou-se um dos presentes simbólicos do Mooncrown Day, provavelmente porque a maioria das pessoas só se lembra da doçura e ignora a amargura.",
  str_item_intro_5276006 = "Esses arcos, com sua forma única, são decorados com flores de várias cores, tornando-os muito adequados para novos casais tirarem fotos ou fazerem pedidos sob eles.",
  str_item_intro_5276007 = "Uma decoração frequentemente usada no Mooncrown Day. Composto por vários copos altos cheios de bebidas, é especialmente utilizado para entreter os convidados.",
  str_item_intro_5276008 = "A forma alta deste castiçal é agradável aos olhos e capaz de dispersar a luz emitida pelas velas uniformemente, adicionando um toque de romance aos ternos casamentos.",
  str_item_intro_5276009 = "Amado por todos os oficiantes de casamento. Este dispositivo permite que todos os convidados presentes ouçam claramente os votos dos dois noivos, e também podem tocar música para encher o local com a atmosfera perfeita.",
  str_item_intro_5276010 = "Perfeito para acomodar casais, mesmo quando não é o Dia da Coroa da Lua. É quase certo que estará ocupado no Mooncrown Day.",
  str_item_intro_5276011 = "Huh? Eles são um casal? Ah, é só uma roupa especial feita para o festival. Muito apropriado para a ocasião, realmente.",
  str_item_intro_5276012 = "Adequado para o Mooncrown Day como decoração e presente para outras pessoas. Dá às celebrações um toque colorido e enche o ar com uma fragrância suave.",
  str_item_intro_5276013 = "Um tapete feito de pétalas de rosas! Verdadeiramente indicativo de quão seriamente o anfitrião leva a cerimônia. Quando os noivos pisam nele, os olhos de todos os convidados se voltam para eles.",
  str_item_intro_5276101 = "Uma mesa com cadeiras combinando com um design vintage pitoresco que felizmente também é muito confortável para se sentar e parece adequado para certas reuniões, especialmente quando se trata de casos complicados. Talvez essa tendência seja toda a influência de um certo detetive famoso.",
  str_item_intro_5276102 = "Dizem que o famoso detetive muitas vezes reunia informações, organizava pistas e fazia diversas análises nesse tipo de tabuleiro, chegando a contar apenas com esse método para encontrar o culpado.",
  str_item_intro_5276103 = "Desde a ascensão desse famoso detetive à fama, seu veículo preferido também cresceu em popularidade. Afinal, quem não gostaria de um veículo tão robusto, rápido e fácil de operar?",
  str_item_intro_5276104 = "Se sua mente está bloqueada, apenas tome uma xícara de café. E se você ainda não conseguir entender, tome outro copo. Como o melhor companheiro de contemplação, o famoso detetive nunca foi sovina na hora de escolher os jogos de café.",
  str_item_intro_5276105 = "Os crimes muitas vezes parecem ocorrer em noites frias, então grandes detetives precisam se equipar com casacos e chapéus à prova de vento. Isso naturalmente torna este cabide essencial no domicílio de qualquer detetive.",
  str_item_intro_5276106 = "Um carrinho pequeno e leve sobre o qual são colocados café, refrescos e outros itens para o chá da tarde. Ao entreter os convidados, é particularmente conveniente para os empregados organizar vários itens de comida em tempo hábil.",
  str_item_intro_5276107 = "Quando sua inspiração dedutiva se esgota, ou ele se vê preso em um labirinto de pensamentos, o famoso detetive gosta de usar esse instrumento para relaxar, enchendo a rua inteira com o som de suas subparidades. Felizmente, o que importa para as pessoas não é o nível de sua proficiência musical, mas sua paixão pela lenda do grande detetive. É por isso que tantas pessoas se aglomeram para comprar este instrumento.",
  str_item_intro_5276108 = "O encosto alto e as almofadas macias proporcionam o máximo conforto, ajudando a manter uma boa postura sentada. Inteiramente adequado para detetives que gostam de relaxar e refletir.",
  str_item_intro_5276109 = "Este rack de design exclusivo pode conter muitos tubos e trazer uma verdadeira sensação de detetive para sua casa. Claro, tudo isso se deve à popularidade do famoso detetive entre os fãs de ficção policial, então mesmo quem não fuma também pode comprar um para decoração.",
  str_item_intro_5276110 = "\"Não deixe uma única pista escapar de você!\" Repetidas vezes, os mínimos detalhes revelam a verdade. Este tipo de lupa é indispensável como acessório padrão para o famoso detetive.",
  str_item_intro_5276111 = "Uma lâmpada leve e resistente ao vento com brilho e vida útil superior que pode ser transportada facilmente com uma mão. Naturalmente, também pode ser colocado no chão.",
  str_item_intro_5276112 = "Este pequeno quadro-negro é relativamente baixo em altura. Mesmo quando o famoso detetive está sentado em sua poltrona, ele pode usá-la para organizar seu caso atual, tornando-a uma ajuda útil para análises rápidas.",
  str_item_intro_5276113 = "A forma deste suporte de livro de duas pernas é bastante especial, mas é muito popular entre um certo detetive famoso. Sendo diferente da maioria das outras pessoas, a estética de seus suportes para livros também é diferente de outros tipos comuns. Claro, como um entusiasta de detetives, você definitivamente deveria ter um par em casa.",
  str_item_intro_5276114 = "Quer esteja a chover ou a fazer sol, os guarda-chuvas são sempre bons escudos e podem ser usados como armas em emergências. Portanto, colocar uma cesta de guarda-chuva como esta na porta parece necessário para armazenar toda uma gama de guarda-chuvas.",
  str_item_intro_5234047 = "\"Quando um escritor fica preso por uma nevasca em uma mansão na montanha, sua eficiência na escrita aumenta dez vezes.\" Isso parece ser uma crença compartilhada por muitos editores da Umbraton e levou à popularidade dessa marca de máquina de escrever, que por um tempo se tornou a máquina de escrever preferida dos escritores da cidade.",
  str_item_intro_5234048 = "Este sofá é essencial se você deseja abrir uma grande empresa em Umbraton. Os diretores se sentavam neste sofá para cuidar de seus negócios.",
  str_item_intro_5223003 = "Um pequeno piso redondo adequado para gramados e decorações de beira de estrada.",
  str_item_intro_5223004 = "Um ladrilho redondo relativamente grande que pode ser usado não apenas para caminhos, mas também como componente principal na pavimentação de estradas.",
  str_item_intro_5351001 = "É o edifício mais atraente e o ponto de referência em Cloud Gardens. Ele contém muitas informações usadas para a reconstrução de Cloud Gardens.",
  str_item_intro_5351002 = "É o edifício mais atraente e o ponto de referência em Cloud Gardens. Ele contém muitas informações usadas para a reconstrução de Cloud Gardens.",
  str_item_intro_5351003 = "É o edifício mais atraente e o ponto de referência em Cloud Gardens. Ele contém muitas informações usadas para a reconstrução de Cloud Gardens.",
  str_item_intro_5352001 = "Um local para exposição de diversos objetos, bem como registro e disseminação de conhecimento.",
  str_item_intro_5352002 = "Ele não só tem um espaço maior do que costumava ser, mas também está levemente decorado para que as exposições possam ser vistas facilmente.",
  str_item_intro_5352003 = "Um museu atualizado com muito mais quartos. Não só tem muito espaço, mas também facilita a triagem de suas exposições.",
  str_item_intro_5353001 = "O local de troca em Cloud Gardens. Ele não apenas realiza negociações gerais, mas também lida com ordens misteriosas!",
  str_item_intro_5353002 = "Adicionadas algumas decorações externas simplificadas, parece muito mais elegante agora.",
  str_item_intro_5353003 = "Uma loja com muitos quartos. É uma mansão dedicada ao comércio agora.",
  str_item_intro_5354001 = "Dê uma olhada na água cristalina da nascente, não apenas você pode apreciar os belos peixes, mas também pode jogar uma moeda para fazer um desejo.",
  str_item_intro_5354002 = "Uma lagoa relativamente grande. Você pode ver peixes nadando sob a água brilhante. E seus sonhos são mais propensos a se tornarem realidade.",
  str_item_intro_5354003 = "A fonte não só traz água fresca para os peixes, mas também ajuda a realizar o seu desejo.",
  str_item_intro_5355001 = "Uma caixa grande, resistente, impermeável e à prova de poeira que é capaz de armazenar muitos itens.",
  str_item_intro_5276201 = "Um assento da corte geralmente agraciado pelos traseiros da nobreza mais nobre de Lumópolis. Seu design luxuoso irradia efetivamente a quintessência do comportamento nobre da classe alta, impressionando a população de queixo caído, enquanto força seu ocupante a restringir subconscientemente seu próprio comportamento. Claro, esse ocupante precisa ter o temperamento certo para isso, para começar.",
  str_item_intro_5276202 = "\"Um mundo dentro de um mundo.\" As pessoas dizem que esta bola de cristal contém o fantasma de uma certa cidade, mas para alguns, é considerada uma memória muito preciosa.",
  str_item_intro_5276203 = "\"Seja gentil com os fracos e corajosos diante da agressão.\" Os cavaleiros formam a pedra angular de Lumopolis e também são os estandartes da cidade-estado, voando alto nos ventos do mundo. Embora o nome desta estátua seja desconhecido, mesmo as pessoas comuns são arrebatadas pelo espírito de cavalheirismo quando veem sua figura imponente.",
  str_item_intro_5276204 = "Este armário de exibição não é apenas luxuoso em design, mas também robusto em estrutura, tornando-o prático e bonito o suficiente para guardar qualquer colecionável.",
  str_item_intro_5234049 = "\"Gravadas em uma placa de pedra, as palavras podem durar milênios.\" Muito tempo depois que seu escultor partiu desta bobina mortal, a cidade estava abandonada, a civilização reduzida a pó, mas este monumento ainda permanecia alto, permitindo que as gerações futuras vislumbrassem o mundo do passado. Talvez este seja o propósito de sua existência.",
  str_item_intro_5276206 = "Um acessório comum nas residências nobres de Lumopolis, onde é frequentemente usado como mesa comprida. Espaçoso, firme e elegante, é adequado para receber convidados, amigos, reuniões familiares e até mesmo discutir assuntos importantes.",
  str_item_intro_5276207 = "Estas cadeiras de espaldar alto comumente encontradas nas nobres mansões de Lumópolis. Garanta o conforto enquanto ajuda a manter uma melhor postura, evitando possíveis gafes em todos os momentos.",
  str_item_intro_5276208 = "Uma bandeira branca para uma cidade branca. O símbolo de Lumopolis, olhando para ela, traz à mente tudo o que faz da cidade o que ela é - os cavaleiros, os nobres, o céu azul claro e a glória de sua civilização.",
  str_item_intro_5276209 = "Na consciência coletiva das massas, esta é uma luz que nunca se apaga e, graças aos poderosos Lumináticos de Lumopolis, realmente nunca se apaga.",
  str_item_intro_5276210 = "Esta elegante cerca baixa não foi projetada para impedir a entrada de estranhos, mas sim para definir os limites de mansões nobres e propriedades.",
  str_item_intro_5276211 = "Mesmo quando se trata de vasos de plantas como este, Lumopolis se destaca da multidão. O vaso não é apenas alto e requintado, mas a planta verde dentro dele também é exuberante e majestosa. Parece que estando tão alto no céu, deve ter absorvido uma grande quantidade de luz solar.",
  str_item_intro_5276212 = "Uma massa de trepadeiras crescidas se espalhando no alto. Embora se arrastem em direções dispersas, há uma uniformidade em seu arranjo, com espaços entre eles que não são nem grandes nem pequenos, aglomerados que não são esparsos nem densos, permitindo que a luz do sol penetre vagarosamente sem causar desconforto súbito. Quando uma brisa suave passa, torna-se o local ideal para relaxar e desfrutar do chá da tarde.",
  str_item_intro_5234050 = "Pode não corresponder à grandiosidade de uma roda-gigante real, mas ainda é bem grande. Não podemos entrar, apenas observamos de longe e revivemos as sensações de um passeio na roda-gigante em nossas mentes.",
  str_item_intro_5234052 = "No deserto, sua carcaça azul e o enorme tanque de água se transformam de símbolos de conflito em uma presença divina. Eles derramam chuva e orvalho, trazendo um alívio refrescante para aqueles que sofrem com a seca.",
  str_item_intro_5234053 = "A escultura realista, que se assemelha a um pássaro delicado envolto em areia, pode facilmente enganar o olho. Tenha cuidado para não molhá-la; caso contrário, ela \"desaparecerá\" em uma poça de areia.",
  str_item_intro_5234054 = "Alguém pode realmente sentar nesta cadeira? Embora as flores acrescentem um toque de beleza, os espinhos que cobrem o assento servem como um lembrete constante para \"Sentar-se ereto, ou arriscar um encontro espinhoso.\"",
  str_item_intro_5400001 = "Um líquido misterioso, que pode encurtar bastante o tempo de reprodução da Árvore Única. É muito volátil, por isso deve ser engarrafado.",
  str_item_intro_5400002 = "Líquido pegajoso provavelmente feito de uma mistura de seiva de árvore única. Fervido e suplementado com uma formulação secreta. Capaz de mudar o gênero de Árvores Únicas.\nAparência: Líquido espesso e verde com restos de lodo amarelo.",
  str_item_intro_5401001 = "Melhoria de Árvore C - B Item de Descoberta Garantida",
  str_item_intro_5401002 = "Melhoria da árvore B - Um item inovador garantido",
  str_item_intro_5401003 = "Atualização de árvore A - S Item inovador garantido",
  str_item_intro_5402001 = "Melhoria de Árvore C - B Item de Descoberta Direcionado",
  str_item_intro_5402002 = "Melhoria da Árvore B - Um Item de Descoberta Direcionado",
  str_item_intro_5402003 = "Atualização de Árvore A - S Item de Descoberta Direcionado",
  str_item_intro_5403001 = "Cristais finos raros que brilham em várias cores. O poder neles pode mudar as cores da Árvore Única.",
  str_item_intro_5403002 = "Grupo de Tingimento de Árvores II",
  str_item_intro_5403003 = "Grupo de Tingimento de Árvores III",
