  str_item_intro_5421111 = "A árvore básica vermelha de Quinlan criada com cristalóides de rosa parece muito vibrante.",
  str_item_intro_5421112 = "A Quinlan Tree I que você cultivou recentemente não parece fora do comum, mas faz um som maravilhoso na brisa.",
  str_item_intro_5421113 = "A árvore de Quinlan básica amarela criada com Cristalóides de Rosa dá uma leve sensação de desolação.",
  str_item_intro_5421211 = "Um gênero da árvore Quinlan da folha anã, que sofreu algumas mutações menores, é criado com cristalóides de rosa e tem uma cor semelhante à das ágatas vermelhas.",
  str_item_intro_5421212 = "A Quinlan Tree II que sofreu algumas pequenas mutações. Suas folhas são pequenas e densas, daí o nome.",
  str_item_intro_5421213 = "Um gênero da árvore Quinlan da folha anã, que sofreu algumas mutações menores, é criado com cristalóides de rosa. As folhas amarelas ondulam maravilhosamente na brisa.",
  str_item_intro_5421221 = "Um gênero da Árvore Quinlan da Folha Gigante, que sofreu algumas pequenas mutações, é criado com Cristalóides de Rosa, e cada folha parece um pedaço fino de cristal vermelho.",
  str_item_intro_5421222 = "A Quinlan Tree II que sofreu algumas pequenas mutações. As folhas são tão largas e fortes que você quase pode fazer roupas com elas diretamente.",
  str_item_intro_5421223 = "Gênero da Árvore Quinlan da Folha Gigante que sofreu algumas pequenas mutações. É criado com Rose Crystalloids e tem uma sensação de outono.",
  str_item_intro_5421311 = "A Quinlan Tree III que sofreu mutações frequentes. Tem uma coroa agrupada e suas folhas são lisas, densas e muito distintas.",
  str_item_intro_5421312 = "Um gênero precioso da árvore Quinlan de boa índole que sofreu mutações frequentes. É criado com Rose Crystalloids. Sua coroa azul dá uma sensação agradável.",
  str_item_intro_5421313 = "Um gênero precioso da árvore Quinlan de boa índole, que sofreu mutações frequentes, é criado com cristalóides de rosa. Suas folhas amarelas estão em camadas umas sobre as outras e, mesmo que o vento forte sopre, elas não se dispersam.",
  str_item_intro_5421321 = "Um gênero precioso da Árvore Sunburst Quinlan, que sofreu mutações frequentes, é criado com Cristalóides de Rosa. Sua coroa vermelha parece ainda mais intensa agora.",
  str_item_intro_5421322 = "A Quinlan Tree III que sofreu mutações frequentes. Tem uma coroa densa, galhos grossos e forte vitalidade.",
  str_item_intro_5421323 = "Um gênero precioso da Árvore Sunburst Quinlan que sofreu mutações frequentes. É criado com Rose Crystalloids. De longe, sua coroa azul parece um corpo de água calmante.",
  str_item_intro_5421331 = "Um gênero precioso da árvore Icy Blue Quinlan que sofreu mutações frequentes. É criado com Rose Crystalloids. As folhas cor-de-rosa da árvore combinam com sua coroa e corpo, adicionando uma sensação de primavera a ela.",
  str_item_intro_5421332 = "Um gênero precioso da árvore Icy Blue Quinlan, que sofreu mutações frequentes, é criado com Rose Crystalloids. A copa vermelha da árvore forma um forte contraste com sua imagem original, fria e bonita.",
  str_item_intro_5421333 = "A Quinlan Tree III que sofreu mutações frequentes. Suas folhas são irregulares, com uma vibe legal e linda.",
  str_item_intro_5421341 = "Um gênero precioso da Árvore Mistral Quinlan, que sofreu mutações frequentes, é criado com Cristalóides de Rosa. O dossel azul adiciona um toque de frieza à sua imagem fria original.",
  str_item_intro_5421342 = "A Quinlan Tree III que sofreu mutações frequentes. Suas folhas têm bordas afiadas, apresentando projeções irregulares. Quando a brisa sopra pelo dossel, parece dançar como uma lâmina afiada, trazendo uma sensação de aspereza.",
  str_item_intro_5421343 = "Um gênero precioso da Árvore Mistral Quinlan, que sofreu mutações frequentes, é criado com Cristalóides de Rosa. As folhas amarelas claras suavizam a aura original de frieza e trazem um toque de calor.",
  str_item_intro_5421411 = "Um gênero raro da Árvore Sungazing Quinlan, que sofreu mutações complexas, é criado com Cristalóides de Rosa. A coroa azul da árvore é como aqueles que têm um coração puro, olhando para o céu azul e orando. Assim, também é chamada de \"Árvore Quinlan Orando\".",
  str_item_intro_5421412 = "A Quinlan Tree IV que sofreu mutações complexas. Tem a forma de uma trombeta estendida até o céu. É difícil imaginar como os galhos finos sozinhos podem sustentar a enorme copa da árvore. Isso deve ser obra de algumas forças desconhecidas.",
  str_item_intro_5421413 = "Um gênero raro da Árvore Sungazing Quinlan, que sofreu mutações complexas, é criado com Cristalóides de Rosa. A coroa amarela em forma de trombeta parece um chifre de latão. Diz-se que nos tempos antigos, os gigantes até o usavam para tocar música! Por causa disso, a árvore também é chamada de \"Árvore Chifre Quinlan\".",
  str_item_intro_5421421 = "Um gênero raro de Monolith Quinlan Tree, que sofreu mutações complexas, é criado com Rose Crystalloids. Ao ficar na copa verde da árvore, você terá a ilusão de que está nas colinas, por isso também é chamada de \"Árvore Quinlan Hill\".",
  str_item_intro_5421422 = "Um gênero raro de Monolith Quinlan Tree, que sofreu mutações complexas, é criado com Rose Crystalloids. A coroa branca parece muito lisa, e você pode até dormir bem nela.",
  str_item_intro_5421423 = "A Quinlan Tree IV que sofreu mutações complexas. A copa das árvores endureceu para se tornar uma pequena plataforma de pedra! Diz-se que há um poste de pedra no tronco que o sustenta, com seu lado externo envolto na casca pesada... Se esta Árvore Única ainda pode ser chamada de planta, é realmente para ser discutido.",
  str_item_intro_5421431 = "A Quinlan Tree IV que sofreu mutações complexas. Suas folhas são filamentosas, delicadas, finas e emaranhadas. Parece uma alma trêmula registrada na lenda. Algumas pessoas dizem que este gênero tem sua consciência e até mesmo alma...",
  str_item_intro_5421432 = "Um gênero raro da Árvore Psique Quinlan, que sofreu mutações complexas, é criado com Cristalóides de Rosa. A coroa vermelha parece sinistra, mas tem uma atração fatal. Quando essas folhas suaves dançam com o vento, é fácil ficar fascinado e observá-las por dias e noites.",
  str_item_intro_5421433 = "Um gênero raro da Árvore Psique Quinlan, que sofreu mutações complexas, é criado com Cristalóides de Rosa. As folhas amarelas formam várias pequenas flâmulas que balançam na copa da árvore como se quisessem dar as boas-vindas a alguém, daí seu apelido, a \"Árvore Quinlan Acolhedora\".",
  str_item_intro_5421441 = "A Quinlan Tree IV que sofreu mutações complexas. As folhas convergentes se uniram para formar um dossel enorme e denso. De vez em quando, as folhas voam para fora, parecendo chover folhas caindo.",
  str_item_intro_5421442 = "Um gênero raro da Blooming Quinlan Tree, que sofreu mutações complexas, é criado com Rose Crystalloids. A coroa verde parece cheia de vitalidade. Se você se aproximar dos galhos pendurados, eles tremerão levemente, e toda a árvore farfalhará como se estivesse respondendo a alguém...",
  str_item_intro_5421443 = "Um gênero raro da Blooming Quinlan Tree, que sofreu mutações complexas, é criado com Rose Crystalloids. Quando as folhas azuis caem umas sobre as outras, dá às pessoas a ilusão de que estão em um rio ou no mar, por isso também é chamada de \"Árvore Quinlan do oceano sobre a terra\".",
  str_item_intro_5421451 = "A Quinlan Tree IV que sofreu mutações complexas. É excepcionalmente raro e vigoroso. Como o próprio nome sugere, há rumores de que a árvore continua crescendo depois de ser cortada.",
  str_item_intro_5421452 = "Um gênero raro da Árvore Quinlan Inflexível que é criada com Cristalóides de Rosa. Suas folhas marrons dão uma sensação de envelhecimento, mas é ainda mais viva. Diz-se ser capaz de sobreviver sem água.",
  str_item_intro_5421453 = "Um gênero raro da Árvore Quinlan Inflexível que é criada com Cristalóides de Rosa. Cresce tão rápido que uma coroa azul quase se forma da noite para o dia, daí seu apelido, Oceano Infinito de Folhas.",
  str_item_intro_5421461 = "A Quinlan Tree IV que sofreu mutações complexas. É excepcionalmente raro. Ele se ramifica de suas raízes para ambos os lados e se curva para cima em um círculo, parecendo uma moldura de porta feita com árvores, daí seu nome informal, The Quinlan Doorway.",
  str_item_intro_5421462 = "Um gênero raro de Archway Quinlan Tree que é criado com Rose Crystalloids. O arco azul da árvore às vezes é enevoado e coberto de geada no inverno. De longe, parece uma árvore formada de neve e gelo.",
  str_item_intro_5421463 = "Um gênero raro de Archway Quinlan Tree que é criado com Rose Crystalloids. Em vez de intimidar quem a contempla, essa porta vermelha gera sentimentos de aconchego e conforto. Alguns dizem que traz boa sorte ao seu plantador.",
  str_item_intro_5421471 = "Uma Quinlan Tree IV que passou por mutações complexas. Esta árvore extremamente rara tem um efeito extraordinariamente relaxante em todos os que a contemplam, devido à forma como o seu tronco bifurcado e a sua copa balançam com a brisa, e como ela brilha com gotas de orvalho. É por isso que é conhecido como o \"Carefree Quinlan\".",
  str_item_intro_5421472 = "Um gênero raro da Winsome Quinlan Tree que passou por mutações complexas depois de ser criado com Rose Crystalloids. Devido ao orvalho azul que se acumula em suas folhas, este Quinlan parece estar submerso em um mar raso quando visto de longe, daí seu apelido - Farol Encantador.",
  str_item_intro_5421473 = "Um gênero raro da Winsome Quinlan Tree que passou por mutações complexas depois de ser criado com Rose Crystalloids. O orvalho roxo confere a esta árvore única um toque de charme. Ao balançar com a brisa, parece despreocupado e contente enquanto irradia um fascínio encantador.",
  str_item_intro_5421481 = "Uma Quinlan Tree IV que passou por mutações complexas. O tronco vertical desta árvore extremamente rara e a coroa em forma de chama fazem com que ela fique alta como um farol em chamas. É possível que aqueles que contemplam sua forma possam confundi-la com uma fonte real de iluminação!",
  str_item_intro_5421482 = "Um gênero raro da Blazing Quinlan Tree que passou por mutações complexas após ser criado com Rose Crystalloids. A enorme copa rosa desta árvore é como uma nuvem de névoa misteriosa flutuando em um tronco e galhos. Quando o vento sopra, a coroa do \"Rosewater Mist\" torna-se irregular, infectando os espectadores com uma sensação peculiar.",
  str_item_intro_5421483 = "Um gênero raro da Blazing Quinlan Tree que passou por mutações complexas após ser criado com Rose Crystalloids. Sua coroa vermelha o transforma em uma verdadeira tocha, especialmente quando dança ao vento, criando a ilusão de um incêndio violento na pradaria.",
  str_item_intro_5422111 = "O Artur Tree Verde Menta criado com Cristalóides de Rosa é alto e tem uma sensação de primavera.",
  str_item_intro_5422112 = "O Arthur Tree Verde Escuro criado com Rose Crystalloids é robusto e calmante.",
  str_item_intro_5422113 = "A Arthur Tree I que você cultivou recentemente não parece fora do comum. Seu tronco alto e reto, galhos compactos e agulhas que crescem para cima são o que o tornam especial.",
  str_item_intro_5422211 = "Um gênero da árvore de Arthur de folha curta, que sofreu algumas mutações menores, é criado com cristalóides de rosa. As agulhas vermelhas são muito curtas e, quando caem, formam um tapete vermelho sob a árvore, o que é agradável aos olhos.",
  str_item_intro_5422212 = "Um gênero da árvore de Arthur de folha curta, que sofreu algumas mutações menores, é criado com cristalóides de rosa. As agulhas curtas têm uma textura verde como esmeraldas mosqueadas.",
  str_item_intro_5422213 = "Um Arthur Tree II que sofreu algumas pequenas mutações é muito diferente do original. Enquanto os ramos se estendem para fora, a coroa é esparsa e as folhas tornam-se curtas e grossas. É difícil identificá-lo como uma Árvore de Arthur se não fosse pela nota pensativa.",
  str_item_intro_5422221 = "Um gênero da Long Leaf Arthur Tree, que sofreu algumas pequenas mutações, é criado com Rose Crystalloids. As folhas secam rapidamente após a queda e haverá sons agradáveis de \"clique\" ao pisar nelas.",
  str_item_intro_5422222 = "Um gênero da Long Leaf Arthur Tree, que sofreu algumas pequenas mutações, é criado com Rose Crystalloids. As folhas finas são macias, mas resistentes, e muitas pessoas gostam de usá-las para fazer barris de canetas.",
  str_item_intro_5422223 = "Um Arthur Tree II que sofreu algumas pequenas mutações. Sua aparência mudou drasticamente. Os galhos crescem arbitrariamente e as folhas se alongam. É difícil imaginar que se originou daquelas altas árvores de Arthur.",
  str_item_intro_5422311 = "Um Arthur Tree III que sofreu mutações frequentes. A coroa e os galhos da árvore se fundem em um, parecendo uma rocha de montanha. Endurecido na superfície e oco por dentro, fará um eco maravilhoso quando batido.",
  str_item_intro_5422312 = "Um gênero precioso da Árvore Ridge Arthur, que sofreu mutações frequentes, é criado com Cristalóides de Rosa. A textura verde em um lado do galho seria facilmente confundida com o musgo preso a ele.",
  str_item_intro_5422313 = "Um gênero precioso da Árvore Ridge Arthur, que sofreu mutações frequentes, é criado com Cristalóides de Rosa. Parte de sua casca mostra uma cor vermelha clara, o que dá origem a algumas histórias de horror, mas tudo isso é bobagem.",
  str_item_intro_5422321 = "Um Arthur Tree III que sofreu mutações frequentes. Tem um dossel baixo e galhos longos e macios pendurados. Parece uma pequena floresta à distância, por isso também tem a reputação de \"One Tree Forest\".",
  str_item_intro_5422322 = "Um gênero precioso da Árvore Banyan Arthur, que sofreu mutações frequentes, é criado com Cristalóides de Rosa. Sua enorme coroa vermelha é como um guarda-chuva, o que é suficiente para bloquear o sol escaldante e trazer uma sombra fresca às pessoas.",
  str_item_intro_5422323 = "Um gênero precioso da Árvore Banyan Arthur, que sofreu mutações frequentes, é criado com Cristalóides de Rosa. Possui uma enorme coroa verde e fortes ramos pendentes. Qualquer um andando perto provavelmente pensaria que eles se desviaram para uma pequena floresta.",
  str_item_intro_5422331 = "Um gênero precioso da árvore Heath Arthur, que sofreu mutações frequentes, é criado com Rose Crystalloids. Seu dossel levemente pálido combina com o tronco rachado, fazendo muitas pessoas pensarem que ele murchou. No entanto, uma vez que eles percebem que a árvore está ali há muito tempo, eles mudam de ideia.",
  str_item_intro_5422332 = "Um Arthur Tree III que sofreu mutações frequentes. Assemelha-se às árvores em decomposição comumente vistas no deserto, daí o nome. No entanto, a pequena coroa que cresce em seu tronco retorcido mostra sua vitalidade tenaz como se dissesse a todos: \"Ainda estou vivo\".",
  str_item_intro_5422333 = "Um gênero precioso da árvore Heath Arthur, que sofreu mutações frequentes, é criado com Rose Crystalloids. Sua coroa verde e galhos murchos formam um forte contraste. Alguns até suspeitariam se os dois são de uma planta, mas o fato é que eles pertencem à mesma árvore de Heath Arthur. Talvez seja esse o encanto da Árvore Única.",
  str_item_intro_5422341 = "Um gênero precioso da Árvore do Lago Arthur, que sofreu mutações frequentes, é criado com Cristalóides de Rosa. Seu suco é amarelo claro e tem um gosto um pouco amargo no início, mas o sabor fica um pouco adocicado. Diz-se que o suco é bom para restaurar a força física, e algumas pessoas dizem que beber demais vai deixá-lo tonto.",
  str_item_intro_5422342 = "Um Arthur Tree III que sofreu mutações frequentes. Tem o nome da piscina natural formada na raiz da árvore, e a ponta da copa pingando água a todo momento. Ninguém pode compreender o princípio e o significado deste ciclo misterioso. As pessoas só podem beber a água da piscina de raízes e se maravilhar com o poder das mutações.",
  str_item_intro_5422343 = "Um gênero precioso da Árvore do Lago Arthur, que sofreu mutações frequentes, é criado com Cristalóides de Rosa. A água da piscina é verde. À primeira vista, parece venenoso, mas na verdade é muito gelado e tem uma fragrância refrescante, o que é muito surpreendente.",
  str_item_intro_5422411 = "Um gênero precioso da Árvore Inkstone Arthur, que sofreu mutações frequentes, é criado com Rose Crystalloids. Parte de seu tronco e coroa brilharão com luz verde como se houvesse um riacho escorrendo nele, o que é fantástico.",
  str_item_intro_5422412 = "Um Arthur Tree IV que sofreu mutações complexas. Tem raízes expostas, troncos inchados e endurecidos e uma coroa que se transforma em uma massa de folhas brilhantes! De longe, parece um pequeno farol, por isso também é chamado de \"Farol Arthur Tree\".",
  str_item_intro_5422413 = "Um gênero raro de Inkstone Arthur Tree, que sofreu mutações frequentes, é criado com Rose Crystalloids. O tronco e a coroa em forma de pedra brilham como ouro. Aqueles que não a conhecem podem até pensar que chegaram a um palácio resplandecente, por isso a árvore também é conhecida como a \"Árvore do Palácio Arthur\".",
  str_item_intro_5422421 = "Um Arthur Tree IV que sofreu mutações complexas. Parte de seu tronco é combinada com sua coroa endurecida para formar placas de pedra ocas! A parede externa dessas placas de pedra é dura, mas muito fina. Ao ser batido, fará uma variedade de sons, e algumas pessoas até dizem que a árvore falaria através de sua copa...",
  str_item_intro_5422422 = "Um gênero raro da Boulder Arthur Tree, que sofreu mutações complexas, é criado com Rose Crystalloids. Sua enorme coroa verde é como uma gema verde. Basta tocar suavemente e ele pode fazer todos os tipos de sons claros e melodiosos, daí seu apelido, o \"Arthur Tree Musician\".",
  str_item_intro_5422423 = "Um gênero raro da Boulder Arthur Tree, que sofreu mutações complexas, é criado com Rose Crystalloids. A placa de pedra azul faz um som melodioso e treme levemente, formando uma pós-imagem azul piscante sonhadora.",
  str_item_intro_5422431 = "Um gênero raro da Shutter Arthur Tree, que sofreu mutações complexas, é criado com Rose Crystalloids. Quando o coração amarelo da árvore irradia, a textura do seu tronco produzirá uma ilusão de folhas amarelas claras, dando às pessoas a sensação de que esta Árvore Única está cheia de vida novamente! Daí o seu apelido, a \"Árvore Arthur Ressuscitada\".",
  str_item_intro_5422432 = "Um Arthur Tree IV que sofreu mutações complexas. Possui um tronco oco, no qual o coração da árvore forma um peculiar formato de cogumelo e emite uma luz maravilhosa. Diz-se que uma vez que o perigo é detectado, a casca externa da árvore se fechará e bloqueará a luz nela, por isso também é chamada de \"Árvore de Arthur Lightblocker\".",
  str_item_intro_5422433 = "Um gênero raro da Shutter Arthur Tree, que sofreu mutações complexas, é criado com Rose Crystalloids. Ele emana um brilho azul do coração da árvore. Depois que a luz for desviada no tronco oco, ela criará uma ilusão para as pessoas de que a árvore está cercada por um riacho, e elas até acreditariam erroneamente que estão debaixo d'água ...",
  str_item_intro_5422441 = "Um Arthur Tree IV que sofreu mutações complexas. Alguns galhos e folhas desta árvore se combinaram e se transformaram em uma \"lanterna\". Os galhos que funcionam como \"pavio\" podem até emitir uma luz quente! Não há dúvida de que este é um farol para os viajantes que caminham no deserto escuro.",
  str_item_intro_5422442 = "Um gênero raro da Brightness Arthur Tree, que sofreu mutações complexas, é criado com Rose Crystalloids. Diz-se que sua \"lanterna\" emite uma luz azul suave porque seu tronco contém Lumina.",
  str_item_intro_5422443 = "Um gênero raro da Brightness Arthur Tree, que sofreu mutações complexas, é criado com Rose Crystalloids. Suas folhas são vermelhas, mas sua \"lanterna\" emite um leve brilho vermelho que reflete no tronco branco, dando-lhe um charme único.",
  str_item_intro_5422451 = "Um Arthur Tree IV que sofreu mutações complexas. A copa da árvore desapareceu e seu tronco está coberto de trepadeiras compostas inteiramente de pétalas de flores brilhantes. Com algumas trepadeiras firmemente entrelaçadas e outras soltas, esta árvore se assemelha a um portão floral à distância.",
  str_item_intro_5422452 = "Um gênero raro de Arthur Tree que é criado com Rose Crystalloids. Suas pétalas brancas são muito frias ao toque, mas parecem levemente quentes depois de serem arrancadas da árvore.",
  str_item_intro_5422453 = "Um gênero raro de Arthur Tree que é criado com Rose Crystalloids. Suas pétalas de flores vívidas e verdes se parecem distintamente com folhas; a diferença só é perceptível quando vista de perto.",
  str_item_intro_5422461 = "Um Arthur Tree IV que sofreu mutações complexas. No lugar de um dossel há uma colossal bola de energia crescendo nas pontas de seus galhos! Este orbe, conhecido como \"fluoróforo\", parece ser composto de Lumina; quando uma brisa suave sopra, sua luz cai em cascata pelas folhas que caem e traz uma luz suave ao ambiente.",
  str_item_intro_5422462 = "Um gênero raro de Arthur Tree que é criado com Rose Crystalloids. Seu fluoróforo brilhante é tão azul quanto o mar e, quando flutua com o vento, dá às pessoas a sensação de que esferas de água estão girando no topo de uma árvore. Em alguns lugares, é conhecido como o Dançarino da Água das Árvores Únicas.",
  str_item_intro_5422463 = "Um gênero raro de Arthur Tree que é criado com Rose Crystalloids. Seu fluoróforo amarelo está repleto de vitalidade palpável e pode até fazer a flora próxima prosperar com sua energia.",
  str_item_intro_5422471 = "Uma Arthur Tree IV que passou por mutações complexas. Sua coroa mudou completamente, a ponto de agora ser essencialmente uma massa sólida que se inclina para todos os lados, formando uma estranha forma de tigela. Seus galhos maravilhosos se projetam do centro desta \"tigela\", brilhando como uma tocha para atrair a atenção de todos que olham para ela.",
  str_item_intro_5422472 = "Um gênero raro da florescente Arthur Tree que passou por mutações complexas após ser criado com Rose Crystalloids. Sua coroa em forma de tigela é de uma cor azul calmante, e a luz refletida nesta seção central gera uma sensação semelhante a estar em águas profundas, daí seu outro nome, a \"Ilusão do Abismo\".",
  str_item_intro_5422473 = "Um gênero raro da florescente Arthur Tree que passou por mutações complexas depois de ser criado com Rose Crystalloids. De pé abaixo dela, você pode ver que a coroa vermelha é como um pôr do sol vermelho-sangue bloqueando o céu, criando a ilusão de estar envolto no crepúsculo.",
  str_item_intro_5422481 = "Uma Arthur Tree IV que passou por mutações complexas. A árvore inteira endureceu e se transformou em uma plataforma de pedra. A água borbulhante que cai do topo simplesmente flui para o buraco da árvore, criando uma cena bastante maravilhosa.",
  str_item_intro_5422482 = "Um gênero raro da Radiant Arthur Tree que é criado com Rose Crystalloids. O tronco é branco. Juntamente com a cascata azul clara, forma uma paisagem bastante refrescante. Simplesmente ficar embaixo da árvore e ouvir o som da água corrente é um prazer, daí o pseudônimo de \"Gotas de Prazer\".",
  str_item_intro_5422483 = "Um gênero raro da Radiant Arthur Tree que é criado com Rose Crystalloids. O tronco e os \"galhos\" superiores são de uma intrigante cor azul. Vista através do riacho amarelo, toda a árvore emite uma vibração estranha, daí o nome \"azul roxo nebuloso\".",
  str_item_intro_5423111 = "Uma árvore de floração básica que foi recentemente nutrida até à maturidade e que já apresenta as suas características únicas, nomeadamente as suas flores desabrochando.",
  str_item_intro_5423112 = "Uma árvore de florescência roxa que foi nutrida usando cristalóides de rosa. Emite um brilho fraco e encantador.",
  str_item_intro_5423113 = "A Árvore Amarela de Arthur criada com Cristalóides de Rosa está se aquecendo em seu brilho suave, trazendo à mente o calor do sol poente.",
  str_item_intro_5423211 = "A Blooming Tree II que sofreu algumas pequenas mutações. Já se assemelhando a uma variedade completamente diferente, tem vários troncos saindo de uma única raiz subterrânea; isso dá a impressão de que é na verdade um aglomerado de várias plantas. Embora seja muito diferente na aparência de uma árvore florescente básica, suas flores são suficientes para mostrar que é um derivado intimamente relacionado, mas mutante.",
  str_item_intro_5423212 = "Um gênero da Festive Blooming Tree, que sofreu algumas pequenas mutações, é criado com Rose Crystalloids. O tom amarelo-claro de suas flores lembra vários pequenos sóis, oferecendo uma visão de tirar o fôlego para todos.",
  str_item_intro_5423213 = "Um gênero da Festive Blooming Tree, que sofreu algumas pequenas mutações, é criado com Rose Crystalloids. Suas flores azul-claras balançam suavemente na brisa como nuvens flutuando no céu.",
  str_item_intro_5423221 = "A Blooming Tree II que sofreu algumas pequenas mutações. Embora seu tronco seja marcadamente mais grosso do que o de uma árvore normal, sua diferença mais notável está em suas flores. Alongadas e em forma de inúmeras trombetas, são também a razão pela qual esta árvore recebeu o seu nome.",
  str_item_intro_5423222 = "Um gênero da árvore florescente sonora, que sofreu algumas mutações menores, é criado com cristalóides de rosa. Suas flores azuis contêm alto teor de água e podem ser usadas para matar a sede ou até mesmo preparar bebidas especiais!",
  str_item_intro_5423223 = "Um gênero da árvore florescente sonora, que sofreu algumas mutações menores, é criado com cristalóides de rosa. Suas flores são vermelho-fogo e amolecem e secam rapidamente uma vez removidas da árvore. Isso os torna um material de graveto muito adequado.",
  str_item_intro_5423311 = "A Blooming Tree III que sofreu mutações frequentes. Suas flores crescem apenas em seu tronco, enquanto vários galhos brotam de suas raízes e os cercam. Sua aparência misteriosa foi comparada a um grupo de guardas imperiais protegendo sua rainha.",
  str_item_intro_5423312 = "Um gênero raro da árvore florescente protegida que é criada com cristalóides de rosa. Suas flores ficaram quase douradas e até parecem refletir a luz do sol quando vistas balançando à distância.",
  str_item_intro_5423313 = "A Sheltered Blooming Tree que sofreu mutações frequentes. Suas flores azul-claras oferecem um forte contraste com suas folhas e tronco, para grande prazer estético de seus admiradores.",
  str_item_intro_5423321 = "Uma árvore florescente melancólica que sofreu mutações frequentes. Seu tronco é deformado em um círculo quase perfeito, e seu dossel é formado por suas flores densas e penduradas. Sua estrutura única, quase ilógica, é tão de tirar o fôlego quanto incompreensível.",
  str_item_intro_5423322 = "Um gênero raro da árvore Wistful Blooming que é criada com Rose Crystalloids. Suas flores azuis baixas e forma circular formam uma entrada natural. Mesmo quando colocado na entrada de um jardim artificial, ele se encaixa perfeitamente no ambiente e ainda oferece uma vista incrível.",
  str_item_intro_5423323 = "Uma árvore florescente melancólica que sofreu mutações frequentes. Suas flores adquiriram um tom pálido e tenro de branco, e uma fragrância fresca e floral pode ser notada sob seu dossel. Como tal, as suas flores tornaram-se uma matéria-prima crucial para muitos perfumes.",
  str_item_intro_5423331 = "A Blooming Tree III que sofreu mutações frequentes. Seu tronco se torceu e se contorceu na forma de uma flor gigante, que pode ser vista de longe. Suas flores reais, no entanto, estão dentro de seu tronco e galhos retorcidos, levando os pesquisadores a teorizar que sua forma única serve para protegê-los de predadores.",
  str_item_intro_5423332 = "Um gênero raro de Iris Blooming Tree que é criado com Rose Crystalloids. As pontas de seus ramos são tingidas de azul claro e gotejam com uma secreção mais escura. Segundo algumas pessoas, essa secreção pode ser usada como um tipo de tinta, ou até mesmo como corante para tecidos.",
  str_item_intro_5423333 = "Uma árvore florescente de íris que sofreu mutações frequentes. As pontas de seus galhos são tingidas de verde claro, enquanto a piscina de água em sua base emite um brilho azul profundo, dando-lhe uma poderosa aura de energia natural.",
  str_item_intro_5423341 = "A Blooming Tree III que sofreu mutações frequentes. Diz-se que se assemelha a uma árvore de uma terra distante, suas flores desabrochando são lindas e cheias de uma leve fragrância. Ao olhar para esta árvore por um longo período de tempo, diz-se que um arco-íris eventualmente aparece diante de seus olhos. Embora isso seja apenas lenda, é, no entanto, a razão pela qual esta árvore recebeu seu nome.",
  str_item_intro_5423342 = "Um gênero raro da árvore florescente iridescente que é criada com cristalóides de rosa. Suas flores roxas são especialmente encantadoras. De fato, sua cor é tão viva que devem ser usadas com moderação quando usadas como decoração ou acentos, para que não dominem os sentidos.",
  str_item_intro_5423343 = "Uma árvore florescente iridescente que sofreu mutações frequentes. Suas flores amarelas estão cheias de vida e parecem permanecer em flor dia e noite. Há até rumores de que suas flores podem ser usadas para preparar poções de vitalidade; como resultado, é conhecido por alguns como o \"Arco-íris Árvore da Vida\".",
  str_item_intro_5423411 = "A Blooming Tree IV que sofreu mutações complexas. Embora seu dossel tenha apenas uma única flor, essa flor é colossal em tamanho, resplandecente em cor e perigosamente doce em aroma; alguns até dizem que os estames de sua flor podem ser um excelente tempero para alimentos. Muitas vezes o objeto de fixação para muitas pessoas, a flor desta árvore pode aparentemente cativar qualquer ser vivo com olhos para vê-la.",
  str_item_intro_5423412 = "Um gênero raro da Árvore Florescente Feiticeira que é criada com Cristalóides de Rosa. Sua flor azul clara flutua na brisa como ondas no oceano, e até emite um cheiro levemente adstringente de peixe. Assim, quem vive longe do mar afirma que ainda pode experimentar a alegria de um dia de verão na praia só de admirar a flor desta árvore.",
  str_item_intro_5423413 = "Um gênero raro da Árvore Florescente Feiticeira que é criada com Cristalóides de Rosa. Sua flor se tornou um tom de rosa perigosamente cativante. Simplesmente olhar para ele pode fazer uma pessoa esquecer todos os seus problemas, tornando especialmente difícil arrancar os olhos dele. Na verdade, alguns até colocam despertadores para lembrá-los dos perigos de exagerar em uma visão tão bonita.",
  str_item_intro_5423421 = "A Blooming Tree IV que sofreu mutações complexas. Suas flores carregam inúmeras pétalas, cada uma das quais é tão macia e esbelta quanto um fio de seda. Dizem que alguns até tentaram usá-las para tecer tecidos, mas essas flores delicadas rapidamente se tornam quebradiças depois de serem removidas da árvore, levando a um desperdício vergonhoso de sua beleza natural.",
  str_item_intro_5423422 = "Um gênero raro de Silken Blooming Tree que é criado com Rose Crystalloids. Seu dossel azul muitas vezes traz à mente imagens da \"Filha do Mar\", uma figura lendária que diz ter cabelos tão azuis quanto o próprio oceano. Alguns até dizem que as flores desta árvore exalam um leve aroma de maresia...",
  str_item_intro_5423423 = "Um gênero raro de Silken Blooming Tree que é criado com Rose Crystalloids. Diz-se que suas flores verdejantes abrigam as almas de todas as flores, e que vê-la com os próprios olhos garantirá amor verdadeiro à primeira vista...",
  str_item_intro_5423431 = "A Blooming Tree IV que sofreu mutações complexas. As corolas de suas enormes flores são distintamente em forma de disco e parecem estar voltadas para algo no alto. Ao ser notado pelas pessoas, suas flores aparentemente se afastam de seu olhar; como resultado, é conhecido como o \"Bashful Bloom\" em certos círculos.",
  str_item_intro_5423432 = "Um gênero raro de Skygazer Blooming Tree que é criado com Rose Crystalloids. Suas flores são brilhantes e vermelhas como chamas desenfreadas. As lendas dizem que esta flor robusta olha para o céu para compartilhar sua riqueza de vitalidade com o mundo.",
  str_item_intro_5423433 = "Um gênero raro de Skygazer Blooming Tree que é criado com Rose Crystalloids. Suas pétalas de flores são brancas como a neve e emitem um brilho estranho. Alguns dizem que ela produz uma variedade de ilusões dependendo da direção em que está voltada, dando-lhe o apelido de \"tecelã de sonhos\".",
  str_item_intro_5423441 = "Uma Blooming Tree IV que passou por mutações complexas. Suas pétalas são elegantes e bonitas, colocadas umas sobre as outras. Basta um olhar para encher o coração de vertigem, e é por isso que é preferido por muitas garotas.",
  str_item_intro_5423442 = "Um gênero raro da Virtuous Blooming Tree que é criado com Rose Crystalloids. Seu dossel azul é inebriante e muitos espectadores se sentem revigorados ao seu redor, como o céu limpo depois da chuva, por isso também é chamado de \"Céu Limpo\".",
  str_item_intro_5423443 = "Um gênero raro da Virtuous Blooming Tree que é criado com Rose Crystalloids. Suas flores roxas parecem perigosas, e diz-se que suas flores balançam ligeiramente coquete quando alguém está olhando para elas, levando-as a um transe. De qualquer forma, tenha cuidado com isso.",
  str_item_intro_5423451 = "Uma Blooming Tree IV que passou por mutações complexas. A enorme copa forma um funil natural, e as paredes internas formadas por suas pétalas são tão lisas que ela recolhe o orvalho da manhã em seu tronco para se alimentar.",
  str_item_intro_5423452 = "Um gênero raro da Dawn Blooming Tree que é criado com Rose Crystalloids. Sua copa roxa tinge o orvalho que coleta da mesma cor. Alguns estudiosos acreditam que esse orvalho tem poderes místicos e o usam para escrever certos livros.",
  str_item_intro_5423453 = "Um gênero raro da Dawn Blooming Tree que é criado com Rose Crystalloids. O orvalho coletado de seu dossel parece azulado e pode refrescar quem o olha. Este orvalho também parece ser capaz de limpar as impurezas do corpo, por isso também é chamado de \"Desintoxicação do Amanhecer\".",
  str_item_intro_5423461 = "Uma Blooming Tree IV que passou por mutações complexas. Sua coroa é dividida em vários segmentos longos e delicados, que são escalonados em torno de seu centro. Dizem que depois de vê-lo, um estilista se inspirou para desenhar uma série de saias com base no formato de suas pétalas, levando ao apelido de \"Beleza Contornada\".",
  str_item_intro_5423462 = "Um gênero raro da Aureate Blooming Tree que é criado com Rose Crystalloids. Suas pétalas de laranja parecem possuir o toque da tentação e, com sua fragrância única, é um poderoso lembrete de tudo o que é sedutor e perigoso no mundo.",
  str_item_intro_5423463 = "Um gênero raro da Aureate Blooming Tree que é criado com Rose Crystalloids. Suas pétalas ganharam a cor do céu, embelezadas com folhas brancas que difundem uma sensação de frescor e limpeza, tornando-o popular entre as crianças.",
  str_item_intro_5423471 = "Uma Blooming Tree IV que passou por mutações complexas. Sua coroa e estame formam uma borboleta que não apenas confunde aqueles que a contemplam, mas também atrai borboletas reais, que dançam ao seu redor como se fosse seu deus.",
  str_item_intro_5423472 = "Um gênero raro de Fluttering Blooming Tree que é criado com Rose Crystalloids. Quando visto de longe, seu enorme estame amarelo parece uma borboleta empoleirada sobre ele. Sempre que uma brisa passa, fica ainda mais difícil distinguir...",
  str_item_intro_5423473 = "Um gênero raro de Fluttering Blooming Tree que é criado com Rose Crystalloids. Seu estame azul e sua forma inata de borboleta deixam as pessoas com uma estranha primeira impressão. Ao finalmente descobrir sua verdadeira forma, só podemos suspirar com a maravilha desta árvore, por isso também é conhecida como a \"Bela Borboleta do Mistério\".",
  str_item_intro_5424111 = "Olhando para as raízes redondas, pode-se ver a diferença entre a Strangefruit Tree básica e outras variedades, e não podemos deixar de nos maravilhar com sua singularidade.",
  str_item_intro_5424112 = "Uma árvore de Strangefruit amarela que é criada com Rose Crystalloids. Dá frutos amarelos e folhas que parecem simbolizar o abraço do outono.",
  str_item_intro_5424113 = "Uma árvore de Strangefruit roxa que é criada com Rose Crystalloids. Você pode achar seu cheiro estranho no começo, mas sua seiva é completamente insípida, a ponto de ser semelhante à água pura.",
  str_item_intro_5424211 = "Uma Strangefruit Tree II que sofreu algumas pequenas mutações. Suas raízes são robustas e seus frutos apresentam espinhos pontiagudos no exterior, que servem como uma formidável defesa. As vinhas ao redor também parecem alertar os estranhos para manter distância.",
  str_item_intro_5424212 = "Um gênero da Blooming Strangefruit Tree que é criado com Rose Crystalloids. As videiras, caules e folhas azuis mostram que é diferente da variedade original, mas parece que seus frutos ainda são os mesmos.",
  str_item_intro_5424213 = "Um gênero da Blooming Strangefruit Tree que é criado com Rose Crystalloids. Suas videiras e caules dão uma sensação de murcha, mas a fruta dentro é rica e exuberante, fazendo com que sua aparência pareça um disfarce.",
  str_item_intro_5424221 = "Uma Strangefruit Tree II que sofreu algumas pequenas mutações. A fruta na raiz foi deformada em uma forma completamente diferente. Acredita-se que os frutos separados e as pétalas das folhas possam absorver nutrientes, respectivamente, de modo que, mesmo que parte da árvore seja danificada, outras partes podem continuar crescendo para garantir sua sobrevivência.",
  str_item_intro_5424222 = "Um gênero da Flourishing Strangefruit Tree que é criado com Rose Crystalloids. Diz-se que sua aparência vermelha se deve à sua seiva, que contém produtos químicos raros.",
  str_item_intro_5424223 = "Um gênero da Flourishing Strangefruit Tree que é criado com Rose Crystalloids. A fruta possui uma cor amarela especial, que parece ser resultado da perda de água de sua casca. Depois que a pele é arrancada, ela logo se torna quebradiça e se transforma em uma pilha de isca.",
  str_item_intro_5424311 = "Uma Strangefruit Tree III que sofreu mutações frequentes. A parte externa da fruta endurece, tornando-se uma bola de pedra que é muito difícil de comer.",
  str_item_intro_5424312 = "Um gênero raro da Thriving Strangefruit Tree que é criado com Rose Crystalloids. Embora não esteja claro se seu fruto também sofreu mutação, você pode senti-lo vagamente pelas folhas. Talvez não seja uma boa ideia provar seu fruto.",
  str_item_intro_5424313 = "Uma próspera árvore Strangefruit que passou por mutações frequentes. A copa e as folhas da árvore exibem cores vivas, que contrastam nitidamente com seus frutos semelhantes a pedras. Algumas pessoas chamam seu fruto de \"pedra florida\".",
  str_item_intro_5424321 = "Uma árvore Arcadian Strangefruit que sofreu mutações frequentes. Possui tronco curvo, e seu fruto é dividido em dois segmentos, formando um vaso natural. Contanto que você o tenha, não terá que se preocupar em ficar com sede.",
  str_item_intro_5424322 = "Um gênero da Arcadian Strangefruit Tree que é criado com Rose Crystalloids. Sua seiva em sua \"poça de frutas\" tem um sabor indescritível, que se diz ser causado por um misterioso elemento desconhecido.",
  str_item_intro_5424323 = "Uma árvore Arcadian Strangefruit que sofreu mutações frequentes. Possui suco ainda mais claro em seu centro que pode permanecer fresco por muito tempo, tornando-o perfeito para os dias quentes de verão.",
  str_item_intro_5424331 = "Uma Strangefruit Tree III que sofreu mutações frequentes. O tronco está torcido, mas na verdade isso é causado pela fruta que está dentro dele. De acordo com alguns estudos, é porque a fruta foi dobrada, e o chamado \"tronco\" realmente protege a casca da fruta.",
  str_item_intro_5424332 = "Um gênero raro de Mellifluous Strangefruit Tree que é criado com Rose Crystalloids. Seu dossel branco parece uma enorme nuvem no céu.",
  str_item_intro_5424333 = "Uma Árvore Melíflua de Frutas Estranhas que passou por frequentes mutações. A variação de cor do tronco da árvore é muito óbvia, o que também indica que o sabor da fruta mudou muito. Segundo os aventureiros, tem um sabor um tanto picante e azedo.",
  str_item_intro_5424341 = "Uma Strangefruit Tree III que sofreu mutações frequentes. Sua forma reflete melhor a essência desta Árvore Única. A enorme fruta amontoada, os ramos que dela se projetam... Por isso é conhecido como o \"Gigante da Fruta\".",
  str_item_intro_5424342 = "Um gênero raro da Hearty Strangefruit Tree que é criado com Rose Crystalloids. Sua enorme fruta azul parece extremamente gorda, provando que realmente merece seu nome. Diz-se que o suco contido nele é suficiente para fornecer água para uma aldeia inteira. É por isso que algumas pessoas a chamam de \"Árvore do Tanque de Água\".",
  str_item_intro_5424343 = "Um gênero raro da Hearty Strangefruit Tree que é criado com Rose Crystalloids. A enorme fruta vermelha é muito brilhante, então ninguém pode ignorar sua existência. É por isso que algumas lendas afirmam que seu suco pode rejuvenescer, mas podem ser apenas lendas.",
  str_item_intro_5424411 = "Um gênero raro de Strangefruit Tree IV que passou por mutações complexas. A fruta é enorme e possui cores maravilhosas. Além disso, os ramos com suas estruturas complexas podem facilmente imbuir alguém com desejo de dominação depois de olhar por muito tempo, levando até mesmo a disputas com parentes e amigos. É por isso que também é conhecida como a \"Árvore Contrária\".",
  str_item_intro_5424412 = "Um gênero raro da Enduring Strangefruit Tree que é criado com Rose Crystalloids. Sua fruta verde tem um forte sabor natural. Se você olhar para ele por muito tempo, poderá se encontrar imerso nele, como se estivesse na floresta. Você pode até ouvir o chilrear dos insetos e pássaros, e sentir as folhas ao vento...",
  str_item_intro_5424413 = "Um gênero raro da Enduring Strangefruit Tree que é criado com Rose Crystalloids. A fruta tornou-se um rosa brilhante e encantador. Se você olhar para ele por um longo tempo, você pode até mesmo ver de repente um ritmo saltitante emergindo de dentro dele, o que é uma visão muito estranha de se ver.",
  str_item_intro_5424421 = "Um gênero raro da Strangefruit Tree IV que passou por mutações complexas. Seus frutos são numerosos, de tamanhos variados e empilhados em formação cruzada. Diz-se que esta é uma das mais antigas Árvores Únicas, e há até registros dela existindo na natureza! É por isso que também é conhecida como a \"Árvore Primordial\".",
  str_item_intro_5424422 = "Um gênero raro da Stately Strangefruit Tree que é criado com Rose Crystalloids. Seu fruto rosa faz com que as pessoas queiram beber o suco que produz. Diz-se que pode ser usada para preparar uma bebida deliciosa e muito elogiada pela realeza, por isso também é conhecida como a \"Árvore Regal\".",
  str_item_intro_5424423 = "Um gênero raro da Stately Strangefruit Tree que é criado com Rose Crystalloids. De longe, seus frutos parecem bolas líquidas condensadas da água azul do mar, e você pode até ver ondulações se espalhando por eles. No entanto, não se sabe se isso é apenas uma ilusão.",
  str_item_intro_5424431 = "Um gênero raro de Strangefruit Tree IV que passou por mutações complexas. Seu enorme fruto emite um cheiro maravilhoso o tempo todo. Há quem diga que pode trazer uma coragem inexplicável a quem o cheira, fazendo-o desejar conquistar tudo o que vê.",
  str_item_intro_5424432 = "Um gênero raro da Tranquil Strangefruit Tree que é criado com Rose Crystalloids. Seu fruto verde pode acalmar os soldados mais ferozes, tornando-o adequado para meditação e pensamento profundo. Diz-se que muitas pessoas sábias atingiram a iluminação sob sua influência, levando ao seu apelido - \"a Árvore da Revelação\".",
  str_item_intro_5424433 = "Um gênero raro da Tranquil Strangefruit Tree que é criado com Rose Crystalloids. Sua enorme fruta rosa pode não apenas imbuir as pessoas de coragem, mas também pode conceder-lhes forte ambição e um senso de obstinação para que possam embarcar em um caminho sem volta para lutar pela supremacia. É por isso que também é conhecido como o \"Kingmaker\".",
  str_item_intro_5424441 = "Um gênero raro da Strangefruit Tree IV que passou por mutações complexas. Seu fruto fica escondido dentro do tronco, mas segundo alguns estudiosos, o tronco é a casca externa endurecida do fruto e não uma camada externa que envolve o fruto! Parece que esta Árvore Única está se esforçando muito para proteger seus frutos.",
  str_item_intro_5424442 = "Um gênero raro da Wonder Strangefruit Tree que é criado com Rose Crystalloids. Diz-se que esta fruta verde contém a essência da vida, que, quando extraída corretamente, pode fazer as plantas crescerem mais rápido, aumentar o rendimento das colheitas e até melhorar o solo estéril e o solo alcalino duro! Por esse motivo, muitos o chamam de fruto da vida.",
  str_item_intro_5424443 = "Um gênero raro da Wonder Strangefruit Tree que é criado com Rose Crystalloids. O seu enorme fruto azul contém uma água doce, e a sua camada externa de \"casca\" também tem um poderoso efeito hidratante que protege a água do interior do fruto de se perder, tornando-o essencialmente um reservatório...",
  str_item_intro_5424451 = "Um gênero raro de Strangefruit Tree IV que passou por mutações complexas. Embora sua fruta enorme pareça comum, por um certo período de tempo, ela libera um aroma muito encantador que se diz inesquecível! Talvez seja por isso que tantas borboletas esvoaçam ao seu redor, embora geralmente não tenha um cheiro especial.",
  str_item_intro_5424452 = "Um gênero raro da Distinguished Strangefruit Tree que é criado com Rose Crystalloids. De acordo com algumas lendas, esta fruta roxa libera uma fragrância que permeia toda a terra uma vez a cada algumas centenas de anos! Existe também a lenda de um \"rei\" que surgirá neste mundo quando sua fragrância se espalhar...",
  str_item_intro_5424453 = "Um gênero raro da Distinguished Strangefruit Tree que é criado com Rose Crystalloids. Ao contrário da fruta de outras Árvores Distinguidas de Frutas Estranhas, esta fruta azul tem um toque de frescor e neutraliza outros odores! É muito popular entre os jardineiros por esse motivo, mas sua incapacidade de ser transplantada faz suspirar os jardineiros comuns.",
  str_item_intro_5424461 = "Um gênero raro da Árvore Strangefruit que passou por mutações complexas. Sua casca externa se transformou em uma gaiola que abriga uma deliciosa fruta. Esta fruta é conhecida por emitir uma névoa sedutora de tempos em tempos, que dizem proteger contra qualquer pretenso forrageador.",
  str_item_intro_5424462 = "Um gênero raro da Misty Strangefruit Tree que é criado com Rose Crystalloids. Seu fruto verde-vivo possui um sabor azedo e um aroma extremamente pungente, levando muitos a acreditar que é venenoso. Na verdade, a fruta é perfeitamente segura para comer.",
  str_item_intro_5424463 = "Um gênero raro da Misty Strangefruit Tree que é criado com Rose Crystalloids. A parte carnuda de seu fruto azul sofreu uma misteriosa transformação, que o tornou extremamente resistente e elástico. Mesmo depois de ser atropelada por um veículo pesado, esta fruta voltará rapidamente à sua forma original...",
  str_item_intro_5424471 = "Um gênero raro da Árvore Strangefruit que passou por mutações complexas. A fruta é dividida em duas partes - a parte principal da fruta é realmente envolta por sua casca grossa, enquanto a fruta brilhante pendurada no final de seu galho é considerada o resultado da mutação de sua copa! No entanto, a forma, o cheiro e o sabor da fruta pouco contribuem para corroborar essa teoria...",
  str_item_intro_5424472 = "Um gênero raro da Sparkling Strangefruit Tree que é criado com Rose Crystalloids. Diz-se que sua luz azul cheira como o oceano, ganhando o apelido de \"enviado da brisa do mar\". Outros, porém, afirmam que se trata apenas de um efeito alucinógeno causado pelo aroma da fruta.",
  str_item_intro_5424473 = "Um gênero raro da Sparkling Strangefruit Tree que é criado com Rose Crystalloids. A suave luz verde emitida por seu fruto tem um efeito calmante, que supostamente torna dócil até o mais feroz dos animais ao se aproximar. Se isso é verdade ou não, ainda não foi confirmado.",
  str_item_intro_5425111 = "Esta Árvore Única sempre foi diferente das outras árvores. Na verdade, deve-se perguntar se ela pode contar como uma árvore... De acordo com a pesquisa de muitos estudiosos, é de fato uma árvore, então só podemos dizer que esta é verdadeiramente uma Árvore Única que parece e se sente maravilhosa.",
  str_item_intro_5425112 = "Uma árvore de cogumelo vermelho que é criada com cristalóides rosas. Seu dossel vermelho deixa as pessoas inquietas e impacientes, então provavelmente não é a melhor árvore para se sentar à sombra.",
  str_item_intro_5425113 = "Uma Blue Mushroom Tree que é criada com Rose Crystalloids. Seu dossel azul cria a ilusão de um vasto céu; alguns até dizem que podem sentir o cheiro da fragrância das nuvens sob ela.",
  str_item_intro_5425211 = "Um Mushroom Tree II que sofreu algumas pequenas mutações. Sua copa sofreu muitas mudanças, tornando-se macia e dura ao mesmo tempo, e seus galhos pendem baixos devido ao peso, criando a ilusão de um arco. Se você adicionar algumas vigas de madeira para suporte e erguer paredes, poderá convertê-la em uma pequena casa.",
  str_item_intro_5425212 = "Um gênero da Fuzzy Mushroom Tree, que sofreu algumas pequenas mutações, é criado com Rose Crystalloids. O interior da copa é azul celeste, o que cria a ilusão de estar no mar.",
  str_item_intro_5425213 = "Um gênero da Fuzzy Mushroom Tree, que sofreu algumas pequenas mutações, é criado com Rose Crystalloids. O interior vermelho do dossel é aterrorizante para alguns. Também há rumores de que esta árvore é venenosa. No entanto, essas são as palavras dos preconceituosos.",
  str_item_intro_5425221 = "Um Mushroom Tree II que sofreu algumas pequenas mutações. Com um tronco grosso e uma copa encolhida, esta árvore parece um balde d'água, e seu tronco grosso realmente pode absorver água e armazená-la, por isso também é chamada de cogumelo d'água.",
  str_item_intro_5425222 = "Um gênero da Stoic Mushroom Tree, que sofreu algumas pequenas mutações, é criado com Rose Crystalloids. Embora seja vermelho, a água armazenada em seu interior não foi afetada. Você pode até ouvir o som da água fluindo por dentro se chegar perto o suficiente.",
  str_item_intro_5425223 = "Um gênero da Stoic Mushroom Tree, que sofreu algumas pequenas mutações, é criado com Rose Crystalloids. Algumas pessoas chamam seu dossel azul de \"dossel do oceano\" devido à forma como foi afetado pela água armazenada em seu interior. Alguns dizem que você pode ouvir o som das ondas do tronco grosso se você ficar no dossel e colocar seus ouvidos contra ele.",
  str_item_intro_5425311 = "Um Mushroom Tree II que sofreu mutações frequentes. O dossel manteve seu tamanho original e ficou ainda mais espesso do que nunca. Também tem um cheiro incrível...",
  str_item_intro_5425312 = "Um gênero raro da Árvore de Cogumelo Sedutora que é criada com Cristalóides de Rosa. Como o dossel é completamente azul, você se sentirá no fundo de um mar raso, mesmo que apenas olhe de longe.",
  str_item_intro_5425313 = "Um gênero raro da Árvore de Cogumelo Sedutora que é criada com Cristalóides de Rosa. O dossel vermelho brilhante é extremamente atraente para alguns e tem um poder mágico que atrai os espectadores cada vez mais perto dele. No entanto, não há razão maliciosa para isso e ninguém sabe por que isso tem esse efeito.",
  str_item_intro_5425321 = "Um Mushroom Tree II que sofreu mutações frequentes. Não só ficou menor, mas também começou a crescer em grupos. Felizmente, é basicamente a mesma forma. Sua maior característica é seu dossel que brilha intensamente com todos os tipos de luzes, criando uma cena de sonho quando a luz reflete no pó que solta no ar.",
  str_item_intro_5425322 = "Um gênero raro da Lambent Mushroom Tree que é criado com Rose Crystalloids. O vermelho ardente desta árvore faz com que sua copa pareça um mar de chamas, enquanto seus pontos brilhantes são confundidos com faíscas. Por esta razão, esta árvore também é conhecida como cogumelo flamejante.",
  str_item_intro_5425323 = "Um gênero raro da Lambent Mushroom Tree que é criado com Rose Crystalloids. O dossel roxo parece amoroso e também libera poeira fluorescente que dizem ser muito encantadora. Alguns estudiosos também afirmam que esta árvore é uma variante ou um parente distante da Árvore do Cogumelo Sedutora, mas isso é apenas especulação.",
  str_item_intro_5425331 = "Um Mushroom Tree II que sofreu mutações frequentes. O tronco desta árvore cresceu torto e tem duas copas. Alguns estudiosos especulam que esta árvore suga uma quantidade excessiva de água do solo para manter ambas as copas vivas, o que faz com que a água seja excretada das copas e caia como gotas de chuva.",
  str_item_intro_5425332 = "Um gênero raro da Moist Mushroom Tree que é criado com Rose Crystalloids. Completamente amarelas, as gotas de chuva que caem desta árvore também criam a atmosfera de um pôr do sol. Quando as gotas de chuva caem rapidamente, parece até que a árvore está envolta em uma cortina de chuva do pôr do sol.",
  str_item_intro_5425333 = "Um gênero raro da Moist Mushroom Tree que é criado com Rose Crystalloids. Esta árvore se assemelha a uma criatura marinha devido à sua cor azul, e as gotas de chuva que caem desta árvore são como salpicos de ondas azuis, por isso também é chamada de controladora da água do mar.",
  str_item_intro_5425341 = "Um Mushroom Tree II que sofreu mutações frequentes. Caracterizada por muitos galhos macios e caídos, à primeira vista, esta árvore parece a barba de um sábio ancião, por isso também é chamada de cogumelo sábio.",
  str_item_intro_5425342 = "Um gênero raro da Lush Mushroom Tree que é criado com Rose Crystalloids. A barba amarela faz com que esta árvore pareça ainda mais sábia, e alguns até afirmam que esta árvore tem a proteção da luz. Quando o vento sussurra através de suas hastes flexíveis, parece que os raios de sol brilham pelas frestas.",
  str_item_intro_5425343 = "Um gênero raro da Lush Mushroom Tree que é criado com Rose Crystalloids. Suas hastes verdes flexíveis se parecem com videiras. Quem curte a sombra e a vista sob a copa vai se sentir em uma floresta primária.",
  str_item_intro_5425411 = "Um cogumelo IV que passou por mutações complexas. Tendo crescido muito e muito fino, diz-se que o dossel é quase transparente quando visto de certos ângulos! Naturalmente, muitos dizem que essa sensação de transparência não vem do dossel fino, mas do ar frio que é irradiado pela árvore a todo o momento e os lembra do gelo transparente.",
  str_item_intro_5425412 = "Um gênero raro da Diluted Mushroom Tree que é criado com Rose Crystalloids. O dossel amarelo e a brisa fria ocasional criam a ilusão de sentir frio mesmo sob o sol escaldante, então algumas pessoas chamam isso de \"árvore maravilhosa da terra do sol congelado\".",
  str_item_intro_5425413 = "Um gênero raro da Diluted Mushroom Tree que é criado com Rose Crystalloids. O dossel vermelho deslumbrante e sua sensação natural de transparência fazem as pessoas se perguntarem se esta é uma obra de arte criada por pessoas em vez de uma criação da natureza.",
  str_item_intro_5425421 = "Uma Árvore de Cogumelo IV que passou por mutações complexas. Embora a copa dessa árvore pareça bastante comum, ela ocasionalmente libera rajadas de ar que criam a ilusão de que está respirando. Esta árvore também vive principalmente em grupos e cria uma leve névoa quando todas liberam rajadas de ar uma após a outra, daí seu nome.",
  str_item_intro_5425422 = "Um gênero raro da Misty Mushroom Tree que é criado com Rose Crystalloids. Quando a copa vermelha desta árvore respira, os buraquinhos que se abrem e fecham de vez em quando fazem pensar em feridas. Além disso, as rajadas de ar liberadas dão a impressão de névoa de sangue em determinados momentos, dando-lhe o nome de retorno trágico do campo de batalha.",
  str_item_intro_5425423 = "Um gênero raro da Misty Mushroom Tree que é criado com Rose Crystalloids. A névoa emitida pelo dossel azul lembra os espectadores do inverno, fazendo muitos acreditarem erroneamente que a árvore veio de Northland. Eles estão todos errados, pois as rajadas de ar liberadas por esta árvore são levemente quentes e nada frias.",
  str_item_intro_5425431 = "Um cogumelo IV que passou por mutações complexas. A copa cresceu tanto que é de se perguntar se seu tronco pode suportar seu peso. Como o dossel é muito grande, ele bloqueia totalmente a visão do céu para quem está embaixo dele. Por esse motivo, alguns a chamam de árvore que cobre o céu.",
  str_item_intro_5425432 = "Um gênero raro da Dome Mushroom Tree que é criado com Rose Crystalloids. De vez em quando, o verde da copa exala a fragrância de plantas aquáticas, dando aos espectadores a estranha ilusão de que estão próximos a um corpo d'água. Diz-se que esta árvore fornece nutrientes para as plantas aquáticas próximas florescerem, mas ninguém confirmou isso.",
  str_item_intro_5425433 = "Um gênero raro da Dome Mushroom Tree que é criado com Rose Crystalloids. O dossel vermelho brilhante cria a ilusão de uma boa colheita, e alguns até disseram que podem sentir o cheiro da doce fragrância da fruta ao seu redor. No entanto, esta Árvore Única é completamente intragável, especialmente a copa, que é difícil de cozinhar e não tem valor nutricional.",
  str_item_intro_5510001 = "Seu corpo rechonchudo não é um obstáculo à sobrevivência porque tem uma grande barriga cheia de toxinas mortais. No entanto, sua carne extremamente deliciosa ainda atrai muitos comensais que não têm medo da morte.",
  str_item_intro_5510002 = "Conhecido por suas cores vivas, grandes números e carne macia, vem dominando as mesas de jantar.",
  str_item_intro_5510003 = "Tem o nome de seu corpo esbelto e em forma de faca, e sempre se move em grupos.",
  str_item_intro_5510004 = "O que parece uma cobra à primeira vista é na verdade um peixe esbelto com barbatanas muito pequenas. Ele gosta de se esconder entre rochas subaquáticas e sair correndo para assustar as pessoas.",
  str_item_intro_5510005 = "Um peixe que gosta de viver em águas claras. Abundante em número e amplamente distribuído, pode ser encontrado em muitos lugares.",
  str_item_intro_5510006 = "Este peixe é considerado um predador dominante na água, mas por causa de sua deliciosa carne, foi alvo de comensais e agora se tornou um \"regular\" em banquetes sofisticados.",
  str_item_intro_5510007 = "Um peixe esguio que se reúne ao longo das margens dos rios, descansando ou navegando, e se alimenta de vários organismos minúsculos na água. Não só a carne é comestível, mas o óleo de peixe também pode ser usado para fazer vários pigmentos.",
  str_item_intro_5510008 = "Gosta de se mover em grupos e é grande em número. Tem uma personalidade violenta e gosta de bater a cabeça contra o inimigo em uma luta feroz, assim como um dardo. A carne de Makaira é firme, e suas escamas são secas e usadas para lanches",
  str_item_intro_5520001 = "Uma tartaruga que navega lentamente pela água mal consegue se mover em terra. Provavelmente porque se move tão lentamente, tem uma casca dura nas costas, da qual depende para manter seus inimigos afastados.",
  str_item_intro_5520002 = "Este raro organismo aquático prospera em águas geladas e geralmente pode ser encontrado vivendo nas profundezas dos mares congelados. Seu corpo é transparente e possui uma variedade de cores bonitas e apêndices em forma de asas, daí seu nome. Uma visão muito rara em águas quentes, provavelmente eles se perderam...",
  str_item_intro_5520004 = "Essas criaturas aquáticas têm corpos planos e nadam muito lentamente. Eles também gostam de explorar e descansar no fundo de rios e córregos. Por causa dos muitos pontos bonitos em suas costas, os pescadores muitas vezes os confundem com grandes grupos de pérolas espalhadas ao olhar para baixo em rios e córregos, daí seu nome.",
  str_item_intro_5520005 = "Uma criatura que gosta de rastejar sob as ondas e é conhecida por sua forma única. Diz-se que quando foi descoberto pela primeira vez, as pessoas pensaram que era um tipo estranho de alga ou coral. Eles não perceberam que estava vivo até que começou a se mover bem devagar...",
  str_item_intro_5520006 = "Um peixe maravilhoso que gosta de viver entre algas, corais e até anêmonas. Tem uma aparência brilhante e um rosto cômico que faz rir quem o vê. Alguns comentaram que as plantas aquáticas dançam sempre que este peixe está perto delas, daí o seu nome.",
  str_item_intro_5520007 = "Este parece ser um organismo aquático descoberto recentemente. Com pele lisa e músculos macios, ele nada pelas profundezas do oceano com um langor elegante que o fez rapidamente ganhar popularidade entre os aficionados por animais. Diz-se que alguns de seus admiradores sentem prazer físico e mental sempre que o veem navegando sem rumo na água, varrendo suas preocupações e conflitos com uma onda de seus tentáculos.",
  str_item_intro_5520016 = "Este peixe gosta de viver em águas vastas, e de alguma forma apareceu aqui... Antigamente as pessoas o temiam devido ao seu corpo negro e forma estranha, mas na verdade ele é muito gentil e adora nadar sem pressa na água. Ele até se esforça para evitar outros pequenos animais aquáticos que encontra.",
  str_item_intro_5520101 = "Por causa de suas cores vibrantes, a enguia marmorizada vermelha e branca tornou-se um dos peixes ornamentais mais valiosos. Não só tem o apelido de \"jóia viva na água\", mas também traz boa sorte aos seus criadores.",
  str_item_intro_5520102 = "A enguia marmorizada tricolor é amada por milhões por causa de seus padrões variáveis e é chamada de \"peixe elegante\". Sempre que você vê-lo, você vai se sentir relaxado. Muitas pessoas pensam que pode trazer harmonia para a família.",
  str_item_intro_5520103 = "Um peixe ornamental de alta qualidade. Conhecido como \"obras de arte da natação\" por causa de seus movimentos de natação graciosos, diz-se que é capaz de eliminar futuros desastres para os criadores.",
  str_item_intro_5520104 = "A enguia marmorizada preta e branca tem um temperamento suave e padrões naturais. É amigável com as pessoas, especialmente as crianças, então algumas pessoas acreditam que pode abençoar o crescimento suave das crianças.",
  str_item_intro_5520105 = "Suas escamas brilharão em uma linda cor dourada ao sol, então acredita-se que a enguia dourada de mármore traz fortuna, e muitos empresários gostariam de manter algumas dessas enguias.",
  str_item_intro_5520201 = "Este peixe ornamental brilha em vermelho na água. Suas escamas são tão pronunciadas que quase fazem um corpo de água parecer rosa, criando uma visão magnífica.",
  str_item_intro_5520202 = "Embora pareça um pouco \"mau\", suas escamas vermelho-sangue mostrarão uma cor vermelhão sob a luz do sol, fazendo as pessoas sentirem como se o peixe estivesse vestindo uma armadura feita de rubis.",
  str_item_intro_5520203 = "Brilhando com escamas azuis, traz uma sensação inexplicável de frescor ao nadar lentamente na água, principalmente no meio do verão.",
  str_item_intro_5520204 = "As escamas douradas fazem com que pareça um general lendário, e sua postura de natação também é tão avassaladora que os pequenos peixes ao redor precisam recuar em sua presença.",
  str_item_intro_5520205 = "Comparado com outros de sua classe, parece elegante e calmo, e suas escamas branco-prateadas e forma aerodinâmica dão-lhe uma vibração aristocrática.",
  str_item_intro_5520301 = "Com um corpo plano e cores deslumbrantes, este peixe é como uma borboleta caindo na água, nadando graciosamente.",
  str_item_intro_5520302 = "Um peixe ornamental com cabeça esbranquiçada e corpo predominantemente preto. Tem um temperamento suave. Se você observar com atenção, os pontos na junção do preto e do branco são ligeiramente diferentes. Pode-se dizer que cada Black Butterflyfish é único.",
  str_item_intro_5520303 = "Tem um corpo amarelo e branco, que é dividido em três grandes seções, daí o nome. É barulhento e gosta de provocar outros peixes. Portanto, as águas se tornarão vivas com sua presença.",
  str_item_intro_5520304 = "Com uma bela aparência azul royal, o brilho deste peixe ornamental varia muito. É tímido e não gosta de se mostrar. Muitas vezes se esconde entre rochas e plantas aquáticas, por isso é apelidada de \"garota tímida\".",
  str_item_intro_5520401 = "Com suas cores vivas e olhos grandes e cheios de alma, gosta de se aproximar de outros peixes e raramente é rejeitado, tornando-se a \"borboleta social\" dos peixes ornamentais.",
  str_item_intro_5520402 = "As manchas manchadas nas costas dão-lhe o seu nome e, se combinadas com plantas aquáticas de cor semelhante a ela... seria uma cor protetora natural. Por isso, na hora de decorar, devemos atentar para a sua colocação de cores com o ambiente, de forma a destacar sua presença.",
  str_item_intro_5520403 = "Seu corpo é principalmente preto, e as barbatanas amarelas e brancas nas costas são suas características. Ele tem um temperamento quieto, mas uma vez enfurecido, ele lutará contra o oponente até o fim, assim como um espinho pungente – então não toque nele.",
  str_item_intro_5520501 = "Poucas pessoas têm esse peixe ornamental porque é muito... feio. Apenas a barba brilhante faz com que pareça diferente.",
  str_item_intro_5520502 = "O tamboril branco parece ser muito mais acessível, mas seu brilho também parece mais fraco. Talvez seja o contraste que faça a mágica.",
  str_item_intro_5520601 = "Diz-se que este cavalo-marinho vive nas profundezas do mar, e ninguém sabe por que veio até aqui. Como está acostumado a viver no fundo do mar, geralmente se esconde no fundo do mar e é difícil de encontrar.\nGeralmente se escondendo da vista, só aparece quando Lumina está ao seu redor e ficará assustado se o Lumina for muito forte.",
  str_item_intro_5520602 = "Este cavalo-marinho gosta de viver nos espaços entre as pedras dos riachos. Recebeu esse nome porque se move muito rapidamente, fazendo as pessoas pensarem que as pedras foram tingidas de amarelo.\nGeralmente se escondendo da vista, só aparece quando Lumina está ao seu redor e ficará assustado se o Lumina for muito forte.",
  str_item_intro_5520603 = "Os cavalos-marinhos do rio branco geralmente vivem em rios e córregos. Sua cor do corpo é uma proteção natural, e seu estilo de natação vertical permite que eles se escondam nas bolhas de água dos riachos e não sejam descobertos por seus inimigos naturais.\nMenos sensível a Lumina, geralmente se esconde da vista e só aparece quando atraído por Lumina mais forte, mas ficará assustado se o Lumina ao redor for muito forte.",
  str_item_intro_5520701 = "Uma criatura subaquática que gosta de viver na curva do rio. Parece extremamente feroz com seus muitos apêndices. No entanto, isso é apenas um disfarce, pois é muito dócil e vive recluso entre as algas, dificultando sua detecção.",
  str_item_intro_5520702 = "Gosta de morar em curvas claras de rios e esconde a maior parte de seu corpo na areia amarela do leito do rio. Como sua pele é quase da mesma cor que a areia, quase nenhuma outra criatura a nota, tornando extremamente fácil para ela emboscar outras.",
  str_item_intro_5520801 = "Não se deixe enganar pelo seu tamanho incrivelmente pequeno. Pesa 1 quilo e é o menor tipo de carpa cabeçuda do mundo. Por mais pequeno e comum que pareça, este peixinho tem um enorme potencial de crescimento...",
  str_item_intro_5520802 = "Uma carpa cabeçuda ligeiramente maior. Pesando 5 quilos, é muito mais difícil de pegar, apesar de suas cores mais vibrantes. Parece que com maior peso vem maior alerta.",
  str_item_intro_5520803 = "Uma carpa cabeçuda de 10 quilos. Com um corpo mais redondo e cheio, seus olhos esbugalhados parecem estar dizendo: \"Eu posso ficar ainda maior, você sabe!\"",
  str_item_intro_5520804 = "O mais forte de todos os Bighead Carp, chegando a 20 quilos. Ele flutua lenta e pacificamente pela água, enchendo os espectadores com uma sensação misteriosamente profunda de tranquilidade.",
  str_item_intro_5520805 = "Uma monstruosidade de uma carpa cabeçuda que pesa esmagadores 50 quilos! Um rei entre as carpas. Sua barriga parece ser a fonte de sua circunferência impressionante. Naturalmente, um peixe deste tamanho é bastante agressivo. Outras criaturas subaquáticas tendem a evitá-lo.",
  str_item_intro_5520806 = "Esta carpa cabeçuda é de tamanho decente, mas sua popularidade selvagem deriva de seu corpo brilhantemente dourado, coberto de escamas deslumbrantes em forma de estrela. A existência de um peixe tão inspirador deve ser realmente um presente do divino.",
  str_item_intro_5520811 = "Embora possa parecer uma criatura aquática extremamente feroz e cruel, suas pinças são usadas simplesmente para afastar obstáculos, como pedras e plantas aquáticas que o impedem de realizar seus negócios. Na verdade, o uso dessas garras em combate é apenas uma função secundária, pois essa criatura é muito meiga, e só faz cara de destemidamente agressiva na hora de se defender.",
  str_item_intro_5520812 = "Esta criatura é conhecida por se esconder entre rochas subaquáticas, pois gosta de carregar pedras para construir seu próprio \"castelo\" e emboscar criaturas azaradas ou simplesmente curiosas para garantir uma refeição saudável.",
  str_item_intro_5520014 = "Famoso pelos anéis azuis em seu corpo, este polvo raramente é visto em rios. Mas quando ele aparece, muitas criaturas aquáticas fogem dele, principalmente devido ao potente veneno em seu corpo que dizem ser capaz de matar com uma gota. Seu veneno é o motivo pelo qual é tão assumidamente atraente e sem medo de atrair a atenção de outras criaturas.",
  str_item_intro_5520901 = "Um peixe extremamente raro que se distingue pelo seu corpo esplendidamente colorido, bem como pela sua estrutura pequena, mas ágil. Incrivelmente alerta, é capaz de esconder suas cores ao primeiro sinal de movimento em sua vizinhança; como tal, capturar um peixe tão esquivo requer muita paciência e determinação. No entanto, o trabalho duro compensa imediatamente ao ver suas \"fitas\" coloridas flutuando graciosamente pela água.",
  str_item_intro_5530001 = "Sorte inesperada! Esta ostra tem pérolas nela. Parece bom em cor e forma e pode ser vendido por um bom preço.",
  str_item_intro_5530101 = "Uma lata velha. Não tenho certeza de quem jogou na água, mas essa pessoa certamente não presta atenção em proteger o meio ambiente...",
  str_item_intro_5530201 = "Este sapato deve estar \"vivendo\" na água há anos, e até as algas marinhas fazem dele sua casa.",
  str_item_intro_5601101 = "Um dia, poderei proteger minha pátria sob o grande céu.",
  str_item_intro_5601201 = "Eu gostaria de entender o incrível poder que canaliza através do Colosso...",
  str_item_intro_5602101 = "Uma memória dura a vida inteira, mas um registro dura mil anos, então vou lembrar, anotar e guardar até que alguém o encontre.",
  str_item_intro_5602201 = "Juro que encontrarei essas plantas mesmo que precise viajar até os confins da terra.",
  str_item_intro_5602202 = "Um estranho disse uma vez que tudo tem um custo. Bem, qual é o custo do conhecimento?",
  str_item_intro_5602203 = "O cérebro é mantido pelo aprendizado e a vida é mantida pelas emoções.",
  str_item_intro_5603101 = "Não desista facilmente. Mesmo que um experimento tenha falhado 99 vezes, ele pode ter sucesso na próxima vez.",
  str_item_intro_5603201 = "Qual é o princípio supremo que transforma um item em outro? Seria bom se pudéssemos encontrar o caminho para a origem do conhecimento.",
  str_item_intro_5603202 = "A inspiração é como uma faísca que passa. Eu passaria minha vida procurando uma maneira de fazê-la durar para sempre.",
  str_item_intro_5603301 = "A lâmina mais afiada nem sempre é a melhor escolha. Às vezes, um contundente pode fazer maravilhas. Também pode ser o caso ao interagir com ela...",
  str_item_intro_5604101 = "Cada árvore tem um destino próprio. Eu também tenho um? Espero encontrar a resposta em breve...",
  str_item_intro_5604201 = "As folhas vêm em prata? Ela me disse que não, mas eu não acreditei nela, então aqui estou.",
  str_item_intro_5604202 = "Os anéis anuais são as marcas dos anos gravadas nas árvores, sua história e sua memória. Fale com eles e talvez você possa aprender sobre o passado que não conhecemos – eles também são nossos anéis anuais.",
  str_item_intro_5604203 = "Entre as sombras entrelaçadas de folhas e árvores, surge seu perfil. É este o projeto do destino?",
  str_item_intro_5604301 = "Eles crescem e murcham silenciosamente. Vale a pena aprender com esse modo distante de viver.",
  str_item_intro_5604302 = "Onde estão nossas raízes? Espero descobrir ainda nesta vida...",
  str_item_intro_5605201 = "A ondulação me lembra meu pai que me ensinou a pescar.",
  str_item_intro_5605301 = "Essa vara de pescar branca é uma relíquia deixada por minha mãe, e vou passá-la para meus filhos.",
  str_item_intro_5605302 = "A única coisa que nos conecta é esse fio fino. Espero que nunca quebre.",
  str_item_intro_5605303 = "Mesmo que o dom dela seja uma isca, eu estaria disposto a aceitá-la.",
  str_item_intro_5605304 = "Às vezes, pescar não tem a ver com a pesca, mas com ver a luz brilhar nas ondas.",
  str_item_intro_5605305 = "Posso dizer para que lado a água está fluindo, mas quando poderei saber o que ela está pensando?",
  str_item_intro_5605306 = "Um movimento sutil do anzol indica que o peixe mordeu a isca. Se ao menos a vida tivesse sinais semelhantes para nos mostrar quando as oportunidades surgem.",
  str_item_intro_5606201 = "Espero não acabar como meu pai, que não conseguiu nada. Boa sorte para mim!",
  str_item_intro_5606301 = "A diligência acabará por encobrir minha tolice e deixar que todos me chamem de gênio da mineração do fundo de seus corações.",
  str_item_intro_5606302 = "Não subestime as pedras. Alguns deles podem esconder tesouros escondidos dentro.",
  str_item_intro_5606303 = "Lembre-se sempre de afiar a ponta da sua picareta!",
  str_item_intro_5606304 = "Assim como o amor, a mineração requer não apenas força, mas também habilidade!",
  str_item_intro_5606305 = "As veias minerais têm um certo cheiro! Meu nariz é muito sensível, mas seria melhor se eu pudesse descobrir onde ele está...",
  str_item_intro_5606306 = "Se perseverarmos, com certeza encontraremos esse filão, seja neste vale ou não.",
  str_item_intro_5607201 = "Ele é a cesta na qual meu coração está contido.",
  str_item_intro_5607301 = "Seria bom se ela pudesse ler minha boa vontade.",
  str_item_intro_5607302 = "Uma fruta caiu na minha cabeça quando eu era pequena, e desde então fui abençoado com boa sorte. Espero que minha sorte persista no futuro.",
  str_item_intro_5607303 = "Na maioria das vezes, basta seguir as abelhas para encontrar um bom néctar. Se eu pudesse entendê-los...",
  str_item_intro_5607304 = "Se nossos corações pudessem usar luvas, talvez não fossem tão facilmente feridos por espinhos...",
  str_item_intro_5607305 = "Você precisa de bons olhos para encontrar todas as frutas de uma vez. Sim, quero manter esse nível ao longo da minha vida.",
  str_item_intro_5608101 = "Espero que ele possa me aceitar como as plantações abraçam a luz do sol.",
  str_item_intro_5608201 = "Não estamos plantando sementes apenas para a colheita, trata-se mais de plantar esperança.",
  str_item_intro_5608301 = "Adoro ver o moinho de vento girar devagar porque você não precisa pensar em nada. Você pode assistir o dia todo...",
  str_item_intro_5608302 = "As sementes são incríveis. Apenas um pouco deles pode crescer tantas colheitas! Então... Enquanto houver sementes, haverá esperança!",
  str_item_intro_5608303 = "Eu preciso dela, assim como as plantas precisam do sol.",
  str_item_intro_5608304 = "Quando o sol estiver muito forte, queimará todas as colheitas. O mesmo se aplica a cuidar de outras pessoas.",
  str_item_intro_5608305 = "As lavouras não devem ser plantadas muito juntas - devem ser separadas por sulcos, da mesma forma que devo manter uma certa distância dela.",
  str_item_intro_5609201 = "Se for possível cultivar grama que não precise ser cortada, ela pode ser usada como um grande tapete confortável para dormir!",
  str_item_intro_5609301 = "A gota de água é macia e dura ao mesmo tempo. Posso me tornar alguém assim?",
  str_item_intro_5609302 = "Precisamos de um bom solo para cultivar plantas fortes e saudáveis, e o mesmo pode ser dito sobre nós, certo? Agradeça aos mais velhos por nos dar um solo diferente, para que possamos nos tornar os diferentes que queremos ser.",
  str_item_intro_5609303 = "Eu quero o néctar mais doce para meus futuros filhos.",
  str_item_intro_5609304 = "Ah... Quando estaremos livres para dançar como a abelha alegre?",
  str_item_intro_5609305 = "Você não pode simplesmente lançar seus olhos para aquelas lindas flores - as folhas verdes também merecem atenção, não é?",
  str_item_intro_5610101 = "Posso conduzir grandes rebanhos, mas não consigo entender o coração da minha família. Espero que meus futuros filhos não sejam assim.",
  str_item_intro_5610201 = "Dizem que se você vir um rosto sorridente ao servir um copo de leite, será abençoado pelo resto do ano!",
  str_item_intro_5610202 = "Ouvi dizer que as outras aldeias usam cães de patrulha para ajudá-los a pastorear animais, mas ele é a única coisa que tenho.",
  str_item_intro_5610203 = "Dizem que existe uma criatura chamada \"camelo\" que mora em desertos distantes, e seu leite é supostamente muito saboroso!",
  str_item_intro_5610204 = "Um dia, verei a grama brotar mais uma vez, e os campos nascerão de novo.",
  str_item_intro_5610301 = "Ouvi dizer que há uma pastagem mais ampla fora do vale, mas gosto da grama verde aqui.",
  str_item_intro_5610302 = "Queijo é a melhor comida do mundo, e se você pode comê-lo todos os dias por toda a vida, você está em um lugar que é conhecido nas lendas como o paraíso.",
  str_item_intro_5610303 = "Eles dizem que as pessoas do deserto estabelecem seus municípios com base na localização das fontes de água. Visto que não suporto ficar nem a um metro de distância dela, talvez ela seja minha fonte de água...?",
  str_item_intro_5611101 = "De acordo com as pessoas à beira-mar, há um grande navio que parece quase uma ilha. Eu quero muito ver!",
  str_item_intro_5611201 = "Eu poderia ficar de guarda o dia todo se não tivesse que dormir.",
  str_item_intro_5611202 = "Eu nunca vou deixar o mal chegar perto daqui. Especialmente nada que pudesse prejudicar as crianças...",
  str_item_intro_5611203 = "Depois de me tornar o guardião deste lugar, não consigo descansar nem à noite.",
  str_item_intro_5611204 = "Nenhum detalhe pode ser ignorado, caso contrário, é provável que ocorra um desastre.",
  str_item_intro_5611301 = "Posso caminhar por três dias e três noites sem me sentir cansado. Vou usar esse talento para patrulhar este vale e tomar cuidado com os forasteiros.",
  str_item_intro_5611302 = "Serei o escudo do meu povo! Haha, eu aprendi com o Juramento do Cavaleiro de Lumopolis, e é legal! Eu vou fazer o que eu digo!",
  str_item_intro_5611303 = "Se realmente iluminarmos aquelas grandes árvores que parecem tochas, podemos usá-las como faróis de sentinela?",
  str_item_intro_6400001 = "Obtenha para desbloquear o título: Frontline Hero\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface de título!",
  str_item_intro_6400002 = "Obtenha para desbloquear o título: Tactical Genius\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface de título!",
  str_item_intro_6400003 = "Obtenha para desbloquear o título: All-Knowing Mastermind\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface de título!",
  str_item_intro_6400004 = "Obtenha para desbloquear o título: Subjugator of Catastrophe\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface de título!",
  str_item_intro_6400005 = "Obtenha para desbloquear o título: Nefarious Conqueror\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface de título!",
  str_item_intro_6400006 = "Obtenha para desbloquear o título: Unyielding Soul\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface de título!",
  str_item_intro_6400007 = "Obtenha para desbloquear o título: Gold Rush\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400008 = "Obtenha para desbloquear o título: Dominator of the Sky\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400009 = "Obtenha para desbloquear o título: Empyrean Zenith\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400010 = "Obtenha para desbloquear o título: Timeless Bond\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400011 = "Obtenha para desbloquear o título: Shifting Seasons.\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400012 = "Obtenha para desbloquear o título: The Awakening.\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400013 = "Obtenha para desbloquear o título: Revelador do Passado.\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400014 = "Obtenha para desbloquear o título: Mighty Entourage.\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400015 = "Obtenha para desbloquear o título: Shining Alliance.\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400016 = "Obtenha para desbloquear o título: Onwards & Upwards.\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400017 = "Obtenha para desbloquear o título: Ultimate Summit.\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400018 = "Obtenha para desbloquear o título: History Unearthed.\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400019 = "Obtenha para desbloquear o título: Wakening Call.\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400020 = "Obtenha para desbloquear o título: Herói das Profundezas.\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400021 = "Obtenha para desbloquear o título: Intellectual Bookworm\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400026 = "Obtenha para desbloquear o título: Inch of Knowledge.\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400030 = "Obtenha para desbloquear o título: Guardião Marítimo.\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6400031 = "Obtenha para desbloquear o título: Empyrean Authority\nDepois de obtê-lo, você pode usar o título no cartão de visita - interface do título!",
  str_item_intro_6500001 = "Fundo inicial do cartão de nome. Pode ser selecionado via Cartão de Nome - Fundos!",
  str_item_intro_6500002 = "Fundo inicial do cartão de nome. Pode ser selecionado via Cartão de Nome - Fundos!",
  str_item_intro_6500003 = "Fundo inicial do cartão de nome. Pode ser selecionado via Cartão de Nome - Fundos!",
  str_item_intro_6500004 = "Fundo inicial do cartão de nome. Pode ser selecionado via Cartão de Nome - Fundos!",
  str_item_intro_6500005 = "Fundo inicial do cartão de nome. Pode ser selecionado via Cartão de Nome - Fundos!",
  str_item_intro_6500008 = "Colinas ondulantes, cobertas por um manto branco. Embora sombrios e parados, eles parecem irradiar uma certa vitalidade.",
  str_item_intro_6500011 = "Negócios obscuros feitos em becos escuros sob a cobertura da neblina no coração de Umbraton são uma visão comum para seus moradores.",
  str_item_intro_6500014 = "Uma planta de manutenção em uma cidade subterrânea de Illumina. Ele pode reparar muitos dispositivos danificados muito rapidamente, mesmo aquelas máquinas grandes.",
  str_item_intro_6500015 = "A celebração em Lumopolis está mais grandiosa do que nunca.",
  str_item_intro_6500016 = "Fontes abundantes de água, interseções e características geográficas e topográficas convenientes contribuem para a prosperidade de Umbraton.",
  str_item_intro_6500017 = "Quando o sol é engolfado por uma escuridão inexplicável, que mudança cataclísmica aguarda o mundo?",
  str_item_intro_6500018 = "Northland, o reino da geada perpétua. Esta terra é governada por Belém, e é também o lugar que ela deseja proteger.",
  str_item_intro_6500020 = "Não importa o que aconteça, não vou deixar esses vilões estragarem o show! Isso é justiça!",
  str_item_intro_6500021 = "Northland, o reino da geada perpétua. Esta terra é governada por Belém, e é também o lugar que ela deseja proteger.",
  str_item_intro_6500024 = "Naquele momento, sua cautela pareceu se dissipar, e seu sorriso feliz brilhou com travessura infantil, escondendo um segredo apenas para dois.",
  str_item_intro_6500026 = "O quintessencial banquete Rediesel Wrench acena - um banquete comemorativo animado que se tornou uma famosa mistura de iguarias do deserto.",
  str_item_intro_6500033 = "Quando estiver cansado de sua jornada, você sempre pode reservar algum tempo para sentar-se com esses seus companheiros enquanto relaxa, conversa e ouve as histórias uns dos outros.",
  str_item_intro_6500035 = "A luz do sol no castelo no alto permanece inalterada por anos. Diante de uma grande pintura a óleo, ela veste um vestido velho e passa muito tempo ali, perdida em pensamentos profundos, talvez em reminiscências.",
  str_item_intro_6500036 = "Com Florine ao seu lado, até as águas mais perigosas se tornarão seguras.",
  str_item_intro_6500037 = "Alguém permaneceu aqui por mais de cem anos, apenas para cumprir uma missão há muito esquecida.",
  str_item_intro_6500038 = "À medida que a brisa suave dispersa a melancolia do passado, os brilhantes raios do amanhecer queimarão todas as tristezas para anunciar um novo futuro para você.",
  str_item_intro_6500039 = "Como um farol, ela iluminará o vasto e escuro oceano, guiando os aventureiros em direção ao lar.",
  str_item_intro_6500041 = "Mesmo que esteja congelando e a terra esteja coberta de gelo e neve, você sempre terá um coração quente se estiver com seus companheiros. Boas festas, Navegador!",
  str_item_intro_6500042 = "Sheol saltou alto no ar para repelir os inimigos invasores. Neste momento, ela revelou um lado de si mesma que ninguém mais conhecia.",
  str_item_intro_6500043 = "Muitas estações de observação foram estabelecidas ao longo da fronteira do deserto. É aqui que eles repelem inimigos e defendem sua distante pátria.",
  str_item_intro_6500044 = "Lojas abundam, fervilhando de vozes, e o animado centro de Twin Pavilions Bay está lotado de residentes e turistas, escolhendo produtos com grande interesse em meio à agitação.",
  str_item_intro_6500045 = "\"Obrigado pelo seu reconhecimento. Noite Branca nas alturas!\"",
  str_item_intro_6500046 = "\"Gosto de ficar sozinho, mas agora... com você aqui, é um tipo diferente de alegria.\"",
  str_item_intro_6500047 = "\"Este mundo ainda está repleto de guerra. Você se juntará a mim para resolver esses conflitos nos próximos dias?\"",
  str_item_intro_6500049 = "\"Croac! Croac!\"",
  str_item_intro_6500051 = "Enquanto um bando de drones a cerca, a garota se vira e olha para você.\n\"Está tudo bem agora.\"",
  str_item_intro_6500053 = "Deslumbrante e brilhante, ela sorri e salta para o abismo.\n\"Não deixe ninguém tirar o seu poder ou a sua alegria.\"",
  str_item_intro_6500054 = "Qual caminho você deve escolher quando está na encruzilhada do destino?",
  str_item_intro_6500056 = "Tudo o que você experimenta deve guiar a True Order para um futuro cada vez maior. ",
  str_item_intro_6500057 = "A brisa do mar, raspadinhas, triciclos. As memórias daquele primeiro verão passado com a donzela ainda permanecem tão vívidas quanto sempre.",
  str_item_intro_6500058 = "O voto de reunião, onde as almas se encontram.",
  str_item_intro_9993001 = "Um auroriano sobrevivente aleatório na equipe regenera 20% de HP após vencer uma batalha.",
  str_item_intro_9993002 = "Apoiador Aurorianos +25% em efeitos de regeneração de Combos e Habilidades Ativas em batalha.",
  str_item_intro_9993003 = "+80% de recuperação de HP ao usar bandagens coletadas em batalha.",
  str_item_intro_9993004 = "Sniper Aurorians +10% contra efeito de elemento.",
  str_item_intro_9993005 = "Aurorians Detonadores: +30% de dano de Combo ao conectar 15+ casas.",
  str_item_intro_9993006 = "+50% de dano de Veneno, Queimadura e Sangramento sofrido por Eclipsites.",
  str_item_intro_9993007 = "Sniper Aurorians + 15% de dano de Chain Combo.",
