  str_item_intro_9993033 = "Aurorians de Trovão: +5% de ATQ.",
  str_item_intro_9993034 = "Aumenta o HP em 3% para Aurorianos Conversores e Apoiadores após cada vitória, até 30%.",
  str_item_intro_9993035 = "Aumenta o ATQ de Aurorians Atiradores e Detonadores em 1,5% após cada vitória, até 15%.",
  str_item_intro_9993036 = "Um Aurorian sobrevivente aleatório na equipe ganha 1,5% de redução de dano acumulável após vencer uma batalha, até o final dessa Exploração do Território Secreto.",
  str_item_intro_9994001 = "Um Aurorian sobrevivente aleatório na equipe regenera 10% de PV, sempre que um Eclipsita for morto.",
  str_item_intro_9994002 = "Os aurorianos de suporte regeneram 100% do dano de veneno em HP toda vez que o veneno é ativado em um Eclipsite envenenado.",
  str_item_intro_9994003 = "Aurorians Detonadores: +30% de dano em Eclipsitas com debuffs.",
  str_item_intro_9994004 = "Inflige 3 acúmulos de Veneno a todos os inimigos quando um Eclipsite Envenenado, Queimando ou Sangrando morre.",
  str_item_intro_9994005 = "A cada rodada de Eclipsite, Eclipsites Envenenados, Queimando ou Sangrando infligem Veneno em Eclipsites em 2 aglomerados ao redor.",
  str_item_intro_9994006 = "Aur. Atiradores: +30% de dano, enquanto a equipe estiver com debuff.",
  str_item_intro_9994007 = "Aurorians Detonadores: +5% de dano bônus, quando dano for recebido (restaura no final da batalha).",
  str_item_intro_9994008 = "Recarrega um curativo no campo quando a batalha começa.",
  str_item_intro_9994009 = "+20% de dano para todos os Sniper Aurorians com mais de 70% HP.",
  str_item_intro_9994010 = "Aurorians Detonadores recebem dano bônus igual a 10% do PV perdido ao atacar.",
  str_item_intro_9994011 = "Fonte de Lúmina regenera 5 MS adicional.",
  str_item_intro_9994012 = "+1 personagem recuperado na Fonte de Lúmina.",
  str_item_intro_9994013 = "Aurorians Detonadores: +10% de ATQ na Área Perigosa.",
  str_item_intro_9994014 = "Aurorians Detonadores em Área Fatal ganham +10% de ATQ.",
  str_item_intro_9994015 = "Atrasa as rodadas de escape para Scroungers em 4 rodadas.",
  str_item_intro_9994016 = "Reduz 1 rodada de recarga para todos os aurorianos após matar um grande Eclipsite.",
  str_item_intro_9994017 = "Aurorians Atiradores: +20% de ATQ ao matar um Eclipsita grande.",
  str_item_intro_9994018 = "O Aurorian com menos PV regenera 20% de PV após um Eclipsita grande ser morto.",
  str_item_intro_9994019 = "Aplica Lentidão nos monstros pequenos.",
  str_item_intro_9994020 = "-20% HP inicial para todos os monstros pequenos.",
  str_item_intro_9994021 = "-10% de ATQ nos monstros pequenos.",
  str_item_intro_9994022 = "-1 de recarga em qualquer Habil. Ativa incompleta de Aur. Conversores no início de uma luta.",
  str_item_intro_9994023 = "Flutua ao redor de um Aurorian e causa dano de Fogo quando o capitão ataca.",
  str_item_intro_9994024 = "Flutua ao redor de um Aurorian e causa dano de Água quando o capitão ataca.",
  str_item_intro_9994025 = "Flutua ao redor de um Aurorian e causa dano de Floresta quando o capitão ataca.",
  str_item_intro_9994026 = "Flutua ao redor de um Aurorian e causa dano de Trovão quando o capitão ataca.",
  str_item_intro_9995001 = "Retorna um Aurorian à vida com 50% de PV após morto (apenas para o primeiro Aurorian que receber dano letal em batalha)",
  str_item_intro_9995002 = "O dano de um único ataque causado a um Auroriano Conversor usando a relíquia nunca pode exceder 20% do HP máximo.",
  str_item_intro_9995003 = "Aurorians de Suporte convertem Cura em excesso em um Escudo, por uma rodada, em um nível.",
  str_item_intro_9995004 = "50% de chance de liberar uma onda de choque que atordoa os inimigos por uma rodada em cada batalha.",
  str_item_intro_9995005 = "Os ataques normais dos Sniper Aurorians e o dano Chain Combo removem imediatamente os escudos Eclipsite.",
  str_item_intro_9995006 = "4 de 8 casas adjacentes aleatórias tornam-se cromáticas no início da partida.",
  str_item_intro_9995007 = "Restaura um Luminômetro MS adicional no início da batalha.",
  str_item_intro_9995008 = "Quando uma partida começa, 10 peças aleatórias 2 × 2 são atingidas por um raio que causa dano estático às unidades dentro do alcance. Aurorianos não são afetados.",
  str_item_intro_9995009 = "Deixa uma bomba no início de seu movimento que detona após suas ações e de seus aliados.",
  str_item_intro_9995010 = "Combos de ataques normais em múltiplos de 5 causam um dano de explosão.",
  str_item_intro_9995011 = "Derrota Eclipsitas com menos de 7% de PV.",
  str_item_intro_9995012 = "Gera uma imagem do Aurorian Detonador soltando habilidades no ponto inicial, enquanto solta um Combo.",
  str_item_intro_9995013 = "Gaste Dados do Destino e ganhe uma Relíquia do Território Secreto aleatória.",
  str_item_intro_9995014 = "Concede 40% de chance para um Sniper Aurorian liberar um Chain Combo adicional.",
  str_item_intro_9995015 = "-1 recarga para um Aurorian Conversor aleatório, quando um Aurorian usa uma Habil. Ativa.",
  str_item_intro_9995016 = "Ataques normais de Aurorians Atiradores aplicam Lentidão e -1 de Mov. em Eclipsitas.",
  str_item_intro_9995017 = "Aplica Ferido e causa 3% de dano por casa movida a todos os Eclipsitas, quando a partida começa.",
  str_item_intro_9995018 = "Ataques normais de Aurorians de Suporte aplicam Ofuscado em Eclipsitas e 30% de chance de erro ao atacar.",
  str_item_rpintro_9993001 = "Vela com um brilho quente que pode curar Aurorians feridos.",
  str_item_rpintro_9993002 = "Tinta antiga capaz de absorver Lúmina.",
  str_item_rpintro_9993003 = "Auxiliar de poção de recuperação que ajuda a curar feridos.",
  str_item_rpintro_9993004 = "Aparentemente escrito por estudiosos antigos, ele detalha as nuances do contraefeito elemental e fornece dicas estratégicas efetivas.",
  str_item_rpintro_9993005 = "Insígnia antiga com um ajuste para guardar Lumina em um nível micro, aumentando a destreza em combate.",
  str_item_rpintro_9993006 = "Relíquia de uma era antiga, possivelmente amaldiçoada. Usuário torna-se letal com toxinas.",
  str_item_rpintro_9993007 = "Talismã de uma era antiga, capaz de guardar Lúmina em um nível micro, causando grande dano a inimigos.",
  str_item_rpintro_9993008 = "Uma lâmina curta afiada, feita de uma superliga antiga.",
  str_item_rpintro_9993009 = "Armadura de couro infundida com Lúmina. Leve e durável, suficiente para aumentar a resistência contra ataques.",
