  str_item_rpintro_9993029 = "Joia amarela inescrutável. Aurorians de Trovão terão um aumento de poder com ela.",
  str_item_rpintro_9993030 = "Joia amarela inescrutável. Aurorians de Trovão terão um aumento de poder com ela.",
  str_item_rpintro_9993031 = "Joia amarela inescrutável. Aurorians de Trovão terão um aumento de poder com ela.",
  str_item_rpintro_9993032 = "Joia amarela inescrutável. Aurorians de Trovão terão um aumento de poder com ela.",
  str_item_rpintro_9993033 = "Joia amarela inescrutável. Aurorians de Trovão terão um aumento de poder com ela.",
  str_item_rpintro_9993034 = "Uma estatueta perdida de uma era antiga feita de materiais de alta qualidade. Resistente, leve e abençoa seu portador.",
  str_item_rpintro_9993035 = "Arma antiga feita de materiais de alta qualidade e infundida com Lúmina. Deixa qualquer portador formidável.",
  str_item_rpintro_9993036 = "Escudo antiga de uma velha era, forma oval e supostamente infundido com o poder do sol para defletir todos os ataques letais.",
  str_item_rpintro_9994001 = "Lâmina imensa de grosseria palpável. Provavelmente usada em duelos até a morte em tempos antigos. Haverá sangue quando for usada.",
  str_item_rpintro_9994002 = "Máscara usada por doutores antigamente, um símbolo de maldição nos tempos de guerra.",
  str_item_rpintro_9994003 = "Espada antiga famosa. Seu portador sente um poder divino.",
  str_item_rpintro_9994004 = "Suposto item amaldiçoado feito por um guerreiro para causar a perdição de seus inimigos.",
  str_item_rpintro_9994005 = "Uma pintura antiga feita por um pintor anônimo que mostra a atrocidade da praga. O artista também morreu na pandemia. Ela possui um poder terrível...",
  str_item_rpintro_9994006 = "Espada antiga famosa brandida por um rebelde famoso. Seu último desejo concedeu poder mágico a ela.",
  str_item_rpintro_9994007 = "Armadura antiga gravada com a palavra \"Vingança\". Seu portador pode sentir a fúria eterna oculta na armadura.",
  str_item_rpintro_9994008 = "Estátua de uma deusa perfeitamente preservada que concede um poder curativo para os que creem na Luz.",
  str_item_rpintro_9994009 = "Carregue e será protegido pela Deusa da Vitória, você vencerá todas as suas batalhas.",
  str_item_rpintro_9994010 = "A adaga, supostamente originária de uma antiga guerra civil, emite uma aura sinistra e deve derramar sangue quando sacada.",
  str_item_rpintro_9994011 = "Tecnologia antiga. Guarda muito mais Lúmina do que aparenta seu pequeno tamanho.",
  str_item_rpintro_9994012 = "Saco de dormir abandonado. Ajuda a recuperar as forças.",
  str_item_rpintro_9994013 = "Arma de fogo abençoada pelo poder solar. Taxa de tiro baixa, mas forte o suficiente contra inimigos formidáveis.",
  str_item_rpintro_9994014 = "Teve muitos donos no passado, mas esses donos nunca duraram muito...",
  str_item_rpintro_9994015 = "Arma de longo alcance que atira um raio paralisante. Alcance limitado, não muito poderosa, usada para pegar bandidos.",
  str_item_rpintro_9994016 = "Relíquia radiante de guerreiros antigos, gravada com glifos abençoados e particularmente efetiva contra inimigos poderosos. (Efeitos dobrados ao possuir as três Relíquias Radiantes).",
  str_item_rpintro_9994017 = "Relíquia radiante de guerreiros antigos, gravada com glifos abençoados e particularmente efetiva contra inimigos poderosos. (Efeitos dobrados ao possuir as três Relíquias Radiantes).",
  str_item_rpintro_9994018 = "Relíquia radiante de guerreiros antigos, gravada com glifos abençoados e particularmente efetiva contra inimigos poderosos. (Efeitos dobrados ao possuir as três Relíquias Radiantes).",
  str_item_rpintro_9994019 = "Arma clássica antiga, gravada com glifos abençoados e particularmente efetiva contra inimigos poderosos. (Efeitos dobrados ao possuir as três Relíquias Lunaprata).",
  str_item_rpintro_9994020 = "Arma clássica antiga, gravada com glifos abençoados e particularmente efetiva contra inimigos poderosos. (Efeitos dobrados ao possuir as três Relíquias Lunaprata).",
  str_item_rpintro_9994021 = "Arma clássica antiga, gravada com glifos abençoados e particularmente efetiva contra inimigos poderosos. (Efeitos dobrados ao possuir as três Relíquias Lunaprata).",
  str_item_rpintro_9994022 = "Moeda antiga misteriosa que ocasionalmente aumenta a velocidade de seu Aurorian, concedendo mais agilidade.",
  str_item_rpintro_9994023 = "Aparentemente uma miniatura da Colossos de velhos tempos, que ajuda seu dono em batalha. Aurorians com uma coleção de flutuadores dos quatro elementos, liberam um ataque poderoso após um Combo.",
  str_item_rpintro_9994024 = "Aparentemente uma miniatura da Colossos de velhos tempos, que ajuda seu dono em batalha. Aurorians com uma coleção de flutuadores dos quatro elementos, liberam um ataque poderoso após um Combo.",
  str_item_rpintro_9994025 = "Aparentemente uma miniatura da Colossos de velhos tempos, que ajuda seu dono em batalha. Aurorians com uma coleção de flutuadores dos quatro elementos, liberam um ataque poderoso após um Combo.",
  str_item_rpintro_9994026 = "Aparentemente uma miniatura da Colossos de velhos tempos, que ajuda seu dono em batalha. Aurorians com uma coleção de flutuadores dos quatro elementos, liberam um ataque poderoso após um Combo.",
  str_item_rpintro_9995001 = "Artesanato com um vínculo misterioso à terra. Ressuscita o portador no momento que seu coração para.",
  str_item_rpintro_9995002 = "Armadura poderosa abençoada pelo sol para que seu portador suporte batalhas cansativas.",
  str_item_rpintro_9995003 = "Dispositivo desconhecido de velhos tempos que sente e converte Lúmina extra em um campo de força protetor para o portador.",
  str_item_rpintro_9995004 = "Cristal bruto com uma superfície rachada que indica Lúmina em excesso no seu interior. Um leve toque pode liberar Lúmina suficiente para atordoar inimigos em batalha.",
  str_item_rpintro_9995005 = "Arma poderosa dos velhos tempos. Ninguém sabe do que é feita, apenas que é afiada demais para alguma armadura resistir.",
  str_item_rpintro_9995006 = "Uma joia que brilha com todas as cores, esplêndida e dinâmica.",
  str_item_rpintro_9995007 = "Dispositivo para guardar e reabastecer Lúmina.",
  str_item_rpintro_9995008 = "Lâmina famosa dos velhos tempos, encantada com o poder do trovão. Sua ira explosiva fica aparente ao ser sacada.",
  str_item_rpintro_9995009 = "Item antigo criado especificamente para lidar com perseguidores. Deixa um rastro de Lúmina que detona posteriormente para matar os perseguidores.",
  str_item_rpintro_9995010 = "Criação da era antiga que parece muito bonita, mas carrega um poder aterrorizante, derrubando inimigos como flores caindo com explosões.",
  str_item_rpintro_9995011 = "Pode sentir a força vital de um inimigo e finalizar aqueles que estão perto da morte, ao estar próxima.",
  str_item_rpintro_9995012 = "Dispositivo poderoso dos velhos tempos que gera ilusões para confundir inimigos.",
  str_item_rpintro_9995013 = "Relíquia antiga que permite que um veja o destino de todos... Ou pode ser apenas uma alucinação.",
  str_item_rpintro_9995014 = "Orquídeas vermelhas raras, desenvolvidas especialmente nos velhos tempos. Elas aparecem, florescem e secam em pares. Parecem formar um laço com o portador e auxiliam em combate.",
  str_item_rpintro_9995015 = "Item antigo que cria laços misteriosos entre dois combatentes.",
  str_item_rpintro_9995016 = "Produto de uma guerra antiga. Supostamente induz à velhice e passos cambaleantes.",
  str_item_rpintro_9995017 = "Supostamente um item misterioso de uma guerra apocalíptica. Carrega uma poderosa maldição que é forte o suficiente para ferir seriamente oponentes.",
  str_item_rpintro_9995018 = "As lentes brilham na batalha, cegando o oponente enquanto protegem o portador. Equipamento auxiliar.",
