  str_item_1602381 = "Mithra",
  str_item_intro_1600011 = "Porta-voz de Northland. Ela carrega um espelho gigante refletindo sua aparência extraordinária, e esconde muitos segredos...",
  str_item_intro_1600021 = "Uma comandante firme, séria e determinada da Federação Illumina. Ela obteve muitas vitórias com sua espada longa em mãos.",
  str_item_intro_1600031 = "Serviu como um mordomo para um nobre de Cidade Alta, até que foi banido para Baixa Lumópolis por ofender outro nobre. Porém, de acordo com alguns, é só um disfarce para sua missão secreta...",
  str_item_intro_1600041 = "Um par de animais excêntricos composto de dois andarilhos. Agora trabalham como mercenários conhecidos por sua destreza em combate e senso de humor.",
  str_item_intro_1600051 = "Uma garota que vaga por Umbraton com uma risada maluca. Ela adora disputar jogos letais com outras pessoas, nenhuma surpresa que ela tenha um amplo espaço.",
  str_item_intro_1600061 = "Segunda filha do Senhor de Lumópolis. Independente desde nova, ela cresceu para ser a Capitã dos Guardiões por seu talento e esforço.",
  str_item_intro_1400071 = "Garota assassina da Rediesel Wrench. Trabalha sozinha e é especialista em missões difíceis.",
  str_item_intro_1400081 = "Um técnico de Rediesel Wrench, inventor do projetor de raio solar, com modo de combate único.",
  str_item_intro_1500091 = "Um jovem cativante da True Order. Ele exala um ar de conhecimento com seu sorriso cativante e gosta de falar sobre suas ideias acadêmicas.",
  str_item_intro_1600101 = "Garota animada de Northland que deseja viajar o mundo e ver tudo através de óculos rosa.",
  str_item_intro_1600111 = "Uma Comandante da Legião da Federação Illumina com Poder de Dragão. Apesar de parecer distante e isolada, ela é uma pessoa na qual você pode contar.",
  str_item_intro_1500121 = "Garota valente da Federação Illumina que luta para manter a justiça com ideais nobres.",
  str_item_intro_1500131 = "Uma moça de Northland com uma magia de gelo poderosa que pode cobrir uma região.",
  str_item_intro_1600141 = "Senhor de Lumópolis, mantém a lei e a ordem na cidade incansavelmente, sem um momento de complacência.",
  str_item_intro_1400171 = "Uma garota pequena e capitã da Rediesel Wrench, ágil e com reflexos rápidos. Poucos inimigos conseguem pegá-la.",
  str_item_intro_1500181 = "Roqueira popular da Rediesel Wrench. Consegue inspirar tropas e liderá-las em investidas.",
  str_item_intro_1600191 = "Uma mulher madura com um charme letal e um membro da True Order com conhecimento proibido. Adora defender uma certa verdade...",
  str_item_intro_1500201 = "Northwind",
  str_item_intro_1500211 = "Seu vizinho da Federação Illumina. Mestre em ciências naturais, proficiente em jardinagem e gosta de punir inimigos com as forças da natureza.",
  str_item_intro_1300221 = "Um jovem rebelde selvagem com um chapéu de coelho. Obcecado por diesel e violência, ele é um dos bandidos da Rediesel Wrench.",
  str_item_intro_1600231 = "Uma garota antissocial, confia em seu clarinete e sua habilidade especial de controlar criaturas aquáticas para achar seu lugar na confusa Umbraton.",
  str_item_intro_1500241 = "Uma dupla de Illumina. Benny é impetuosa e descuidada, Kuro é calma e serena. Apesar de suas diferenças, elas se dão muito bem e estão entre os maiores guerreiros de Illumina.",
  str_item_intro_1600251 = "Oficial de logística da Federação Illumina, proprietário e amigo de Other End, o trem, na vida ou na batalha.",
  str_item_intro_1600261 = "Um dos Quatro Anjos nos Cavaleiros Lumo. Ela é uma pessimista crônica, o que é um curioso contraste com sua aparência arrasadora...",
  str_item_intro_1600271 = "Uma cavaleira Lumópolis e um dos famosos Quatro Anjos. Ela está sempre pronta e raramente sorri. Foi transformada pela Illumina após ser gravemente ferida em batalha, o que resultou na perda de parte das suas emoções.",
  str_item_intro_1600281 = "Um dos Quatro Anjos nos Cavaleiros Lumo. Ela possui um poder único de cura e um otimismo contagiante.",
  str_item_intro_1600291 = "Um dos Quatro Anjos nos Cavaleiros Lumo. Ela é quieta, serena e calma a ponto de nada parecer incomodá-la.",
  str_item_intro_1600301 = "O resoluto líder da Rediesel Wrench. É extremamente próximo de seus companheiros e o maior protetor de sua irmãzinha. Seu principal objetivo é garantir a sobrevivência da gangue.",
  str_item_intro_1500311 = "Schumann",
  str_item_intro_1400321 = "Uma Integrante da Equipe da Corte de Justiça Lumo e um anjo de uma asa só. Ela é sensível e orgulhosa. Apesar de sua idade, Angel já vivenciou a guerra.",
  str_item_intro_1500331 = "Ainda muito nova mas experiente para sua idade. Trabalhadora e entusiasmada, ela é um talento em ascensão muito valorizada pela Federação Illumina.",
  str_item_intro_1500341 = "Soneto",
  str_item_intro_1400351 = "Um mensageiro viciado em trabalho que não consegue dormir enquanto não terminar o serviço.",
  str_item_intro_1500361 = "Lobo solitário de Umbraton. Um rebelde com um grande desprezo pela ordem de Lumópolis e inexplicavelmente hostil aos nobres.",
  str_item_intro_1600381 = "Uma pilota de um robô gigante e a Oficial de Tecnologia da Federação Illumina. Dizem que ela é genial e aposentada do exército.",
  str_item_intro_1400401 = "Uma garotinha da Rediesel Wrench, fascinada por explosões, que fica estranhamente animada quando algo explode.",
  str_item_intro_1400411 = "Uma guia para recém-chegados em Lumópolis. Ela continua calma em catástrofes, indicando um passado extraordinário.",
  str_item_intro_1400441 = "Rigorosa e estrita, como Chefe de Gabinete da Federação Illumina, ela é capaz de planejar e organizar qualquer coisa nos mínimos detalhes.",
  str_item_intro_1300461 = "Quatro crianças que compõem a Equipe de Transmissão de Lumópolis. São membros do Coro da Academia, mas seu maior prazer é caçoar cruelmente das outras pessoas, em vez de serem as crianças inocentes que deveriam ser...",
  str_item_intro_1300471 = "Uma pesquisadora genial da Federação Illumina. Sua fome de conhecimento e... uma certa Comandante da Legião exigem toda sua atenção.",
  str_item_intro_1400481 = "Líder dos Pardais desde nova, ela comanda Umbraton com sua determinação inigualável e armas diabólicas e traiçoeiras.",
  str_item_intro_1300491 = "Um guerreiro alto e forte que costuma caminhar por Umbraton usando sua armadura completa e seu espadão. Ele nunca tira o capacete, um homem de poucas palavras que prefere força bruta a diálogos.",
  str_item_intro_1200501 = "Um tubarão assustador, mesmo quando sorri! O protetor de um pequeno assentamento. Apesar da sua aparência feroz e temível, ele é muito gentil.",
  str_item_intro_1300511 = "Um crocodilo granadeiro melancólico e um pássaro atirador barulhento compõem essa dupla mercenária de confiança da Rediesel Wrench.",
  str_item_intro_1300521 = "Uma mensageira fornecendo serviços postais para a Federação Illumina, uma completa preguiçosa sem orgulho profissional. Ela fará qualquer coisa para evitar o trabalho...",
  str_item_intro_1300531 = "Um comerciante da Rediesel Wrench. Um típico mercador inescrupuloso, ele nunca deixa uma oportunidade de lucro escapar.",
  str_item_intro_1300741 = "Um baixo oficial da Legião de Illumina. Ele é antissocial e não se dá bem com os outros, supostamente uma característica de sua misteriosa linhagem...",
  str_item_intro_1300581 = "A determinada e zelosa Nova Cavaleira de Lumópolis. Às vezes, sente-se sobrecarregada por carregar tamanha responsabilidade ainda tão jovem.",
  str_item_intro_1400161 = "Uma atiradora habilidosa da Rediesel Wrench que usa seu supercanhão para eliminar seus oponentes.",
  str_item_intro_1400541 = "Capitã dos Recrutas da Vigia Noturna Lumo. Tranquila, focada e admirada por tratar tudo com seriedade.",
  str_item_intro_1400611 = "Uma pesquisadora otimista e alegre da Federação Illumina, com a habilidade especial de absorver as emoções negativas dos outros e curar suas feridas internas.",
  str_item_intro_1400731 = "Novos membros da Guilda Istvan de Umbraton. São sempre hiperativos, então cuidado!",
  str_item_intro_1500421 = "Comandante da Legião da Federação Illumina. Alguém que anseia pela guerra e não suporta a monotonia da paz. Busca a vitória a qualquer custo.",
  str_item_intro_1500761 = "Um cavalheiro cortês, educado e calmo, mas um mentiroso comum. Ele também é um vigarista infame em Umbraton.",
  str_item_intro_1500781 = "Membro dos Pardais de Umbraton. Reservada e socialmente ansiosa, ela e Dayna confiam uma na outra para sobreviver em Umbraton.",
  str_item_intro_1600771 = "A soberana de Northland, com incontáveis anos de sabedoria e experiência. Ela é capaz de lidar com qualquer adversidade.",
  str_item_intro_1300591 = "Integrante da União Mensageira, responsável pelas correspondências da True Order. Apesar das suas falhas, todos a aceitam por sua honestidade.",
  str_item_intro_1300801 = "Uma pesquisadora da Federação Illumina. Ela é um gênio, apaixonada por máquinas e modelos e com dificuldades de socializar. Mas pode falar pelos cotovelos quando o assunto é do seu interesse.",
  str_item_intro_1300821 = "Uma Fada inocente e amável de Pinha de Northland que desconhece o mundo exterior. Possui um par de Chifres Preciosos que foram cuidadosamente protegidos desde sua infância.",
  str_item_intro_1400451 = "Um instrutor da True Order devoto à Victoria. Ele é calado e acredita fielmente nos ideais da Ordem. Seu objetivo de vida é espalhar os ensinamentos da True Order.",
  str_item_intro_1400571 = "A Chefe de Inteligência da Federação Illumina. Ela normalmente é gentil, acessível e um pouco preguiçosa, mas sua outra personalidade é bem rebelde.",
  str_item_intro_1400681 = "Uma integrante da União Mensageira, responsável pela área da Rediesel Wrench. Confiante, fofa, valente e propensa a aceitar desafios, ela gosta de fazer algazarra enquanto entrega cartas e é uma encrenqueirinha adorável.",
  str_item_intro_1400791 = "Uma Coletora de Impostos Lumo racional, justa e independente. Ela tem o hábito de converter o valor de tudo em ouro para comparações.",
  str_item_intro_1400811 = "Um membro dos Parafusos Soltos da Rediesel Wrench. Confiante, intenso e ingênuo, alguém incapaz de conspirar. Ele deseja ser o melhor em tudo.",
  str_item_intro_1400831 = "Uma integrante da comitiva do Instituto de Pesquisas Científicas da Federação Illumina. Apesar de falar como uma donzela mecânica, ela é na verdade uma Replicante de um certo ser poderoso.",
  str_item_intro_1601231 = "Essa xerife de Illumina costuma chorar de medo até mesmo do menor problema, mas ela permanece otimista e trabalha duro em nome da justiça.",
  str_item_intro_1601201 = "Uma garota nobre nascida em uma família rica, ela é inteligente e adora ler sozinha em seu quarto. Seu único amigo é uma armadura gigante chamada Pompey, que foi ativada por ela mesma.",
  str_item_intro_1500151 = "Um comerciante de arte de Umbraton, Hachi sabe tudo sobre belas obras de arte, enquanto Gin é um pintor de habilidade incomparável. Eles compartilham um vínculo inquebrável e trabalham juntos como mercenários.",
  str_item_intro_1501321 = "Uma residente do Vale da Geada de Pinha de Northland. Adora qualquer coisa que tenha mel. A vinha florida em seu corpo pode ser bonita, mas, na verdade, possui habilidades especiais.",
  str_item_intro_1601311 = "Um habitante de Northland que é próximo de Bethlehem. Compassivo e conhecedor de história. Ele acredita que Northland é o último paraíso para os Aurorians e deseja protegê-lo com seu poder.",
  str_item_intro_1601331 = "Tohru é um dragão muito cruel que lutou contra deuses um contra um e quase morreu. Após se apaixonar por Kobayashi em um mundo alienígena, Tohru decidiu viver com ela como sua empregada.",
  str_item_intro_1601341 = "Um dragão como Tohru, como uma aparência e personalidade infantil. Expulsa de casa por causa dos trotes que ela fez, segue Tohru desde então.",
  str_item_intro_1501351 = "Um dragão lutando para resolver conflitos mortais. Antigamente chamada de Bruxa do Mar Sagrado. Honesta e trabalhadora, ela ama uma boa comida e não consegue resistir a doces.",
  str_item_intro_1501361 = "Antigamente era uma divindade responsável pelas culturas e civilizações antigas. Muito poderosa, mas também muito apática e relaxada.",
  str_item_intro_1401371 = "Colega de Tohru que protegeu uma caverna de tesouro em outro mundo. Ele é muito hostil e cínico porque viu muitas pessoas gananciosas.",
  str_item_intro_1601381 = "Um pesquisador da Federação Illumina. Ela é racional e muito eficiente no trabalho, mas preguiçosa e casual em particular. Fascinada pela tecnologia antiga, ela viaja o ano todo ao redor do mundo para investigar todos os tipos de ruínas.",
  str_item_intro_1501391 = "Ela nasceu em Lumopolis e foi membro do conselho estudantil da Dawn Academy. Ela segue Florine em todos os lugares e tem ideias fantásticas. Às vezes, ela surpreende as pessoas com o que diz.",
  str_item_intro_1601401 = "Nascida em Lumopolis, ela era a presidente do conselho estudantil na Dawn Academy. Com um coração caloroso por trás de sua aparência fria, ela cuida bem de seus amigos em sua jornada para se tornar um excelente cavaleiro.",
  str_item_intro_1601411 = "Nascida na Rediesel Wrench, Ruby sempre amou histórias de aventura enquanto crescia. Alegre e vivaz por natureza, ela partiu em sua própria aventura assim que adquiriu conhecimentos e habilidades suficientes.",
  str_item_intro_1501421 = "Um membro da Rediesel Wrench, ela é fortemente dependente de Ruby. Ela pode parecer má e amarga, mas por trás de sua língua afiada há um coração atencioso e terno.",
  str_item_intro_1601431 = "Uma sacerdotisa da Ilha das Nuvens que aprendeu e se preparou. Criada pelo general que governa a Ilha das Nuvens, ela espera ajudar as pessoas com sua força.",
  str_item_intro_1501441 = "Uma mulher alta de Cloud Island que já foi salva por Rinne. Ela afirma ser capaz de ver \"coisas\" e tem medo de estranhos.",
  str_item_intro_1601451 = "Nascida em Cloud Island, ela perdeu sua casa devido à guerra e mais tarde foi resgatada e ensinada Ninjutsu. Seu passado a fez parecer fria, mas no fundo, ela é extremamente leal a seus companheiros.",
  str_item_intro_1601461 = "Nascida em Cloud Island, ela estudou a \"Arte do Qi\" com a Lin Guild. Ela possui fortes habilidades de combate, tem uma personalidade viva e gosta de viajar enquanto luta contra a injustiça.",
  str_item_intro_1501471 = "Nascidos em Cloud Island, os gêmeos costumam ser vistos vendendo Kaniya Ramen em seu carrinho, e os negócios estão crescendo. Eles esperam ganhar dinheiro enquanto, ao mesmo tempo, exploram os limites da delícia.",
  str_item_intro_1201631 = "Uma criatura fascinante do norte que é apaixonada por jogos. Sempre que se depara com alguém novo, ele sempre pergunta: \"Estimado mestre, você aceita encomendas?\"",
  str_item_intro_1601481 = "Um membro de espírito livre da equipe de exploração da Rediesel Wrench que sempre trabalhou sozinho na investigação de todos os tipos de informações que podem beneficiar a Rediesel Wrench. Ela já foi considerada uma corredora lendária.",
  str_item_intro_1501491 = "O gerente de logística da Rediesel Wrench. Embora ele pareça desorganizado, ele é de fato muito atencioso e protetor com todos em Rediesel Wrench.",
  str_item_intro_1601501 = "Um membro da Verdadeira Ordem, quieto, mas muito capaz. Ela não parece ter seus próprios pensamentos ou qualquer ambição. O propósito de sua vida é receber e cumprir ordens.",
  str_item_intro_1601511 = "Um membro da Verdadeira Ordem, geralmente bastante apático, a menos que seja acionado. Ele acredita firmemente que foi enviado a este mundo para espalhar um certo conto infantil.",
  str_item_intro_1501521 = "Uma jovem obstinada e socialmente inepta que tenta desesperadamente agradar os adultos ao seu redor na Verdadeira Ordem. Ela anseia por atenção como resultado de ser emocionalmente negligenciada.",
  str_item_intro_1601551 = "Depois de usar o dispositivo \"Chord Link\", embora a aparência e as habilidades do Comandante da Legião da Federação Illumina tenham mudado, ele ainda continua sendo um belicista no coração.",
  str_item_intro_1601541 = "Capitão de Expedição da Illumina com uma personalidade gentil. Por um golpe do destino, ela resgatou o último descendente de Caelestite preso no subsolo, abrindo caminho para novas e emocionantes aventuras.",
  str_item_intro_1601531 = "O verdadeiro Grande Marechal da Federação Illumina. Ela não é apenas corajosa e habilidosa no campo de batalha, ela também é uma líder honesta e altamente capaz, respeitada por todos os Illumina.",
  str_item_intro_1601561 = "Nascida em uma família Lumo Noble em Umbraton, ela parece ser difícil de se conviver, mas na verdade é bastante fácil de abordar... Bem, mais ou menos.",
  str_item_intro_1501571 = "Nascida em Cloud Island, ela sofre muitos reveses durante sua infância. Depois de se mudar para Astra para uma vida melhor, ela de alguma forma assume uma dívida enorme. Tudo o que ela deseja é um emprego estável.",
  str_item_intro_1601581 = "Um jovem de outro mundo com um poder especial chamado Persona.\nEscondido atrás de uma máscara, ele é conhecido apenas por um codinome e emite uma aura especial.\nEm seu mundo, ele era o líder dos sensacionais Phantom Thieves of Hearts.",
  str_item_intro_1601591 = "Um membro dos Phantom Thieves de outro mundo.\nGênio da tática da gangue, ela planeja o curso de ação de seus companheiros.\nCapaz de usar o poder especial Persona.",
  str_item_intro_1501601 = "Um membro dos Phantom Thieves de outro mundo.\nDe disposição excêntrica, esse jovem muitas vezes parece distante e indiferente.\nCapaz de usar o poder especial Persona.",
  str_item_intro_1501611 = "Uma jovem do mesmo mundo que os Phantom Thieves.\nTrabalhando temporariamente com eles por vários motivos.\nCapaz de usar o poder especial Persona.",
  str_item_intro_1501621 = "Uma criatura misteriosa de outro mundo. Parece um gato, mas fala como um humano.\nEle guia os Phantom Thieves em várias ocasiões.\nCapaz de usar o poder especial Persona.",
  str_item_intro_1601641 = "Carleen de Schwartz. A caminho de Harbor City, seus poderes mudam, dando-lhe uma compreensão mais profunda da liderança.",
  str_item_intro_1501651 = "Um engenheiro genial da Illumina. Introvertida, tímida, mas ansiosa para se comunicar com as pessoas, seu sonho é criar um poderoso mecha dinâmico.",
  str_item_intro_1601661 = "Um pequeno extrozoologista que é obstinado e teimoso, mas inesperadamente adora chorar. Ela está trabalhando duro para se tornar uma extrozoóloga ainda maior que Vic.",
  str_item_intro_1601671 = "O mestre de cerimônias do The Illusionist & Old Bill's Circus, bem como um membro da True Order. Misterioso, assustador e taciturno, sua ambição é se tornar o maior mago.",
  str_item_intro_1501681 = "Uma jovem que foi forçada a deixar sua cidade natal por causa dos ataques do Eclipsite. Pura de coração e vivaz, ela assumiu como missão proteger a Esmeralda, e muitas vezes se apresenta como convidada no circo para aquecer a atmosfera.",
  str_item_intro_1501301 = "Um membro da família Troy de Lumopolis. Mas por que seu assento é tão baixo para alguém de tão alto nascimento? Talvez a resposta esteja em sua personalidade.",
  str_item_intro_1501711 = "Aparentemente distante, mas na verdade muito responsável. Juntou-se a Pollux para formar a dupla de mercenários apelidada de \"Raven's Blood\" para melhor defender as crianças que vivem na igreja.",
  str_item_intro_1601701 = "Imponente e competente, ela tem um passado que prefere deixar para trás. Agora um fiel guardião de uma igreja que abriga crianças sem-teto na Euforia oprimida.",
  str_item_intro_1401691 = "Uma jovem absurdamente poderosa vinda de Umbraton. Sob seu exterior frio e carismático bate um coração puro e determinado, e ela considera qualquer tarefa dada a ela como parte de seu treinamento para se tornar uma verdadeira espadachim.",
  str_item_intro_1601721 = "Uma garota fofa, alegre e otimista. Para perseguir seu sonho de trabalhar no cinema, ela se estabeleceu no Alleywood de Umbraton sozinha e encontrou trabalho em sua crescente indústria cinematográfica. Apesar de ter passado por inúmeras dificuldades, ela nunca pensou em desistir.",
  str_item_intro_1601731 = "O mordomo-chefe da família Andersen em Umbraton. Gracioso, cortês e perfeccionista ao extremo, ele jurou retribuir a bondade de seu mestre servindo-o com cada grama de sua força e lealdade.",
  str_item_intro_1601751 = "O Combat Cyborg conhecido como Axelia é afiliado à Federação Illumina. Apesar de sua reputação, sua condição física é preocupante em particular.",
  str_item_intro_1501761 = "Um médico de combate de Lumopolis que já foi salvo por um médico chamado John; depois disso, ela decidiu se tornar uma boa médica.",
  str_item_intro_1601771 = "Nascida em Umbraton, esta jovem e famosa idol é agraciada com fortuna, espalhando seu otimismo e positividade para todos que ela encontra.",
  str_item_intro_1601781 = "Um extrozoólogo que vive recluso na floresta. Embora muitas vezes enfureça as pessoas com suas palavras e ações e intimide seu discípulo Fia, ele é gentil com todos os animais maravilhosos.",
  str_item_intro_1501801 = "Embora atualmente seja apenas uma repórter estagiária de uma pequena agência jornalística, ela está entusiasmada em entrevistar qualquer pessoa que puder e está atenta às últimas fofocas. Seu objetivo é se tornar a jornalista mais famosa de Umbraton.",
  str_item_intro_1601811 = "Uma vez chefe geral do reino de Zhao em Longzhou, agora um andarilho. Não importa quando ou onde, ele não se preocupa com nada além de seus próprios objetivos pessoais.",
  str_item_intro_1601821 = "Capitão do Shadowind. Distante, decisivo, o que você vê é o que você consegue. Seu objetivo é construir o maior navio de longo alcance e abrir a rota de viagem mais segura.",
  str_item_intro_1501831 = "Um jovem médico que estudou com o grande médico Bucunzi. Pequeno em estatura, mas ambicioso, ele é um médico confiável com uma língua afiada. Dito isto, um elogio é suficiente para deixá-lo cheio de si.",
  str_item_intro_1601841 = "Um membro sênior da divisão Rediesel Wrench da Courier Union. Ela é descontraída e desorganizada, mas também uma observadora muito astuta.",
  str_item_intro_1501851 = "Embora ela seja apenas uma novata, ela também é uma das poucas pessoas conscienciosas e responsáveis no Courier Union. No entanto, sua adesão excessivamente rígida às regras do sindicato às vezes leva a erros.",
  str_item_intro_1601861 = "Uma garota nobre que herdou seu título e também é juíza do Tribunal de Justiça. Ela também tem uma constituição especial que a faz dormir o tempo todo.",
  str_item_intro_1601891 = "Um juiz honesto de Lumopolis que odeia todos os males e sempre trata os outros com igualdade. Ao mesmo tempo, ele tem um lado teimoso e distante.",
  str_item_intro_1501901 = "Um juiz extremamente talentoso do Lumo Hall of Justice que não tem muita ambição e só quer viver uma vida comum feliz e rica.",
  str_item_intro_1601911 = "Uma loba solitária de Umbraton de ascendência semi-humana, que muitas vezes acaba envolvida em mal-entendidos desnecessários devido à sua falta geral de tato.",
  str_item_intro_1501931 = "Embora nascida em uma família nobre, ela sempre trilhou seu próprio caminho e seguiu seu coração para se tornar uma juíza estagiária de Lumopolis.",
  str_item_intro_1601921 = "O capitão dos Ironthorn Knights, ele tem uma personalidade decisiva e é digno e amigável. Ele procura trazer a decadente Lumópolis de volta à vida.",
  str_item_intro_1601991 = "Ela nasceu em uma família de soldados Illumina e agora é uma oficial sênior de inteligência do Comitê. Muitos planos estão escondidos no fundo de seus olhos.",
  str_item_intro_1502001 = "Um oficial de inteligência calmo e confiável da Federação Illumina que ocasionalmente faz reclamações inesperadas. Ninguém sabe se essas reclamações são feitas intencionalmente ou não.",
  str_item_intro_1602011 = "Uma cavaleira de Lumopolis que vive uma vida isolada em Umbraton, ela é na verdade a raramente mencionada filha mais velha do Schwartz família - uma menina pura e gentil que anseia pelo reconhecimento de seu pai.",
  str_item_intro_1602021 = "No auge dele, Schwartz, empunhando uma espada e lutando contra os eclipsitas, não era apenas o governante recém-ascendido de Lumopolis, ele também era um valente guerreiro que lutou na linha de frente para conter os inimigos da civilização.",
  str_item_intro_1502031 = "O enviado do norte Jakine é entusiasta e apaixonada por natureza, mas sua adivinhação inábil e personalidade descuidada muitas vezes a colocam em problemas imprevisíveis.",
  str_item_intro_1602041 = "EveTodos dizem que ela se parece com a falecida esposa do Senhor da Cidade, mas ela também não parece ser ela. Joshua espera ir a ainda mais lugares no mundo com seus ideais...",
  str_item_intro_1502051 = "Blanc, que se aposentou como capitã da Guarda Noturna há muitos anos, vestiu seu uniforme de combate novamente. A Sra. Rot voltou!",
  str_item_intro_1602061 = "Nascida em uma família abastada em Umbraton, ela poderia ter levado uma vida despreocupada no conforto de sua casa. No entanto, escolheu aventurar-se por conta própria, movida por uma determinação inabalável de tornar seus sonhos realidade.",
  str_item_intro_1602071 = "O gerente do Denuo Valley Resort, que vive pelo lema de \"viver o momento\". Ele pode parecer frívolo por fora, mas surpreendentemente, ele é incrivelmente confiável quando se trata de negócios.",
  str_item_intro_1502081 = "Ela não é apenas a navegadora do Lepidoz, mas também a estrategista por trás da Rediesel Wrench. No entanto, aos olhos de todos, ela parece mais uma animada mascote do que qualquer outra coisa...",
  str_item_intro_1400861 = "Uma integrante da Academia Matinal de Lumópolis e Mestre de Cerimônias. Positiva e ousada, mas gentil e delicada, ela enfrenta tudo com calma e um sorriso no rosto.",
  str_item_intro_1400911 = "Uma musicista gentil e amigável de Lumópolis que se perde facilmente em suas lembranças tristes. Sua família morreu na guerra, e por isso ela tem dificuldades em esquecer seu sofrimento.",
  str_item_intro_1500701 = "A rebelde de Umbraton que possui o Poder de Dragão. Arrogante e orgulhosa, está sempre mal-humorada. Ela sente que o destino da sua família está em suas mãos.",
  str_item_intro_1500751 = "Uma integrante da Equipe Técnica da Rediesel Wrench altamente confiante em suas tecnologias de comunicação. Gosta de gritar e reclamar de todos no Canal de Comunicação, mas se afoba quando há problemas.",
  str_item_intro_1500841 = "O Líder do Submundo de Umbraton. Decisivo, livre e leal àqueles ao seu redor. Ele suportou inúmeras provações e adversidades, o que lhe rendeu seu atual prestígio e status.",
  str_item_intro_1500881 = "Uma integrante da Rediesel Wrench encarregada de missões de reconhecimento. Tímida e desajeitada, ela não consegue controlar seu poder nas batalhas. Maggie também se incomoda bastante com isso.",
  str_item_intro_1500901 = "A famosa cantora da Rediesel Wrench, Barbara, aparenta ser gentil e agradável, mas revela um lado irritadiço quando encontra um fã desagradável.",
  str_item_intro_1500921 = "Integrante da True Order que é honesta e inflexível. Possui uma mente focada em um objetivo, portanto ela concentra-se em alcançar uma meta assim que a identifica. Possui um gosto único e frequentemente discute com outras pessoas.",
  str_item_intro_1600601 = "No passado uma caçadora de recompensas, Jona é parte de Rediesel Wrench e uma atiradora de elite. Ela é desregrada e não leva as coisas muito a sério, mas não demonstra piedade com seus inimigos. Ela nunca foi vista sem suas algemas.",
  str_item_intro_1600641 = "Uma Comandante da Legião de Guarda da Federação Illumina que cobiça a liderança da Federação. Ela é enérgica, trabalha incansavelmente para obter mais poder e tem um forte desejo de monopolizar tudo.",
  str_item_intro_1600891 = "A Juíza Principal da Corte de Justiça Lumo. Ela é gentil, bondosa, firme e um exemplo de dedicação. Em seu âmago, esconde um lado paranoico.",
  str_item_intro_1601031 = "Uma interrogadora da True Order e seguidora fervorosa de Victoria, com pupilas suprimidas devido ao seu \"Poder da Perdição.\"",
  str_item_intro_1500871 = "Uma das nobres militantes de Lumópolis, conta com grande prestígio e poder. Tradicionalista e responsável, ela pode ser um pouco arrogante, mas está melhorando gradualmente.",
  str_item_intro_1401011 = "Uma oficial de Illumina responsável pelas comunicações. Trata o trabalho com zelo e respeito, apesar de suas ocasionais brincadeiras.",
  str_item_intro_1401021 = "Uma aliada independente dos Pardais de Umbraton. Conhecida por seus pirulitos e pela eletricidade que emana de suas mãos.",
  str_item_intro_1500991 = "Uma mercenária errante de Umbraton. Nasceu com uma maldição que a tornou anêmica e depende de sua espada mágica para sobreviver.",
  str_item_intro_1501001 = "Um membro da True Order. Nascida em uma família nobre antiga, ainda jovem foi escolhida para proteger a catacumba secreta. Bem-educada e intelectual, mas fria.",
  str_item_intro_1600931 = "Uma pesquisadora de Illumina encarregada da ciência da vida. Aparentemente preguiçosa, mostra sua compostura em momentos importantes.",
  str_item_intro_1500981 = "Uma maldição removeu suas emoções, mas ela parece confiar na primeira pessoa que encontra no dia. Atualmente, vive em reclusão em Umbraton e trabalha como assassina para Istvan.",
  str_item_intro_1400621 = "Um protetor das florestas de Northland. Bonito e de comportamento indiferente, mas com um coração de ouro que anseia pela amizade. Relativamente jovem, possui uma aparência infantil.",
  str_item_intro_1400951 = "Nascida com um corpo de animal, ela é uma mercenária errante que reclama de tudo.",
  str_item_intro_1300941 = "Uma patrulheira inocente, gentil e ingênua de Northland. Ela está acostumada a patrulhar no frio e traz primavera e esperança para o povo.",
  str_item_intro_1600961 = "Nascida em Illumina, ela partiu para Umbraton em busca do seu avô. É um pouco distraída e fácil de enganar.",
  str_item_intro_1500971 = "Um assassino de Umbraton que realiza tarefas \"especiais\" para Istvan. No passado, foi um cirurgião habilidoso.",
  str_item_intro_1500561 = "Um caçador de Eclipsitas solitário que vaga por Astra com uma mente limpa. Ele carrega um rifle e um caderno aonde quer que vá, pronto para abater Eclipsitas e anotar suas façanhas.",
  str_item_intro_1701071 = "Antigo herói banido. Transformado pelo ódio que guarda dos Eclipsitas. Já foi um selvagem feroz, mas recuperou a calma e sua personalidade positiva.",
  str_item_intro_1701081 = "Antiga heroína banida. Transformada, ganhou um imenso poder, mas causou uma catástrofe por não conseguir controlá-lo. Até hoje ela carrega essa culpa.",
  str_item_intro_1701091 = "Antiga heroína banida. Perdeu a maior parte de suas emoções após ser transformada. Supostamente abandonada pelo estado que servia ao completar uma missão.",
  str_item_intro_1701101 = "Antiga heroína banida. Luta contra Eclipsitas desde a infância. Fala de forma obsessiva. Foi transformada, mas manteve sua inocência.",
  str_item_intro_1501041 = "Forças sombrias cegaram seus dois olhos. Distante e reservada aparentemente, ela fala francamente após conhecer alguém.",
  str_item_intro_1601051 = "A irmã mais nova de Sinsa. Quando criança caiu sob a influência dos Eclipisitas e perdeu o controle. Ela recuperou sua inocência após curada.",
  str_item_intro_1500711 = "O proprietário da Trabalhos Estranhos que chegou à Umbraton do Oriente. Aliado de Istvan, ele é um recluso contraditório que faz as coisas com eficiência.",
  str_item_intro_1400671 = "Uma jovem garota semi-humana de Northland com cabelos negros e brancos. Ingênua, brincalhona e um pouco teimosa, possui grande curiosidade pelo que está ao seu redor. Atualmente, viaja com duas bonecas mágicas.",
  str_item_intro_1601111 = "Membro da True Order que pode controlar o poderoso Domínio do Cristal para armar para os inimigos. Porém, seus cristais sanguíneos geram um prejuízo em sua mente, deixando-a distante, silenciosa e frequentemente pessimista.",
  str_item_intro_1601121 = "Agente livre que vive em Umbraton e possui grande poder sobre o fogo. Selvagem e direta, ela gosta de buscar coisas novas e emocionantes.",
  str_item_intro_1501131 = "Música e membro da True Order, apesar da aparência adorável e delicada, fará de tudo para conquistar seu objetivo de encontrar o movimento supremo. Ela tem grande confiança em sua compreensão de música e despreza as práticas musicais de Lumópolis.",
  str_item_intro_1501141 = "Apesar de não parecer nada além de uma caçadora de recompensas, ela é membro da True Order. Elegante e sempre de bom humor, adora beber drinques e atualmente tenta criar uma rede de inteligência para a True Order enquanto busca o paradeiro de uma certa pessoa.",
  str_item_intro_1601151 = "Membro da União Mensageira, especializado em atender a região de Lumópolis. Calma e elegante, ela tem o misterioso poder de se comunicar com animais e plantas, sendo seguida por diversos animais e inúmeros vaga-lumes por onde passa.",
  str_item_intro_1601161 = "Técnico bem-humorado da Rediesel Wrench que não sabe dizer não, um traço pessoal que sempre o coloca em vários tipos de situações incômodas. É mestre no reparo de vários tipos de maquinário, mas quer construir um robô próprio.",
  str_item_intro_1401271 = "Ela já morou no Deserto Rediesel e depois se juntou à True Order. Suas habilidades envolvem o controle de pedaços mágicos de papel na batalha. Embora pareça ser bastante tímida, sua firme crença na existência de almas chega a parecer quase fanática.",
  str_item_intro_1601191 = "Uma nova recruta de Illumina. Genial em combate, mas indiferente, impulsiva e uma comunicadora falha. Ela anseia por glória em batalha e se provar capaz.",
  str_item_intro_1601221 = "Uma mercenária franco-atiradora de Umbraton com habilidades excepcionais. Meticulosa e cuidadosa com dinheiro, ela é colecionadora de antiguidades e deseja abrir sua própria loja, após juntar dinheiro suficiente.",
  str_item_intro_1601171 = "Um veterano que já foi ativo na linha de defesa de Illumina, que agora se aposentou do campo de batalha e serve à federação como um oficial de logística. Ele pode ser um pouco áspero, mas seu exterior grosseiro esconde um coração nobre e sentimental. Um dos camaradas mais confiáveis que você poderia esperar. Dizem que ele caiu em depressão devido ao seu passado sangrento. Agora, ele emergiu da escuridão da derrota, ainda mais forte do que era antes.",
  str_item_intro_1601211 = "Membro da True Order, ela é rebelde, racional e não leva desaforos pra casa. Originalmente, ela era uma freira do Templo de Lumópolis, mas depois que uma trágica injustiça mudou sua vida, percebeu a hipocrisia que prevalecia em Lumópolis e foi embora. Ela tem se dedicado a expor as verdades escondidas da cidade desde então.",
  str_item_intro_1300651 = "Membro da União Mensageira responsável pelas entregas de Northland. Uma mensageira energética e um pouco desajeitada, com aparência e sotaque únicos que a fazem parecer fofa e inocente.",
  str_item_intro_1500551 = "Um juiz da Corte de Justiça Lumo, ele é bem puritano, pragmático e resoluto em sua convicção. Agora, em nome da justiça, está se aprofundando em casos anteriores para descobrir uma verdade oculta.",
  str_item_intro_1601261 = "A líder da Sede da Guilda de Umbraton e filha adotiva de Istvan, ela é seu braço direito de maior confiança. Com sua atitude séria e estóica, ela mostra uma atitude profissional em todos os momentos.",
  str_item_intro_1601291 = "Subcomandante de um esquadrão de mercenários de Umbraton, um homem de honra que sabe de tudo na cidade. Ele está trabalhando para expandir suas forças de mercenários.",
  str_item_intro_1602371 = "Dizem que ela é descendente do clã Mirage, ela tem dificuldade em reter memórias, mas permanece otimista e bondosa. Em gratidão por ter sido acolhida por Harbour City, ela se dedica a ajudar os outros.",
  str_item_intro_1602381 = "Mithra, nascida no clã Longinus, mantém um dever milenar de proteger os segredos das estrelas. Apesar de sua aparência tranquila e plumagem escura, ela esconde uma agudeza sob sua natureza reservada.",
  str_item_intro_1702361 = "Claymore era o braço direito do rei e o capitão dos Caçadores Silenciosos. Ele defende a justiça com uma vontade inabalável. Mesmo sem o favor da Lúmina, ele forja um futuro com o Poder das Estrelas.",
  str_item_get_discovery = "{0}",
