  str_item_get_cloudgardensitem19 = "Obter da recuperação de recurso",
  str_item_get_cloudgardensitem20 = "Mine em Cloud Gardens para obter",
  str_item_get_cloudgardensitem21 = "Desmonte a Árvore Única para obter",
  str_item_get_cloudgardensitem22 = "Obter dos feitos do Cloud Gardens",
  str_item_get_cloudgardensitem23 = "Recompensa do Livro de Eventos Especiais da Fase 8",
  str_item_get_cloudgardensitem24 = "Recompensa do Livro de Eventos Especiais da Fase 9",
  str_item_get_cloudgardensitem25 = "Obtenha em conversas secretas geradas aleatoriamente quando os Aurorianos estiverem vivendo de forma relativamente confortável em Cloud Gardens.",
  str_item_get_cloudgardensitem26 = "Obtenha em conversas secretas geradas aleatoriamente quando os Aurorianos estiverem vivendo muito confortavelmente em Cloud Gardens.",
  str_item_get_cloudgardensitem27 = "Obtenha em conversas secretas geradas aleatoriamente quando os Aurorianos estiverem vivendo confortavelmente em Cloud Gardens.",
  str_item_get_cloudgardensitem28 = "Obtido no evento Symphony: The Obelisk's Shackles.",
  str_item_get_cloudgardensitem29 = "Obtido no evento \"Árvores, Peixes e Vida Lenta\"",
  str_item_get_cloudgardensitem30 = "Obtido no evento Heist Under a Moonlit Night",
  str_item_get_cloudgardensitem31 = "Obtido após coletar um certo número de Wish Coins.",
  str_item_get_cloudgardensitem32 = "Feito na Hyacinth Tower após obter o projeto das recompensas do nível Cloud Gardens.",
  str_item_get_cloudgardensitem33 = "Feito na Hyacinth Tower depois de obter o projeto das recompensas da missão Cloud Gardens.",
