  str_item_get_cloudgardensitem38 = "Feito na Torre Hyacinth depois de obter o projeto em conversas secretas geradas aleatoriamente quando os Aurorianos estão vivendo relativamente confortavelmente nos Jardins das Nuvens.",
  str_item_get_cloudgardensitem39 = "Feito na Hyacinth Tower após obter o projeto em conversas secretas geradas aleatoriamente quando os Aurorianos estão vivendo muito confortavelmente em Cloud Gardens.",
