  str_item_5234040 = "\"Rediesel Foodfest\"",
  str_item_5234041 = "\"Na Casa Assombrada\"",
  str_item_5234042 = "\"Esplendor Ilumina!\"",
  str_item_5234031 = "Estátua da Besta Espinhosa",
  str_item_5234032 = "Estátua da Besta de Três Chifres",
  str_item_5241014 = "Balão de ar quente colorido",
  str_item_5232007 = "Assento Shell Flutuante",
  str_item_5234035 = "Monumento das Linhas",
  str_item_5222001 = "Cerca de arbustos baixos",
  str_item_5222002 = "Cerca alta para arbustos",
  str_item_intro_5212001 = "\"Agora que eu afundei este navio, você é o próximo a ir! Argh! Por que você está deslizando pelo meu tentáculo? Tudo bem, eu vou deixar você sair desta vez, já que você parece estar se divertindo muito! \"\nSupostamente, este slide foi modelado após o tentáculo de um monstro marinho. Emocionante, não é?",
  str_item_intro_5212002 = "Eu me pergunto quem moveu o mastro de um navio aqui. De qualquer forma, você poderá ver muito longe se subir. Você pode até gritar: \"Cap'n! Land ahoy!\" como se estivesse navegando no mar.",
  str_item_intro_5212003 = "Uma barraca leve que fica firme na areia fofa da praia. É até feito de materiais à prova de fogo, provavelmente porque os turistas gostam de acender fogos em barracas por diversão.",
  str_item_intro_5212004 = "Este balanço que é largo o suficiente para duas pessoas balançarem lado a lado é ótimo para brincar na costa. Você terá boas lembranças da brisa suave do mar acariciando seu rosto enquanto você se senta nele.",
  str_item_intro_5212005 = "Esta espreguiçadeira é feita de metade de um barco abandonado. Parece a criação caprichosa de alguns marinheiros.",
  str_item_intro_5212006 = "Uma placa de sinalização para a praia. Você pode desenhar vários padrões nele ou deixar mensagens nele, e muitas bandeiras coloridas podem ser amarradas ao estande para atrair a atenção dos turistas.",
  str_item_intro_5212007 = "No espírito da reciclagem, alguns marinheiros desmontaram metade de um barco e usaram suas tábuas para fazer uma mesa e cadeiras. A quilha foi usada para fazer uma estrutura de videira exclusiva para fornecer sombra do sol.",
  str_item_intro_5212008 = "Um guarda-chuva um pouco pesado que é difícil de transportar. A extremidade de sua alça é pontiaguda para que possa ser esfaqueada no chão e presa firmemente lá.",
  str_item_intro_5212009 = "Esta cadeira foi projetada para abraçar o corpo, tornando-a muito confortável para se deitar com muito espaço para esticar os braços e as pernas satisfatoriamente.",
  str_item_intro_5212010 = "Uma mesa leve e prática que os turistas podem movimentar livremente para que possam encontrar facilmente um bom local na praia para se divertir com seus amigos.",
  str_item_intro_5212011 = "Esta cadeira será útil quando você precisar de uma pausa de todas as suas brincadeiras! Sente-se e tome uma bebida para recuperar as energias rapidamente.",
  str_item_intro_5212012 = "Huh? Esses pilares de pedra não são do fundo do mar? E corais? Quando isso foi trazido para terra firme? Após uma inspeção mais detalhada, pode-se ver que esta é realmente uma cerca de madeira pintada habilmente feita. É bonito e emite uma atmosfera maravilhosa do mar.",
  str_item_intro_5212013 = "A areia fina pavimentada nesta área cria uma forte atmosfera à beira-mar que faz parecer que você está na praia.",
  str_item_intro_5241018 = "Há rochas em miniatura e plantas aquáticas nesta caixa gigante, além de um dispositivo que mantém a água circulando, criando um ambiente no qual os peixes podem nadar com segurança.",
  str_item_intro_5241019 = "Ao olhar para este ornamento de coral colorido no topo de sua base de pedra, quase parece que você está no oceano e pode ver cardumes de peixes nadando...",
  str_item_intro_5241020 = "Uma das misteriosas ruínas antigas. Diz-se que absorve a Lumina circundante e emite luz inofensiva, o que a torna uma opção ideal para decoração, iluminação ou envio de sinais à distância.",
  str_item_intro_5212014 = "Que concha enorme! Parece tão grande que não parece ser natural. Se houvesse uma pérola dentro dela, definitivamente teria sido um tesouro raro. Pode ser uma concha, mas foi equipado com estofamento por dentro, tornando-o um sofá maravilhoso.",
  str_item_intro_5212015 = "Quando este balão em forma de água-viva flutua no céu, suas fitas caídas se tornam seus \"tentáculos\", fazendo com que pareça uma verdadeira água-viva flutuando no céu.",
  str_item_intro_5212016 = "Não deixe sua aparência assustá-lo! Ele só quer iluminar o caminho para você. Ver? Não há dentes dentro de sua boca.",
  str_item_intro_5212027 = "Um banco alto que complementa perfeitamente mesas mais longas. A altura ajustável e o assento giratório fazem dele o favorito de muitas crianças.",
  str_item_intro_5212028 = "Um pote verde indispensável que complementa outras decorações festivas.",
  str_item_intro_5212029 = "Uma fileira de cercas especialmente pintadas usadas para particionamento durante festivais. Sinta-se livre para colocar outras decorações nele!",
  str_item_intro_5212030 = "Um viveiro criado especificamente para o Windelion Festival, com dentes-de-leão maduros esperando para serem lançados na noite da festividade.",
  str_item_intro_5212031 = "A estrutura pode ser simples e construída com madeira comum, mas é durável devido às peças reforçadas. Além de ser usado para pendurar luzes, também pode funcionar como um abrigo temporário para pequenos animais.",
  str_item_intro_5212032 = "Alinhe essas colunas baixas festivas e você terá uma cerca.",
  str_item_intro_5234034 = "O exterior em pedra parece um pouco tosco, mas o interior é extremamente intrincado, com um grande espaço. Basta abrir a tampa para reciclar o lixo dentro facilmente.",
  str_item_intro_5212020 = "Perfeito para a beira da estrada. Os transeuntes podem colocar pequenos itens nele ou modificá-lo ao seu gosto e transformá-lo em um marco.",
  str_item_intro_5212021 = "Parece grande, mas é feito de madeira e oco por dentro. Muito leve e pode ser movido rapidamente entre os locais, usado principalmente como decoração secundária de férias.",
  str_item_intro_5212022 = "Poste simples de madeira com interior aparentemente reforçado para muitos pequenos animais pousarem. Provavelmente bom para os outros se apoiarem também, provavelmente...",
  str_item_intro_5212023 = "Leve, com uma construção especial para lidar com várias lanternas ao mesmo tempo. Usado para iluminação ou como peça de destaque em festivais.",
  str_item_intro_5212024 = "Composto por postes de madeira e tecido branco decorado com várias trepadeiras, folhas verdes e flores. Usado principalmente em vários festivais. Dá sorte se a cortina roçar em você, ou se a brisa soprar uma pétala ou folha em seu ombro.",
  str_item_intro_5212025 = "Não se sabe quem construiu o primeiro ninho para o festival, mas atraiu muitos pequenos animais. Isso então se tornou uma tradição informal para as pessoas em festivais subsequentes. Há rumores de que quanto mais pequenos animais se atrair, mais bênçãos seu construtor receberá.",
  str_item_intro_5212026 = "Esta mesa é um pouco pesada porque é feita de madeira maciça com suportes de pedra, supostamente para evitar que ela desmorone caso se decida dançar sobre ela.",
  str_item_intro_5234021 = "Pode ser colocado não apenas em uma sala, mas também no gabinete nos subúrbios. A madeira é sólida o suficiente para suportar o sol e a chuva. Geralmente serve como armazenamento temporário para objetos que não estão em uso.",
  str_item_intro_5212018 = "Boneca Windelion pendurada, popular entre as crianças durante o Festival Windelion. Continha confete que se espalha depois de ser aberto. Sinos ou \"moedas da sorte\" às vezes são colocados dentro para atrair mais crianças.",
  str_item_intro_5212019 = "Um tambor gigante grande o suficiente para permitir que as pessoas dancem nele. A superfície é fina, mas forte o suficiente para não quebrar se você pular nela! Devido à sua construção especial, seu som pode ser ouvido de muito longe. O tambor também é sensível o suficiente para responder a mudanças na forma como as pessoas pisam nele e produzem sons diferentes.",
  str_item_intro_5241021 = "Bestas escamadas não são comuns, e os lendários Pangalo são ainda mais raros! Apresse-se e tire uma foto! Você pode fingir ser um deles você mesmo!",
  str_item_intro_1601881 = "Nascida princesa do Reino Ye, Dantang agora é mantida como refém no Reino Ji. Mas ela ainda mantém uma postura serena enquanto se dedica aos estudos, esperando silenciosamente por uma chance de retornar à sua terra natal.",
  str_item_intro_5212017 = "O propósito específico desta estátua de pedra é desconhecido, mas diz-se que é uma relíquia dos tempos antigos. Muitos celestitas vinham pedir bênçãos e fazer desejos durante o Festival de Windelion. Diz-se que as velas ouviam e passavam os desejos para a estátua para que ela pudesse ajudar com seu poder misterioso.",
  str_item_intro_5271001 = "Uma enorme piscina que ocupa um grande espaço e tem uma grande capacidade. Quanto mais melhor.",
  str_item_intro_5272001 = "Um pequeno cubículo com chuveiro, comumente encontrado em piscinas. É usado para limpar o corpo e, mais importante, trocar de roupa.",
  str_item_intro_5272002 = "Nadar é muito cansativo, então você deve fazer uma pausa se ficar muito cansado. Por que não experimentar a alegria divina de obter um sorvete desta incrível máquina de sorvete automática?",
  str_item_intro_5272003 = "A música é essencial! É fácil ficar entediado brincando na água, então venha aqui para relaxar e dançar algumas músicas!",
  str_item_intro_5272004 = "Este sofá inflável é muito confortável para se deitar. Torna-se um pequeno barco quando colocado na água, tornando-se uma excelente opção tanto para relaxar quanto para ficar à tona.",
  str_item_intro_5272005 = "Como é inflada, esta cadeira é extremamente leve. Pode ser transportada para todo o lado e até colocada na mochila depois de esvaziada, onde quase não ocupa espaço.",
  str_item_intro_5272006 = "Esta é uma bênção para todos aqueles que não sabem nadar! Mesmo os landlubbers podem flutuar na água e fazer algumas tentativas de nadar com isso.",
  str_item_intro_5272007 = "Um brinquedo que funciona tanto fora como dentro de uma piscina. Quando está totalmente inflado, pode ser tratado como uma bola saltitante. Mas o mais importante é que não afunda na água!",
  str_item_intro_5272008 = "A natação é um exercício extremamente exaustivo, então deite-se para recuperar sua força, se necessário. Esta almofada em forma de peixe é particularmente confortável e tem fortes vibrações de praia.",
  str_item_intro_5272009 = "Este guarda-chuva é um pouco grande e inconveniente de transportar, mas sem dúvida vale a pena ter um porque cria uma sombra preciosa que o protege da luz solar direta quando está quente.",
  str_item_intro_5272010 = "Uma decoração adornada com várias conchas do oceano. Se colocado no lugar certo, dá a sensação de estar na praia.",
  str_item_intro_5272011 = "As estrelas do mar são tão populares que apenas alguns desses ornamentos são suficientes para atrair os olhos de muitos.",
  str_item_intro_5272012 = "Uma placa de exibição que supostamente usa tecnologia antiga para exibir imagens diferentes automaticamente! Também parece haver um dispositivo misterioso que pode ser usado para alterar o conteúdo exibido nele. Deve ter sido usado para algo importante...",
  str_item_intro_5271002 = "Projetado por um certo celestita que ama o oceano. Existem estátuas correspondentes que supostamente trazem as bênçãos do oceano! Se você quiser viajar por mar, venha aqui por um tempo. Talvez seja útil!",
  str_item_intro_5272013 = "Vê-lo no oceano significa que sua viagem será abundante! Mas essas criaturas realmente existem? Ou são apenas a fantasia de um marinheiro? De qualquer forma, pelo menos esta estátua é linda e vai chamar a atenção dos jovens.",
  str_item_intro_5272014 = "No mar, alguns polvos perdidos sobem em navios por engano e não conseguem retornar às águas. Quando marinheiros de bom coração os libertam, eles geralmente voltam alguns dias depois para dar-lhes um pequeno presente, como pequenas pérolas ou moedas que se perderam no mar. Esta estátua representa amizade e doação.",
  str_item_intro_5272015 = "Muitas pessoas dizem que ver golfinhos saltando durante a navegação significa que sua viagem será segura. Eu me pergunto se eles abençoam aqueles que viajam na terra?",
  str_item_intro_5271003 = "Com os adereços, equipamentos e ângulo de câmera certos, as visões artísticas de um diretor até mesmo dos lugares mais incríveis podem se tornar realidade. De masmorras perigosas a países das maravilhas caprichosos, as maiores histórias são realizadas antes de cenários magistralmente elaborados.",
  str_item_intro_5273001 = "Embora seja apenas um pano de fundo, ainda reflete a magnificência opulenta de um palácio real quando capturado em filme. Perfeito para filmar dramas de época que acontecem nas cortes dos governantes.",
  str_item_intro_5273002 = "À primeira vista, parece um piso de pedra habilmente trabalhado, mas na realidade, nada mais é do que uma folha de papel! Como um \"piso\" estilo prop, pode ser trocado de forma relativamente rápida.",
  str_item_intro_5273003 = "Apesar de ser um adereço, este \"espelho mágico\" é bastante pesado (dado que é feito de ferro). Naturalmente, o banho de ouro e as pedras preciosas são falsos, mas o espelho possui uma propriedade peculiar: sua superfície não reflete nada! Mas como isso poderia ser? Talvez seja realmente um espelho mágico!",
  str_item_intro_5273004 = "Um simples adereço e nada mais. Afinal, não podemos transportar uma árvore de brilho real de Northland; este é apenas um adereço feito de madeira, papel e fitas e nunca deve ser presenteado aos nortistas.",
  str_item_intro_5273005 = "Um cabide de madeira apenas no nome, na verdade é feito de madeira compensada barata. Um substituto aceitável, já que raramente comporta roupas de qualquer tipo.",
  str_item_intro_5273006 = "Uma figura de barro coberta por uma camada de areia branca pura. À primeira vista, parece um boneco de neve real, só que este mantém sua forma sob o calor das luzes do palco.",
  str_item_intro_5273007 = "Um suporte de madeira de alta qualidade criado por artesãos qualificados. Não parece diferente de uma estátua de pedra real. Sua construção leve também facilita a movimentação no set.",
  str_item_intro_5273008 = "Um brinquedo de pelúcia antigo, mas genuíno, lavado e seco. Apesar de algumas partes parecerem bastante antigas e desgastadas, de certos ângulos, ainda se pode dizer que parece bastante novo.",
  str_item_intro_5273009 = "E-ele flutua! Na verdade, flutua! Isso é realmente apenas um adereço, ou algo mais aterrorizante? De qualquer forma, como ele consegue flutuar não está claro, mas um filme realmente precisa de algo tão assustador?",
  str_item_intro_5273010 = "Embora seja apenas um pano de fundo preso a uma parede, ainda consegue encher as pessoas com uma sensação de pavor. Poderia ser o estilo de pintura chocantemente realista, ou a cabine no fundo é tão assustadora? De qualquer forma, talvez os atores que atuam na frente não estejam apenas atuando quando gritam.",
  str_item_intro_5273011 = "Um suporte de piso usado em conjunto com o cenário da cabine assombrada. Parece exalar o cheiro de mofo de tábuas podres quando desenroladas. Perfeito para muitos filmes de terror.",
  str_item_intro_5273012 = "Uma réplica de grimório antigo que foi intencionalmente projetada para parecer antiga, completa com texto escrito e tudo! Para manter um ar de realismo, cada página contém exatamente o mesmo texto que o original no mesmo formato; até as capas são cópias umas das outras! Parecem parte de um conjunto. No entanto, o conteúdo permanece um mistério.",
  str_item_intro_5273013 = "Um suporte projetado para flutuar no ar. Talvez abrigue um balão para mantê-lo no ar? Ele é preso ao chão com um fio para evitar que ele se desvie.",
  str_item_intro_5273014 = "Um brinquedo pouco usado e inalterado que é utilizado como adereço em vários filmes. Normalmente proporcionaria alegria e entretenimento para as crianças, mas quando usado em filmes de terror... tem o efeito oposto.",
  str_item_intro_5273015 = "Da lápide ao monte de terra em que está, tudo é feito inteiramente de madeira e papel. Leve e portátil, pode ser produzido em grandes quantidades muito rapidamente e adiciona uma vibração sombria e assombrada a qualquer cena.",
  str_item_intro_5273016 = "Transmissores de voz prop, geralmente feitos de madeira ou metal, são completamente inúteis para comunicação. Quando você assiste a um filme de terror e vê uma cena com um transmissor de voz, geralmente é o ator que interpreta o personagem em ambas as extremidades do dispositivo! O que deve ser exaustivo.",
  str_item_intro_5273017 = "A parte da máscara fantasmagórica do manto é perfeita para filmes de terror, mas o chapéu... Parece algo que as pessoas no deserto usariam. Talvez esse suporte esteja tentando se ramificar em diferentes papéis também?",
  str_item_intro_5273018 = "O vaso e o solo são reais, mas as flores não; eles são feitos com tecidos tingidos. Baratas e fáceis de fazer, essas \"plantas\" vibrantes nunca murcharão.",
  str_item_intro_5273019 = "Quando devidamente arrumados, quase se pode sentir o aroma de um bom vinho ou ouvir o tilintar dos copos ao som de uma música suave. Quem sabe quantas cenas famosas foram filmadas em \"bares\" como este?",
  str_item_intro_5273020 = "As tábuas do piso de madeira parecem muito mais antigas do que realmente são, e os buracos só aumentam o efeito. Sua aparência surrada é realmente bastante adequada para configurações de bar.",
  str_item_intro_5273021 = "Talvez um dos adereços mais caros (dado que é inteiramente real). Produz música maravilhosa quando um disco é colocado nele. Devido ao seu alto preço, os roteiristas são frequentemente solicitados a evitar escrever cenas que envolvam danificar o toca-discos de alguma forma. Isso restringe um pouco a criatividade, mas pelo menos pode ser usado para sincronização labial no caso de um ator ter uma voz de canto terrível! São dois pássaros com uma cajadada só!",
  str_item_intro_5273022 = "Um balcão de bar feito de madeira compensada. Resistente e confiável, mas nunca se compara a um balcão de madeira maciça em um bar real. As cadeiras, no entanto, foram compradas em um bar de verdade! E com uma ou duas demãos de tinta fresca, eles ficam como novos!",
  str_item_intro_5273023 = "Mesas e cadeiras acentuam a atmosfera de um bar. Do design aos adornos, qualquer um concordaria que pertence a um bar. Apenas a visão desses adereços diria aos atores que a próxima cena acontece em um bar, tudo sem nenhum aviso do diretor.",
  str_item_intro_5273024 = "Aparentemente, alguns diretores emprestam móveis como esse para filmar certas cenas não convencionais. Embora isso seja perfeitamente normal para o conjunto de um escritório, é realmente adequado para um conjunto de bar? É quase como se tivesse sido emprestado de outro estúdio por falta de financiamento...",
  str_item_intro_5273025 = "Pianos reais são muito pesados, e muitas vezes estão fora do orçamento de um estúdio, então é melhor se contentar com um suporte convincente! Além disso, dado o nível de habilidade dos atores mais novos de hoje, há pouca necessidade de fornecer a eles um piano de verdade...",
  str_item_intro_5273026 = "Um palco de madeira construído às pressas. Embora não seja tão resistente quanto um palco real, requer muito pouco esforço para ser construído e pode ser reconstruído rapidamente no caso de quebrar.",
  str_item_intro_5273027 = "Este suporte de lâminas de madeira é real, mas as lâminas nele... nada mais são do que adereços. Usá-los deve ser bastante seguro, considerando que não possuem arestas vivas; como tal, eles podem ser usados em cenas de luta sem causar ferimentos graves aos atores envolvidos.",
  str_item_intro_5273028 = "Na sala ensolarada, as mesas e cadeiras estão bem arrumadas e quase dá para sentir o cheiro de giz.\nEste assento perto da janela na penúltima fileira deve estar preparado para você.",
  str_item_intro_5273029 = "Um piso de madeira muito comum que foi especialmente tratado para torná-lo mais durável. Por favor, mude para sapatos internos antes de andar sobre ele.",
  str_item_intro_5273030 = "A máquina de cozinhar de aparência estranha também é uma máquina de gashapon. É difícil dizer o que há dentro até você abrir o item que caiu.",
  str_item_intro_5273031 = "Um dispositivo de cozimento misterioso que é mais saudável do que fritar. Mesmo quem nunca cozinhou antes pode usá-lo facilmente.",
  str_item_intro_5273032 = "As bolhas continuam subindo dentro dele, e é necessário ficar mexendo o tempo todo para integrar totalmente os ingredientes em seu interior.\nQuem não gostaria de ter uma linda garota fazendo esse trabalho?",
  str_item_intro_5273033 = "Um barril contendo um líquido misterioso que exala um leve odor sinistro.",
  str_item_intro_5273034 = "Uma máquina que trabalha dia e noite para fornecer comida e bebida, a salvadora de todos os preguiçosos.",
  str_item_intro_5273035 = "É preciso muita habilidade para tocar este instrumento, mas ele continua fazendo barulho à noite, mesmo que não haja ninguém por perto.",
  str_item_intro_5273036 = "Este é apenas um adereço. Não coma!",
  str_item_intro_5273037 = "Uma pousada cheia de vida, barulho e gente de todo tipo. Ninguém sabe quem está lá ou o que vai acontecer lá.",
  str_item_intro_5273038 = "Um piso de madeira que range quando é pisado.",
  str_item_intro_5273039 = "O balcão em que a caixa registradora é colocada na pousada. O chefe sempre senta aqui, então você pode vir conversar com o chefe se se sentir sozinho.",
  str_item_intro_5273040 = "Um requintado prato de porcelana. Percebe-se que o patrão tem bom gosto para decoração.",
  str_item_intro_5273041 = "Um ornamento estranho. Talvez um dos hóspedes tenha dado para a pousada.",
  str_item_intro_5273042 = "A julgar pelo tamanho deste espécime feito de ossos de peixe, este peixe deve ter sido muito poderoso quando estava vivo.",
  str_item_intro_5273043 = "Uma peça de mobília toscamente feita de madeira. Os móveis são sempre os primeiros a sofrer quando há um hóspede mal-humorado, por isso não compre nada muito caro.",
  str_item_intro_5273044 = "Mesas e cadeiras familiares que fazem você se sentir em casa.",
  str_item_intro_5273045 = "Este mobiliário parece muito quente e confortável. Deve ser tão bom ficar dentro disso o dia inteiro no inverno.",
  str_item_intro_5273046 = "O vinho feito pelo patrão exala um forte aroma ao abrir a tampa. Aqueles que o inalam muitas vezes entram em transe e começam a chorar pelas coisas das quais se arrependem em suas vidas.",
  str_item_intro_5273047 = "Uma lembrança de algum lugar que dá um toque exótico à loja. Talvez algumas pessoas se perguntem se existem histórias memoráveis entre o antigo patrão e este graal de outra terra.",
  str_item_intro_5273049 = "Os corvos grasnam constantemente no vento sussurrante e no ambiente sombrio. O heróico guerreiro que caminha sozinho aqui está destinado a embarcar em uma jornada perigosa.",
  str_item_intro_5273050 = "Existem muitos lugares sem nome como este em tempos difíceis. Ao se esgueirar por aqui, tente não quebrar os galhos secos sob seus pés ou deixar rastros de si mesmo.",
  str_item_intro_5273051 = "Parece um armário comum, não importa como você olhe, mas uma espada preciosa aparecerá imediatamente assim que o mecanismo for acionado. Por favor, opere isso sob a supervisão de um especialista.",
  str_item_intro_5273052 = "Uma folha decorativa com padrões de junco. Se for usado para decorar um cenário, as pessoas terão vontade de galopar livremente nele a cavalo.",
  str_item_intro_5273053 = "Uma folha decorativa que cria a imagem de um campo de trigo. Se isso for usado para decorar um cenário, um samurai emboscará as pessoas nele?",
  str_item_intro_5273054 = "Uma folha decorativa com padrões de girassol. Se isso for usado para decorar um cenário, talvez até atraia a luz do sol para ele.",
  str_item_intro_5273055 = "Um reprodutor de vídeo de origem misteriosa que tem um pano de aparência antiga por baixo. Parece que ele exibirá algumas informações importantes se uma fita de vídeo for inserida nele.",
  str_item_intro_5273056 = "Um mapa de origem misteriosa. Parece um mapa militar usado em tempos de guerra e parece conter algumas informações importantes.",
  str_item_intro_5273057 = "Uma caixa de correio de origem misteriosa. Ninguém sabe há quanto tempo está aqui. Se você olhar atentamente para os arranhões na caixa de correio, poderá ver algumas informações importantes deixadas por pessoas no passado.",
  str_item_intro_5234040 = "Jomu, o vendedor habilidoso de Rediesel Wrench, até postou anúncios aqui, de todos os lugares. Eles parecem estar convidando a todos para participar de algo chamado \"Rediesel Foodfest\", e afirmam que há muitas ótimas ofertas para aproveitar. Apesar de estar no meio do deserto... Espero que a comida não seja muito exótica, certo?",
  str_item_intro_5234041 = "Aparentemente, um \"impressionante filme de estreia do produtor/diretor/atriz/operador de câmera mais jovem e mais bonito da história\". É suposto ser hilário e horripilante, o que se pode deduzir do outdoor. Como será nas bilheterias? Vamos ter que esperar para ver!",
  str_item_intro_5234042 = "Um anúncio de recrutamento para a Federação Illumina. Ele exala a opulência da Illumina. \"A linha de defesa mais forte e final. Fique conosco em nossa luta contra o flagelo do Eclipsite!\" diz. Muitas pessoas devem ter sido estimuladas a agir por esse chamado apaixonado às armas.",
  str_item_intro_5234031 = "Um animal que tem espinhos na cabeça e parece ser muito irritável. Felizmente, é apenas uma escultura.",
  str_item_intro_5234032 = "Parece muito gentil, embora tenha chifres longos... Por alguma razão, dá vontade de acariciá-lo.",
  str_item_intro_5241014 = "O que aconteceu aqui? Como ficou tão inchado? Mesmo assim, ele ainda pode voar e permitir que seus usuários experimentem a sensação de voar no céu.",
  str_item_intro_5232007 = "A tecnologia deste assento de pedra funciona de maneiras misteriosas. Ele flutua depois que você se senta nele e até se equilibra. Não tenha medo, experimente!",
  str_item_intro_5234035 = "As esculturas repetitivas e metódicas neste monumento antigo formam padrões maravilhosos que dizem representar princípios matemáticos de algum tipo, mas os detalhes exatos são desconhecidos.",
  str_item_intro_5222001 = "Arbustos fáceis de cultivar que foram cultivados juntos para formar um muro baixo. Serve um propósito decorativo e também pode ser usado como uma divisória.",
  str_item_intro_5222002 = "Uma parede formada por arbustos altos densamente plantados. Geralmente é usado como parede externa em pátios. Diz-se que muitos arbustos altos são plantados juntos em alguns lugares para formar um labirinto de plantas.",
  str_item_condition_103 = "Desbloqueia após a exploração primária de Undercity π",
  str_item_condition_104 = "Desbloqueia após a exploração avançada de Undercity π",
  str_item_condition_105 = "Desbloqueia após a exploração em profundidade de Undercity π",
