  str_item_use_3000297 = "Um roteiro de filme. Usado para começar a filmar filmes no Film Set de Cloud Gardens.",
  str_item_use_3000298 = "Um roteiro de filme. Usado para começar a filmar filmes no Film Set de Cloud Gardens.",
  str_item_use_3000299 = "Um roteiro de filme. Usado para começar a filmar filmes no Film Set de Cloud Gardens.",
  str_item_3661026 = "Peru Assado Festivo",
  str_item_intro_3661026 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nAs férias são para festejar! Este peru assado merece ser a estrela do dia, tanto no aspecto como no sabor. O que você está esperando?",
  str_item_3661181 = "relógio colosso",
  str_item_intro_3661181 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nEste relógio de parede tinha originalmente a forma de uma coruja, mas um certo comerciante o mudou para um Colosso porque achou que era muito comum. Parece surpreendentemente bom, mas é uma pena que suas asas não se movam.",
  str_item_3661182 = "Cavaleiro Colher de Metal",
  str_item_intro_3661182 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nPegue isso! Ataque de colher! O Metal Spoon Knight é famoso por ser um glutão. Sua barriga é tão grande que até sua armadura deve ser feita sob medida! Olhe para a baba pingando de sua boca. Ele está de olho na comida de alguém?",
  str_item_3661027 = "Faixa Fã Goldie",
  str_item_intro_3661027 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nVenha dar tudo de si por Goldie! Deixe sua música se espalhar por todos os cantos do continente!",
  str_item_3000289 = "EXP de Maestria de Talentos",
  str_item_3000290 = "Ponto de Maestria de Talento",
  str_item_3661183 = "cabine de DJ",
  str_item_intro_3661183 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUma cabine de DJ com sistema de alto-falantes embutido, com uma série de botões que permitem ao operador emitir sons quase infinitos. Com seus ritmos em constante mudança, basta um DJ para alimentar a atmosfera de festa e mergulhar a multidão em uma música hipnotizante.",
  str_item_3661184 = "Pôster da Garota dos Sonhos",
  str_item_intro_3661184 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nSiga seus sonhos! Você também pode ser como ela - uma garota que comanda o palco, espalhando amor e esperança por todo o continente! Nunca desista de seus sonhos!",
  str_item_3661185 = "Estatueta Tourdog",
  str_item_intro_3661185 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nEsteja sempre na vanguarda das últimas tendências da Umbraton! Mesmo como estatueta, Tourdog exibe sua estética visionária o tempo todo. Há rumores de que esta figura é muito popular entre seus seguidores, então certifique-se de que eles não coloquem as mãos nela!",
  str_item_3661186 = "Mega Blaster",
  str_item_intro_3661186 = "Artigo de mobília. Pode ser colocado em quartos no seu Colossus.\nDiz-se que apenas os mais corajosos se atrevem a tocar este poderoso instrumento musical, pois o som que ele gera é forte o suficiente para dominar a constituição frágil de um indivíduo fraco. Embora faça um barulho horrível, é perfeito para multidões deslumbrantes em shows lotados.",
  str_item_5259309 = "Pingente potencial",
  str_item_5259310 = "Pedra Enfeitiçada",
  str_item_5259311 = "Caixa trancada misteriosa",
  str_item_5259410 = "Lâmina do Caos",
  str_item_5259411 = "Manoplas Berserker",
  str_item_5259412 = "Estátua de Bond",
  str_item_5259505 = "Cinturão de Energia",
  str_item_5259506 = "Alma Berserker",
  str_item_5259507 = "espada de luz",
  str_item_5259513 = "Armadura Berserker",
  str_item_5259514 = "Estátua da Deusa da Guerra",
  str_item_intro_5259301 = "Aumenta o dano do Chain Combo ao conectar 15 peças ou mais.",
  str_item_intro_5259302 = "Ao calcular o dano, os aliados ignoram os efeitos negativos de ter seu elemento anulado.",
  str_item_intro_5259303 = "Imediatamente causa dano adicional ao infligir Envenenado/Queimado/Sangramento nos inimigos.",
  str_item_intro_5259304 = "Aumenta permanentemente o HP máximo dos aliados.",
  str_item_intro_5259305 = "Sempre que o HP cair abaixo de 50%, um item de recuperação de HP será gerado no campo.",
  str_item_intro_5259306 = "Recupera HP no início de cada onda.",
  str_item_intro_5259307 = "Concede um escudo no início de cada onda.",
  str_item_intro_5259308 = "Causa alto dano a inimigos não chefes ao seu redor a cada rodada.",
  str_item_intro_5259309 = "Reduz o cooldown do Special Caelestite Gear em 1.",
  str_item_intro_5259310 = "Todos os aliados e inimigos perdem uma proporção de seu HP a cada rodada.",
  str_item_intro_5259311 = "Concede um Equipamento Caelestite Especial adicional aleatório.",
  str_item_intro_5259401 = "Aumenta o dano que os inimigos com debuff recebem.",
  str_item_intro_5259402 = "Converte uma porcentagem do excesso de cura dos aurorianos em um escudo.",
  str_item_intro_5259403 = "Envenena todos os aliados e inimigos na área quando um inimigo morre.\nReduz o dano de Veneno recebido por aliados.",
  str_item_intro_5259404 = "Aumenta o dano de Chain Combos quando afetado por um debuff.",
  str_item_intro_5259405 = "Tem uma chance extremamente baixa de matar instantaneamente inimigos que não sejam chefes.",
  str_item_intro_5259406 = "Restaura o HP dos aliados quando uma habilidade ativa mata um inimigo.",
  str_item_intro_5259407 = "Aumenta todo o dano dos aliados quando no HP máximo.",
  str_item_intro_5259408 = "Restaura o HP dos aliados quando o dano de veneno de um inimigo é acionado.\nReduz a chance de que aliados sejam Envenenados.",
  str_item_intro_5259409 = "Reflete o dano de volta aos inimigos quando eles causam dano aos aliados.",
  str_item_intro_5259410 = "Aumenta o dano dos aliados quando houver pelo menos 3 aurorianos com diferentes elementos primários na equipe.",
  str_item_intro_5259411 = "Os elementos secundários dos aurorianos causam dano sem redução de dano.",
  str_item_intro_5259412 = "Chances de mudança de capitão +5.\nReduz em 1 o tempo de recarga da Habilidade Ativa dos Aurorianos que se tornam Capitães pela primeira vez nesta rodada.",
  str_item_intro_5259501 = "O capitão libera um Chain Combo adicional no início da linha.",
  str_item_intro_5259502 = "Gera um efeito de explosão a cada 5 ataques normais.",
  str_item_intro_5259503 = "Gera um pequeno número de ladrilhos cromáticos dentro de 1 aglomerado circundante a cada rodada.",
  str_item_intro_5259504 = "Derrota instantaneamente inimigos com menos de 10% de HP.",
  str_item_intro_5259505 = "Acelera o tempo de recarga das Habilidades Ativas quando está parado.",
  str_item_intro_5259506 = "Converte a DEF de todos os aurorianos aliados em ATK.",
  str_item_intro_5259507 = "O primeiro ladrilho de uma linha pode ter uma cor diferente dos ladrilhos subsequentes. Esses dois elementos diferentes levarão os aurorianos a agir.",
  str_item_intro_5259508 = "Trata os ladrilhos Verdes como ladrilhos cromáticos.",
  str_item_intro_5259509 = "Trata os ladrilhos azuis como ladrilhos cromáticos.",
  str_item_intro_5259510 = "Trata os ladrilhos vermelhos como ladrilhos cromáticos.",
  str_item_intro_5259511 = "Trata os ladrilhos amarelos como ladrilhos cromáticos.",
  str_item_intro_5259512 = "Aumenta muito o dano dos aliados, mas cada conexão gera ladrilhos quebrados.",
  str_item_intro_5259513 = "Aumenta o dano de Chain Combos conforme o HP dos aliados diminui.",
  str_item_intro_5259514 = "Chances de mudança de capitão +5.\nOs aurorianos que foram o capitão nesta rodada atacarão com seu elemento primário, independentemente da cor da conexão.",
  str_item_rpintro_5259301 = "Aumenta o dano do Chain Combo em 30% quando aliados conectam 15 ou mais blocos.",
  str_item_rpintro_5259302 = "Ao causar dano, os aliados ignoram o efeito de redução de dano de ter seu elemento anulado. Ao receber dano, os aliados ignoram o bônus de ter seu elemento anulado.",
  str_item_rpintro_5259303 = "Ao infligir Envenenamento/Queimação/Sangramento nos inimigos, o alvo perde HP instantaneamente em 50% de seu ataque. Pode ser acionado uma vez por rodada em cada alvo.",
  str_item_rpintro_5259304 = "Aumenta o HP máximo dos aurorianos da equipe em 100% sem alterar o HP atual.",
  str_item_rpintro_5259305 = "Quando o HP dos aliados cair abaixo de 50%, uma bandagem, que recupera 20% do HP máximo quando os aliados passarem por ela, será gerada em um local aleatório do campo.",
  str_item_rpintro_5259306 = "Recupera 20% do Max HP no início de cada onda.",
  str_item_rpintro_5259307 = "Concede um escudo igual a 40% do HP máximo que dura 1 rodada no início de cada onda.",
  str_item_rpintro_5259308 = "Causa dano igual a 50% do HP máximo a todos os inimigos não chefes dentro de 1 grupo ao redor no início de cada onda.",
  str_item_rpintro_5259309 = "Reduz o cooldown do Special Caelestite Gear em 1 nas batalhas subseqüentes.",
  str_item_rpintro_5259310 = "Todos os aliados e inimigos (incluindo chefes) perdem 7% de seu HP atual no início de cada rodada.",
  str_item_rpintro_5259311 = "Concede um Equipamento Caelestite Especial aleatório que você ainda não possui. Isso pode ser usado em batalhas subsequentes e seu tempo de espera é calculado separadamente.",
  str_item_rpintro_5259401 = "Todo o dano sofrido por inimigos com debuff ou sob efeito de debuff aumenta em 20%.",
  str_item_rpintro_5259402 = "Converte 100% do excesso de cura dos aurorianos em um escudo que dura 1 rodada.",
  str_item_rpintro_5259403 = "Inflige 1 pilha de veneno em todos os aliados e inimigos no campo sempre que um inimigo morre. Aliados recebem -50% de dano de veneno.",
  str_item_rpintro_5259404 = "Aumenta o dano do Chain Combo em 30% quando seu time é afetado por debuffs.",
  str_item_rpintro_5259405 = "Inimigos não chefes têm 3% de chance de morrer instantaneamente ao receber qualquer dano.",
  str_item_rpintro_5259406 = "Os aliados recuperam HP igual a 15% do HP máximo do lançador sempre que um inimigo é morto por uma habilidade ativa.",
  str_item_rpintro_5259407 = "Aumenta todo o dano causado em 20% quando sua equipe está no HP máximo.",
  str_item_rpintro_5259408 = "Sempre que os inimigos recebem dano de veneno, os aliados recuperam HP igual a 100% desse dano de veneno. Aliados recebem -50% de dano de veneno.",
  str_item_rpintro_5259409 = "Reflete 100% do dano sofrido pelos inimigos quando eles causam dano aos aliados.",
  str_item_rpintro_5259410 = "Aumenta todo o dano causado por aliados em 25% quando houver pelo menos 3 aurorianos com diferentes elementos primários em seu time.",
  str_item_rpintro_5259411 = "Os elementos secundários dos aurorianos causam dano com o mesmo multiplicador de seus elementos primários.",
  str_item_rpintro_5259412 = "O capitão muda as chances +5 ao obter este item.\nAo trocar de capitão, o cooldown da habilidade ativa do novo capitão é reduzido em 1. Cada auroriano só pode ativar esse efeito uma vez a cada rodada.",
  str_item_rpintro_5259501 = "Gera uma imagem do Capitão Aurora no ponto inicial. Esta imagem também desencadeia Chain Combos nesta rodada.",
  str_item_rpintro_5259502 = "Gera uma explosão que ataca os inimigos quando o combo de ataque normal é múltiplo de 5.",
  str_item_rpintro_5259503 = "Converte 3 ladrilhos dentro de 1 aglomerado circundante em ladrilhos cromáticos no início de cada rodada.",
  str_item_rpintro_5259504 = "Os inimigos que tiverem menos de 10% de HP restante serão derrotados instantaneamente.",
  str_item_rpintro_5259505 = "Reduz o cooldown de todas as habilidades aurorianas que estão em cooldown em 1 se nenhuma conexão for feita nesta rodada.",
  str_item_rpintro_5259506 = "Reduz a DEF de todos os aurorianos em sua equipe para 0 e aumenta seu ATK pela quantidade total de DEF reduzida.",
  str_item_rpintro_5259507 = "O primeiro ladrilho de uma linha pode ter uma cor diferente dos ladrilhos subsequentes. Esses dois elementos diferentes levarão os aurorianos a agir.",
  str_item_rpintro_5259508 = "Ao conectar outras cores, os ladrilhos verdes também podem ser conectados.",
  str_item_rpintro_5259509 = "Ao conectar outras cores, os ladrilhos azuis também podem ser conectados.",
  str_item_rpintro_5259510 = "Ao conectar outras cores, os ladrilhos vermelhos também podem ser conectados.",
  str_item_rpintro_5259511 = "Ao conectar outras cores, os ladrilhos amarelos também podem ser conectados.",
  str_item_rpintro_5259512 = "Aumenta todo o dano causado por aliados em 25%, mas o ponto inicial de cada conexão se tornará uma peça quebrada que não pode ser movida por 5 rodadas.",
  str_item_rpintro_5259513 = "Aumenta o dano do Chain Combo em até 80% de acordo com a porcentagem de HP perdida pelos aliados.",
  str_item_rpintro_5259514 = "Chances de mudança de capitão +5.\nOs aurorianos que foram o capitão nesta rodada atacarão com seu elemento primário, independentemente da cor da conexão.",
  str_item_intro_9994027 = "Aumenta todo o dano causado por aliados em 25% quando houver pelo menos 3 aurorianos com diferentes elementos primários em seu time.",
  str_item_intro_9994028 = "Os elementos secundários dos aurorianos causam dano sem redução de dano.",
  str_item_intro_9994029 = "Chances de mudança de capitão +3.\nReduz em 1 o tempo de recarga da Habilidade Ativa dos Aurorianos que se tornam Capitães pela primeira vez nesta rodada.",
  str_item_intro_9995019 = "Reduz o cooldown da habilidade ativa em 1 com 2 toques enquanto está parado.",
  str_item_intro_9995020 = "Reduz a DEF de todos os aurorianos em sua equipe para 50% e aumenta o ATK pela quantidade de DEF reduzida.",
  str_item_intro_9995021 = "Aumenta o dano do Chain Combo em até 80% de acordo com a porcentagem de HP perdida pelos aliados.",
  str_item_intro_9995022 = "Chances de mudança de capitão +3.\nOs aurorianos que foram o capitão nesta rodada atacarão com seu elemento primário, independentemente da cor da conexão.",
  str_item_rpintro_9994027 = "Uma arma que parece ser capaz de se fundir com Lumina perfeitamente... Isso é realmente raro...",
  str_item_rpintro_9994028 = "Diz-se que um certo guerreiro antigo foi derrotado em batalha porque não conseguiu exercer todo o poder de sua mão não dominante. Após a derrota, ele mandou fazer essas manoplas especialmente. Com certeza, ele era invencível em suas próximas batalhas.",
  str_item_rpintro_9994029 = "As mãos estão conectadas ao seu coração. Portanto, pode-se dizer que duas pessoas que estão de mãos dadas têm uma conexão espiritual uma com a outra e nunca se separarão.",
  str_item_rpintro_9995019 = "O poder surpreendente nesta antiga relíquia permite que seu usuário lance todos os tipos de Luminatics poderosos mais rapidamente, concedendo ao usuário a habilidade de lidar com várias situações perigosas.",
  str_item_rpintro_9995020 = "Como diz o velho ditado, \"quem vive pela espada morre pela espada\". Embora isso torne possível derrotar inimigos extremamente poderosos, a premissa é que você lute bravamente sem se importar com sua própria segurança...",
  str_item_rpintro_9995021 = "De acordo com alguns contos transmitidos de boca em boca, esta armadura possui grande e terrível poder, tornando-se um tesouro para alguns e uma maldição para outros.",
  str_item_rpintro_9995022 = "Alguns dizem que esta estátua não retrata um deus, mas uma lendária guerreira que pode fornecer apoio na batalha.",
  str_item_3661187 = "Nó de Bênção de Longzhou",
  str_item_intro_3661187 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUma corda habilmente tecida em um nó quadrado, uma prova da criatividade do tecelão. Supostamente de Longzhou, onde as pessoas o penduram em suas casas para proteger sua família de danos.",
  str_item_3661188 = "Lanterna suspensa alta",
  str_item_intro_3661188 = "Artigo de mobília. Pode ser colocado em quartos no seu Colossus.\nUm suporte de lanterna de Longzhou com uma estrutura de madeira única, da qual pende uma lanterna vermelha. Parece ter o poder de colocar as pessoas em outro mundo em um instante.",
  str_item_3661028 = "enfeites estrelados",
  str_item_intro_3661028 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nEstrelas e elementos galácticos amarrados juntos em uma corda. Pode-se admirar um vislumbre do universo quando está iluminado. Pode ser colocado na parede ou pendurado em uma árvore ao ar livre para criar a ilusão de um céu estrelado em um dia nublado.",
  str_item_3010001 = "Star Flare (Limitado)",
  str_item_intro_3010001 = "Um dispositivo que envia sinais de recrutamento para atrair a atenção dos aurorianos e chamá-los para serem seus parceiros. Este é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 9 de fevereiro de 2023 (UTC +0), 23:00 em 8 de fevereiro de 2023 (UTC -5).",
  str_item_intro_3010002 = "Um dispositivo que envia sinais de recrutamento para atrair a atenção dos aurorianos e os chama para serem seus parceiros.\nEste é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 9 de março de 2023 (UTC +0), 23:00 em 8 de março de 2023 (UTC -5).",
  str_item_intro_3010003 = "Um dispositivo que envia sinais de recrutamento para atrair a atenção dos aurorianos e os chama para serem seus parceiros.\nEste é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 6 de abril de 2023 (UTC+0), 23:00 em 5 de abril de 2023 (UTC-5).",
  str_item_intro_3010004 = "Um dispositivo que envia sinais de recrutamento para atrair a atenção dos aurorianos e os chama para serem seus parceiros.\nEste é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 11 May 2023 (UTC +0), 23:00 em 10 May 2023 (UTC -5).",
