  str_item_intro_3020013 = "Um dispositivo que envia sinais de imagem especiais para atrair a atenção de certos aurorianos.\nEste é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 20 de dezembro de 2023 (UTC+0), 23:00 em 19 de dezembro de 2023 (UTC-5).",
  str_item_3030001 = "Pacote de recarga (limitado)",
  str_item_intro_3030001 = "Caixa de cristal quadrada com um centro brilhante que fornece mais energia ao prisma. Use para obter 60 Prisma. Este é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 9 de fevereiro de 2023 (UTC +0), 23:00 em 8 de fevereiro de 2023 (UTC -5).",
  str_item_intro_3030002 = "Uma caixa quadrada de cristal com um centro brilhante que fornece mais energia ao Prisma.\nUse para obter 60 Prisma.\nEste é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 9 de março de 2023 (UTC +0), 23:00 em 8 de março de 2023 (UTC -5).",
  str_item_intro_3030003 = "Uma caixa quadrada de cristal com um centro brilhante que fornece mais energia ao Prisma.\nUse para obter 60 Prisma.\nEste é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 6 de abril de 2023 (UTC+0), 23:00 em 5 de abril de 2023 (UTC-5).",
  str_item_intro_3030004 = "Uma caixa quadrada de cristal com um centro brilhante que fornece mais energia ao Prisma.\nUse para obter 60 Prisma.\nEste é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 11 May 2023 (UTC +0), 23:00 em 10 May 2023 (UTC -5).",
