  str_item_intro_3030006 = "Uma caixa quadrada de cristal com um centro brilhante que fornece mais energia ao Prisma. Use para obter 60 Prisma. Este é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 6 de julho de 2023 (UTC +0), 23:00 em 5 de julho de 2023 (UTC -5).",
