  str_item_intro_3030008 = "Caixa quadrada de cristal com um centro brilhante que fornece mais energia para Prismas.\nUse para ganhar 60 Prismas.\nEste é um item por tempo limitado. Ele desaparecerá após o vencimento. Por favor, use-o a tempo. Prazo de validade: 04:00 de 31 de agosto de 2023 (UTC+0), 23:00 de 30 de agosto de 2023 (UTC-5).",
