  str_item_intro_3030010 = "Uma caixa quadrada de cristal com um centro brilhante que fornece mais energia ao Prisma.\nUse para obter 60 Prisma.\nEste é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 18 de outubro de 2023 (UTC+0), 23:00 em 17 de outubro de 2023 (UTC-5).",
  str_item_intro_3030011 = "Uma caixa quadrada de cristal com um centro brilhante que fornece mais energia ao Prisma.\nUse para obter 60 Prisma.\nEste é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 8 de novembro de 2023 (UTC+0), 23:00 em 7 de novembro de 2023 (UTC-5).",
