  str_item_intro_3030013 = "Uma caixa quadrada de cristal com um centro brilhante que fornece mais energia ao Prisma.\nUse para obter 60 Prisma.\nEste é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 20 de dezembro de 2023 (UTC+0), 23:00 em 19 de dezembro de 2023 (UTC-5).",
