  str_item_intro_3020027 = "Um dispositivo que envia sinais de imagem especiais para atrair a atenção de certos aurorianos.\nEste é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 16 de outubro de 2024 (UTC +0), 23:00 em 15 de outubro de 2024 (UTC -5).",
  str_item_intro_3030027 = "Uma caixa quadrada de cristal com um centro brilhante que fornece mais energia ao Prisma.\nUse para obter 60 Prisma.\nEste é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 16 de outubro de 2024 (UTC +0), 23:00 em 15 de outubro de 2024 (UTC -5).",
  str_item_intro_3010028 = "Um dispositivo que envia sinais de recrutamento para atrair a atenção dos aurorianos e os chama para serem seus parceiros.\nEste é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 16 de outubro de 2024 (UTC +0), 23:00 em 15 de outubro de 2024 (UTC -5).",
