  str_item_intro_3030028 = "Uma caixa quadrada de cristal com um centro brilhante que fornece mais energia ao Prisma.\nUse para obter 60 Prisma.\nEste é um item por tempo limitado. Ele desaparecerá após a expiração. Por favor, use-o a tempo. Hora de expiração: 04:00 em 16 de outubro de 2024 (UTC +0), 23:00 em 15 de outubro de 2024 (UTC -5).",
  str_item_3000301 = "Pacote de ingredientes",
  str_item_intro_3000301 = "Um pacote cheio de vários ingredientes empilhados.\nPode ser usado para fazer comida.",
  str_item_3000302 = "penas raras",
  str_item_intro_3000302 = "As penas de um misterioso pássaro desconhecido. Por causa de suas cores vivas, eles são apreciados por alguns membros do Courier Union. Talvez você possa trocá-los por algo.",
  str_item_3661189 = "rosas à luz de velas",
  str_item_intro_3661189 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nQue as flores nunca murchem e a luz das velas nunca se apague, para que a beleza desse momento fique para sempre em seu coração.",
  str_item_3661190 = "caixa de correio de confissões",
  str_item_intro_3661190 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nCom medo de revelar os segredos do seu coração? Há um segredo dentro de sua alma? Em caso afirmativo, esta caixa de correio é para você. É paciente, seguro e confiável, sendo um excelente confidente.",
  str_item_3661191 = "peluche coroa de lua",
  str_item_intro_3661191 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nQuem poderia recusar um urso tão fofo, especialmente um com um coração amoroso! Se alguém lhe der esse presente, é óbvio o que essa pessoa sente por você.",
  str_item_3661192 = "buquê coroa de lua",
  str_item_intro_3661192 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nFlores vermelhas e brancas são símbolos de amor apaixonado e um coração puro. Quando você dá este buquê para sua amada, é hora de dizer essas três palavrinhas.",
  str_item_3661029 = "Namoradeira de coração",
  str_item_intro_3661029 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUm sofá espaçoso e confortável, adequado para casais relaxarem juntos. Se você não tem ninguém com quem se sentar, tudo bem também. A sensação de estar enrolado em uma grande almofada macia também pode fazer você se sentir como se não estivesse sozinho...",
  str_item_3661193 = "Asas Brancas Puras",
  str_item_intro_3661193 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nComo se diz que os anjos são os guardiões do amor, alguns penduram essas asas brancas na parede na esperança de encontrar seu verdadeiro amor em breve.",
  str_item_3661194 = "Torre de Bolo Cisne",
  str_item_intro_3661194 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUm bolo decorado com cisnes requintados. Parece mais uma obra de arte do que comida... Tem certeza que quer comer?",
  str_item_3661030 = "estrela flutuante",
  str_item_intro_3661030 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nIsso parece mais adequado como um balão que aparece em um parque de diversões em vez de uma decoração em casa, mas também parece bastante especial em casa. No entanto, ele provavelmente voará por toda parte se você não o amarrar a algo.",
  str_item_3000308 = "Registro de Caso",
  str_item_intro_3000308 = "Registrei alguns traços do culpado. Vamos ver se eles vão nos ajudar a descobrir a verdade...",
  str_item_3661195 = "Gramofone Clássico",
  str_item_intro_3661195 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUm gramofone clássico considerado popular em Umbraton há várias décadas, é um acessório comum nas casas de muitos empresários ricos. Parece ter sido criado por um artesão da época ou por alguém que se esforçou para pesquisar e desenhar o seu timbre e decoração, que mergulham os membros da geração mais velha na música e no zeitgeist do passado.",
  str_item_3661196 = "Quadro de dicas",
  str_item_intro_3661196 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nEste quadro não só pode ser usado para desenhar vários mapas mentais para analisar um caso de todos os ângulos, mas também é o lugar perfeito para colar pistas importantes e fotos de testemunhas. Ele também exibe convenientemente informações coletadas de várias fontes, facilitando o acesso, a dedução e o resumo e permitindo que você descubra a verdade e o culpado rapidamente.",
  str_item_3661197 = "Mesa de centro do detetive",
  str_item_intro_3661197 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nOriginalmente usada para tomar chá da tarde e jogar cartas, esta mesa de centro agora está repleta de livros e papéis relacionados a casos criminais, junto com uma lupa, cachimbo e lanterna colocados ao lado deles. Parece que o dono deve ser um detetive ou pelo menos um entusiasta de detetives.",
  str_item_3661198 = "Cabide de Detetive",
  str_item_intro_3661198 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nAo sair para conduzir uma investigação, é importante que a pessoa tenha uma boa aparência. O sobretudo pode suportar o ar frio da noite e pode conter muitos itens usados ao farejar pistas, como cadernos, lupas e pequenas armas para autodefesa. E o chapéu, é claro, não é bom apenas para proteger do vento - também faz com que o usuário pareça mais um detetive.",
  str_item_3661031 = "Sofá Raciocínio Dedutivo",
  str_item_intro_3661031 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nEles dizem que alguns detetives podem inferir a verdade de um caso sentando em um sofá e desenhando várias pistas coletadas por outros. Parece que este sofá não só proporciona relaxamento, mas também aumenta o poder da mente.",
  str_item_3661199 = "Rack de tubos",
  str_item_intro_3661199 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUm rack cheio de tubos. Mesmo que você não goste do cheiro de tabaco, vale a pena colecionar esses cachimbos de formato único.",
  str_item_3661200 = "Binóculos de chão",
  str_item_intro_3661200 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nA maior característica desses binóculos é a capacidade de permitir que você veja tudo nos arredores distantes. Sua lente é muito clara, mas seu barril de metal a torna tão pesada que deve ser colocada em um tripé especial para mantê-la estável.",
  str_item_3661032 = "Seguro Seguro",
  str_item_intro_3661032 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\n\"Esta é a prisão mais segura e forte para seus bens neste continente\", disse o comerciante. Com certeza, a grande alça de trava parece forte e sua caixa pesada parece imune à maioria dos danos.",
  str_item_3661033 = "pato do campeão",
  str_item_intro_3661033 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\neste pato Gronru projetado é o prêmio para o vencedor de seu jogo! Incrivelmente fofo, sua aparência dourada simboliza a honra de um campeão.",
  str_item_3661207 = "Tapete de Ordem",
  str_item_intro_3661207 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nAcima das nuvens no céu está a cidade flutuante. Como a luz da civilização de Astra, este tapete é um símbolo de identidade e status e também representa ordem e rituais.",
  str_item_3661208 = "Estandarte que não cai",
  str_item_intro_3661208 = "Artigo de mobília. Pode ser colocado em quartos no seu Colossus.\nO símbolo da \"cidade eterna e imperecível\", sua aparição no continente significa que a luz da civilização de Lumopolis brilha intensamente aqui.",
  str_item_3661201 = "Tributo Harpa",
  str_item_intro_3661201 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nEsta harpa é usada exclusivamente durante grandes celebrações em Lumopolis. Preservado com uma forma única de Luminatics, seu tom permanece perfeitamente afinado. Somente os músicos mais habilidosos podem tocar melodias edificantes com este instrumento, que é perfeito para canções de louvor.",
  str_item_3661202 = "ampulheta cintilante",
  str_item_intro_3661202 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\n\"Em meio ao fluxo e refluxo da luz e da escuridão, apenas este artefato pode medir o tempo com precisão.\" Rumores de conter os grãos de areia mais requintados encontrados no continente e, por meio da calibração de Luminatics exclusivos, a precisão desta ampulheta rivaliza com a dos melhores relógios.",
  str_item_3661203 = "Fonte acima das nuvens",
  str_item_intro_3661203 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nNo pátio bem acima das nuvens, você pode perceber o som suave da água corrente? Não se surpreenda, pois se origina do Lumopolis' Fountain Terrace. Abençoada pelos encantadores Luminatics, a água parece se manifestar do nada, descendo graciosamente de um nível para o outro. Mesmo do céu, as pessoas podem apreciar a vista cativante desta cachoeira celestial.",
  str_item_3661204 = "A última espada e escudo",
  str_item_intro_3661204 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nComo a cidade inflexível, Lumopolis permanece como o último bastião da civilização. Esta espada e escudo incorporam o pilar final desta defesa... Eles simbolizam o dever, a bravura e a determinação inabalável de lutar até o fim.",
  str_item_3661034 = "Bola de cristal dos velhos tempos",
  str_item_intro_3661034 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUma rápida olhada no cristal revela apenas o seu próprio reflexo, mas uma inspeção minuciosa revela cenas do passado. A essência das memórias queridas permanece diante de seus olhos, convidando você a mergulhar em seu alcance...",
  str_item_3000325 = "lágrima de cristal",
  str_item_intro_3000325 = "Dizem que são lágrimas derramadas por este mundo... Elas só podem ser obtidas naquele dia e contêm a verdade deste mundo.\nUso: Pode ser trocado por suprimentos no Hall of Remembrance.\nFonte: Conclua os estágios da História Principal ou Raid de Recursos que requerem Prism.",
  str_item_3661205 = "Castiçal de braço duplo",
  str_item_intro_3661205 = "Artigo de mobília. Pode ser colocado em quartos no seu Colossus.\n\"A luz deve ser emitida no escuro para ajudar as pessoas a encontrar o caminho.\" Este projeto utiliza Luminatics especiais de Lumopolis. Pode ser montado em paredes automaticamente sem ganchos, e suas velas não serão facilmente apagadas pelo vento.",
  str_item_3661206 = "Vaso Elegante",
  str_item_intro_3661206 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nOs vasos grandes, cada um caro o suficiente para os plebeus viverem luxuosamente por alguns anos, usados pelos Nobres Lumo são conhecidos por suas formas elegantes. No entanto, são apenas enfeites que custam dez centavos para uma dúzia em suas opulentas mansões.",
  str_item_3661035 = "Traje formal digno",
  str_item_intro_3661035 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nEste traje é elegante e solene o suficiente até mesmo para as maiores cerimônias, festivais ou bailes em Lumopolis, onde a etiqueta é tida em alta estima. Quando usado por alguém com boa aparência e bom gosto, o usuário atrai o olhar de todos e se torna a estrela da multidão.",
  str_item_3661209 = "Resort Lounge com Sombra Solar",
  str_item_intro_3661209 = "Item de mobília. Pode ser colocado em quartos no seu Colossus.\nNenhum destino de férias está completo sem ele, proporcionando relaxamento e proteção contra o sol. Faltar até mesmo uma das duas peças diminui o espírito de férias.",
  str_item_3661210 = "Parede de Anúncios do Parque de Diversões",
  str_item_intro_3661210 = "Item de mobília. Pode ser colocado em salas no seu Colossus.\nAparentemente indispensável em todo parque de diversões - colossal, chamativo, decorado com padrões cativantes que parecem convidar: \"Venha e veja! Não perca!\"",
  str_item_3661211 = "Caminhão de Sorvete do Resort",
  str_item_intro_3661211 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nTais carrinhos oferecem guloseimas geladas nos dias escaldantes de verão. Eles funcionam como mini estações de reposição espalhadas pelo parque de diversões, atraindo sempre crianças que ficam ao redor e querem mais.",
  str_item_3661212 = "Pônei da Primavera no Resort",
  str_item_intro_3661212 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUm recurso de diversão adorado pelas crianças. Com molas sob ele, fazendo o cavaleiro saltar suavemente para cima e para baixo, sempre provoca um coro interminável de gritos animados dos pequenos.",
  str_item_3661213 = "Jet Ski Oásis",
  str_item_intro_3661213 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nCorridas de jet ski são possíveis até mesmo no meio do deserto! Quem diria! Tudo graças às abundantes águas do extenso oásis que os jet skis encontram seu propósito, evitando se tornarem relíquias do passado.",
  str_item_3661214 = "Planta de Cacto do Deserto",
  str_item_intro_3661214 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nA planta mais comum no deserto, incrivelmente adaptada às condições áridas. É vista como um símbolo de tenacidade, levando as pessoas a transplantá-la para vasos como decoração de casa. Mas lembre-se, nunca regue demais - ela pode se afogar caso contrário.",
  str_item_level_2905111 = "Campo de energia",
  str_item_10000100 = "Caixa de seleção auroriana de água",
  str_item_10000101 = "Caixa de seleção auroriana de fogo",
  str_item_10000102 = "Caixa de seleção auroriana da floresta",
  str_item_10000103 = "Caixa de seleção do trovão auroriano",
  str_item_intro_10000100 = "Após o uso, você pode selecionar um dos seguintes Aurorianos de 5 estrelas para participar de sua aventura. (<color=#ffffff>Noah, Hydrad, Barton, Kleken, Philyshy, Corax</color>)",
  str_item_intro_10000101 = "Após o uso, você pode selecionar um dos seguintes Aurorianos de 5 estrelas para participar de sua aventura. (<color=#ffffff>Faust, Regina, Benny and Curo, Leona, Istvan, Maggie, Barbara</color>)",
  str_item_intro_10000102 = "Após o uso, você pode selecionar um dos seguintes Aurorianos de 5 estrelas para participar de sua aventura. (<color=#ffffff>Louise, Robyn, Odi, Pact, Areia, Sikare, Cuscuta</color>)",
  str_item_intro_10000103 = "Após o uso, você pode selecionar um dos seguintes Aurorianos de 5 estrelas para participar de sua aventura. (<color=#ffffff>Mia, Nemesis, Schwartz, Vivian, Keating, Dayna, Beverly</color>)",
  str_item_3000327 = "Ficha da Máquina de Garra",
  str_item_intro_3000327 = "Esses tokens são usados em máquinas de garra e várias outras instalações de jogos. Cada um apresenta o sorriso alegre de Lorelei, transmitindo seus melhores votos para que todos os convidados tenham uma experiência agradável.",
  str_item_3000328 = "Moeda Denuo Pass",
  str_item_intro_3000328 = "Moedas circuladas dentro do Resort Vale Denuo. Devido à sua alta qualidade e superioridade, podem ser trocadas por moedas de outras facções.\nUse-as com sabedoria no modo de gerenciamento para melhorar os edifícios.",
  str_item_intro_3410627 = "Contém: Cx. Pedido Amarela II ×15, Cx. Pedido Amarela I ×25, Jaspe Amarelo II ×5, Jaspe Amarelo I ×8, Noitium ×35.000, Cx. Pedido de Coalizão I ×8",
  str_item_intro_3410628 = "Contém: Cx. Pedido Amarela III ×15, Cx. Pedido Amarela II ×25, Jaspe Amarelo II ×30, Jaspe Amarelo I ×7, Noitium ×121.000, Cx. Pedido de Coalizão II ×8",
