  str_item_intro_3410643 = "Contém: Cx. Pedido Rubra III ×15, Cx. Pedido Rubra II ×25, Jaspe Rubro II ×30, Jaspe Rubro I ×7, Noitium ×121.000, Cx. Pedido de Coalizão II ×8",
  str_item_intro_3410644 = "Contém: Cx. Pedido Rubra IV ×15, Cx. Pedido Rubra III ×25, Jaspe Rubro III ×25, Jaspe Rubro II ×10, Jaspe Rubro I ×6, Noitium ×331.000, Cx. Pedido de Coalizão III ×8",
  str_item_intro_3410645 = "Contém: Cx. Pedido Amarela II ×15, Cx. Pedido Amarela I ×25, Jaspe Amarelo II ×5, Jaspe Amarelo I ×8, Noitium ×35.000, Cx. Pedido de Coalizão I ×8",
  str_item_intro_3410646 = "Contém: Cx. Pedido Amarela III ×15, Cx. Pedido Amarela II ×25, Jaspe Amarelo II ×30, Jaspe Amarelo I ×7, Noitium ×121.000, Cx. Pedido de Coalizão II ×8",
  str_item_intro_3410647 = "Contém: Cx. Pedido Amarela IV ×15, Cx. Pedido Amarela III ×25, Jaspe Amarelo III ×25, Jaspe Amarelo II ×10, Jaspe Amarelo I ×6, Noitium ×331.000, Cx. Pedido de Coalizão III ×8",
  str_item_intro_3000900 = "Algodão macio que é freqüentemente usado como enchimento ou trabalhado em ornamentos decorativos.",
  str_item_intro_3000901 = "Um material de vestuário comum encontrado em Astra, conhecido por sua resistência, durabilidade e facilidade de tingimento.",
  str_item_intro_3000902 = "Tingir. Sinsa só mostrou a você este único barril, mas ele mencionou que na verdade existem muitos outros barris de várias cores.",
  str_item_intro_3000903 = "Um botão comumente usado na costura. Ele tem um toque frio e é frequentemente confundido com moedas por crianças.",
  str_item_intro_3000904 = "Parece um novelo de lã comum. Sinsa mostrei apenas o preto, com medo de estragar a ordem das cores se brincar com ele.",
  str_item_7000100 = "Caderno de desenho esfarrapado",
  str_item_7000101 = "Fragmento de Caderno de Desenhos: Doutor",
  str_item_7000102 = "Fragmento de Caderno de Desenhos: Pote Vazio",
  str_item_7000103 = "Relatório de diagnóstico",
  str_item_7000104 = "xícara de chá",
  str_item_7000105 = "sapo branco",
  str_item_7000106 = "brinquedo usado",
  str_item_7000107 = "Carta de desculpas",
  str_item_7000108 = "Livro razão danificado",
  str_item_7000109 = "Notas do Pesquisador",
  str_item_7000110 = "Chave inglesa adorável",
  str_item_7000111 = "faixa de cabelo minúsculo",
  str_item_7000112 = "Sapo Orientador",
  str_item_7000113 = "Semente",
  str_item_7000114 = "Fragmento de caderno de rascunhos: Dawn Flor",
  str_item_7000115 = "Fragmento de Caderno de Desenhos: Chave",
  str_item_7000116 = "Fragmento de Sketchbook: Rediesel Boss",
  str_item_7000117 = "Fragmento de Caderno de Desenhos: Colosso",
  str_item_7000118 = "Fragmento de Caderno de Esboços: Príncipe Lírio",
  str_item_7000119 = "Caderno de esboços completo",
  str_item_intro_7000100 = "Caderno de esboços com desenhos simples, com página aberta retratando uma jovem alegremente sentada com três pessoas à sua volta. Estranhamente, todas as cabeças dessas pessoas no desenho foram arrancadas.",
  str_item_intro_7000101 = "Parece que este pedaço de papel foi arrancado de um livro ilustrado. Ele descreve vagamente a cabeça de uma mulher misteriosa vestindo um jaleco branco.",
  str_item_intro_7000102 = "Sobre o pedaço de papel está a imagem de um vaso de flores de cerâmica contendo um pequeno monte de terra.",
  str_item_intro_7000103 = "Um pedaço de papel um tanto desgastado que lembra um relatório de diagnóstico.",
  str_item_intro_7000104 = "Uma xícara de chá requintadamente trabalhada, exibindo valor significativo.",
  str_item_intro_7000105 = "Uma misteriosa criaturinha branca de origem desconhecida. Mostra uma forte predileção por dentes-de-leão.",
  str_item_intro_7000106 = "Um brinquedo com uma aparência distinta. Embora seu design básico pareça bastante comum, ele carrega as marcas de um artesanato requintado.",
  str_item_intro_7000107 = "Um pedaço de papel amassado cheio de caligrafia torta. Apesar de sua aparência desleixada, pode-se sentir as intenções sinceras do escritor.",
  str_item_intro_7000108 = "Um livro antigo que revela a falta de hábitos contábeis do proprietário. Em vez de registrar receitas e despesas, serve como um recipiente para capturar seus pensamentos e ideias talentosos.",
  str_item_intro_7000109 = "Um caderno desgastado, pertencente a alguém de idade avançada.",
  str_item_intro_7000110 = "Uma chave inglesa enorme embelezada com adesivos adoráveis.",
  str_item_intro_7000111 = "Uma faixa de cabeça com padrão intrincado que é pequena o suficiente para ser usada por uma criatura do tamanho de uma boneca.",
  str_item_intro_7000112 = "Um sapo branco com uma faixa na cabeça como um cachecol, acrescentando charme.",
  str_item_intro_7000113 = "Uma semente solitária, como um voto solene, espera ser descoberta no canto.",
  str_item_intro_7000114 = "Uma menina com nome de flores que dão as boas-vindas ao amanhecer. Ela é pequena e radiante como uma flor.",
  str_item_intro_7000115 = "Um pedaço de papel com o desenho de uma chave grande. Uma ferramenta tão grande deve pertencer a alguém alto e bonito.",
  str_item_intro_7000116 = "O líder da Rediesel Wrench, uma figura caminhando através de tempestades, confrontando conspirações e rindo diante do desespero. Sob o exterior de ferro, a gentileza ainda reside.",
  str_item_intro_7000117 = "Um lendário Colosso em forma de dragão, representado com traços adoráveis que lembram uma figura elegante, mas não se pode deixar de admirar suas asas brancas puras.",
  str_item_intro_7000118 = "O mensageiro branco do mundo exterior.",
  str_item_intro_7000119 = "Um caderno de esboços com um estilo de arte fofo, mostrando algumas pessoas rindo alegremente.",
  str_item_sub_intro_7000100 = "\"Estas foram feitas para serem memórias felizes, mas estão cheias de buracos... Quem exatamente eu desenhei nelas naquela época?\"",
  str_item_sub_intro_7000101 = "\"Ei, quem foi tão descuidado a ponto de arrancar o rosto do médico? Foi mordido por um animalzinho? Bem, então não posso fazer nada a respeito.\"",
  str_item_sub_intro_7000102 = "\"Eu também tenho essas bacias de cerâmica em casa! Tenho uma bela coleção porque realmente gosto delas... embora não consiga lembrar o motivo exato de ter gostado delas.\"",
  str_item_sub_intro_7000103 = "\"Medo, raiva, dor... Todos os fatores negativos que afetam seu estado físico e psicológico foram eliminados com sucesso. Parabéns, agora você é uma criança saudável.\"",
  str_item_sub_intro_7000104 = "\"Além de mim, o médico tem outros pacientes para atender. Há uma nobre jovem de Lumopolis que adora chá preto e carrega uma xícara pequena para todo lugar... Espero que ela já tenha se recuperado.\"",
  str_item_sub_intro_7000105 = "\"O que há de errado com sapos? Eu adoro sapos ainda mais!... Hein? Você não é um sapo?\"",
  str_item_sub_intro_7000106 = "\"Para minha amada, quando não podemos estar ao seu lado, que essas pequenas bugigangas tragam alegria a ela...\"",
  str_item_sub_intro_7000107 = "\"Devemos nos abster de usar linguagem chula na frente de ***. Vamos todos responsabilizar uns aos outros. Qualquer um que quebrar esta regra terá que comer dezoito garrafas de molho de pimenta cru, e eu não sou exceção.\"",
  str_item_sub_intro_7000108 = "\"Devo dizer que estou profundamente surpreso com sua intensidade. Certa vez, acreditei que o nível de ** representava o limite do que as sementes poderiam alcançar e que o verdadeiro avanço deveria estar na influência de ** sobre a personalidade de alguém. No entanto, o poder bruto, violento e inimaginável de ** me cativou. Estou surpreso que as sementes possam exercer tais habilidades. Essa força, esse poder, é exatamente o que **** precisa. Agora anseio pelo poder de ** para remodelar o mundo.\"",
  str_item_sub_intro_7000109 = "\"Quando chegamos ao local, ficamos totalmente chocados com os vestígios devastadores de destruição. Especulamos que um indivíduo liberou uma energia imensa, destruindo todas as instalações e edifícios do subsolo à superfície... É difícil imaginar que tipo de monstro poderia possuir tanto poder...\"",
  str_item_sub_intro_7000110 = "\"Esses adesivos com estampas de flores parecem familiares... Eu os coloquei?\"",
  str_item_sub_intro_7000111 = "\"Uma tiara branca com listras pretas... onde eu já vi isso antes...\"",
  str_item_sub_intro_7000112 = "\"Que mensagem você tem para mim? Você vai me guiar, uma alma perdida, ao longo do caminho?\"",
  str_item_sub_intro_7000113 = "\"Se você tirar as flores do meu mundo, meu coração vai afundar ainda mais em um abismo de longo alcance, suponho.\"",
  str_item_sub_intro_7000114 = "\"Quero voltar e plantar flores por toda a Garganta dos Olhos Vermelhos.\"",
  str_item_sub_intro_7000115 = "\"Com tais habilidades, você pode realmente capturar a grandiosidade desta chave... Se alguém se atrever a criticá-la, eles podem realmente experimentar o poder da chave...\"",
  str_item_sub_intro_7000116 = "\"Ele sempre consegue me encontrar!\"",
  str_item_sub_intro_7000117 = "\"Adivinha que tipo de pessoa pode controlar um Colosso tão magnífico... Você está brincando comigo! Eu não estava zombando Lepidoz de forma alguma! Isso é tão injustorrrrrrr—\"",
  str_item_sub_intro_7000118 = "\"Fique vivo e nos encontraremos novamente.\"",
  str_item_sub_intro_7000119 = "\"O mundo real e a felicidade genuína.\"",
  str_item_get_7000100 = "Obtido em Sonho: Despertar na Tempestade",
  str_item_get_7000101 = "Obtido em Sonho: Despertar na Tempestade",
