  str_item_7000200 = "Lupa",
  str_item_7000201 = "Pena",
  str_item_7000202 = "Relatório de Notas",
  str_item_7000203 = "Bastão Apontador",
  str_item_7000204 = "Precedente Legal (1)",
  str_item_7000205 = "Relatório Confidencial de Investigação",
  str_item_7000206 = "Precedente Legal (2)",
  str_item_intro_7000200 = "Uma lupa de design único e cores distintas, uma ferramenta indispensável em investigações.",
  str_item_intro_7000201 = "Uma pena dourada cintilante que parece pesada em sua mão.",
  str_item_intro_7000202 = "Um boletim de notas perfeito da Dawn Academia, mostrando um desempenho de alto nível.",
  str_item_intro_7000203 = "Uma bengala escondida em um canto, aparentemente discreta, evocando memórias da infância de Irridon.",
  str_item_intro_7000204 = "Um precedente deixado pelo Juiz Rodell Novek, refletindo sua própria natureza fria e implacável.",
  str_item_intro_7000205 = "Um relatório confidencial de investigação escrito pelo pai de Irridon, muito antes do julgamento do testamento do Barão, ele já sabia das intenções ocultas por trás do testamento.",
  str_item_intro_7000206 = "Um precedente deixado pelo juiz Rodell Novek, com um veredicto resultando na erradicação de uma família inteira.",
  str_item_sub_intro_7000200 = "\"É apenas minha imaginação, ou essa lupa está realmente chamando meu nome? Bem, isso não pode ser possível. Mas essa lupa parece estranhamente familiar... Será que é minha? O que está acontecendo comigo? Como não consigo me lembrar de algo assim?\"",
  str_item_sub_intro_7000201 = "\"Por que isso? Por que nunca consigo ganhar a aprovação deles, seja do meu pai ou dos meus colegas...\"",
  str_item_sub_intro_7000202 = "\"Eu não dei o meu melhor...?\"",
  str_item_sub_intro_7000203 = "\"Quanto esforço é necessário para esquecer aqueles momentos sombrios da minha infância?\"",
  str_item_sub_intro_7000204 = "\"Devo levar adiante o pensamento por trás dessa decisão...\"",
  str_item_sub_intro_7000205 = "O-O que eu fiz...?",
  str_item_sub_intro_7000206 = "\"Eu acredito... que tenho minha própria resposta.\"",
  str_item_7000300 = "Obter Evidências",
  str_item_7000301 = "Obter Depoimento",
  str_item_7000302 = "Obter Evidências",
  str_item_7000303 = "Obter Depoimento",
  str_item_7000304 = "Obter Estatuto",
  str_item_7000305 = "Obter Estatuto",
