  str_item_7000307 = "Obter Evidências",
  str_item_7000308 = "Obter Depoimento",
  str_item_7000309 = "Obter Depoimento",
  str_item_7000310 = "Obter Estatuto",
  str_item_7000311 = "Obter Estatuto",
  str_item_7000312 = "Obter Evidências",
  str_item_7000313 = "Obter Evidências",
  str_item_7000314 = "Obter Depoimento",
  str_item_7000315 = "Obter Depoimento",
  str_item_7000316 = "Obter Estatuto",
  str_item_7000317 = "Obter Estatuto",
  str_item_7000318 = "Peso Dourado",
  str_item_7000319 = "Peso Dourado",
  str_item_7000320 = "Peso Dourado",
  str_item_intro_7000300 = "Nodirri não parece ter o emblema com ela.",
  str_item_intro_7000301 = "Depoimento de um membro do conselho estudantil: A família da Pam está enfrentando dificuldades financeiras.",
  str_item_intro_7000302 = "Existe uma relação competitiva entre Nodirri e Pam.",
  str_item_intro_7000303 = "Depoimento do porteiro idoso: Nodirri já visitou a sala de estudo individual antes.",
  str_item_intro_7000304 = "Crime contra a Propriedade",
  str_item_intro_7000305 = "Ofensa à Ordem Pública",
  str_item_intro_7000306 = "O testamento do avô foi confirmado como autêntico.",
  str_item_intro_7000307 = "As impressões digitais de Jerry foram encontradas nas ferramentas usadas pelo avô para cometer suicídio.",
  str_item_intro_7000308 = "Depoimento do vizinho: O avô mencionou querer passar tudo para sua neta.",
  str_item_intro_7000309 = "Depoimento da testemunha: Não foram observadas anomalias quando o avô redigiu seu testamento.",
  str_item_intro_7000310 = "Falsificação de Documentos",
  str_item_intro_7000311 = "Lei de Herança Testamentária",
  str_item_intro_7000312 = "O emblema da família Pyrrhus encontrado no quarto dos Gautier.",
  str_item_intro_7000313 = "Maldições escritas por Mirren Gautier em seu caderno de esboços.",
  str_item_intro_7000314 = "A família Gautier capturou membros da família Pyrrhus para experimentos.",
  str_item_intro_7000315 = "A família Pyrrhus ainda está pesquisando os Cristais Sanguíneos.",
  str_item_intro_7000316 = "Traição",
  str_item_intro_7000317 = "Crime de Espalhar Rumores",
  str_item_intro_7000318 = "Evidência encontrada para o caso de roubo do Emblema Dawn!",
  str_item_intro_7000319 = "Evidência encontrada para o Caso do Testamento do Avô!",
  str_item_intro_7000320 = "Evidências encontradas para o Caso de Traição da Família Gautier!",
  str_item_sub_intro_7000300 = "Ao ouvir o relato de Pam sobre o caso, Nodirri fica visivelmente enfurecida. Ela se aproxima de Pam, fazendo uma série de perguntas sobre por que ela a difamaria dessa maneira. Para provar sua inocência, Nodirri permite que Irridon a reviste e, como esperado, nada incriminador é encontrado.",
  str_item_sub_intro_7000301 = "No caminho para a sala de estudo individual, Irridon é abordado discretamente por um membro do conselho estudantil, que compartilha apaixonadamente sua perspectiva: \"A família da Pam nunca foi uma casa nobre de alta posição, e seus pais nunca ocuparam cargos públicos oficiais. Ultimamente, parece que eles estão enfrentando dificuldades financeiras por algum motivo!\"",
  str_item_sub_intro_7000302 = "No quadro de avisos da escola, Irridon se depara com um anúncio do Templo de Lumópolis: este ano, eles aceitaram duas noviças em treinamento, Pam e Nodirri. No entanto, apenas uma delas terá a chance de permanecer no templo.",
  str_item_sub_intro_7000303 = "Irridon chega perto da sala de estudo e vê um porteiro idoso cochilando por perto. Claramente, o porteiro não esqueceu Irridon, que já o ajudou várias vezes durante a escola. O porteiro menciona que hoje, além de Pam, apenas Nodirri entrou na sala de estudo. Ele achou estranho na época por que Nodirri usou um lenço para abrir a porta. \"Talvez ela seja uma germofóbica; eu não dei muita importância naquele momento.\"",
  str_item_sub_intro_7000304 = "O roubo de propriedade significativa, quando o valor roubado é substancial, é punível com prisão de três a dez anos e multa.",
  str_item_sub_intro_7000305 = "Insultar publicamente ou difamar intencionalmente outras pessoas, em circunstâncias graves, pode levar a uma pena de prisão de até três anos e uma multa.",
  str_item_sub_intro_7000306 = "Jerry apresenta o testamento que tem em mãos a Irridon, e após uma comparação e análise meticulosas, Irridon confirma que o testamento do avô de Pam foi realmente escrito por ele mesmo. No testamento, o avô deixa seu título e riqueza para Jerry, declarando: \"Eu vivi tempo suficiente e não tenho arrependimentos.\" Irridon presta muita atenção a essa declaração, pois parece que o avô insinuou sua intenção de suicídio ao escrever o testamento.",
  str_item_sub_intro_7000307 = "Irridon chega à residência do avô de Pam e descobre que ele tirou a própria vida usando uma pequena faca de frutas. No entanto, após uma inspeção minuciosa da faca, Irridon identifica as impressões digitais de Jerry nela. Jerry explica que costuma preparar refeições, então ter suas impressões digitais nos talheres não é incomum. Irridon reavalia a situação e confirma o suicídio do avô.",
  str_item_sub_intro_7000308 = "Irridon bate na porta do vizinho do avô e o vizinho conta a Irridon que, embora o avô frequentemente lamentasse as inadequações de seu filho, ele se gabava constantemente de sua neta. O avô até mesmo declarou publicamente que pretendia passar seu título e riqueza para sua neta, não deixando nada para seu filho.",
  str_item_sub_intro_7000309 = "A testemunha do testamento é um velho servo bem instruído. O velho servo expressa imensa honra por ser convidado pelo avô para ser a testemunha. Logo que as palavras saem da boca do velho servo, ele de repente sente que se expressou mal. Um pouco envergonhado, o servo continua a explicar que não houve nada de incomum quando o avô redigiu o testamento, e ele confirmou repetidamente que essas eram de fato as verdadeiras intenções do avô.",
  str_item_sub_intro_7000310 = "A falsificação de documentos públicos ou privados para atividades fraudulentas é punível com prisão de três a dez anos e multa.",
  str_item_sub_intro_7000311 = "Testamentos legalmente válidos devem ser seguidos na distribuição de propriedades conforme seu conteúdo.",
  str_item_sub_intro_7000312 = "Irridon invade sorrateiramente o quarto pertencente à família Gautier em Lumópolis Inferior, vasculhando cuidadosamente. Para sua surpresa, ela descobre um emblema da família Pyrrhus escondido em um canto. Ambas as famílias Gautier e Pyrrhus foram exiladas para Lumópolis Inferior devido ao caso do Cristal Sanguíneo. Será possível que essas duas famílias estejam colaborando em uma rebelião? Irridon não ousa pensar mais nisso. \"Pam também é membro da família Pyrrhus...\"",
  str_item_sub_intro_7000313 = "Irridon se depara com outra casa em ruínas e, lá dentro, encontra um caderno de esboços assinado por \"Mirren Gautier\". O livro contém alguns padrões abstratos que Irridon acha difícil de compreender. Irridon franze a testa e, entre os padrões, descobre uma pequena linha de texto: \"Por que você me trata assim... Por quê, POR QUÊ?! Vou assumir o controle do meu próprio destino novamente... mesmo que isso signifique que eu tenha que usar a força deles.\"",
  str_item_sub_intro_7000314 = "Um Eclipsita estranho surge repentinamente na rua. Sem hesitar, Irridon avança e perfura o peito do Eclipsita, fazendo-o cair no chão. Mas, de repente, como se despertasse de um transe, o Eclipsita levanta a mão na direção do público, aparentemente lutando para dizer algo. Irridon se aproxima, ouvindo os murmúrios do Eclipsita: \"Gautier... buscando vingança... contra Pyrrhus... eles... nos capturaram... para experimento... eles estão planejando... uma rebelião!\"",
  str_item_sub_intro_7000315 = "Enquanto Irridon contempla seu próximo passo para a investigação, um transeunte maltrapilho se aproxima discretamente. Ele afirma saber tudo sobre os acontecimentos recentes na Baixa Lumópolis, revelando que a família Pyrrhus ainda está conduzindo pesquisas sobre os Cristais Sanguíneos. Irridon pergunta por que ele está compartilhando essa informação, e o transeunte abre os lábios, revelando seus dentes escurecidos e dizendo: \"Você pode me levar de volta ao Pátio de Lumópolis?\"",
  str_item_sub_intro_7000316 = "Tramar deliberadamente ou tentar derrubar o governo de Lumopolis resultará em prisão perpétua, com a possibilidade de pena de morte para casos graves.",
  str_item_sub_intro_7000317 = "Espalhar boatos falsos sobre os outros intencionalmente pode levar a prisão de até um ano e uma multa.",
  str_item_sub_intro_7000318 = "Com base em evidências e declarações de testemunhas, Irridon deduz que Nodirri é o culpado que roubou o Emblema Dawn.",
  str_item_sub_intro_7000319 = "Você considera o testamento válido e o servo Jerry herdará o título do avô de Pam e toda a sua riqueza...",
  str_item_sub_intro_7000320 = "Você coletou provas abrangentes e depoimentos, confirmando que Mirren Gautier sequestrou membros da casa Pyrrhus para experimentação e tinha intenções rebeldes.",
  str_item_7000400 = "Chave Antiga",
  str_item_7000401 = "Cookies de Dayna",
  str_item_7000402 = "Projeto para Novo Lar",
  str_item_7000403 = "Trombone Imponente",
  str_item_7000404 = "Nova Partitura",
  str_item_7000405 = "Retrato de Dayna",
  str_item_7000406 = "Retrato de Robyn",
  str_item_7000407 = "Senhora no Retrato do Bule",
  str_item_7000408 = "Retrato do Golfinho Branco",
  str_item_intro_7000400 = "Chave do sótão dada a Connolly por sua tia. Use-a com cuidado para que o antigo trinco não faça barulho e incomode os outros.",
  str_item_intro_7000401 = "Biscoitos que Connolly trouxe para Dayna, mas foram roubados pelos guardas tritões. Estes são sem açúcar, conforme o pedido de Dayna.",
  str_item_intro_7000402 = "Rascunho para a fortaleza do Senhor Aqua. Provavelmente não está correto, mas Queen Connolly reserva todos os direitos de interpretação.",
  str_item_intro_7000403 = "Este novo instrumento musical encontrado pelos moradores da cidade para Connolly pode produzir sons mais altos e autoritários para transmitir raiva.",
  str_item_intro_7000404 = "A Partitura Aqua que Connolly encontrou no antigo sótão, agora assinada com um novo nome.",
  str_item_intro_7000405 = "Um retrato de Dayna pintado por um artista em uma cidade subaquática, atualmente colocado em um assento vazio por Queen Connolly como um adereço durante o ensaio de seu discurso.",
  str_item_intro_7000406 = "Um retrato de Robyn pintado por um artista em uma cidade submarina, atualmente colocado em um assento vazio por Queen Connolly como um adereço durante o ensaio de seu discurso.",
  str_item_intro_7000407 = "Um retrato de um consultor misterioso pintado por um artista em uma cidade subaquática, atualmente colocado em um assento vazio por Queen Connolly como um adereço durante o ensaio de seu discurso.",
  str_item_intro_7000408 = "Um retrato de um peixe amigável pintado por um artista em uma cidade submarina, atualmente colocado em um assento vazio por Queen Connolly como um adereço durante o ensaio de seu discurso.",
  str_item_sub_intro_7000400 = "\"Ela dorme no sótão, comendo o que os outros recusaram. Falando em sussurros suaves, se escondendo nos cantos mais distantes! Varrendo o quarto durante o dia, tocando o instrumento à noite. Confortando seu coração solitário com música!\"",
  str_item_sub_intro_7000401 = "\"Meus biscoitos! Connolly me deu isso! Por que os lacaios imundos não poupariam nem os biscoitos!\"",
  str_item_sub_intro_7000402 = "\"Outro mundo de... estética grandiosa... deleite nela!\"",
  str_item_sub_intro_7000403 = "\"Dor e tristeza... encontrarão salvação na música!\"",
  str_item_sub_intro_7000404 = "\"Ele já expressou o desejo de que eu lhe desse um novo nome. Pensei muito. Rubinstein, Salieri, Leopold, Dvorak... Esses eram todos os seus favoritos... O quê, algo mais íntimo?\"",
  str_item_sub_intro_7000405 = "\"Eu estava sendo muito cáustico, você disse? Como eu não poderia ser, quando estava defendendo meus irmãos?\"",
  str_item_sub_intro_7000406 = "\"Sim, um peixe já me chamou de achatado e pouco perceptível antes... Mas é exatamente assim que eu sobrevivo...\"",
  str_item_sub_intro_7000407 = "\"Você quer que eu saia da aposentadoria? Bem, isso vai te custar.\"",
  str_item_sub_intro_7000408 = "\"Quem sou eu para Queen Connolly, você pergunta? Isso é confidencial!\"",
  str_item_7000801 = "Antiguidade",
  str_item_intro_7000801 = "Antiguidades encontradas em cada canto da Baía dos Pavilhões Gêmeos. Os artefatos culturais de Longzhou são altamente valorizados em outros países, mas alguns são obtidos através de transações honestas envolvendo pedidos e pagamentos correspondentes, enquanto outros são roubados nas sombras por ladrões.",
  str_item_6030101 = "Caderno de esboços em miniatura",
  str_item_6030102 = "Temperatura do Sorriso",
  str_item_6030103 = "de Eva Dawn",
  str_item_6030104 = "Templo de Lumópolis",
  str_item_6030105 = "Arte do Equilíbrio",
  str_item_6030106 = "Oração Inocente",
  str_item_6030107 = "Placa Aqua",
  str_item_6030108 = "Solo de Amor",
  str_item_6030109 = "Lar Maravilhoso",
  str_item_6030110 = "Sonhos de Glicínia",
  str_item_6030111 = "A Flor e a Espada Mágica",
  str_item_6030112 = "Barco dos Sonhos",
  str_item_6030113 = "Seu Olhar Atento",
  str_item_6030114 = "Seu Sagrado Juramento",
  str_item_6030115 = "Espada Regal",
  str_item_6030116 = "Locomotiva Doce",
  str_item_6030117 = "Novo Visual da Pedra de Caça",
  str_item_6030118 = "Floresta Creme",
  str_item_6030119 = "Placa de Identificação do Soldado",
  str_item_6030120 = "Luz da Luz Estelar",
  str_item_6030121 = "Bandeira de Illumina",
  str_item_6030122 = "Pensamento de Nikinis",
  str_item_6030123 = "Desejo de Nepolis",
  str_item_6030124 = "Espelho de Northland",
  str_item_intro_6030101 = "Medalhão Stand By Me. \nO pequeno caderno de esboços retrata padrões infantis, mas não consegue esconder os sentimentos de relutância e apego internos, tornando difícil se desapegar.",
  str_item_intro_6030102 = "Medalhão Stand By Me.\nMesmo que chegue o dia do juízo final, ele sempre preparará água na temperatura certa para sua irmã mais nova.",
  str_item_intro_6030103 = "Medalhão Stand By Me.\nNaqueles anos sombrios, esta flor foi o seu amanhecer.",
  str_item_intro_6030104 = "Medalhão Stand By Me.\nUm reconhecimento do Templo de Lumopolis.",
  str_item_intro_6030105 = "Medalhão Stand By Me.\nO olhar atento de Irridon não poupa nenhuma balança desequilibrada.",
  str_item_intro_6030106 = "Medalhão Stand By Me.\nNaquela época, Paloma ainda estava disposto a acreditar...",
  str_item_intro_6030107 = "Medalhão Stand By Me.\nEsta é a apreciação do grande Senhor Aqua! Vocês, mortais, estiquem seus membros para receber minha graça!",
  str_item_intro_6030108 = "Medalhão Stand By Me.\nJoguei isso sozinho com a esperança dos membros da minha família, o cuidado dos meus companheiros, bem como... amor e coragem.",
  str_item_intro_6030109 = "Medalhão Stand By Me.\nEu procurava apenas um abrigo, mas para minha surpresa, transformei-o em um lar maravilhoso.",
  str_item_intro_6030110 = "Medalhão Stand By Me. \nEsse calor que sinto agora é o brilho do sol da manhã ou o seu calor depois de passar pelos espinhos afiados?",
  str_item_intro_6030111 = "Medalhão Stand By Me. Pouquíssimas pessoas sabem que a flor da árvore casta também floresce. No entanto, é menor que uma flor de glicínia, tem uma cor lavanda suave e se parece com a saia de um espadachim.",
  str_item_intro_6030112 = "Medalhão Stand By Me. \nQuando ela passar pelo murmurante Rio Dourado um dia, ela se lembrará do passeio de barco em seus sonhos e ansiará por compartilhar um barco com uma certa pessoa.",
  str_item_intro_6030113 = "Medalhão Stand By Me.\n\"Você é a razão pela qual o mundo vale a pena minha proteção.\"",
  str_item_intro_6030114 = "Medalhão Stand By Me.\n\"Você é a razão pela qual eu quero proteger este mundo.\"",
  str_item_intro_6030115 = "Medalhão Stand By Me. \nFoi imbuído de uma força extraordinária através da infusão do amor de Regal. Talvez este seja o único motivo pelo qual ela pode permanecer ao lado dele em uma forma diferente.",
  str_item_intro_6030116 = "Um Medalhão Stand By Me. \nQuando parte, parece uma máquina fria e insensível. Somente quando retorna é que sua doce natureza se torna aparente.",
  str_item_intro_6030117 = "Um Medalhão Stand By Me.\nJá que se livrar dele é impossível... Pode muito bem servir como um acessório de moda único.",
  str_item_intro_6030118 = "Um Medalhão Stand By Me. \nÁrvores fluindo com creme espesso e flores carregando as frutas mais doces... O lugar perfeito para um piquenique, caso a oportunidade surja.",
  str_item_intro_6030119 = "Medalhão Stand By Me. \nCada etiqueta representa uma vida. May que todas essas almas resplandecentes descansem em paz.",
  str_item_intro_6030120 = "Medalhão Stand By Me. Quem são os pais dessa pessoa? Essa pessoa tem filhos ou irmãos? O nome inscrito na pedra permanece em silêncio enquanto reflete o caminho à frente.",
  str_item_intro_6030121 = "Medalhão Stand By Me. \nBandeiras tremulam ao vento enquanto o chamado para as armas soa. Os defensores mais altruístas de Astra avançam destemidos, nunca recuando enquanto mantêm a escuridão à distância.",
  str_item_intro_6030122 = "Medalhão Stand By Me.\n\"Tudo que eu quero é ficar ao lado da minha irmã...\"",
  str_item_intro_6030123 = "Medalhão Stand By Me.\n\"Tudo que eu desejo é que minha irmãzinha sobreviva...\"",
  str_item_intro_6030124 = "Medalhão Stand By Me. \nEste espelho testemunhou a queda de muitas coisas. Talvez seja hora de ver algo novo.",
  str_item_6130101 = "Laje Memorial Stand By Me",
  str_item_6130102 = "Placa de Espelho Stand By Me",
  str_item_6130103 = "Quadro de Concerto Stand By Me",
  str_item_6130104 = "Quadro dos Sonhos Stand By Me",
  str_item_6130105 = "Quadro de Olhares Compartilhados",
  str_item_6130106 = "Quadro Stand By Me",
  str_item_6130107 = "Stand By Me Quadro Militar",
  str_item_6130108 = "Quadro de Poema Stand By Me",
  str_item_intro_6130101 = [[
Placa comemorativa Stand By Me.
Acabou; o passado se foi. Vamos voltar para casa.]],
  str_item_intro_6130102 = "Placa Comemorativa Stand By Me.\nO que está no espelho, vamos acordar juntos.",
  str_item_intro_6130103 = "Placa Comemorativa Stand By Me.\nMinha mente nunca foi tão forte e minha voz nunca foi tão melodiosa.",
  str_item_intro_6130104 = "Placa comemorativa Stand By Me.\nEla luta contra a maldição todos os dias depois de acordar de manhã, mas seus sonhos são brilhantes: ela receberá a fraca luz da manhã em uma cidade arrumada e movimentada.",
  str_item_intro_6130105 = "Placa Comemorativa Stand By Me.\nEmbora mil anos possam ter desaparecido como poeira, dissipando-se no nada, meu coração permanece firme.",
  str_item_intro_6130106 = "Uma Placa Comemorativa Stand By Me.\nClic-clic, clic-clic! Agarrado aos trilhos, o trem atravessa um sonho brilhante. Ele passa pela Floresta Creme, por uma fonte de mel, e pelos arrependimentos fermentando de um viajante solitário...",
  str_item_intro_6130107 = "Placa comemorativa Stand By Me.\n\"Estou disposto a ser temperado inúmeras vezes, pois acredito firmemente que essas provações me levarão à luz de Illumina. A bala de metal completo afiada encapsula nossas aspirações inabaláveis.\"",
  str_item_intro_6130108 = "Placa Comemorativa Stand By Me. \n\"Seu corpo está sepultado na neve, sua alma é presa pelo espelho, e seu rosto é coroado com flores murchas, mas seu amor nunca murcha.\"",
  str_item_3001000 = "fragmentos de sonho",
  str_item_intro_3001000 = "Fragmentos obtidos de uma história onde realidade e ilusão se entrelaçam, recontando traços do mundo real. Eles podem ser trocados por recompensas de itens na loja Paisagens Autênticas dos Sonhos.",
  str_item_get_3001000 = "Dream - Conversão de Expiração de Tokens da Loja Temática",
  str_item_3001001 = "metamorfo",
  str_item_intro_3001001 = "Uma lembrança deixada para trás depois de enfrentar desafios e experimentar o crescimento. Pode ser trocado por recompensas de itens em Dream - Awakening in the Storm - Memory Workshop.",
  str_item_get_3001001 = "Sonho - Despertar na fase da Tempestade",
  str_item_3001002 = "fragmento de sedimento",
  str_item_intro_3001002 = "Fragmentos obtidos após enfrentar desafios e vivenciar o crescimento. Eles podem ser trocados por recompensas de itens em Dream - Awakening in the Storm - Memory Workshop.",
  str_item_get_3001002 = "Sonho - Despertar na fase da Tempestade",
  str_item_3001003 = "sagacidade",
  str_item_intro_3001003 = "O fator chave para Eve permanecer racional e lúcida, permitindo que ela enfrente o Presságio em Despertar na Tempestade. O ponto de Sabedoria será reposto em 3 pontos todos os dias às 05:00 (UTC+0) ou 00:00 (UTC-5) (Nenhum ponto será dado se o limite for atingido).",
  str_item_get_3001003 = "Recuperação automática ao longo do tempo",
  str_item_3001004 = "ondas de alegria",
  str_item_intro_3001004 = "A xícara favorita de Eve contém apenas água comum, mas alimenta sua força. Colete e atualize o nível \"Sorrisos Levam à Felicidade\".",
  str_item_get_3001004 = "Obtenha pela primeira vez concluindo os estágios Nightmare no Dream with 3-Star.",
  str_item_3001005 = "Contrapesos da Alma",
  str_item_intro_3001005 = "Um peso obtido durante a busca pela verdadeira identidade para equilibrar as balanças da vida. Pode ser usado para trocar recompensas de itens em Sonho - Provas Entre Ondulações Douradas - Leilão de Provas.",
  str_item_get_3001005 = "Sonho - Etapa dos Julgamentos Entre Ondulações Douradas",
  str_item_3001006 = "Vela da Justiça",
  str_item_intro_3001006 = "Uma chama de vela estrelada deixada para trás no caminho da busca da justiça no coração de alguém. Pode ser usada para trocar recompensas de itens em Sonho - Provas Entre Ondulações Douradas - Leilão de Provas.",
  str_item_get_3001006 = "Sonho - Etapa dos Julgamentos Entre Ondulações Douradas",
  str_item_3001007 = "sagacidade",
  str_item_intro_3001007 = "Como a chave para ajudar a manter a racionalidade e a clareza, ela será consumida durante a exploração, mas pode se reabastecer gradualmente com o tempo.",
  str_item_get_3001007 = "Recuperação automática ao longo do tempo",
  str_item_3001008 = "Luz da Justiça",
  str_item_intro_3001008 = "A luz da justiça que Irridon reconquistou através de seus próprios esforços. Acumule-a para aumentar o nível do Foco da Verdade.",
  str_item_get_3001008 = "Obtenha pela primeira vez concluindo os estágios Nightmare no Dream with 3-Star.",
  str_item_3001010 = "Concha Ecoante",
  str_item_intro_3001010 = "Dentro desta concha que ecoa melodias estão os fragmentos de partituras antigas que podem ser trocados por prêmios no Sonho: Café Bolhas Subaquáticas da Fantasia Submarina de Connolly.",
  str_item_get_3001010 = "Sonho: Palco da Fantasia Subaquática de Connolly",
  str_item_3001011 = "Delicioso Fluorófora",
  str_item_intro_3001011 = "Algas brilhantes no canto do fundo do oceano costumavam ser usadas para fazer uma bebida popular do mar profundo. Resgatável por prêmios no Sonho: Café Sea Bubbles da Fantasia Subaquática de Connolly.",
  str_item_get_3001011 = "Sonho: Estágio de Fantasia Subaquática de Connolly",
  str_item_3001012 = "sagacidade",
  str_item_intro_3001012 = "Como a chave para ajudar a manter a racionalidade e a clareza, ela será consumida durante a exploração, mas pode se reabastecer gradualmente com o tempo.",
  str_item_get_3001012 = "Sonho: Estágio de Fantasia Subaquática de Connolly",
  str_item_3001013 = "Estudo do Pact",
  str_item_intro_3001013 = "A tentativa de Connolly em compreender tudo descrito pelo Senhor Aqua e fazer sentido da sabedoria profunda. Acumule para melhorar o nível de Conexão Aqua.",
  str_item_get_3001013 = "Obtenha pela primeira vez concluindo os estágios Nightmare no Dream with 3-Star.",
  str_item_3001014 = "Presilha de Glicínia",
  str_item_intro_3001014 = "Um grampo de cabelo feito de pequenas flores resistentes que pode ser usado para resgatar recompensas de itens em Sonho - Canção da Espada Sob um Dossel de Sonhos - Troca Verdejante.",
  str_item_get_3001014 = "Sonho - Canção da Espada Sob um Dossel de Sonhos Palcos",
  str_item_3001015 = "Moeda Antiga de Cobre",
  str_item_intro_3001015 = "Uma moeda antiga enferrujada do Oriente que não é mais usada como forma de moeda ao longo do tempo. Pode ser usada para resgatar recompensas de itens em Sword Song Under a Canopy of Dreams - Troca Verdejante.",
  str_item_get_3001015 = "Sonho - Canção da Espada Sob um Dossel de Sonhos Palcos",
  str_item_3001016 = "sagacidade",
  str_item_intro_3001016 = "Como a chave para ajudar a manter a racionalidade e a clareza, ela será consumida durante a exploração, mas pode se reabastecer gradualmente com o tempo.",
  str_item_get_3001016 = "Sonho - Canção da Espada Sob um Dossel de Sonhos Palcos",
  str_item_3001017 = "Vontade de Forjar Espada",
  str_item_intro_3001017 = "Cada batalha é uma chance de melhorar a esgrima de um espadachim. A melhoria constante levará a uma mudança qualitativa. Acumule para melhorar o nível do Coração da Espada.",
  str_item_get_3001017 = "Obtenha pela primeira vez concluindo os estágios Nightmare no Dream with 3-Star.",
  str_item_3001018 = "Capital de Giro",
  str_item_intro_3001018 = "Como diriam as pessoas de Umbraton, a Guilda Índigo começou como apenas uma guilda vazia, mas não é do estilo de seu fundador dizer não ao dinheiro, então por que não operá-la como uma guilda adequada?",
  str_item_3001019 = "Energia Auspiciosa",
  str_item_intro_3001019 = "A Energia Auspiciosa obtida de transações monetárias e financeiras comerciais pode ser usada para melhorar o Feng Shui e eliminar o mal.",
  str_item_3001021 = "Guirlanda de Prata",
  str_item_intro_3001021 = "A guirlanda de ramos de oliveira simboliza vitória e paz. Resgatável por prêmios no Sonho - Vigília de Mil Anos - Mercado Northwind.",
  str_item_get_3001021 = "Sonho - Uma Vigília de Mil Anos",
  str_item_3001022 = "Moeda do Vigia",
  str_item_intro_3001022 = "Moeda de Bronze criada para comemorar o triunfo da Legião Northwind. Resgatável por prêmios no Sonho - Vigília de Mil Anos - Mercado Northwind.",
  str_item_get_3001022 = "Sonho - Uma Vigília de Mil Anos",
  str_item_3001023 = "sagacidade",
  str_item_intro_3001023 = "Como a chave para ajudar a manter a racionalidade e a clareza, ela será consumida durante a exploração, mas pode se reabastecer gradualmente com o tempo.",
  str_item_get_3001023 = "Recuperação automática ao longo do tempo",
  str_item_3001024 = "Orelha de Trigo Perfumada",
  str_item_intro_3001024 = "O confortante aroma de trigo, simbolizando promessas para um futuro brilhante, é um lembrete constante para a alma dentro da espada - não parta ainda. Acumule para aumentar o nível da Alma da Espada.",
  str_item_3001025 = "Fragmento de Templo",
  str_item_intro_3001025 = "Com um estrondo, um lado do templo desaba, transformando as pedras intricadamente esculpidas e os preciosos vasos oferecidos no interior em fragmentos espalhados. No entanto, esses fragmentos ainda retêm algum valor.",
  str_item_3001026 = "Balas Pop Rocks",
  str_item_intro_3001026 = "Um doce estranho feito de uma planta rara. Pode ser usado para trocar por recompensas em Sonho - Paraíso da Comida Estranha e Maluca - Entrega de Delícias.",
  str_item_get_3001026 = "Sonho - Palco do Paraíso Comida Estranha e Maluca",
  str_item_3001027 = "Creme de Madeira",
  str_item_intro_3001027 = "Um tipo especial de madeira colhida das árvores da Floresta Creme. Pode ser usado para trocar por recompensas em Sonho - Paraíso Estranho e Maluco da Comida - Entrega de Delícias.",
  str_item_get_3001027 = "Sonho - Palco do Paraíso Comida Estranha e Maluca",
  str_item_3001028 = "sagacidade",
  str_item_intro_3001028 = "Como a chave para ajudar a manter a racionalidade e a clareza, ela será consumida durante a exploração, mas pode se reabastecer gradualmente com o tempo.",
  str_item_get_3001028 = "Recuperação automática ao longo do tempo",
  str_item_3001029 = "Coração Querido",
  str_item_intro_3001029 = "Um produto da preocupação e do chamado descarado de Pact... Embora a Pedra de Caça nunca tenha pedido por isso. Reúna mais para aumentar o nível da Pedra de Caça.",
  str_item_3001030 = "Talheres Finos",
  str_item_intro_3001030 = "Uma requintada obra de arte criada por um mestre. Pode ser usada para tornar um prato de alta qualidade ainda mais atraente.",
  str_item_3001031 = "Distintivo de Fósforo",
  str_item_intro_3001031 = "Uma antiga insígnia Illumina, um item de colecionador de profundo significado. A medalha em si não é valiosa, mas tornou-se um tesouro inestimável devido à glória do herói que a conquistou. Conceder tal medalha a um herói é apenas um pequeno sinal de gratidão. Pode ser resgatada por recompensas de itens em Sonho - Noite Evanescing à Luz das Estrelas - Distribuição de Sonhos.",
  str_item_get_3001031 = "Sonho: Noite Evanescente à Luz das Estrelas",
  str_item_3001032 = "Vale Illumina",
  str_item_intro_3001032 = "Vouchers populares em Illumina. Pontos são ganhos dependendo da duração do trabalho e do serviço, que podem ser usados para resgatar vários recursos. Podem ser trocados por recompensas de itens em Sonho - Noite Evanescing à Luz das Estrelas - Distribuição de Sonhos.",
  str_item_get_3001032 = "Sonho: Noite Evanescente à Luz das Estrelas",
  str_item_3001033 = "sagacidade",
  str_item_intro_3001033 = "Como a chave para ajudar a manter a racionalidade e a clareza, ela será consumida durante a exploração, mas pode se reabastecer gradualmente com o tempo.",
  str_item_get_3001033 = "Recuperação automática ao longo do tempo",
  str_item_3001034 = "Assobio",
  str_item_intro_3001034 = "Os soldados estão tão acostumados ao estridente apito que na verdade não conseguem se sentir seguros sem ele. Colete o suficiente para aumentar o nível da Rodada Afiada.",
  str_item_3001035 = "Jogos de guerra",
  str_item_intro_3001035 = "Uma forma rara de entretenimento em Illumina, mantendo os elementos de combate. Este requintado jogo de guerra transmite o coração de seu criador.",
  str_item_3001036 = "Marca Páginas de Flor Seca",
  str_item_intro_3001036 = "Um marcador de páginas feito pela própria garota que usava enquanto lia. Acompanhada por flores, ela folheou inúmeros livros de fábulas, procurando por vestígios de seu passado fragmentado. Pode ser usado para trocar por recompensas em Sonho - Através do Espelho Soneto de Inverno - Mercado Sem-nome.",
  str_item_get_3001036 = "Sonho - Através do Espelho Inverno Sonnet Stages",
  str_item_3001037 = "Fragmento de Espelho",
  str_item_intro_3001037 = "Esses fragmentos são extensões da força do espelho mágico, e dentro deles reside a essência da estrutura do mundo do espelho. Cada peça forma um pequeno domínio fraturado. Pode ser usado para trocar por recompensas em Sonho - Através do Espelho Soneto de Inverno - Mercado Sem-nome.",
  str_item_get_3001037 = "Sonho - Através do Espelho Inverno Sonnet Stages",
  str_item_3001038 = "sagacidade",
  str_item_intro_3001038 = "Como a chave para ajudar a manter a racionalidade e a clareza, ela será consumida durante a exploração, mas pode se reabastecer gradualmente com o tempo.",
  str_item_get_3001038 = "Recuperação automática ao longo do tempo",
  str_item_3001039 = "Dimensão Espelho Aurorescer",
  str_item_intro_3001039 = "O poder de Nikinis muitas vezes se manifesta na forma de flores, e a Dimensão Espelho não é exceção.",
  str_item_3001040 = "Coleção de Fábulas de Northland",
  str_item_intro_3001040 = "Nikinis está em busca de suas memórias perdidas e, mesmo procurando ajuda de outros, ela nunca desiste das pistas dentro de si mesma.",
  str_item_not_enough_plm = "Frutos Firethorn Insuficientes",
  str_item_3751396 = "Olheiras por Trás dos Óculos de Sol",
  str_item_3751397 = "Senhora da Igreja no Crepúsculo",
  str_item_3751551 = "Aflições do Novo Grande Marechal",
  str_item_intro_3751396 = "Que a luz brilhe sobre Crepúsculo, dissipando as sombras que ali permanecem.",
  str_item_intro_3751397 = "Olheiras? De jeito nenhum.",
  str_item_intro_3751551 = "Não podemos ter uma conversa que não envolva relatórios de trabalho?",
  str_item_3000131 = "Sinfonia do Crepúsculo Fulgor Estelar Especial",
  str_item_intro_3000131 = "Pode ser usado para recrutar uma vez do evento de recrutamento exclusivo Twilight Symphony.\nEste item eventualmente expira e não será convertido em outro item; por favor, lembre-se de usá-lo antes do final do evento de recrutamento exclusivo Twilight Symphony.",
  str_item_10000992 = "Kleken Caixa United",
  str_item_intro_10000992 = "Permite que Kleken participe da sua aventura.",
  str_item_1000099 = "Kleken Caixa United",
  str_item_intro_1000099 = "Permite que Kleken participe da sua aventura.",
  str_item_3755023 = "Marionete Adorável de Cachorrinho",
  str_item_3755024 = "Sapo?",
  str_item_3755025 = "Dawn Flor",
  str_item_intro_3755023 = "Desbloqueia o avatar correspondente.\n*choraminga*... Você gosta?",
  str_item_intro_3755024 = "Desbloqueia o avatar correspondente.\nDente-de-leão? Não fuja de mim!",
  str_item_intro_3755025 = [[
Desbloqueia o quadro de avatar correspondente.
Por menor que seja a flor branca, ela representa o amanhecer...]],
  str_item_3661219 = "Retrato do Cavaleiro Fiat",
  str_item_intro_3661219 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nUm retrato feito à imagem de Irridon durante seus dias como cavaleira, aparentemente um presente que uma jovem garota não conseguiu entregar.\n\"Senhora Irridon, agradeço sinceramente por sua ajuda e cuidado contínuos. Espero que você continue abraçando os valores de justiça e compaixão, guiando Lumopolis em direção a um futuro mais brilhante.\"",
  str_item_3661220 = "Retrato de Freira Inocente",
  str_item_intro_3661220 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nUm retrato feito à imagem de Paloma durante seus dias como freira, aparentemente um presente que um pai não pôde dar.\n\"Pam, que você permaneça sempre inocente e gentil, e que nossa família sempre encontre felicidade.\"",
  str_item_3751039 = "Determinação Inabalável",
  str_item_3751040 = "fim da luz",
  str_item_3751041 = "Hino Triunfante",
  str_item_3751398 = "Sede de Conhecimento",
  str_item_3751399 = "Poder do Guardião",
  str_item_3751400 = "O que você disse?",
  str_item_intro_3751039 = "Desbloqueia o avatar correspondente.\n\"Negador, Reinhardt... Seja o que for, que cada um de nós encontre seu próprio caminho.\"",
  str_item_intro_3751040 = "Desbloqueia o avatar correspondente.\n\"Não tenho intenção nem interesse em fazer inimigos — Eles são apenas obstáculos no meu caminho.\"",
  str_item_intro_3751041 = "Desbloqueia o avatar correspondente.\n\"A Iluminação Iluminada pode ser qualquer um - você, eu, quem quer que seja - desde que guiem os Aurorianos através dos desafios.\"",
  str_item_intro_3751398 = "Desbloqueia o Avatar correspondente.\n\"Oh, o céu noturno... é como uma biblioteca infinita, guardando todos os segredos do mundo.\"",
  str_item_intro_3751399 = [[
Desbloqueia o Avatar correspondente.
"Talvez um dia, eu possa realmente dominar esse poder que o destino me concedeu com destreza."]],
  str_item_intro_3751400 = [[
Desbloqueia o avatar correspondente.
"Huh?"]],
  str_item_3751552 = "Assunto Tabu",
  str_item_intro_3751552 = "Desbloqueia o avatar correspondente.\n\"Chega dessa piada de picolé!\"",
  str_item_3751553 = "Alegre Tweety",
  str_item_intro_3751553 = "Desbloqueia o avatar correspondente.\n\"Com as férias se aproximando, já tenho meus planos de viagem prontos. Quer saber qual é o plano do Tweety?\"",
  str_item_3763034 = "Surpresa Doce",
  str_item_intro_3763034 = "Desbloqueia o quadro de avatar correspondente.\nZarya estava preocupada que o frio intenso do Norte pudesse ser demais para você, então ela te deu seu chapéu.",
  str_item_3661215 = "Mesa de escrita",
  str_item_intro_3661215 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUma elegante escrivaninha de madeira que traz paz de espírito no trabalho.",
  str_item_3661216 = "Mesa de café pequena",
  str_item_intro_3661216 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUma pequena mesa de centro de madeira. Uma parte da superfície é feita de mármore, conferindo-lhe um ar de refinamento.",
  str_item_3661217 = "Mesa Lateral Coruja",
  str_item_intro_3661217 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUma coruja pousa sobre esta pequena mesa, como se estivesse olhando para a distância.",
  str_item_3661218 = "Vassoura Mágica",
  str_item_intro_3661218 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nAlgumas lendas dizem que, se você se sentar nele, ele voará alto no ar. De onde poderia ter surgido tal ideia?",
  str_item_5234055 = "Ornamento de Barco",
  str_item_intro_5234055 = "Um pequeno e colorido barco, erguido na vertical e usado como decoração. Será que apenas vê-lo pode realmente inspirar o desejo de zarpar para terras distantes?",
  str_item_3661052 = "Vaga-lume Efêmero",
  str_item_intro_3661052 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nEle só pode flutuar no ar e é completamente incapaz de se mover... Então, para que serve? Para pendurar coisas? Corrimãos?",
  str_item_3000338 = "Restos Antigos",
  str_item_intro_3000338 = "Fragmentos de alguma relíquia antiga espalhados pela terra ao longo de inúmeros anos. Se alguém estivesse disposto a reconhecer seu valor, talvez também estivesse disposto a pagar uma certa quantia de remuneração para adquiri-los.",
  str_item_3751401 = "Basquete de Brock",
  str_item_3751402 = "Vice novato em tênis de mesa",
  str_item_3751403 = "Esports Pro Gronru",
  str_item_3751404 = "Mestre Atirador Charon",
  str_item_intro_3751401 = "Desbloqueia o avatar correspondente. Confira minha configuração de três etapas! Sim! Por que ele teve que quicar direto na tabela?!",
  str_item_intro_3751402 = "Desbloqueia o avatar correspondente. Esporte é vida! Mesmo sendo um novato, darei tudo o que tenho na mesa de pingue-pongue!",
  str_item_intro_3751403 = "Desbloqueia o avatar correspondente. Quando se trata de jogos, nunca vou me deixar ficar para trás! Apenas me veja dominar esses noobs na próxima grande competição de esportes eletrônicos!",
  str_item_intro_3751404 = "Desbloqueia o avatar correspondente. Você não sabia? Eu sempre tenho um desempenho magnífico no campo de tiro também!",
  str_item_3440011 = "Caixão de Luz",
  str_item_intro_3440011 = "Abra para obter um dos seguintes itens aleatoriamente: Nightium ×10.000, Nightium ×5.000, General Jasper II ×2, General Jasper I ×3, Sublime ×100 ou Sublime ×50.",
  str_item_3440012 = "Caixa do Iluminismo",
  str_item_intro_3440012 = "Abra para obter um dos seguintes itens aleatoriamente: Nightium ×5.000, Nightium ×2.000, Nightium ×1.000, General Jasper II ×1, General Jasper I ×2 ou Sublime ×30.",
  str_item_3440013 = "Caixão do Mar",
  str_item_intro_3440013 = "Abra para obter um dos seguintes itens aleatoriamente: Anonymous Gift II ×1, Coalition Order Box III ×2, Nightium ×20.000 ou General Jasper II ×4.",
  str_item_3440019 = "Caixão do Mar",
  str_item_intro_3440019 = "Abra para obter um dos seguintes itens aleatoriamente: Anonymous Gift II ×1, Coalition Order Box III ×2, Nightium ×20.000 ou General Jasper II ×4.",
  str_item_3755036 = "Cavaleiro da Justiça Irridon",
  str_item_intro_3755036 = "Desbloqueia o avatar correspondente.\n\"Não vou deixar nenhuma pista escapar!\"",
  str_item_3755037 = "Culinária da Pam.",
  str_item_intro_3755037 = "Desbloqueia o avatar correspondente.\n\"Pode não parecer sofisticado, mas confie em mim, o sabor é fantástico!\"",
  str_item_6110001 = "Quadro de Arte Stand By Me",
  str_item_intro_6110001 = "Placa Comemorativa Stand By Me.\nO padrão na placa evoca imagens de visitantes distantes trazidos aqui pela brisa do mar, acompanhados pela suave melodia da pipa e pelo farfalhar das bandeiras...",
  str_item_3661221 = "Modelo de Trem Lembrança",
  str_item_intro_3661221 = "Um presente para o público da estreia do filme de Charon. Esta magnífica mini locomotiva, bem como a impressionante atuação do famoso ator, encantou muito os espectadores.\n\"Lembre-se desta sensação!\"",
  str_item_3000027 = "Vale do Coração",
  str_item_3000028 = "Balão de Coração",
  str_item_intro_3000027 = "Use isso para votar no Aurorian que você gosta no Evento de Votação de Trajes.\n\"Será que eles sentirão meu carinho?\"",
  str_item_intro_3000028 = "Use-o para votar na Roupa que você gosta no Evento de Votação de Roupas.\n\"Por favor, entregue ao destinatário com cuidado, ou seu amor pode simplesmente se dissipar no céu.\"",
  str_item_3661222 = "Retrato da Garota do Clarinete",
  str_item_3661223 = "Retrato Queen Aqua",
  str_item_intro_3661222 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nEste item foi originalmente produzido como um bule especial para cafeterias, mas não recebeu boas críticas devido ao seu design de descarregar água pela boca.\n\"D-Não use minha aparência para algo assim!\"",
  str_item_intro_3661223 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nUm belo retrato da rainha, esculpido para reduzir seu peso. Alguém sugeriu que o design poderia ser usado para desenvolver um recipiente para suco de Fluorophora, mas a rainha rejeitou firmemente a ideia.\n\"Ah, por que... isso sempre acontece comigo...?\"",
  str_item_3661224 = "Armário Médico",
  str_item_3661225 = "Leito de doença",
  str_item_3661226 = "Carrinho",
  str_item_3661227 = "Fileira de Assentos",
  str_item_intro_3661224 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUm armário de madeira com várias garrafas e potes nele. Esperamos que esses soros possam aliviar o sofrimento dos outros.",
  str_item_intro_3661225 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUma cama feita especialmente para pacientes. Venha aqui para descansar se você não se sentir bem.",
  str_item_intro_3661226 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUm carrinho médico simples. É extremamente importante, mesmo que tenha espaço limitado.",
  str_item_intro_3661227 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nUma fileira de assentos. Talvez você possa aliviar sua ansiedade conversando com os companheiros sentados ao seu redor.",
  str_item_5234056 = "Pátio Silencioso",
  str_item_intro_5234056 = "Um lugar maravilhoso para se refrescar e descansar. Você pode vir aqui se estiver preocupado com alguma coisa.",
  str_item_3000344 = "Jarra de Coleção",
  str_item_intro_3000344 = "Quanto mais preciso coletar antes de poder parar...?",
  str_item_3000345 = "Vale Diversão",
  str_item_intro_3000345 = "Esses tíquetes de sorteio comuns feitos pela Guilda Umbraton são a moeda designada para o jogo Surpresa da Caixa Misteriosa.",
  str_item_3661228 = "Caranguejo Forjado em Fornalha",
  str_item_3661229 = "Modelo de Navio da Sorte",
  str_item_intro_3661228 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nOriginalmente criado por Xuan Ji para auxiliar artesãos na forja mecânica, este autômato de Longzhou perdeu sua mobilidade após anos de uso. No entanto, ainda serve como uma peça decorativa distinta.",
  str_item_intro_3661229 = "Item de mobília. Pode ser colocado em salas no seu Colossus.\nNos navios da fortuna que os habitantes de Longzhou enviam ao mar, inúmeros desejos são imbuídos. Por exemplo, as moedas de cobre e espelhos embutidos nas juntas criam o layout das Sete Estrelas seguindo a Lua, significando boa sorte e uma jornada próspera. Embora este seja apenas um modelo feito por Xuan Ji, ele não economiza nos detalhes necessários e nos desejos sinceros.",
  str_item_3763035 = "Elixir de Cura",
  str_item_intro_3763035 = "Desbloqueia o quadro de avatar correspondente.\n\"Não se preocupe, não vai te machucar...\"",
  str_item_3751554 = "Enfraquecido",
  str_item_intro_3751554 = "Desbloqueia o avatar correspondente.\n\"Tossindo, tossindo... E-Eu estou bem... só preciso de um pouco de descanso.\"",
  str_item_3751555 = "Coração de Gratidão",
  str_item_intro_3751555 = "Desbloqueia o avatar correspondente.\n\"É por minha conta hoje!\"",
  str_item_3751405 = "Curador Solidário",
  str_item_intro_3751405 = [[
Desbloqueia o avatar correspondente.
"Por favor, sente-se e deixe-me verificar isso."]],
  str_item_3751406 = "A força prevalece",
  str_item_intro_3751406 = "Desbloqueia o avatar correspondente.\n\"Eu vou caçar qualquer um que ousar te dever dinheiro e não pagar!\"",
  str_item_3751407 = "Relíquia do Mar Profundo",
  str_item_intro_3751407 = "Desbloqueia o avatar correspondente.\nUm tesouro enterrado no fundo do oceano.\nResiste ao desgaste constante e à erosão da água do mar, na esperança de um dia reaparecer em terra.",
  str_item_3751408 = "Convite de Xuan Ji",
  str_item_intro_3751408 = "Desbloqueia o avatar correspondente.\n\"Os Celestitas têm algumas crenças semelhantes às do meu próprio povo. Você teria interesse em visitar Ye para uma troca cultural?\"",
  str_item_3751556 = "Mecanismo de Cobre-forjado",
  str_item_intro_3751556 = "Desbloqueia o Avatar correspondente.\n\"Uma criação de maquinaria sem função prática. Se você achar esteticamente agradável, então vale a pena tê-la.\"",
  str_item_3751409 = "Chovendo Ouro",
  str_item_intro_3751409 = "Desbloqueia o avatar correspondente.\n\"Embora isso não seja nem 1% da minha riqueza, não há motivo para recusar dinheiro grátis.\"",
  str_item_3751410 = "A Quebra do Senhor Sombrio",
  str_item_intro_3751410 = "Desbloqueia o avatar correspondente.\n\"Está quase nas férias. Eu deveria relaxar um pouco.\"",
  str_item_3751557 = "Xeque-mate",
  str_item_intro_3751557 = "Desbloqueia o avatar correspondente.\n\"Não hesite. Surpreenda seus inimigos e vença.\"",
  str_item_3751558 = "Moeda da Sorte",
  str_item_intro_3751558 = "Desbloqueia o avatar correspondente.\n\"Esta moeda da sorte é para você, que com certeza será abençoado com sorte no próximo ano.\"",
  str_item_3763036 = "Cobra de Névoa",
  str_item_intro_3763036 = "Desbloqueia o quadro de avatar correspondente.\nEsta serpente fumegante e enrolada eventualmente devorará tudo.",
  str_item_3751411 = "Venha Beber Chá",
  str_item_intro_3751411 = "Desbloqueia o avatar correspondente.\n\"São três horas. Você quer uma xícara de chá?\"",
  str_item_3751559 = "Cerejeira Florescendo",
  str_item_intro_3751559 = "Desbloqueia o avatar correspondente.\n\"Uma cor estranha é lançada no rosto de Hiiro, provavelmente pela cor das cerejeiras que floresceram cedo em um lugar distante.\"",
  str_item_3751560 = "Croquete Geek",
  str_item_intro_3751560 = "Desbloqueia o avatar correspondente.\n\"A sabedoria me sacia, não a comida.\"",
  str_item_3751412 = "Comandante Sábio",
  str_item_intro_3751412 = "Desbloqueia o avatar correspondente.\n\"Os Aurorianos são seus próprios inimigos.\"",
  str_item_3763037 = "Presente Sakura",
  str_item_intro_3763037 = "Desbloqueia a moldura de avatar correspondente.\nA linhagem da Família Sakura tem guardado silenciosamente Hiiro em nome do resto do clã.",
  str_item_3751561 = "Esfregão de Tigre",
  str_item_3751562 = "Não Picante",
  str_item_3751563 = "Leve",
  str_item_3751564 = "Moderado",
  str_item_3751565 = "Astra Picante",
  str_item_intro_3751561 = "Desbloqueia o avatar correspondente.\n\"Quem pode resistir à vontade de esfregar a cabeça contra um tigre tão fofo com poderes tão deliciosos?\"",
  str_item_intro_3751562 = "Desbloqueia o avatar correspondente.\n\"Esse nível de picância não é nada para a Rediesel Wrench.\"",
  str_item_intro_3751563 = "Desbloqueia o avatar correspondente.\n\"As pessoas de Ye gostam de pratos apimentados. Embora ultra picante seja um pouco demais para Dantang, ela é uma excelente cozinheira e consegue entender a beleza deste sabor.\"",
  str_item_intro_3751564 = "Desbloqueia o avatar correspondente.\n\"Você sempre deve comer de maneira elegante! Carleen continua lembrando a si mesma que não pode esquecer a etiqueta do jantar dos Cavaleiros Lumo apenas por causa da estimulação em sua boca.\"",
  str_item_intro_3751565 = [[
Desbloqueia o avatar correspondente.
"Ahhhhhhhhh! Astra picante! Essa foi a primeira coisa que o estorninho disse depois de comer o molho de pimenta."]],
  str_item_9997004 = "Curativo",
  str_item_9997005 = "Escudo Lunaprata",
  str_item_9997008 = "Deusa da Piedade",
  str_item_9997009 = "Pedra Enfeitiçada",
  str_item_9997010 = "Nota de Morte",
  str_item_9997011 = "Armadura Berserker",
  str_item_9997012 = "Gloria Sol",
  str_item_9997013 = "Ataque de Trovão",
  str_item_9997014 = "Caleidojoia",
  str_item_9997015 = "espada de luz",
  str_item_9997016 = "Facão Lunaprata",
  str_item_9997017 = "Arco Lunaprata",
  str_item_9997018 = "Lâmina Aguçada",
  str_item_9997019 = "Óculos Luz Solar",
  str_item_9997020 = "Tinta Absorvente",
  str_item_9997021 = "Sakura Cadente",
  str_item_9997023 = "Máscara Toque Fatal",
  str_item_9997024 = "Mão de Deus",
  str_item_9997025 = "Morte Silenciosa",
  str_item_9997026 = "Cinturão de Energia",
  str_item_9997027 = "Escudo Lúmina",
  str_item_9997028 = "Luz do Ceifador",
  str_item_9997029 = "Amuleto de Combo",
  str_item_9997030 = "Estátua de Bond",
  str_item_9997031 = "Pingente potencial",
  str_item_9997033 = "Energizador Móvel",
  str_item_9997035 = "Ceifalma",
  str_item_9997003 = "Vela de Cura",
  str_item_9997006 = "Coração da Devoção",
  str_item_9997007 = "Escudo Solar",
  str_item_9997032 = "Distintivo da Ressonância",
  str_item_9997022 = "Sarcófago",
  str_item_9997036 = "Manuscrito Velho",
  str_item_9997037 = "Pestilência",
  str_item_9997038 = "Chaos Blade",
  str_item_9997034 = "Botas Estilhaçantes",
  str_item_9997039 = "Moeda da Sorte",
  str_item_9997040 = "Ecos Duplos",
  str_item_9997041 = "Gelador Voante",
  str_item_9997042 = "Abrasador Voante",
  str_item_9997043 = "Florestalma Voante",
  str_item_9997044 = "Trovão Voante",
  str_item_9997045 = "Prato do Amanhecer",
  str_item_9997046 = "Cristal Atordoante",
  str_item_9997047 = "Cx. Mágica Lúmina",
  str_item_intro_9997004 = "Recarrega um curativo no campo quando a batalha começa.",
  str_item_intro_9997005 = "Concede um escudo de 20% do HP máximo que dura 2 rodadas no início da batalha.",
  str_item_intro_9997008 = "Restaura o HP para 30% no início da batalha se o HP atual estiver abaixo de 30%.",
  str_item_intro_9997009 = "Perca 7% do HP atual no início de cada rodada. Depois disso, cause dano igual a 150% do ATK médio da equipe aos inimigos em 2 círculos ao redor.",
  str_item_intro_9997010 = "Aumenta o dano da Habilidade Ativa dos Aurorianos em 50%. Perde 8% do HP atual cada vez que uma Habilidade Ativa é usada.",
  str_item_intro_9997011 = "Aumenta o dano do Chain Combo em até 40% de acordo com a porcentagem de HP perdida pelos aliados.",
  str_item_intro_9997012 = "Aumenta o dano do Aurorian em 20% quando o HP atual é maior que 70%.",
  str_item_intro_9997013 = "Ao atacar 3 ou mais inimigos ao mesmo tempo, lança um raio que ataca todos os inimigos, causando dano igual a 100% do ATK médio da equipe.",
  str_item_intro_9997014 = "Gera 1 peça cromática aleatoriamente no campo no início de cada rodada.",
  str_item_intro_9997015 = "Ao remover pelo menos 15 ladrilhos de uma vez com um toque, aumenta o dano do Combo em Cadeia dos Aurorianos em 30%. O Combo em Cadeia não pode ser lançado se menos de 8 ladrilhos forem removidos de uma vez.",
  str_item_intro_9997016 = "Quanto mais próximos estiverem de um inimigo, maior será o dano do Combo em Cadeia dos Aurorianos, aumentando-o em até 20%.",
  str_item_intro_9997017 = "Quanto mais longe estiverem de um inimigo, maior será o dano do Chain Combo dos Aurorianos, aumentando-o em até 30%.",
  str_item_intro_9997018 = "Aurorians Detonadores têm 30% de chance de lançar o Chain Combo 1 vez adicional.",
  str_item_intro_9997019 = "Aumenta o número de alvos do Chain Combo dos Aurorianos Atiradores em 1.",
  str_item_intro_9997020 = "Supporter Aurorians +25% regeneration effects from Chain Combos and Active Skills in battle.",
  str_item_intro_9997021 = "No início da batalha, reduz em 1 o tempo de recarga da Habilidade Ativa dos Aurorianos Conversores.",
  str_item_intro_9997023 = "Quando as Habilidades Ativas ou Habilidades de Combo em Cadeia lançadas pelos Aurorianos causam dano, há uma chance de 30% de resolver imediatamente os efeitos de Envenenamento/Queimação/Sangramento do alvo uma vez.",
  str_item_intro_9997024 = "Todo o dano sofrido por inimigos com debuff ou sob efeito de debuff aumenta em 20%.",
  str_item_intro_9997025 = "Derrota inimigos com menos de 7% de HP.",
  str_item_intro_9997026 = "Após tocar para remover os ladrilhos, se os Aurorianos não lançaram o Combo em Cadeia nesta rodada, reduz o tempo de espera da Habilidade Ativa de todos os Aurorianos em 1.",
  str_item_intro_9997027 = "Converte uma porcentagem do excesso de cura dos aurorianos em uma pilha de Escudo que dura 1 rodada.",
  str_item_intro_9997028 = "Quando um inimigo Envenenado/Queimado/Sangrando é derrotado, inflige 1 acúmulo de Envenenado a outro inimigo aleatório no campo de batalha.",
  str_item_intro_9997029 = "Reduz em 5 o número de peças que precisam ser removidas para acionar a habilidade de suporte da facção.",
  str_item_intro_9997030 = "Quando um Auroriano usa uma Habilidade Ativa, reduz em 1 o tempo de recarga das Habilidades Ativas dos Aurorianos que possuem vínculo com ele.",
  str_item_intro_9997031 = "Reduz o tempo de recarga da primeira Habilidade Ativa lançada na batalha em 2.",
  str_item_intro_9997033 = "Um indicador surge aleatoriamente no campo de batalha no início de cada rodada. Após destruir este indicador, o dano do Chain Combo aumenta em 25% nesta rodada.",
  str_item_intro_9997035 = "Aurorianos ganham 2% de Dreno de Vida ao causar dano e perdem 15% do HP atual no início de cada rodada.",
  str_item_intro_9997003 = "Restaura 10% do HP máximo após vencer uma batalha.",
  str_item_intro_9997006 = "Aumenta o PV Máx. de todos os Aurorianos em 3% após vencer uma batalha.",
  str_item_intro_9997007 = "Aumenta a DEF de todos os Aurorianos em 1,5% após vencer uma batalha.",
  str_item_intro_9997032 = "Aumenta o ATQ de todos os Aurorianos em 1% após vencer uma batalha.",
  str_item_intro_9997022 = "Número total de rodadas +10 ao obter este item. ",
  str_item_intro_9997036 = "Ao tocar para remover peças, há uma chance de 25% de aumentar o número de tentativas de remoção em 1.",
  str_item_intro_9997037 = "Ao tocar para remover ladrilhos, inflige aleatoriamente 1 pilha de Envenenamento, Sangramento ou Queimação aos inimigos dentro do alcance dos ladrilhos removidos.",
  str_item_intro_9997038 = "Ao tocar para remover as casas, causa dano igual a 120% do ATK médio da equipe aos inimigos dentro do alcance das casas removidas.",
  str_item_intro_9997034 = "Os inimigos recebem dano igual a 150% do ATK médio da equipe uma vez para cada ladrilho que se movem dentro da área dos ladrilhos que foram tocados e serão removidos nesta rodada.",
  str_item_intro_9997039 = "No início da batalha, 1 Equipamento Caelestite Especial aleatório pode ser usado uma vez.",
  str_item_intro_9997040 = "Obtenha Equipamento Caelestite Especial: Converte 2 peças selecionadas em peças cromáticas. Isso pode ser usado uma vez a cada 60 peças que são removidas.",
  str_item_intro_9997041 = "Obtenha Equipamento Especial de Caelestite: Seleciona uma área de 3x3 e remove todas as peças azuis dentro dela. Isso pode ser usado uma vez a cada 50 peças removidas.",
  str_item_intro_9997042 = "Obtenha Equipamento Especial de Caelestite: Seleciona uma área de 3x3 e remove todas as peças vermelhas dentro dela. Isso pode ser usado uma vez a cada 50 peças removidas.",
  str_item_intro_9997043 = "Obtenha Equipamento Especial de Caelestite: Seleciona uma área de 3x3 e remove todas as peças verdes dentro dela. Isso pode ser usado uma vez a cada 50 peças removidas.",
  str_item_intro_9997044 = "Obtenha Equipamento Especial de Caelestite: Seleciona uma área de 3x3 e remove todos os ladrilhos amarelos dentro dela. Isso pode ser usado uma vez a cada 50 ladrilhos removidos.",
  str_item_intro_9997045 = "Obtenha Equipamento Especial de Caelestite: Reinicia todas as peças no campo de batalha. Isso pode ser usado uma vez a cada 80 peças removidas.",
  str_item_intro_9997046 = "Obtenha Equipamento Especial de Caelestite: Selecione 1 cor e reinicie todas as peças dessa cor no campo de batalha. Isso pode ser usado uma vez a cada 80 peças removidas.",
  str_item_intro_9997047 = "Obtenha Equipamento Especial de Caelestite: Seleciona 1 ladrilho e remove os 4 ladrilhos mais próximos da mesma cor. Isso pode ser usado uma vez a cada 60 ladrilhos removidos.",
  str_item_rpintro_9997004 = "Auxiliar de poção de recuperação que ajuda a curar feridos.",
  str_item_rpintro_9997005 = "Arma clássica antiga, gravada com glifos abençoados e particularmente efetiva contra inimigos ágeis.",
  str_item_rpintro_9997008 = "Estátua perfeitamente preservada que proporciona poder de cura ao seu portador.",
  str_item_rpintro_9997009 = "Item antigo que amaldiçoa o usuário e concede poder igual em troca.",
  str_item_rpintro_9997010 = "Supostamente um item misterioso de uma guerra apocalíptica. Carrega uma poderosa maldição que é forte o suficiente para ferir seriamente oponentes.",
  str_item_rpintro_9997011 = "Coloque isso para transformar a agonia em força e, finalmente, alcançar a vitória.",
  str_item_rpintro_9997012 = "Carregue e será protegido pela Deusa da Vitória, você vencerá todas as suas batalhas.",
  str_item_rpintro_9997013 = "Lâmina famosa dos velhos tempos, encantada com o poder do trovão. Sua ira explosiva fica aparente ao ser sacada.",
  str_item_rpintro_9997014 = "Uma joia que brilha com todas as cores, esplêndida e dinâmica.",
  str_item_rpintro_9997015 = "Espada antiga de grande porte que, ao segurar, você pode sentir o poder dentro de você crescer.",
  str_item_rpintro_9997016 = "Arma clássica antiga, gravada com glifos abençoados e particularmente efetiva contra inimigos ágeis.",
  str_item_rpintro_9997017 = "Arma clássica antiga, gravada com glifos abençoados e particularmente efetiva contra inimigos ágeis.",
  str_item_rpintro_9997018 = "Uma lâmina curta afiada, feita de uma superliga antiga.",
  str_item_rpintro_9997019 = "The lenses glow in battle, blinding the opponent while protecting the wearer from it. Auxiliary equipment.",
  str_item_rpintro_9997020 = "Tinta antiga capaz de absorver Lúmina.",
  str_item_rpintro_9997021 = "Old-era creation that seems very pretty but carries terrifying power, dropping enemies like falling flowers with explosions.",
  str_item_rpintro_9997023 = "Relíquia de uma era antiga, possivelmente amaldiçoada. Usuário torna-se letal com toxinas.",
  str_item_rpintro_9997024 = "Espada antiga famosa. Seu portador sente um poder divino.",
  str_item_rpintro_9997025 = "Pode sentir a força vital de um inimigo e finalizar aqueles que estão perto da morte, ao estar próxima.",
  str_item_rpintro_9997026 = "Um cinto bem ajustado que fornece ao usuário a Lúmina necessária quando ativado sob certos requisitos.",
  str_item_rpintro_9997027 = "Dispositivo desconhecido de velhos tempos que sente e converte Lúmina extra em um campo de força protetor para o portador.",
  str_item_rpintro_9997028 = "Suposto item amaldiçoado feito por um guerreiro para causar a perdição de seus inimigos.",
  str_item_rpintro_9997029 = "Talismã de uma era antiga, capaz de guardar Lúmina em um nível micro, causando grande dano a inimigos.",
  str_item_rpintro_9997030 = "Item da era antiga para regenerar uma certa quantidade de Lúmina para Aurorians vinculados.",
  str_item_rpintro_9997031 = "Use este item da era antiga para recuperar rapidamente uma parte da Lúmina perdida.",
  str_item_rpintro_9997033 = "Dispositivo para guardar e reabastecer Lúmina.",
  str_item_rpintro_9997035 = "Lâmina imensa de grosseria palpável. Provavelmente usada em duelos até a morte em tempos antigos. Haverá sangue quando for usada.",
  str_item_rpintro_9997003 = "Vela com um brilho quente que pode curar Aurorians feridos.",
  str_item_rpintro_9997006 = "Uma estatueta perdida de uma era antiga feita de materiais de alta qualidade. Resistente, leve e abençoa seu portador.",
  str_item_rpintro_9997007 = "Escudo antiga de uma velha era, forma oval e supostamente infundido com o poder do sol para defletir todos os ataques letais.",
  str_item_rpintro_9997032 = "Insígnia antiga com um ajuste para guardar Lumina em um nível micro, aumentando a destreza em combate.",
  str_item_rpintro_9997022 = "Saco de dormir abandonado. Ajuda a recuperar as forças.",
  str_item_rpintro_9997036 = "Aparentemente escrito por estudiosos antigos, ele detalha as nuances do contraefeito elemental e fornece dicas estratégicas efetivas.",
  str_item_rpintro_9997037 = "Uma pintura antiga feita por um pintor anônimo que mostra a atrocidade da praga. O artista também morreu na pandemia. Ela possui um poder terrível...",
  str_item_rpintro_9997038 = "Uma arma que parece ser capaz de se fundir com Lumina perfeitamente... Isso é realmente raro...",
  str_item_rpintro_9997034 = "Old-time item created specifically to deal with pursuers. Leaves Lumina on the trail that detonates later to kill the pursuers.",
  str_item_rpintro_9997039 = "Moeda antiga misteriosa que ocasionalmente aumenta a velocidade de seu Aurorian, concedendo mais agilidade.",
  str_item_rpintro_9997040 = "Orquídeas vermelhas raras, desenvolvidas especialmente nos velhos tempos. Elas aparecem, florescem e secam em pares. Parecem formar um laço com o portador e auxiliam em combate.",
  str_item_rpintro_9997041 = "Aparentemente uma miniatura da Colossus da era antiga que auxilia o dono na batalha.",
  str_item_rpintro_9997042 = "Aparentemente uma miniatura da Colossus da era antiga que auxilia o dono na batalha.",
  str_item_rpintro_9997043 = "Aparentemente uma miniatura da Colossus da era antiga que auxilia o dono na batalha.",
  str_item_rpintro_9997044 = "Aparentemente uma miniatura da Colossus da era antiga que auxilia o dono na batalha.",
  str_item_rpintro_9997045 = "Item antigo que cria laços misteriosos entre dois combatentes.",
  str_item_rpintro_9997046 = "Cristal bruto com uma superfície rachada que indica Lúmina em excesso no seu interior. Um leve toque pode liberar Lúmina suficiente para atordoar inimigos em batalha.",
  str_item_rpintro_9997047 = "Tecnologia antiga. Guarda muito mais Lúmina do que aparenta seu pequeno tamanho.",
  str_item_3000349 = "Token Cloudrover",
  str_item_intro_3000349 = "Um token que pode ser trocado por benefícios da Guilda Cloudrover. Apenas clientes leais têm a chance de conseguir isso.",
  str_item_3000134 = "Explosão Estelar Especial da Avariciosa Lachesis",
  str_item_intro_3000134 = "Pode ser usado para recrutar uma vez do atual recrutamento exclusivo.\nEste item irá expirar, então, por favor, use-o antes do final do atual recrutamento exclusivo Avaricious Lachesis, ou então ele desaparecerá. Não será convertido em outro item quando expirar.",
  str_item_3420133 = "Kit de recrutamento de 2,5 anos",
  str_item_intro_3420133 = "Escolha um Auroriano da seguinte lista de Aurorianos de 6 estrelas para lutar ao seu lado: <color=#ffffff>Dantang, Zarya, Antony, Lorelei, Cena, Joshua, Schwartz: Almighty Clamor, Yingel, Leo, Hati, Tina, Leyn, Jeriah, Mu Yuebai, Zhong Xu, Vic, Axelia, Lilica, Minos, Pollux, Jeno, Fia, Carleen: Smoldering Soul, Nina, Barton: Deft Blades, Giles, Lenore, Azure, Yao, Amemori, Rinne, Florine, Ruby, Siobhan, Novio, Hedy, Bethel, Luke, Paloma, Gram, Revy, Smokey, Fleur, Beryl, Hiiro, Sinsa, Eve, Uriel, Carleen, Sharona, Sariel, Raphael, Connolly, Charon, Eicy, Victoria, Jona, Nikinis, Gabriel, Migard, Michael, Gronru, Irridon, Wrath.</color>.Observação: este kit expira às 09:00 de 28 de fevereiro de 2024 (UTC+0), 04:00 de 28 de fevereiro de 2024 (UTC-5). Reivindique-o a tempo, ou ele será automaticamente convertido em 3.000 Lumamber e enviado a você pela caixa de correio do jogo.",
  str_item_3661231 = "Trono Sombrio",
  str_item_intro_3661231 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nA Guilda Cloudrover fez especialmente esta cadeira luxuosa e dominante de couro rígido para Istvan. Como é um produto tão inovador, não faltaram compradores apesar de seu preço elevado.",
  str_item_3661232 = "Modelo de Aeronave Cloudrover",
  str_item_intro_3661232 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nDada a popularidade do Dirigível Cloudrover, um destino único que atende todas as suas necessidades de turismo, compras, recreação e férias, é natural que modelos deste dirigível estejam disponíveis em vários tamanhos para os clientes comprarem. Embora este modelo em particular não seja o maior, ele é feito com a mais requintada mão de obra.",
  str_item_3661233 = "Luzes Festivas",
  str_item_intro_3661233 = "Item de mobília. Pode ser colocado em salas no seu Colossus.\nIlumine espaços escuros com fileiras dessas luzes coloridas. Esperamos que a luz suave delas lhe dê algum calor neste dia digno de celebração.",
  str_item_3661234 = "Caixa de Presente Festiva",
  str_item_intro_3661234 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nOs Aurorianos lhe deram este presente atencioso. Embora não valha muito, seu verdadeiro valor reside no trabalho duro e esforço que representa. May que este presente lhe traga boa sorte no próximo ano.",
  str_item_5234057 = "Carruagem de Gelo",
  str_item_intro_5234057 = "Uma carruagem ornamental feita de gelo. Sua aparência cristalina é extremamente calmante e relaxante.",
  str_item_3661236 = "Retrato do Espadachim de Troca de Roupa",
  str_item_3661237 = "Retrato do Espadachim de Barco",
  str_item_3661241 = "Ventilador de Bool",
  str_item_3661242 = "Lâmpada de Planta",
  str_item_intro_3661236 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nObra de um certo artesão, esta boneca pode mudar rapidamente para outro traje aleatório ao pressionar um botão. Dizem que esta boneca é inspirada em um tipo de arte performática de Longzhou.\n\"Se eu quiser interpretar o papel de uma pessoa de Longzhou... também precisaria aprender a mudar minha roupa instantaneamente assim?\"",
  str_item_intro_3661237 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nPara comemorar a bem-sucedida cooperação com o espadachim, o artesão fez um retrato baseado na postura do espadachim ao completar uma missão.\n\"Você quer deixar o assento do outro lado do barco vazio? Claro, apenas me diga quando quiser adicionar alguém lá.\"",
  str_item_intro_3661241 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nEste ventilador é usado exclusivamente no laboratório dos cientistas da Illumina. Suas pernas podem ser dobradas de forma flexível ou fixadas em superfícies. Alguns dizem que este ventilador foi inspirado por um robô chamado Bool.",
  str_item_intro_3661242 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nUma lâmpada de design requintado que fornece às plantas a luz necessária para crescer e cria um ambiente interno quente e natural.",
  str_item_3000352 = "Pena celestita",
  str_item_intro_3000352 = "Diz-se que esta pena de aparência única é extremamente valiosa para os Celestitas.",
  str_item_3661243 = "Sofá Dumpling",
  str_item_3661244 = "Obra de Arte de Ano Novo: O Dragão",
  str_item_3661238 = "Decoração de Fogos de Artifício",
  str_item_3661239 = "Pingente de Ano Novo",
  str_item_3661240 = "Estante Pitoresca",
  str_item_intro_3661243 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nSofá preguiçoso em forma de bolinho, com uma caixa de voz que uma vez estava viva com cânticos:\n\"Dumplings, uma infinidade de dumplings!\"\n\"Vamos todos fazer dumplings juntos!\"\nAgora, o dispositivo de voz foi removido pelos Aurorianos cansados do barulho, restaurando a tranquilidade dentro do Colossus.",
  str_item_intro_3661244 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nUma pintura de Ano Novo da Donzela Dragão, um item festivo popular do Reino Ji. Mas este \"retrato artístico\" dado por Chen'ni é o único que retrata com precisão a aparência da Donzela Dragão.",
  str_item_intro_3661238 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nÀ medida que o festival tradicional de Longzhou se aproxima, para que nossos amigos de Longzhou no Colossus sintam a atmosfera festiva, todos no Colossus penduram as decorações de fogos de artifício feitas em conjunto, na esperança de afastar a má sorte e convidar a boa sorte.",
  str_item_intro_3661239 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nAtualmente um best-seller na Baía dos Pavilhões Gêmeos, é uma decoração indispensável de Longzhou durante os tempos festivos, simbolizando a esperança por um futuro brilhante.",
  str_item_intro_3661240 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nCriada por artesãos da Baía dos Pavilhões Gêmeos, esta prateleira de madeira é intricadamente esculpida e projetada tanto para armazenamento quanto para admiração, enriquecendo as câmaras da Colossus com um toque de elegância clássica.",
  str_item_intro_3763039 = "Desbloqueia o quadro de avatar correspondente.\n\"As flores de pêssego são delicadas e graciosas, irradiando sua beleza resplandecente. E a fortuna vem, em seu abraço vibrante.\"",
  str_item_intro_3751417 = "Desbloqueia o avatar correspondente.\n\"Caelestite recebeu um chapéu especial como presente de Ano Novo e o colocou feliz!\"",
  str_item_intro_3751566 = "Desbloqueia o avatar correspondente.\n\"Chen'ni concede bênçãos, concedendo riqueza e prosperidade!\"\nA Donzela do Dragão, reverenciada como uma divindade do mar, pode realmente conceder felicidade ao mundo mundano? Chen'ni pode não saber, mas está determinada a tentar!",
  str_item_intro_3751567 = "Desbloqueia o avatar correspondente.\n\"Meu paladar é o padrão!\"\nComo enviado da Astra, o Navegador é super experiente em degustação de alimentos, ostentando um paladar refinado.",
  str_item_intro_3763038 = "Desbloqueia o quadro de avatar correspondente.\n\"Colete todos os Cartões de Primavera para invocar o dragão divino!\"\nNão tenho certeza se é verdade, mas essa mania de colecionar cartões tornou o Ano Novo de Longzhou muito mais divertido.",
  str_item_intro_3751413 = "Desbloqueia o avatar correspondente.\n\"Eu tenho uma longa lista de coisas que gostaria de ver - a armadura mecanizada gigante em Azurite, os shows barulhentos no deserto, as intensas lutas subterrâneas...\"\nAté uma divindade tem muitos desejos para o Ano-Novo.",
  str_item_intro_3751414 = "Desbloqueia o avatar correspondente.\nCuidado com a besta Nian de Umbraton, um verdadeiro devorador de homens com longos chifres! Confira \"Feira do Templo Proibido\", o mais recente filme de terror de Alleywood, que chega nesta primavera!\n\"Então... qual é o meu papel de novo...?\"",
  str_item_intro_3751415 = "Desbloqueia o avatar correspondente.\n\"Aqui está, apenas uma coisinha que eu preparei... Eu posso fazer coisas além de picolés, você sabe!\"\nA única coisa que Zarya conseguiu fazer após inúmeras falhas, com um toque extra de doçura para manifestar seus sentimentos.",
  str_item_intro_3751416 = "Desbloqueia o avatar correspondente.\nEsperando que o reencontro de hoje traga a você um sentimento de lar e força. É o mesmo céu acima de nós, onde quer que estejamos.",
  str_item_intro_3751568 = "Desbloqueia o avatar correspondente.\n\"Embora muitos expressem seu carinho por mim, acho o Navegador o mais especial. Nós realmente compartilhamos uma conexão de coração para coração!\"",
  str_item_intro_3751569 = "Desbloqueia o avatar correspondente.\n\"Coração com a mão, sério?... Ok, aceite este gesto meu e seja grato... mas não se empolgue demais!\"",
  str_item_3763039 = "Flor da Fortuna",
  str_item_3751417 = "Celestita com Chapéu de Dragão",
  str_item_3751566 = "Donzela Dragão Longzhou no Ano do Dragão",
  str_item_3751567 = "Enviado Foodie",
  str_item_3763038 = "Dragão da Primavera Soar",
  str_item_3751413 = "Desejo de Ano Novo",
  str_item_3751414 = "Conjunto Festivo",
  str_item_3751415 = "Doce Delícia",
  str_item_3751416 = "Grande Reunião",
  str_item_3751568 = "Fleur's Consideração",
  str_item_3751569 = "Olhar de Zarya",
  str_item_3763041 = "Coroa de Mil Dias",
  str_item_3751420 = "Dia do Cavaleiro da Coroa Lunar",
  str_item_3751419 = "Abrangendo Mil Noites",
  str_item_3751570 = "Limbo em Chamas",
  str_item_3763040 = "Labareda Final",
  str_item_3751421 = "Coração de Mil Dias",
  str_item_3751422 = "Flecha do Amor",
  str_item_intro_3751421 = "Desbloqueia o avatar correspondente.\n\"Navegador, por aqui!\"\nO amor tem sido seu companheiro constante nesta jornada por mil dias. Continue avançando com as bênçãos de todos!",
  str_item_intro_3751422 = [[
Desbloqueia o avatar correspondente.
"Aproveite o momento; hoje pode ser o ponto de virada em nosso destino!"]],
  str_item_intro_3763041 = "Desbloqueia a moldura de avatar correspondente.\n\"Aqueles que são firmes serão recompensados com glória!\"\nObrigado pela sua orientação e proteção ao longo de mil dias de perseverança e companheirismo. Aguardamos futuras aventuras juntos.",
  str_item_intro_3751420 = "Desbloqueia o avatar correspondente.\n\"Você também quer participar do julgamento especial do Dia da Coroa da Lua?\"",
  str_item_intro_3751419 = "Desbloqueia o avatar correspondente.\nNavegador, obrigado por me acompanhar por mil dias sob este céu. Por favor, continue a me guiar no futuro!",
  str_item_intro_3751570 = "Desbloqueia o avatar correspondente.\n\"Você quer estar no Limbo comigo? Então pegue minha mão e deixe nossas esperanças brilharem intensamente!\"",
  str_item_intro_3763040 = "Desbloqueia o quadro de avatar correspondente.\n\"Minha roupa irá pegar fogo quando a poção acabar. Você seguirá o último rastro da chama até mim?\"",
  str_item_3751042 = "Mensagens do Viajante",
  str_item_3751043 = "Frutos do Treinamento",
  str_item_3751044 = "A Verdade Permanece",
  str_item_3751045 = "Guardião na Jornada",
  str_item_3751046 = "Festa do Chá Regular",
  str_item_3751047 = "Minha História",
  str_item_3751048 = "Irmãos de Armas",
  str_item_3751573 = "Escondendo Fox",
  str_item_3763042 = "Melhor Crocodilo",
  str_item_intro_3751042 = "Desbloqueia o avatar correspondente.\n\"Eu entendo como é difícil o caminho para um Navegador. Continue com o bom trabalho.\"",
  str_item_intro_3751043 = "Desbloqueia o avatar correspondente.\n\"Resistir por tanto tempo é realmente louvável. Vamos continuar treinando juntos no futuro!\"",
  str_item_intro_3751044 = "Desbloqueia o avatar correspondente.\n\"Lembre-se sempre: não importa como o tempo muda, a verdade perdura.\"",
  str_item_intro_3751045 = "Desbloqueia o avatar correspondente.\n\"Nas jornadas que estão por vir, sempre vou te manter seguro.\"",
  str_item_intro_3751046 = "Desbloqueia o avatar correspondente.\n\"Quantas vezes eu já te convidei para o chá da tarde?\"",
  str_item_intro_3751047 = "Desbloqueia o avatar correspondente.\n\"Eu compartilhei minha história com você; qual é a sua?\"",
  str_item_intro_3751048 = "Desbloqueia o avatar correspondente.\n\"Depois de tanto tempo juntos, já somos verdadeiros irmãos!\"",
  str_item_intro_3751573 = "Desbloqueia o avatar correspondente.\n\"Você já terminou de se esconder?\" \"Ainda não.\"",
  str_item_intro_3763042 = [[
Desbloqueia o quadro de avatar correspondente.
"Parece um pouco familiar."]],
  str_item_intro_3751423 = [[
Desbloqueia o avatar correspondente.
"Ribbit! Ribbit!! Ribbit!!!"]],
  str_item_intro_3751424 = "Desbloqueia o avatar correspondente.\n\"O que eu deveria fazer... A resposta sempre esteve no meu coração?\"",
  str_item_3751423 = "Príncipe Lilypad",
  str_item_3751424 = "Respostas Abaixo do Farol",
  str_item_3440014 = "Bolsa Maravilha",
  str_item_intro_3440014 = "Eu sou apenas um pobre sapo que te deu todas as minhas economias da vida.",
  str_item_intro_3440015 = "As recompensas oferecidas na bolsa de fortuna de super valor são frequentemente enganosas.",
  str_item_intro_3440016 = "Boa sorte sobe de maneira escalonada, muito parecido com a minha vida.",
  str_item_intro_3440017 = "Desenhe mais uma vez; parece que estamos nos aproximando da recompensa garantida.",
  str_item_intro_3440018 = "Esta é a minha última tentativa! Depois, vou apenas tocar em Voltar, fechar a tela e sair do jogo.",
  str_item_3751574 = "Apresentando: Goldie o Ídolo",
  str_item_intro_3751574 = "Desbloqueia o Avatar correspondente.\n\"Todos os olhos estão nela; ela é o epítome da perfeição e radiância, o ídolo supremo.\"",
  str_item_3751425 = "Cansaço do Ídolo",
  str_item_intro_3751425 = "Desbloqueia o avatar correspondente.\n\"Bocejo! Sinto-me tão sonolento desde o momento em que troquei para este pijama.\"",
  str_item_3763043 = "Marshmallow que eu escolhi",
  str_item_intro_3763043 = "Desbloqueia a moldura de avatar correspondente.\n\"A figura graciosa encanta com seu adorável fofo, enredando outro em sua teia encantadora.\"",
  str_item_3751572 = "Onde está o Pai",
  str_item_intro_3751572 = "Desbloqueia o avatar correspondente.\n\"Pai, por favor me informe sua localização atual.\"",
  str_item_3751571 = "Bênção dos Sorrisos",
  str_item_intro_3751571 = "Desbloqueia o avatar correspondente.\n\"Eu dou este componente ao Pai, desejando que sua expressão esteja alinhada com a exibida na tela.\"",
  str_item_3751429 = "Olá Toto",
  str_item_intro_3751429 = "Desbloqueia o avatar correspondente.\n\"Olá, Toto! O caloroso Colossus abriga todo trabalhador de coração partido.\"",
  str_item_3751430 = "Emblemas e Honra",
  str_item_3751577 = "Esquadrão Eagleeye, reúnam-se!",
  str_item_3751578 = "Confete de Carnaval",
  str_item_3751579 = "Companheirismo Eterno",
  str_item_3763046 = "Grandes Bênçãos",
  str_item_3763047 = "Koinobori",
  str_item_intro_3751430 = "Desbloqueia o avatar correspondente.\n\"Muito bom. Não manchei minha honra hoje.\"",
  str_item_intro_3751577 = "Desbloqueia o avatar correspondente.\n\"Seu olhar deve ser aguçado como o de um falcão, seus ataques devem ser tão afiados quanto suas garras e seus movimentos devem ser tão rápidos quanto suas asas batendo.\"",
  str_item_intro_3751578 = [[
Desbloqueia o avatar correspondente.
"Diga comigo: FELIZ CARNAVAL!"]],
  str_item_intro_3751579 = "Desbloqueia o avatar correspondente.\n\"May todas as coisas neste mundo contribuem para a realização dos seus desejos por toda a eternidade.\"",
  str_item_intro_3763046 = "Desbloqueia o quadro de avatar correspondente.\n\"Desejo que tudo corra do seu jeito. Desejo que você seja imparável. Desejo que você alcance tudo o que deseja. Desejo que você sempre persista. Desejo que você sempre esteja comigo para que possamos compartilhar ainda mais momentos felizes juntos!\"",
  str_item_intro_3763047 = "Desbloqueia o quadro de avatar correspondente.\nEste estandarte de totem, que é popular em toda a Ilha das Nuvens, é um símbolo de crescimento e coragem.",
  str_item_3751581 = "Tocando Sensações",
  str_item_3751582 = "Yum-Yum",
  str_item_3751580 = "Dono das Presas Ocultas",
  str_item_intro_3751581 = "Desbloqueia o Avatar correspondente.\n\"Oh, é assim... que se sente ao ser amado por alguém?\"",
  str_item_intro_3751582 = [[
Desbloqueia o avatar correspondente.
"Mais uma mordida... Sim, mais uma mordida!"]],
  str_item_intro_3751580 = "Desbloqueia o Avatar correspondente.\n\"Sou o proprietário do Hidden Fangs em Umbraton. Bem-vindo ao mundo dos jogos!\"",
  str_item_3751436 = "Olhar Determinado",
  str_item_3751583 = "Chamas da Rebelião",
  str_item_3751584 = "Convidado de Honra",
  str_item_3751585 = "Brinde à Nossa Amizade",
  str_item_3763048 = "Perspectivas Futuras da Illumina",
  str_item_3763049 = "Chave da Tumba Secreta",
  str_item_intro_3751436 = "Desbloqueia o avatar correspondente.\n\"É maravilhoso ter todos vocês aqui!\"",
  str_item_intro_3751583 = "Desbloqueia o avatar correspondente.\n\"Você precisa ser mais forte. Mais forte que os Aurorians mais fortes do mundo.\"",
  str_item_intro_3751584 = [[
Desbloqueia o avatar correspondente.
"Mesmo que eu morra hoje, ainda quero ver seu rosto verdadeiro."]],
  str_item_intro_3751585 = "Desbloqueia o avatar correspondente.\n\"Aproximar-se dele é perfeitamente aceitável, mas peço que se comportem com um pouco mais de dignidade. Afinal, ele está aqui a meu pedido.\"",
  str_item_intro_3763048 = "Desbloqueia o quadro de avatar correspondente.\n\"Mas não se preocupe. Nada pode permanecer o mesmo para sempre, e enquanto algumas mudanças podem realmente nos sobrecarregar, na maioria das vezes, a mudança é emocionante.\"",
  str_item_intro_3763049 = "Desbloqueia o quadro de avatar correspondente.\n\"Pode-se revelar os segredos guardados pela Caixa Preta à fraca luz de uma simples vela?\"",
  str_item_3751438 = "Percepção da Verdade",
  str_item_3751586 = "Iluminado",
  str_item_3763050 = "Estrada Brilhante",
  str_item_intro_3751438 = "Desbloqueia o avatar correspondente.\n\"Os buscadores da verdade são como aqueles que perseguem estrelas distantes; eles precisam de olhos sinceros para ver a luz.\"",
  str_item_intro_3751586 = "Desbloqueia o avatar correspondente.\n\"Eu confesso! Eu me arrependo! Eu... Eu sou o abençoado pela verdade.\"",
  str_item_intro_3763050 = "Desbloqueia o quadro de avatar correspondente.\n\"May a Verdade abençoe você, e May sua vida brilhe intensamente daqui em diante.\"",
  str_item_3751426 = "Aura de Ryza",
  str_item_3751427 = "Sorriso de Klaudia",
  str_item_3751428 = "A Tenacidade de Patricia",
  str_item_3751575 = "Rumo a Uma Nova Aventura",
  str_item_3751576 = "Flor de Verão Esplêndida",
  str_item_3751587 = "Rei Naval Ambicioso",
  str_item_3751588 = "Drone Aquático",
  str_item_3763044 = "Devaneio Espumante",
  str_item_3763045 = "Brisa Marinha Cintilante",
  str_item_3763051 = "Capture o Verão",
  str_item_3763052 = "Rico Imundo",
  str_item_3763053 = "Juramento Angel",
  str_item_3751444 = "Por favor, divirta-se.",
  str_item_3751443 = "O Elfo no Mar",
  str_item_3751589 = "Princesa dos Contos",
  str_item_3751594 = "Caçador de Acheron",
  str_item_3751593 = "Serpente Dourada",
  str_item_3751592 = "Leitor de Juramento",
  str_item_3751591 = "Claymore",
  str_item_intro_3751594 = "Desbloqueia o avatar correspondente.\n\"As asas negras cortam o céu sobre o Acheron como uma lâmina afiada.\"",
  str_item_intro_3751593 = "Desbloqueia o avatar correspondente.\n\"Seja para negócios ou apenas por diversão, com ouro suficiente, estou à sua disposição!\"",
  str_item_intro_3751592 = "Desbloqueia o avatar correspondente.\n\"O juramento milenar não será esquecido. Um sinal de gratidão do clã Longinus, concedido apenas àqueles que completam a verdadeira jornada de um herói.\"",
  str_item_intro_3751591 = "Desbloqueia o avatar correspondente.\n\"Não mostre misericórdia - minha lâmina está aqui para guardar as histórias das estrelas.\"",
  str_item_intro_3763052 = "Desbloqueia o quadro de avatar correspondente.\n\"O ouro é cegante!\"",
  str_item_intro_3763053 = "Desbloqueia o quadro de avatar correspondente.\n\"As asas negras são as guardiãs de um juramento milenar.\"",
  str_item_intro_3751444 = "Desbloqueia o avatar correspondente.\n\"Olhe para os competidores, totalmente envolvidos e lutando por suas posições. Por favor, aproveite este jogo e mostre seu apoio!\"",
  str_item_intro_3751443 = "Desbloqueia o avatar correspondente.\n\"Gosto de água e adoro nadar. Devo entrar na competição e me divertir com todos?\"",
  str_item_intro_3751589 = "Desbloqueia o avatar correspondente.\n\"Eu quero ter um sonho bonito, onde não há tristeza e a felicidade dura para sempre...\"",
  str_item_intro_3751426 = "Desbloqueia o avatar correspondente.\n\"O que é isso? Que comovente...\"",
  str_item_intro_3751427 = "Desbloqueia o avatar correspondente.\n\"Bem-vindo de volta. Como foi sua aventura? Você viu algo particularmente interessante?\"",
  str_item_intro_3751428 = "Desbloqueia o avatar correspondente.\n\"Ah, desculpe por deixar você ver um lado tão embaraçoso de mim. Eu vou me certificar de manter a minha compostura na próxima vez.\"",
  str_item_intro_3751575 = "Desbloqueia o avatar correspondente.\n\"Em direção a uma nova aventura!\"",
  str_item_intro_3751576 = "Desbloqueia o avatar correspondente.\n\"Passar o verão com amigos é o melhor!\"",
  str_item_intro_3751587 = "Desbloqueia o avatar correspondente.\n\"Já que essa teimosia pode conquistar a terra, enfrentar o mar não deveria ser um problema... certo?\"",
  str_item_intro_3751588 = "Desbloqueia o avatar correspondente.\n\"Beep-beep, ativando o modo de navegação na água...\"",
  str_item_intro_3763044 = "Desbloqueia o quadro de avatar correspondente.\n\"Todos que se banham nesta luz sentirão seus corações se tornando mais brilhantes.\"",
  str_item_intro_3763045 = "Desbloqueia o quadro de avatar correspondente.\n\"Vir para Astra é o acidente mais surpreendente deste verão!\"",
  str_item_intro_3763051 = "Desbloqueia a moldura de avatar correspondente.\n\"Um bóia de natação na moda que faz ansiar pelo mar à primeira vista. Não perca o verão fugaz - aja rapidamente e use-o para abraçar a estação!\"",
  str_item_3661248 = "Estátua do Herói Antigo",
  str_item_3661249 = "Estátua do Oficial Antigo",
  str_item_intro_3661248 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUma antiga estátua, recentemente desenterrada e identificada como um guerreiro civil honrado em tempos passados com base em sua vestimenta e adereços de cabeça. Arqueólogos observam que apenas nobres tinham o direito de encomendar suas estátuas durante aquela era, o que significa que ele deve ter realizado feitos tão notáveis que as pessoas criaram esta estátua em admiração.\n\"Eu protegerei o mundo que ela tanto estimava!\"",
  str_item_intro_3661249 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUma antiga estátua, recentemente desenterrada e identificada como um oficial de alta patente militar com base em sua vestimenta e adereços de cabeça. Arqueólogos observam que os oficiais militares eram quase exclusivamente de nascimento nobre durante aquela era. Portanto, ao contrário da estátua de um guerreiro civil, esta provavelmente veio das mãos de um escultor dedicado a servir a nobreza.\n\"Deixe o resto comigo; eu cuidarei disso.\"",
  str_item_3661250 = "Estátua de Neve Fox",
  str_item_3661251 = "Castiçal de Pinha",
  str_item_3661252 = "Estante de Robyn",
  str_item_3661253 = "Estéreo do Colecionador",
  str_item_3661254 = "Mesa Baixa de Lazer",
  str_item_intro_3661250 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nUma estátua amada entre os Northlanders, supostamente modelada após um guarda de Northland, criada para homenagear um camarada significativo perdido na batalha.",
  str_item_intro_3661251 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nFeito do mais fino pinho, este castiçal atmosférico libera um delicado aroma de pinho, auxiliando na relaxação e no sono.",
  str_item_intro_3661252 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nUma estante de formato simples feita de madeira de alta qualidade, exala uma fragrância sutil.",
  str_item_intro_3661253 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUm elegante aparelho de som perfeito para eventos solenes. Sua tonalidade é mais adequada para uma procissão cerimonial do que para a música heavy metal que Ansia adora.",
  str_item_intro_3661254 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUma mesa elegante e econômica perfeita para momentos de lazer dos moradores urbanos, um best-seller em qualquer lugar.",
  str_item_3661256 = "Relógio Vintage",
  str_item_3661257 = "Pintura Decorativa Noite ao Luar",
  str_item_3661258 = "Pelúcia de Lebracão",
  str_item_3661260 = "Grelha Rediesel",
  str_item_intro_3661256 = "Item de mobília. Pode ser colocado em salas no seu Colossus.\nA estrutura metálica deste relógio é elegantemente trabalhada, e seu rosto foi especialmente tratado para produzir um brilho bronzeado ao longo do tempo.",
  str_item_intro_3661257 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nUma bela pintura decorativa da lua contra o céu noturno. Do centro da pintura, emite um brilho suave e gentil.",
  str_item_intro_3661258 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUma boneca em forma de beagle. Seus olhos parecem dizer: \"Eu vejo, eu quero e eu preciso ter!\"",
  str_item_intro_3661260 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nA churrasqueira mais comum encontrada nos acampamentos da Rediesel Wrench. Embora seja em grande parte construída de sucata, esta churrasqueira dá aos alimentos um sabor irresistivelmente tostado - Ou pelo menos a Rediesel Wrench parece pensar assim.",
  str_item_3661265 = "Retrato Elegante do Viajante",
  str_item_3661266 = "Estátua Grotesca de Cenoura",
  str_item_intro_3661265 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nLendas falam de um viajante que construiu a doce cidade de Folta em uma terra de leite e mel infinitos...\n\"Onde exatamente fica essa cidade? Poderia ser... Em um mundo completamente diferente?\"",
  str_item_intro_3661266 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nPara crianças que odeiam comer cenouras, seus olhos verdes brilhantes e garras afiadas são mais aterrorizantes do que qualquer Eclipsite...\n\"Po... Mas eu sou Popo, uma pobre e pequena cenoura...\"",
  str_item_3661267 = "Jogo de Arcade Retro",
  str_item_intro_3661267 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\n\"Se eu vou ficar a bordo do Colossus, então eu tenho que levar isso comigo... Ou então eu não vou sobreviver.\"\nQuando apresentado com tal pedido, o Navegador estava mais do que disposto a arriscar alguns músculos puxados para acomodar seu amigo.",
  str_item_3661268 = "Decoração de Parede com Óculos de Sol Pixel",
  str_item_intro_3661268 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\n\"Você perdeu, Yingel. Deixe os despojos para trás.\"\nUm prêmio arduamente conquistado após derrotar Yingel. Parece alguma mercadoria de um jogo.",
  str_item_3661271 = "Caixa de Armazenamento de Boneca",
  str_item_intro_3661271 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nPara colecionadores de pelúcias que tendem a perder o controle de seus pertences, esta é possivelmente a maior invenção do mundo.",
  str_item_3661272 = "Relógio de Pata de Gato",
  str_item_intro_3661272 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUm relógio de parede supremamente adorável na forma de uma pata de gato. É quase uma pena ter que pendurar algo tão macio na parede.",
  str_item_3661273 = "Pódio do Calouro",
  str_item_intro_3661273 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nUm certo rumor está se espalhando por Illumina: novos estudantes que gritam seus sonhos de um pódio se tornarão heróis respeitados algum dia.",
  str_item_3661274 = "Lareira de Ferro Fundido",
  str_item_intro_3661274 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nUma lareira de ferro fundido produzida na Federação Illumina. Além de sua respeitável capacidade de aquecimento, sua aparência pitoresca e chamas quentes trazem um aconchego inegável para qualquer sala.",
  str_item_3661275 = "Tapete da Iluminação",
  str_item_intro_3661275 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nRoupa de cama de alta qualidade da cidade de Varaki. Confortável e aconchegante, tem um ar distintamente clássico. Discípulos da Verdadeira Ordem o consideram como uma cama de revelação divina.",
  str_item_3661276 = "Espelho do Amanhã",
  str_item_intro_3661276 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\n\"Aqueles que buscam a verdade devem olhar para este antigo espelho de madeira e contemplar visões do que está por vir.\" Sério, quem inventa essas coisas...?",
  str_item_3661277 = "Retrato do Soldado Corajoso",
  str_item_intro_3661277 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nO rugido avassalador dos Eclipsitas atacantes abafou até mesmo o sinal do clarim para a carga. Mas quando um soldado heroico içou o estandarte e avançou, milhares de outros seguiram de perto.\n\"Dedicado àqueles heróis destemidos que bravamente deram suas vidas.\"",
  str_item_3661278 = "Estátua do Sino do Juízo Final",
  str_item_intro_3661278 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nUma estátua repulsiva e aterrorizante. Sua aparência malévola leva as pessoas a acreditarem que foi criada como uma inimiga do mundo.\nDiz-se que, ao avançar pesadamente, a armadura de metal que usava batia dully - o requiem rancoroso do sino do pôr do sol.",
  str_item_3661262 = "Modelo do Guardião das Ruínas",
  str_item_intro_3661262 = "Item de mobília. Pode ser colocado nas salas da sua Colossus.\nUm modelo criado por Fleur, que está sempre pensando no guardião das ruínas.\n\"Provavelmente poderia ser considerado um tipo de mecha!\"",
  str_item_3661263 = "Caldeirão de Alquimia",
  str_item_intro_3661263 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nCom isso, o Atelier do Ryza na Colossus finalmente pode abrir para negócios!",
  str_item_3661264 = "Pós-imagem de Aventura",
  str_item_intro_3661264 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nVamos relembrar deste verão uma vez que ele acabe!",
  str_item_3661279 = "Elmo da Brisa do Verão",
  str_item_intro_3661279 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nCom ambas as mãos colocadas sobre ele, quase se pode sentir o carinho da brisa do mar, capturando perfeitamente a essência fresca do oceano de verão. Um móvel essencial para qualquer entusiasta de vela.",
  str_item_3661280 = "Bóia Brisa de Verão",
  str_item_intro_3661280 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nProjetado com um esquema de cores clássico e estrutura robusta, seja colocado em casa ou usado no mar, é sempre uma visão encantadora.",
  str_item_3661281 = "Bandeira Brisa do Verão",
  str_item_intro_3661281 = "Artigo de mobília. Pode ser colocado em salas do seu Colossus.\nUm banner decorativo simples, mas elegante, adequado para qualquer espaço que necessite de um toque náutico.",
  str_item_3661282 = "Guardião de Aves Marinhas Concha",
  str_item_intro_3661282 = "Item de mobília. Pode ser colocado em salas no seu Colossus.\n\"Grande concha, toot-toot-toot. As gaivotas ouvem e caem do céu.\"\nNão se sabe ao certo a origem, mas essa música tem se espalhado no Colossus.",
  str_item_3661283 = "Blaster de Bolhas Brisa",
  str_item_intro_3661283 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nUma arma de bolhas fixada em uma base, parece soprar bolhas com um único pressionar.\n\"Que adereço casual! Espero que não faça todos dormirem.\"",
  str_item_3661284 = "Retrato do Narciso Branco",
  str_item_intro_3661284 = "Item de mobília. Pode ser colocado nos quartos da sua Colossus.\nNikinis adora cultivar flores de narciso. Ela cuida profundamente de suas plantas e jogará qualquer um que as pise no Lago Espelho.",
  str_item_3661285 = "Retrato Puro de Lírio",
  str_item_intro_3661285 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nNepolis gosta de cultivar lírios. Ela frequentemente os colhe para dar como presentes, deixando apenas sua doce fragrância para trás.",
  str_item_3661286 = "Radiância Estelar",
  str_item_intro_3661286 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nA pintura de Mithra - o sorriso fugaz de Aquiles.\nEstrela inflexível, que você e seus companheiros brilhem intensamente novamente.",
  str_item_3661287 = "Lâminas Duplas",
  str_item_intro_3661287 = "Item de mobília. Pode ser colocado em salas na sua Colossus.\nRéplicas das armas usadas pelo capitão e vice-capitão dos Caçadores Silenciosos.\nEis! Este é o auge da inovação e a determinação para guardar! Isso é o que os Caçadores Silenciosos representam.",
  str_item_3661288 = "Estande de Predador",
  str_item_intro_3661288 = "Artigo de mobiliário. Pode ser colocado em salas do seu Colossus.\nUm poleiro que Mithra montou para o predador.\nEles podem parecer relaxados lá em cima, mas essas garras não são brincadeira.",
  str_item_3661289 = "Unidade Estelar",
  str_item_intro_3661289 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUma peça antiga que foi restaurada.\nSe as estrelas que riscam o céu pudessem um dia encontrar onde pertencem na suavidade do tempo...\nMay você recebe felicidade atrasada.",
  str_item_3661290 = "Melodia ao Luar",
  str_item_intro_3661290 = "Artigo de mobília. Pode ser colocado em salas no seu Colossus.\nUma melodia de Ludweiss, um Caelestite.\nÉ pura e graciosa como a luz da lua, com um toque de tristeza inabalável. May você recebe felicidade atrasada.",
  str_item_9998002 = "Máscara Elo Venenoso",
  str_item_9998003 = "Grito Rebelde",
  str_item_9998004 = "Mão de Deus",
  str_item_9998005 = "Luz do Ceifador",
