  str_item_9998039 = "Pedra Enfeitiçada",
  str_item_9998040 = "Armadura Berserker",
  str_item_9998041 = "Cristal Atordoante",
  str_item_9998042 = "Lâmina Aguçada",
  str_item_9998043 = "Mão Maldita",
  str_item_9998044 = "Regicida",
  str_item_9998045 = "Armazenamento de Energia",
  str_item_9998046 = "Estátua do Legionário",
  str_item_9998047 = "Amplificador",
  str_item_9998048 = "Óculos Luz Solar",
  str_item_9998049 = "Morte Silenciosa",
  str_item_9998050 = "Perfuração Final",
  str_item_9998051 = "Ragnarok",
  str_item_9998052 = "Armadura Lúmina",
  str_item_9998053 = "Escudo Lúmina",
  str_item_9998054 = "Cx. Mágica Lúmina",
  str_item_9998055 = "Armadilha de Aumento de Dano",
  str_item_9998056 = "Jarra de Doces Energéticos",
  str_item_9998057 = "Manuscrito Velho",
  str_item_9998058 = "Energizador Móvel",
  str_item_9998059 = "Botas Estilhaçantes",
  str_item_9998060 = "Caixa trancada misteriosa",
  str_item_9998061 = "Caleidojoia",
  str_item_9998062 = "Paralisador",
  str_item_9998063 = "Nota de Morte",
  str_item_9998064 = "Escudo Lunaprata",
  str_item_9998065 = "Sakura Cadente",
  str_item_9998066 = "Coração da Devoção",
  str_item_9998067 = "Estratégia de Conservação",
  str_item_9998068 = "Golpe de Escudo do Batalhão",
  str_item_9998069 = "Concerto do Batalhão",
  str_item_9998070 = "Vaso Sacrifical do Batalhão",
  str_item_9998071 = "Tambor do Batalhão",
  str_item_9998072 = "Bandeira de Guerra do Batalhão",
  str_item_9998073 = "Ceifalma",
  str_item_9998074 = "Blaster",
  str_item_9998075 = "Caltrops Deslumbrantes",
  str_item_9998076 = "Tinta Absorvente",
  str_item_intro_9998002 = "No início de cada rodada, inflige aleatoriamente 1 acúmulo de Veneno, Sangramento ou Queimação em todos os inimigos no campo; o efeito é repetido 4 vezes. Reduz o dano causado pelos Aurorianos em 15%.",
  str_item_intro_9998003 = "Todo o dano sofrido por inimigos com debuff ou sob efeito de debuff aumenta em 20%.",
  str_item_intro_9998004 = "Ao remover ladrilhos, inflige aleatoriamente 1 acúmulo de Tóxico, Sangramento ou Queimação nos inimigos dentro do alcance dos ladrilhos removidos; o efeito é repetido 5 vezes.",
  str_item_intro_9998005 = "Quando um inimigo Envenenado/Queimando/Sangrando é derrotado, inflige 1 acúmulo de Veneno, Sangramento e Queimação em todos os inimigos restantes no campo.",
  str_item_intro_9998006 = "Aumenta o dano recebido pelos inimigos de Veneno, Sangramento ou Queimação em 100%.",
  str_item_intro_9998007 = "Ao infligir com sucesso Envenenamento, Queimação ou Sangramento nos inimigos, o alvo perde imediatamente 1% de seu HP atual.",
  str_item_intro_9998008 = "Concede o Equipamento Especial de Caelestite: Consome 2 rodadas para lançar instantaneamente uma habilidade de suporte de facção Lv.2 uma vez. Só pode ser usado uma vez a cada rodada.",
  str_item_intro_9998009 = "Quanto mais perto do inimigo, maior o dano do Combo em Cadeia dos Aurorianos, com um aumento máximo de 30%.",
  str_item_intro_9998010 = "Concede aos Aurorians Detonadores 30% de chance de lançar um Combo em Cadeia adicional; para cada ladrilho removido nesta rodada, a chance de acionamento aumenta em 1%.",
  str_item_intro_9998011 = "O Capitão luta com base apenas em seu próprio elemento, causando 100% mais dano.",
  str_item_intro_9998012 = "Quando o líder da equipe lança um Combo, gera uma sombra na posição prestes a ser removida e libera um Combo ao mesmo tempo.",
  str_item_intro_9998013 = "Após a próxima vitória, concede 2 chances adicionais para selecionar o Equipamento de Iluminação na próxima batalha, efetivo uma vez.",
  str_item_intro_9998014 = "Concede uma chance de reembaralhar ao selecionar o Equipamento de Iluminação, disponível para uso 8 vezes.",
  str_item_intro_9998015 = "Remove o Equipamento Especial Caelestite inicial e concede imediatamente 2 chances para a seleção de Equipamento de Iluminação.",
  str_item_intro_9998016 = "Quando um Auroriano ataca 3 ou mais inimigos com uma Habilidade Ativa ao mesmo tempo, lança um raio que ataca todos os inimigos, causando dano igual a 200% do ATQ médio da equipe.",
  str_item_intro_9998017 = "Após trocar o Capitão, o tempo de recarga da Habilidade Ativa do novo Capitão é reduzido em 1 rodada. O mesmo Auroriano pode acioná-lo no máximo uma vez por rodada.",
  str_item_intro_9998018 = "Torna a equipe invencível por 1 rodada quando o HP da equipe cai para 1%, depois restaura 20% do HP máximo. Este efeito só pode ser acionado uma vez a cada batalha, até um total de 2 vezes.",
  str_item_intro_9998019 = "Restaura 35% do PV perdido da equipe após vencer uma batalha.",
  str_item_intro_9998020 = "Recarrega um curativo no campo no início da batalha.",
  str_item_intro_9998021 = "Aumenta o dano dos Aurorianos em 15% quando o HP atual da equipe é superior a 90%.",
  str_item_intro_9998022 = "Concede um escudo igual a 40% do HP máximo que dura 2 rodadas no início de cada onda.",
  str_item_intro_9998023 = "Restaura o HP para 50% no início da batalha se o HP atual for inferior a 50%.",
  str_item_intro_9998024 = "Apoiador Aurorianos +40% em efeitos de regeneração de Combos e Habilidades Ativas em batalha.",
  str_item_intro_9998025 = "Para cada elemento primário de Aurorianos na equipe, aumenta o dano causado pelos Aurorianos em 6%, com um aumento máximo de 24%.",
  str_item_intro_9998026 = "Quando os Aurorianos causam dano, ignoram o efeito de redução de dano de ter seu elemento anulado. Ao receber dano, ignoram o bônus de ter seu elemento anulado.",
  str_item_intro_9998027 = "O elemento secundário do auroriano causa dano com o mesmo multiplicador que o seu elemento primário.",
  str_item_intro_9998028 = "Permite que os Aurorianos Ligados ignorem os elementos das casas a serem removidas ao lançar o Combo em Cadeia.",
  str_item_intro_9998029 = "Para cada conjunto de Aurorianos Ligados, restaura 5% do HP Máx. da equipe no início de cada rodada.",
  str_item_intro_9998030 = "Para cada conjunto de Aurorianos Ligados, há uma chance de 40% de ganhar 1 carga adicional para o Equipamento Especial Caelestite ao remover ladrilhos. Acionado independentemente quando há múltiplos conjuntos de Laços.",
  str_item_intro_9998031 = "Aurorians Vinculados herdam 20% do ATQ Básico um do outro.",
  str_item_intro_9998032 = "Quando um Auroriano lança uma Habilidade Ativa, reduz o tempo de espera das Habilidades Ativas dos Aurorianos vinculados em 1 rodada. Pode ser acionado até 5 vezes por batalha.",
  str_item_intro_9998033 = "Reduz o tempo de recarga da primeira Habilidade Ativa lançada em cada batalha em 2 rodadas imediatamente após ser lançada.",
  str_item_intro_9998034 = "Após tocar para remover os ladrilhos, se os Aurorianos não lançaram o Combo em Cadeia nesta rodada, reduz o tempo de espera da Habilidade Ativa de todos os Aurorianos em 1.",
  str_item_intro_9998035 = "Quanto mais longe os Aurorianos estiverem de um inimigo, maior será o dano do seu Combo em Cadeia, com um aumento máximo de 50%.",
  str_item_intro_9998036 = "Aumenta o número de alvos do Combo em Cadeia dos Aurorians Atiradores em 2.",
  str_item_intro_9998037 = "Aurorianos ganham 3% de Dreno de Vida ao causar dano e perdem 10% do seu HP atual no início de cada rodada.",
  str_item_intro_9998038 = "Quanto menor o HP atual, maior o dano do Chain Combo de Aurorian, com um aumento máximo de 50%.",
  str_item_intro_9998039 = "Todos os aliados e inimigos perdem 7% de seu HP atual no início de cada rodada.",
  str_item_intro_9998040 = "Quando o HP atual de Aurorian está em 50%, aumenta o dano causado pelo Aurorian em 30%; para cada 1% de diferença de HP, esse aumento diminui em 5%.",
  str_item_intro_9998041 = "Perca 7% do HP atual no início de cada rodada. Depois disso, cause dano igual a 150% do ATK médio da equipe aos inimigos em 2 círculos ao redor.",
  str_item_intro_9998042 = "No início da batalha, perde 70% do seu HP atual e causa dano a todos os inimigos igual a 300% dessa perda.",
  str_item_intro_9998043 = "Aumenta o dano da Habilidade Ativa dos Aurorianos em 80%. Perde 8% do HP atual cada vez que uma Habilidade Ativa é lançada.",
  str_item_intro_9998044 = "Ignora o número de ladrilhos tocados e removidos e permite que os Aurorianos lancem seu Combo de Cadeia de nível mais alto cada vez após a remoção.",
  str_item_intro_9998045 = "No início da batalha, ganha 1 chance de uso para todo o Equipamento Especial de Caelestite.",
  str_item_intro_9998046 = "Cada uso do Equipamento Caelestite Especial aciona uma habilidade de suporte de facção Lv.1 uma vez; efetivo 2 vezes por batalha.",
  str_item_intro_9998047 = "Expande o alcance efetivo do Equipamento Caelestite Especial inicial para 5x5; ganha 1 chance de uso após acumular 40 pontos de energia.",
  str_item_intro_9998048 = "Aumenta a eficiência de recarga da chance de uso do Equipamento Especial de Caelestite em 50%.",
  str_item_intro_9998049 = "Derrota inimigos com menos de 9% de HP.",
  str_item_intro_9998050 = "Aumenta o dano causado pelos Aurorianos em 20%; duplica o consumo de rodadas.",
  str_item_intro_9998051 = "Reduz a DEF de todos os aurorianos na equipe para zero e transforma 50% de sua DEF básica em ATK.",
  str_item_intro_9998052 = "Aumenta o PV Máx. de todos os Aurorians em 2% para cada peça de Equipamento de Iluminação possuída.",
  str_item_intro_9998053 = "Aumenta a DEF de todos os Aurorianos em 1,5% para cada peça de Equipamento de Iluminação possuída.",
  str_item_intro_9998054 = "Aumenta o ATQ de todos os Aurorians em 1% para cada peça de Equipamento de Iluminação possuída.",
  str_item_intro_9998055 = "Uma Armadilha de Aumento de Dano aparece aleatoriamente no campo de batalha no início de cada rodada. Após destruir esta armadilha, o dano do Chain Combo aumenta em 35% nesta rodada.",
  str_item_intro_9998056 = "No início de cada onda, um Pote de Doces de Energia surge aleatoriamente no campo de batalha, que concede 1 chance de uso para um Equipamento Caelestite Especial aleatório ao ser destruído.",
  str_item_intro_9998057 = "Aumenta o número de todos os itens removíveis no campo de batalha para 2 ao surgir.",
  str_item_intro_9998058 = "No início de cada onda, um Energizador Móvel aparece aleatoriamente no campo de batalha, que concede 3 rodadas extras ao ser removido.",
  str_item_intro_9998059 = "No início de cada rodada, quebra o ladrilho abaixo, aumentando o dano causado pelos Aurorianos em 15%.",
  str_item_intro_9998060 = "Redefina a contagem de eficácia de todo o Equipamento de Iluminação para seu estado inicial.",
  str_item_intro_9998061 = "Concede o Equipamento Especial de Caelestite: Converte todos os ladrilhos no campo em ladrilhos cromáticos. Vem com 2 chances de uso após a aquisição.",
  str_item_intro_9998062 = "Aumenta o dano do Chain Combo aos inimigos dentro do alcance das peças removidas em 35%.",
  str_item_intro_9998063 = "Ao tocar para remover as casas, causa dano igual a 150% do ATK médio da equipe aos inimigos dentro do alcance das casas removidas.",
  str_item_intro_9998064 = "Ao tocar para remover ladrilhos, concede um escudo igual a 0,5% do HP máximo para cada ladrilho removido, durando 1 rodada.",
  str_item_intro_9998065 = "Ao remover pelo menos 15 ladrilhos de uma vez com um toque, aumenta o dano do Combo em Cadeia dos Aurorianos em 30%. O Combo em Cadeia não pode ser lançado se menos de 7 ladrilhos forem removidos de uma vez.",
  str_item_intro_9998066 = "Aumenta o ATK básico do Auroriano com o menor ATK na equipe em 60%.",
  str_item_intro_9998067 = "Reduz o número de ladrilhos necessários para acionar habilidades de suporte de facção: reduz 5 para habilidades de suporte de facção de Lv.1; reduz 10 para habilidades de suporte de facção de Lv.2.",
  str_item_intro_9998068 = "Permite habilidades de suporte de facção para repelir inimigos em 1 quadrado.",
  str_item_intro_9998069 = "No início de cada rodada, para cada Auroriano na equipe pertencente à mesma facção que a habilidade de suporte de facção, todo o Equipamento Caelestite Especial ganha 3 cargas.",
  str_item_intro_9998070 = "Concede o efeito Life Drain para habilidades de suporte de facção; para cada Aurorian dessa facção na equipe, concede um extra de 5% de Life Drain.",
  str_item_intro_9998071 = "Ao tocar para remover peças, cada peça removida aumenta o dano final da habilidade de suporte da facção em 5% para a rodada atual.",
  str_item_intro_9998072 = "Para cada Auroriano na equipe pertencente à mesma facção que a habilidade de suporte da facção, aumenta o dano final da habilidade de suporte da facção em 25%.",
  str_item_intro_9998073 = "Para cada Aurorian na equipe pertencente à mesma facção que a habilidade de suporte da facção, aumenta a DEF Básica e o PV Máx. de todos os Aurorians em 3%.",
  str_item_intro_9998074 = "Aumenta o dano das Habilidades Ativas dos Aurorians em 100%; apenas a Ascensão I do Combo em Cadeia pode ser lançada.",
  str_item_intro_9998075 = "No início de cada rodada, converte 1 peça abaixo de 2 inimigos aleatórios no campo para cromática.",
  str_item_intro_9998076 = "Quando um inimigo é eliminado, converte 1 ladrilho abaixo dele para o mesmo elemento que o Capitão.",
  str_item_4090264 = "Feitiço Encantador da Noite",
  str_item_intro_4090264 = "Navegador, eu não quero mais ser um Aurorian.\nIncapaz de suportar o vazio, Uriel deseja mudar sua forma de existência com uma poção mágica. No entanto, a mistura não leva à mudança esperada, mas a uma embriaguez caprichosa. Seu desânimo e distanciamento habituais desaparecem, substituídos por um espírito novo e cheio de energia, ansiando por aventuras emocionantes com você. Como você vai navegar por essa reviravolta inesperada?",
  str_item_3400132 = "Mentes Ligadas, Ribbit",
  str_item_intro_3400132 = "Desbloqueia o fundo: Mentes Ligadas, Ribbit\nA notável habilidade do sapo reside em sua conexão consciente com todas as coisas, e através deste dom, o sapo assume o importante dever de curar seus companheiros...",
