  str_item_9011087 = "Lâminas de Braço Lunar",
  str_item_9011088 = "Chifre Lunar",
  str_item_intro_9011001 = "No início da rodada, causa 4.444 de dano fixo a todos os inimigos e elimina aqueles com menos de 6% de HP.",
  str_item_intro_9011002 = "Gera peças cromáticas na área circundante a cada rodada, com a quantidade igual ao número de tipos de Elementos Primários dos Aurorianos na equipe. A habilidade é executada mais 2 vezes no início da batalha.",
  str_item_intro_9011003 = "Converte todos os ladrilhos para cromáticos na terceira rodada da batalha. Após o término da conexão do ladrilho, todos os ladrilhos cromáticos serão limpos.",
  str_item_intro_9011004 = "Aumenta o dano causado por Aurorianos com HP igual ao máximo em 15%.",
  str_item_intro_9011005 = "Após completar a fase Devorador de Sonhos, ganha juros equivalentes a 30% do seu saldo atual de Moedas do Sonho.",
  str_item_intro_9011006 = "Uso único: Ganha 2 Bombas dos Sonhos.",
  str_item_intro_9011007 = "Quanto mais Moedas dos Sonhos você possui, maior o dano que seus ataques normais causam.",
  str_item_intro_9011008 = "O primeiro ladrilho em uma linha pode ter uma cor diferente dos subsequentes, permitindo que ambos os tipos de Aurorianos entrem na batalha.",
  str_item_intro_9011009 = "Randomiza todas as Dream Orbs desequipadas em novas (sem nível inferior ao original) e cada Dream Orb tem 30% de chance de aumentar a classificação.",
  str_item_intro_9011010 = "Quando a cor das casas conectadas corresponde ao elemento do Capitão, o Orbe dos Sonhos ganha 1 carga para cada 2 casas conectadas.",
  str_item_intro_9011011 = "Quando as habilidades do Orbe dos Sonhos causam dano, são realizados dois cálculos aleatórios dentro de um intervalo e o valor mais alto é escolhido como o dano causado, aumentando a variação de dano em 10%.",
  str_item_intro_9011012 = "Redefine a classificação das Esferas do Sonho obtidas posteriormente para 1 estrela.",
  str_item_intro_9011013 = "Ao selecionar um Cartão de Adivinhação dos Sonhos, diminui as escolhas disponíveis em 1, mas duplica os efeitos de recompensa dos cartões.",
  str_item_intro_9011014 = "Diminui o HP Máx. de todos os Aurorianos em 20% após entrar em combate, mas aumenta o número de Cartas de Divinação do Sonho selecionáveis em +1 durante as ações.",
  str_item_intro_9011015 = "Antes de conectar os ladrilhos, sempre que um Auroriano se move, causa dano a uma área em forma de diamante no local de aterrissagem, com média de 150% de seu ATK. Além disso, o Orbe dos Sonhos ganha 1 carga para cada círculo de movimento.",
  str_item_intro_9011016 = "Quando os Combos de Aurorianos Conversores e de Suporte causam dano, aleatoriamente infligem um acúmulo de Envenenado, Sangrando ou Queimando no alvo.",
  str_item_intro_9011017 = "Ao causar dano a inimigos Envenenados, Sangrando ou Queimados, aumenta o dano para cada efeito.",
  str_item_intro_9011018 = "Após infligir um acúmulo de Envenenado, Sangrando ou Queimando no alvo, há uma chance de aplicar outro acúmulo de debuff aleatório. Este efeito pode ser acionado repetidamente, com a probabilidade reduzida pela metade a cada vez.",
  str_item_intro_9011019 = "Quando um inimigo morre, aplica aleatoriamente uma pilha de Envenenado, Sangrando ou Queimando a todos os inimigos.",
  str_item_intro_9011020 = "Ao lançar ataques normais, o Capitão causa dano adicional de Fogo equivalente a 50% do ATK geral da equipe.",
  str_item_intro_9011021 = "Ao lançar ataques normais, o Capitão causa dano adicional de Trovão equivalente a 50% do ATK geral da equipe.",
  str_item_intro_9011022 = "Ao lançar ataques normais, o Capitão causa dano adicional de Floresta equivalente a 50% do ATK geral da equipe.",
  str_item_intro_9011023 = "Ao lançar ataques normais, o Capitão causa dano adicional de Água equivalente a 50% do ATK geral da equipe.",
  str_item_intro_9011024 = "No início de cada rodada, converte os 3 ladrilhos vermelhos mais próximos em ladrilhos cromáticos.",
  str_item_intro_9011025 = "No início de cada rodada, converte as 3 peças amarelas mais próximas em peças cromáticas.",
  str_item_intro_9011026 = "No início de cada rodada, converte os 3 ladrilhos verdes mais próximos em ladrilhos cromáticos.",
  str_item_intro_9011027 = "No início de cada rodada, converte os 3 ladrilhos azuis mais próximos em ladrilhos cromáticos.",
  str_item_intro_9011028 = "No início de cada rodada, converte até 1 peça sob cada inimigo em cromática.",
  str_item_intro_9011029 = "Ao receber dano, converte 3 ladrilhos dentro de 2 aglomerados circundantes em cromáticos.",
  str_item_intro_9011030 = "No início de cada rodada, os Aurorianos com menos HP se recuperam proporcionalmente ao seu HP perdido.",
  str_item_intro_9011031 = "Após a vitória na batalha, todos os Aurorianos restauram 20% de seu HP.",
  str_item_intro_9011032 = "Se houver Ladrilhos Escuros obtidos na rodada atual, ganha 1 pilha de Espírito de Batalha.",
  str_item_intro_9011033 = "Aurorianos Apoiadores ganham 1 acúmulo de Espírito de Batalha ao lançar Habilidades Ativas ou Combos para curar a equipe.",
  str_item_intro_9011034 = "Quando as Habilidades Ativas dos aurorianos derrubam ou puxam os inimigos, ganham pilhas de Espírito de Batalha com base no número de alvos afetados. Este efeito pode ser acionado até 3 vezes por rodada.",
  str_item_intro_9011035 = "Ganha 1 acúmulo de Espírito de Batalha sempre que monstros são afligidos com Envenenamento, Sangramento ou Queimação. Este efeito pode ser acionado até 4 vezes por rodada.",
  str_item_intro_9011036 = "Ganha Dream Coins igual a 4 vezes o nível sempre que o Nível dos Sonhos aumenta.",
  str_item_intro_9011037 = "Ganha Moedas dos Sonhos igual a 7 vezes o incremento sempre que o Interesse dos Sonhos aumenta.",
  str_item_intro_9011038 = "Ganha 4 Moedas dos Sonhos para cada Eclipsite derrotado na batalha.",
  str_item_intro_9011039 = "Uso único: Extrai 5 Cartas de Adivinhação dos Sonhos do seu baralho e obtém Interesse dos Sonhos igual à soma de seus passos.",
  str_item_intro_9011040 = "Obtém duas recompensas simultaneamente no Reino do Tesouro dos Sonhos.",
  str_item_intro_9011041 = "Ganha 30 EXP de Sonho toda vez que atravessa um Reino de Sonho Perigoso.",
  str_item_intro_9011042 = "Diminui os preços dos itens compráveis e reduz o custo de re-randomizar Equipamento dos Sonhos, Aurorianos e itens em 35%.",
  str_item_intro_9011043 = "Após a aquisição, os Aurorians enviados para os Reinos Sonhados Inexplorados retornam imediatamente, e a produção de Moedas dos Sonhos e Juros dos Sonhos da expedição são dobrados.",
  str_item_intro_9011044 = "Ganhe 40 EXP de Sonho toda vez que passar por um acampamento.",
  str_item_intro_9011045 = "Uso único: Todos os Aurorianos perdem 70% do seu HP atual; ganha 25 EXP de Sonho para cada Auroriano perdendo HP.",
  str_item_intro_9011046 = "Uso único: Consome metade das atuais Moedas dos Sonhos e ganha 2 EXP dos Sonhos para cada Moeda dos Sonhos consumida.",
  str_item_intro_9011047 = "Aumenta significativamente o dano das Habilidades Ativas dos Aurorianos; Aurorianos perdem HP ao causar dano.",
  str_item_9011048 = "Blaster",
  str_item_9011049 = "Pisador",
  str_item_9011050 = "Regicida",
  str_item_9011051 = "Quebra-Muro",
  str_item_9011052 = "Paralisador",
  str_item_9011053 = "Ataque de Trovão",
  str_item_intro_9011048 = "Ativa o <link=\"1005\"><color=#98500f><u>Módulo de Atualização de Algoritmo</u></color></link>; quanto menos inimigos no campo, maior o dano final.",
  str_item_intro_9011049 = "Ativa o <link=\"1005\"><color=#98500f><u>Módulo de Atualização de Algoritmo</u></color></link>; O Capitão ganha 3 <link=\"1006\"><color=#98500f><u>Pontos de Sobrecarga</u></color></link> ao lançar um ataque normal.",
  str_item_intro_9011050 = "Ativa o <link=\"1005\"><color=#98500f><u>Módulo de Atualização de Algoritmo</u></color></link>; Habilidade Ativa dos Aurorianos: gera 4 <link=\"1006\"><color=#98500f><u>Pontos de Sobrecarga</u></color></link> para cada inimigo atingido.",
  str_item_intro_9011051 = "Ativa o <link=\"1005\"><color=#98500f><u>Módulo de Atualização de Algoritmo</u></color></link>; no início da rodada, quanto menor o PV da equipe, mais <link=\"1006\"><color=#98500f><u>Pontos de Sobrecarga</u></color></link> são ganhos.",
  str_item_intro_9011052 = "Ativa o <link=\"1005\"><color=#98500f><u>Módulo de Atualização de Algoritmo</u></color></link>; ganha 8 <link=\"1006\"><color=#98500f><u>Pontos de Sobrecarga</u></color></link> toda vez que sofre dano.",
  str_item_intro_9011053 = "Ativa o <link=\"1005\"><color=#98500f><u>Módulo de Atualização de Algoritmo</u></color></link>; aumenta o limite de acionamento da Data Bomb para 120 <link=\"1006\"><color=#98500f><u>Pontos de Sobrecarga</u></color></link>, causando mais dano a monstros de grande porte.",
  str_item_intro_9011054 = "Não entra mais no Aurora Time; em vez disso, ganha +1ms de valor cada vez que deveria entrar no Aurora Time, e recebe 5 Ouros (o Aurora Time interrompido por ondas de monstros ou vitória na batalha também conta).",
  str_item_intro_9011055 = "Quando um inimigo morre, converte até 1 ladrilho abaixo dele em um Ladrilho Escuro.",
  str_item_intro_9011056 = "No início da rodada, converte os 2 ladrilhos mais próximos do mesmo elemento que o do Capitão em Ladrilhos Escuros.",
  str_item_intro_9011057 = "Aumenta o número de opções fornecidas durante a seleção de Equipamento dos Sonhos em 1.",
  str_item_intro_9011058 = "A primeira atualização das opções do Dream Gear é gratuita.",
  str_item_intro_9011059 = "Para cada peça de Equipamento dos Sonhos possuída, aumenta o ATQ dos Aurorians Detonadores e Atiradores em 0,5%",
  str_item_intro_9011060 = "Para cada peça de Dream Gear possuída, aumenta a DEF de Aurorianos Conversores e Apoiadores em 2%.",
  str_item_intro_9011061 = "Para cada peça de Equipamento dos Sonhos possuída, aumenta o PV Máx. de todos os Aurorians em 1,5%.",
  str_item_intro_9011062 = "No início de cada rodada, gera 1 relógio (pode existir apenas 1 de cada vez), reduzindo em 1 rodada o tempo de espera da habilidade do Auroriano com o maior tempo de espera.",
  str_item_intro_9011063 = "Aplica <link=\"1010\"><color=#98500f><u>Ofuscado</u></color></link> nos alvos que recebem dano.",
  str_item_intro_9011064 = "Toda vez que sofrem dano, todos os Aurorianos ganham um bônus de dano de 5%, até um máximo de 30% (restaura no final da batalha).",
  str_item_intro_9011065 = "Aumenta o dano de ataques normais em 30%. Este efeito expira após receber dano.",
  str_item_intro_9011066 = "Reduz pela metade a DEF de todos os Aurorianos e aumenta seu próprio ATK pela quantidade de DEF reduzida.",
  str_item_intro_9011067 = "Gera uma imagem do Capitão Aurora no ponto inicial. Esta imagem também desencadeia Chain Combos nesta rodada.",
  str_item_intro_9011068 = "Aumenta o dano em 3,5% para cada Auroriano com diferentes Elementos Primários na equipe.",
  str_item_intro_9011069 = "Os Elementos Secundários podem causar dano com base no multiplicador dos Elementos Primários, com um aumento adicional no multiplicador quando os elementos primários e secundários são os mesmos.",
  str_item_intro_9011070 = "O Capitão anterior pode ser implantado na batalha, independentemente dos elementos das casas conectadas.",
  str_item_intro_9011071 = "Chances de mudança de capitão +2 em cada batalha.\nAo trocar de capitão, o cooldown da habilidade ativa do novo capitão é reduzido em 1. Cada auroriano só pode ativar esse efeito uma vez a cada rodada.",
  str_item_intro_9011072 = "Após cada conexão ou movimento de ladrilho, o ladrilho inicial deve ser do mesmo elemento que o do Capitão.",
  str_item_intro_9011073 = "Aumenta o dano causado por todos os aliados em 15%, mas converte a peça inicial de cada linha conectada em uma peça quebrada que não pode ser atravessada por 8 rodadas.",
  str_item_intro_9011074 = "Quando as Habilidades Ativas dos Aurorianos derrubam ou puxam um inimigo, causam 3.000 de dano fixo para cada ladrilho que o alvo atravessa.",
  str_item_intro_9011075 = "Todos os níveis de Avanço dos Aurorians +1 (Não se aplica a Aurorians cujo nível de Avanço atingiu o máximo).",
  str_item_intro_9011076 = "Uso único: Seleciona qualquer Aurorian para se juntar à equipe; eleva o nível de Avanço deste Aurorian ao máximo.",
  str_item_intro_9011077 = "Aurorians Detonadores infligem 1 acúmulo de <link=\"1003\"><color=#98500f><u>Derretimento</u></color></link> no alvo atingido por seus Combos em Cadeia.",
  str_item_intro_9011078 = "As Habilidades Ativas dos Aurorians Detonadores têm 40% de chance de infligir <link=\"1011\"><color=#98500f><u>Paralisia</u></color></link> no alvo.",
  str_item_intro_9011079 = "Expande o alcance dos Combos de Cadeia de nível mais alto dos Aurorians Detonadores para 2 aglomerados.",
  str_item_intro_9011080 = "Os ataques normais dos Aurorians Detonadores causam dano extra que ignora a DEF e, adicionalmente, infligem dano igual a 10% do PV perdido do Aurorian no alvo.",
  str_item_intro_9011081 = "Os ataques normais dos Aurorians Detonadores têm 30% de chance de causar 150% de dano.",
  str_item_intro_9011082 = "Para cada Aurorian Detonador implantado, aumenta o dano causado por todos os Combos de Cadeia dos Aurorians Detonadores em 4%.",
  str_item_intro_9011083 = "Os ataques normais dos Aurorians Atiradores infligem <link=\"1004\"><color=#98500f><u>Sabedoria</u></color></link> igual a 20% do seu ATQ nos alvos.",
  str_item_intro_9011084 = "Aumenta o dano causado pelos Combos em Cadeia dos Aurorianos Atiradores aos monstros que ocupam vários ladrilhos.",
  str_item_intro_9011085 = "Expande o alcance dos Combos de alvo único dos Aurorians Atiradores em 2 aglomerados e aumenta o número de alvos em 1.",
  str_item_intro_9011086 = "Aumenta o dano dos Combos de Corrente dos Aurorians Atiradores com base em seu HP perdido, com um aumento máximo de 50%.",
  str_item_intro_9011087 = "Habilidades ativas dos Aurorians Atiradores têm 30% de chance de infligir <link=\"1012\"><color=#98500f><u>Medo</u></color></link> nos alvos.",
  str_item_intro_9011088 = "Para cada Aurorian Sniper implantado, aumenta o dano causado por todos os ataques normais dos Aurorians Sniper em 5%.",
  str_item_9810702 = "Atualização de Algoritmo: Conjunto de Equip. dos Sonhos 2",
  str_item_9810704 = "Atualização de Algoritmo: Conjunto de Equip. dos Sonhos 4",
  str_item_9810706 = "Melhoria de Algoritmo: Conjunto de Equip. dos Sonhos 6",
  str_item_intro_9810702 = "A Bomba de Dados causa dano a todos os inimigos igual a 300% do ATK médio da equipe.",
  str_item_intro_9810704 = "A Bomba de Dados causa dano a todos os inimigos igual a 400% do ATK médio da equipe.",
  str_item_intro_9810706 = "A Bomba de Dados causa dano a um único alvo em todos os inimigos igual a 500% do ATK médio da equipe; quanto maior a porcentagem de HP do alvo, maior o dano, até o dobro.",
