  str_item_intro_8800103 = "Orvalho retirado do cume dos picos de cedro, tão puro que parece limpar o espírito de alguém.",
  str_item_intro_8800102 = "Uma flor que floresce no frio, exalando uma fragrância suave e delicada.",
  str_item_intro_8800101 = "Blocos de gelo onipresentes que produzem frio quando reunidos em grandes números.",
  str_item_intro_8800203 = "Gordura picante e avançada que incorpora a paixão e o vigor do Rediesel.",
  str_item_intro_8800202 = "Pedras com óleo derretido correndo sobre suas superfícies.",
  str_item_intro_8800201 = "Grãos ásperos de areia laranja, ainda quentes do deserto.",
  str_item_intro_8800303 = "Um galho exuberante, pulsando com uma vitalidade surpreendente.",
  str_item_intro_8800302 = "Flufes suaves e arejados que espalham sementes de esperança com o vento.",
  str_item_intro_8800301 = "Sementes verdes simples, esperando para brotar.",
  str_item_intro_8800403 = "Um cristal precioso e raro, brilhando com o esplendor do amanhecer.",
  str_item_intro_8800402 = "Uma gema amarela, crepitando com o poder do trovão.",
  str_item_intro_8800401 = "Um minério discreto, um pouco mais denso do que as rochas comuns.",
  str_item_intro_8800113 = "Essência nutritiva que revigora tanto plantas quanto animais.",
  str_item_intro_8800213 = "Macio e doce, cada mordida é um deleite.",
  str_item_intro_8800313 = "Uma encantadora Boneca Windelion com apelo visual e prazer tátil, com potencial para ser um presente popular.",
  str_item_intro_8800413 = "Um orbe de cristal que emite um brilho cativante, ideal para decoração de casa.",
  str_item_intro_8800112 = "Uma pomada de ação rápida para torções e contusões. É indispensável para casa e viagens.",
  str_item_intro_8800212 = "Minimiza o atrito e suaviza as superfícies, adequado para múltiplos usos.",
  str_item_intro_8800312 = "Uma planta em vaso vibrante e ecológica que prospera em lugares ensolarados.",
  str_item_intro_8800412 = "Uma faca incrivelmente afiada. Corta tudo com facilidade, preferida pelos artesãos.",
  str_item_intro_8800111 = "É adequado para resfriar itens e também seguro para beber.",
  str_item_intro_8800211 = "Explosivo de alta potência que deve ser manuseado com cautela.",
  str_item_intro_8800311 = "Tecido de cânhamo durável e simples, adequado para muitos propósitos.",
  str_item_intro_8800411 = "Um ornamento modesto que exala um charme sutil.",
  str_item_intro_8800123 = "Uma receita detalhando os requisitos para criar o Suplemento Nutricional.",
  str_item_intro_8800223 = "Uma receita detalhando os requisitos para preparar o Bolo Delicioso.",
  str_item_intro_8800323 = "Uma receita detalhando os requisitos para criar a Boneca Windelion Ornamentada.",
  str_item_intro_8800423 = "Uma receita detalhando os requisitos para criar o Enfeite de Cristal.",
  str_item_intro_8800122 = "Uma receita detalhando os requisitos para criar o Unguento Externo.",
  str_item_intro_8800222 = "Uma receita detalhando os requisitos para criar o Elixir Lubrificante.",
  str_item_intro_8800322 = "Uma receita detalhando os requisitos para criar a Planta Retentora de Água.",
  str_item_intro_8800422 = "Uma receita detalhando os requisitos para criar a Faca de Fio de Lâmina.",
  str_item_intro_8800121 = "Uma receita detalhando os requisitos para criar a Água de Resfriamento.",
  str_item_intro_8800221 = "Uma receita detalhando os requisitos para criar o Bloco de Dinamite.",
  str_item_intro_8800321 = "Uma receita detalhando os requisitos para confeccionar a Tira de Pano.",
  str_item_intro_8800421 = "Uma receita detalhando os requisitos para confeccionar o Pingente de Cobre.",
  str_item_8800005 = "Fragmento Antigo",
  str_item_intro_8800005 = "Originalmente parte de uma ruína, este fragmento de pedra é marcado pela passagem do tempo.",
  str_item_8800006 = "Transporte de Exploração",
  str_item_intro_8800006 = "Transporte projetado para exploração de material de alquimia, com 2 unidades repostas diariamente às 05:00 do horário do servente.",
  str_item_8800008 = "Fundo do Ateliê",
  str_item_intro_8800008 = "Lucros do Mini Atelier. Com a ajuda de Klaudia, esta loja certamente fará um nome em Astra!",
  str_item_8800010 = "SP",
  str_item_intro_8800010 = "Ganho através de trabalho diligente no Mini Atelier, ele pode atualizar Amuletos e Truques na Árvore de Habilidades.",
  str_item_8800011 = "Caixa de Material de Alquimia I",
  str_item_intro_8800011 = "Contém materiais de alquimia de baixo nível.",
  str_item_8800012 = "Caixa de Material de Alquimia II",
  str_item_intro_8800012 = "Contém materiais de alquimia de nível médio.",
  str_item_8800013 = "Caixa de Material de Alquimia III",
  str_item_intro_8800013 = "Contém materiais de alquimia de alto nível.",
  str_item_1602411 = "Pepita",
  str_item_intro_1602411 = "Pepita, uma bola de fogo audaciosa da liberdade. Embora tenha nascido em Illumina, ela se juntou à Verdadeira Ordem. Ela é uma rebelde de coração, recusando-se a se submeter à vontade de qualquer um. Em vez disso, ela segue suas paixões e instintos onde quer que a levem.",
  str_item_3220241 = "Pepita Solamber",
  str_item_intro_3220241 = "A gema parece bruta, mas quando segurada, irradia um calor intenso, um testemunho de sua natureza indomável.\nObjeto inovador essencial para Pepita.",
  str_item_3777777 = "Vou ter roupas novas para usar!",
  str_item_intro_3777777 = "Qual vai ser a minha nova roupa? Estou animado! Mal posso esperar para vesti-la!",
